// ============================================================================
// IMPORTS
// ============================================================================

// React core hooks
import { useState, useEffect, useRef, useMemo, lazy, Suspense } from "react";
import { runLocalStorageMigration } from "./utils/migrateScores";

// Critical components - keep eager loading (needed immediately)
import Header from "./components/Header";
import ToastContainer from "./components/ToastContainer";
import Footer from "./components/Footer";
import SignIn from "./components/SignIn";
import InviteSignUp from "./components/InviteSignUp";
import ApiKeyModal from "./components/ApiKeyModal";
import ConflictModal from "./components/ConflictModal";
import { getInviteFromUrl } from "./services/inviteService";

// Lazy load heavy components (loaded on-demand)
const LandingPage = lazy(() => import("./components/LandingPage"));
const MainLayout = lazy(() => import("./components/MainLayout"));
const GlobalModals = lazy(() => import("./components/GlobalModals"));
const CrashRecoveryPrompt = lazy(() =>
  import("./components/CrashRecoveryPrompt")
);

// Custom Hooks
import { useAppConfig } from "./hooks/useAppConfig";
import { useQuestionManager } from "./hooks/useQuestionManager";
import { useFileHandler } from "./hooks/useFileHandler";
import { useGeneration } from "./hooks/useGeneration";
import { useExport } from "./hooks/useExport";
import { useCrashRecovery } from "./hooks/useCrashRecovery";
import { useTutorial } from "./hooks/useTutorial";
import { useReviewActions } from "./hooks/useReviewActions";
import { useDatabaseActions } from "./hooks/useDatabaseActions";
import { useNavigation } from "./hooks/useNavigation";
import { useFiltering } from "./hooks/useFiltering";
import { useKeyboardShortcuts } from "./hooks/useKeyboardShortcuts";
import { useToast } from "./hooks/useToast";
// useBulkSelection removed - bulk selection feature no longer used
import { useAuth } from "./hooks/useAuth";
import { useModalState } from "./hooks/useModalState";
import { useAppHandlers } from "./hooks/useAppHandlers";
import { useMigrations } from "./hooks/useMigrations";
import { usePendingCount } from "./hooks/usePendingCount";
import { useNavigationAfterLanguageSwitch } from "./hooks/useNavigationAfterLanguageSwitch";

// Concurrent Editing Agents
import { initializeAgents } from "./agents";
// Utilities
import { TOAST_DURATION, APP_MODES } from "./utils/constants";
import { FullPageSpinner as LoadingSpinner } from "./components/LoadingSpinner";
import { logger } from "./utils/logger";

const App = () => {
  // ========================================================================
  // HOOKS - Toast Notifications
  // ========================================================================
  const { toasts, removeToast, showMessage } = useToast();

  // ========================================================================
  // HOOKS - Auth, Custom Tags, and Compliance (extracted to useAuth)
  // ========================================================================
  const {
    user,
    authLoading,
    isAdmin,
    userRole,
    isRegistered: _isRegistered,
    registrationLoading,
    markAsRegistered,
    customTags,
    handleSaveCustomTags,
    tokenUsage,
    showTerms,
    setShowTerms,
    showAgeGate,
    setShowAgeGate,
    setTermsAccepted,
  } = useAuth(showMessage);

  // ... (rest of the file)

  // 0. Tutorial System
  const {
    tutorialActive,
    currentStep,
    tutorialSteps,
    activeScenario,
    handleTutorialNext,
    handleTutorialPrev,
    handleTutorialSkip,
    handleTutorialComplete,
    handleRestartTutorial,
    handleStartTutorial,
  } = useTutorial(showMessage, undefined, {
    // FUTURE: Wire up actual panel/modal setters when implementing tutorial actions
    // setShowAdvancedConfig: (open) => { /* implement */ },
    // setShowCritiqueModal: (open) => { /* implement */ },
    // setActiveAnalyticsTab: (tab) => { /* implement */ },
  });

  // ========================================================================
  // CONCURRENT EDITING AGENTS - Initialize once when user is authenticated
  // ========================================================================
  useEffect(() => {
    if (user && !authLoading) {
      // Initialize agents with Firestore instance
      const initAgents = async () => {
        try {
          const { getDb } = await import("./services/firebase");
          initializeAgents(getDb());
          logger.log("Γ£à Concurrent editing agents initialized");
        } catch (error) {
          logger.error("Γ¥î Failed to initialize agents:", error);
        }
      };
      initAgents();
    }
  }, [user, authLoading]);

  // ========================================================================
  // HOOKS - State Management
  // ========================================================================

  // 1. App Configuration & UI State
  const {
    appMode,
    setAppMode,
    config,
    setConfig,
    isAuthReady,
    isApiReady,
    effectiveApiKey,
    apiKeyStatus,
    showNameModal,
    setShowNameModal,
    showGenSettings,
    setShowGenSettings,
    setShowApiError,
    batchSizeWarning,
    showSettings,
    setShowSettings,
    showApiKey,
    setShowApiKey,
    handleChange,
    handleNameSave,
    handleLanguageSwitch,
    pendingNavigationUniqueId,
    setPendingNavigationUniqueId,
  } = useAppConfig();

  // Run all migrations (extracted to useMigrations hook)
  useMigrations({
    user,
    authLoading,
    isAdmin,
    showMessage,
    handleLoadFromFirestore: () => {}, // Will be set after useExport is called
    setConfig,
  });

  // 2. Question Data Management
  const {
    questions,
    historicalQuestions,
    databaseQuestions,
    allQuestionsMap,
    translationMap,
    addQuestionsToState,
    updateQuestionInState,
    updateAllVariantsInState,
    handleUpdateStatus,
    approvedCounts,
    approvedCount,

    pendingCount: totalApproved,
    overallPercentage,
    isTargetMet,
    maxBatchSize,
    deleteConfirmId,
    setDeleteConfirmId,
    showClearModal,
    setShowClearModal,
    handleDelete,
    confirmDelete,
    handleDeleteAllQuestions,
    checkAndStoreQuestions,
    unifiedQuestions,
    handleUpdateQuestion, // Persistent update handler
    // Concurrent editing conflict resolution
    conflictData,
    showConflictModal,
    setShowConflictModal,
    replaceQuestions,
    bulkDeleteQuestions,
    moveQuestion,
  } = useQuestionManager(config, showMessage);

  // 2.5. Crash Recovery - detect and restore from cloud backup
  const {
    showRecoveryPrompt,
    recoveryData,
    isRecovering,
    handleRecover,
    dismissRecovery,
  } = useCrashRecovery(questions, addQuestionsToState, showMessage);

  // 3. Status State (Shared)
  const [status, setStatus] = useState("");

  // 4. File Handling
  const { fileInputRef, handleFileChange, getFileContext, handleDetectTopics } =
    useFileHandler(
      config,
      setConfig,
      addQuestionsToState,
      showMessage,
      setStatus,
      isApiReady,
      effectiveApiKey
    );

  // 5. Filtering & Search (extracted to useFiltering hook)
  const {
    searchTerm,
    setSearchTerm,
    filterMode,
    setFilterMode,
    showHistory,
    setShowHistory,
    filterByCreator,
    setFilterByCreator,
    filterTags,
    setFilterTags,
    filterScoreTier,
    setFilterScoreTier,
    currentReviewIndex,
    setCurrentReviewIndex,
    sortBy,
    setSortBy,
    contextCounts,
    filteredQuestions,
    uniqueFilteredQuestions,
  } = useFiltering({
    questions: unifiedQuestions,
    historicalQuestions: [], // We are using the unified list as source of truth
    config,
    appMode,
    allQuestionsMap,
  });

  // Language switch navigation (extracted to hook)
  useNavigationAfterLanguageSwitch({
    pendingNavigationUniqueId,
    uniqueFilteredQuestions,
    setCurrentReviewIndex,
    setPendingNavigationUniqueId,
  });

  // Calculate total PENDING questions for the Review badge (extracted to hook)
  const totalPendingQuestions = usePendingCount(allQuestionsMap);

  // 6. Generation & Translation Logic
  const {
    isGenerating,
    isProcessing,
    translationProgress,
    handleGenerate,
    handleTranslateSingle,
    handleExplain,
    handleVariate,
    handleCritique,
    handleApplyRewrite,
    handleBulkTranslateMissing,
  } = useGeneration(
    config,
    setConfig,
    effectiveApiKey,
    isApiReady,
    isTargetMet,
    maxBatchSize,
    getFileContext,
    checkAndStoreQuestions,
    addQuestionsToState,
    updateQuestionInState,
    updateAllVariantsInState,
    handleLanguageSwitch,
    showMessage,
    setStatus,
    setShowNameModal,
    setShowApiError,
    setShowHistory,
    translationMap,
    allQuestionsMap
  );

  // 7. Modal State (extracted to useModalState hook)
  const {
    showExportMenu,
    setShowExportMenu,
    showBulkExportModal,
    setShowBulkExportModal,
    showAnalytics,
    setShowAnalytics,
    showAdvancedConfig,
    setShowAdvancedConfig,
    showDangerZone,
    setShowDangerZone,
    showApiKeyModal,
    setShowApiKeyModal,
  } = useModalState();

  // 8. Export Logic (must come before Navigation since Navigation depends on handleLoadFromFirestore)
  const {
    handleExportToSheets,
    handleLoadFromSheets,
    handleLoadFromFirestore,
    handleBulkExport,
  } = useExport(
    config,
    questions,
    historicalQuestions,
    uniqueFilteredQuestions,
    allQuestionsMap,
    showHistory,
    showMessage,
    setStatus,
    () => {},
    setAppMode,
    setShowExportMenu,
    setShowBulkExportModal,
    replaceQuestions
  );

  // Auto-load database questions on startup for difficulty distribution chart
  const hasAutoLoadedRef = useRef(false);
  useEffect(() => {
    if (user && !authLoading && !hasAutoLoadedRef.current) {
      // One-time migration: Add improvedScore to existing critiques
      const migrated = runLocalStorageMigration();
      if (migrated.updated > 0) {
        logger.log(
          `≡ƒöä Migrated ${migrated.updated} questions with estimated improved scores`
        );
      }

      hasAutoLoadedRef.current = true;
      logger.log("≡ƒôè Auto-loading database for difficulty chart...");
      handleLoadFromFirestore(true); // Silent auto-recovery
    }
  }, [user, authLoading, handleLoadFromFirestore]);

  // Migrations handled by useMigrations hook (called earlier in component)

  // 9. Review Actions (bulk operations)
  const {
    handleClearPending,
    handleBulkAcceptHighScores,
    handleBulkCritiqueAll,
    handleTrimExcess,
    handleAutoTagAll,
  } = useReviewActions({
    uniqueFilteredQuestions,
    allQuestions: unifiedQuestions, // Pass complete dataset for Trim accuracy
    handleUpdateStatus,
    handleUpdateQuestion, // Pass persistent handler
    handleCritique,
    showMessage,
    bulkDeleteQuestions,
  });

  // 10. Database Actions
  const { handleUpdateDatabaseQuestion, handleKickBackToReview } =
    useDatabaseActions({
      showMessage,
      handleLoadFromFirestore,
      moveQuestion,
      updateQuestionInState,
    });

  // 11. Navigation (depends on handleLoadFromFirestore from useExport)
  const { handleModeSelect, handleViewDatabase, handleGoHome } = useNavigation({
    setAppMode,
    setShowExportMenu,
    setShowHistory,
    setFilterMode,
    setCurrentReviewIndex,
    handleLoadFromFirestore,
  });

  // Bulk selection feature removed

  // Keyboard Shortcuts (extracted to useKeyboardShortcuts hook)
  useKeyboardShortcuts({
    appMode,
    isGenerating,
    isTargetMet,
    isApiReady,
    maxBatchSize,
    handleGenerate,
    config,
    handleExportToSheets,
    handleBulkExport,
    setShowBulkExportModal,
    uniqueFilteredQuestionsLength: uniqueFilteredQuestions.length,
    setCurrentReviewIndex,
    isAdmin, // Only admins can use export shortcuts (Ctrl+S, Ctrl+E)
  });

  // App Handlers (extracted to useAppHandlers hook)
  const { handleManualUpdate, handleSelectCategory, handleSaveApiKey } =
    useAppHandlers({
      updateQuestionInState,
      setConfig,
      handleChange,
      setShowApiKeyModal,
    });

  // Memoize viewRouterHandlers to prevent unnecessary re-renders
  const viewRouterHandlers = useMemo(
    () => ({
      handleLoadFromSheets,
      handleLoadFromFirestore,
      handleUpdateDatabaseQuestion,
      handleKickBackToReview,
      handleUpdateStatus,
      handleExplain,
      handleVariate,
      handleCritique,
      handleApplyRewrite,
      handleTranslateSingle,
      handleLanguageSwitch,
      handleDelete,
      handleManualUpdate,
      handleTrimExcess,
      handleUpdateQuestion,
      userRole,
    }),
    [
      handleLoadFromSheets,
      handleLoadFromFirestore,
      handleUpdateDatabaseQuestion,
      handleKickBackToReview,
      handleUpdateStatus,
      handleExplain,
      handleVariate,
      handleCritique,
      handleApplyRewrite,
      handleTranslateSingle,
      handleLanguageSwitch,
      handleDelete,
      handleManualUpdate,
      handleTrimExcess,
      handleUpdateQuestion,
      userRole,
    ]
  );

  // Render - Loading state
  if (authLoading || registrationLoading) {
    return <LoadingSpinner />;
  }

  // Render - Not authenticated
  if (!user) {
    // Check if there's an invite code in URL - show invite signup
    const inviteCode = getInviteFromUrl();
    if (inviteCode) {
      return (
        <InviteSignUp
          onSuccess={(role) => {
            markAsRegistered(role);
          }}
        />
      );
    }
    return <SignIn />;
  }

  // User is authenticated - enforce registration check
  if (!_isRegistered) {
    // If not registered and not on an invite URL, show invite-only message or redirect to sign in
    return (
      <InviteSignUp
        onSuccess={(role) => {
          markAsRegistered(role);
        }}
      />
    );
  }

  if (appMode === APP_MODES.LANDING) {
    return (
      <Suspense fallback={<LoadingSpinner />}>
        <LandingPage
          onSelectMode={handleModeSelect}
          apiKeyStatus={apiKeyStatus}
          isCloudReady={isAuthReady}
          onOpenSettings={() => {
            logger.log("≡ƒÜÇ Configure Now clicked!");
            setShowApiKeyModal(true);
          }}
          isAdmin={isAdmin} // Pass admin status
          onStartTutorial={() => handleStartTutorial("welcome")} // Start welcome tour
        />
        {/* API Key Modal for Configure Now button */}
        <ApiKeyModal
          isOpen={showApiKeyModal}
          onClose={() => setShowApiKeyModal(false)}
          onSave={handleSaveApiKey}
          currentKey={config.apiKey}
        />
      </Suspense>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-950 font-sans text-slate-200">
      <Suspense fallback={null}>
        {/* Crash Recovery Prompt - highest priority */}
        <CrashRecoveryPrompt
          isOpen={showRecoveryPrompt}
          recoveryData={recoveryData}
          isRecovering={isRecovering}
          onRecover={handleRecover}
          onDismiss={dismissRecovery}
        />
        <GlobalModals
          visibility={{
            showNameModal,
            showClearModal,
            showBulkExportModal,
            showSettings,
            showAnalytics,
            showDangerZone,
            showApiKeyModal,
            showTerms,
            showAgeGate,
            tutorialActive,
            deleteConfirmId,
            showAdvancedConfig,
            showApiKey,
          }}
          state={{
            config,
            isProcessing,
            status,
            translationProgress,
            allQuestionsMap,
            appMode,
            currentStep,
            tutorialSteps,
            activeScenario,
            metrics: {
              totalApproved: approvedCount,
              totalQuestions: questions.length,
            },
            isApiReady,
            customTags,
            isAdmin,
          }}
          handlers={{
            handleNameSave,
            handleDeleteAllQuestions,
            handleBulkExport,
            confirmDelete,
            setDeleteConfirmId,
            onCloseBulkExport: () => setShowBulkExportModal(false),
            onCloseSettings: () => setShowSettings(false),
            onCloseAnalytics: () => setShowAnalytics(false),
            onCloseDangerZone: () => setShowDangerZone(false),
            onCloseApiKey: () => setShowApiKeyModal(false),
            handleChange,
            handleSaveApiKey,
            setShowTerms,
            setTermsAccepted,
            setShowAgeGate,
            setShowClearModal,
            handleTutorialNext,
            handleTutorialPrev,
            handleTutorialSkip,
            handleTutorialComplete,
            onResetSettings: () =>
              setConfig({ ...config, ...useAppConfig.defaultConfig }),
            onHardReset: () => {
              localStorage.clear();
              window.location.reload();
            },
            fileInputRef,
            handleFileChange,
            setShowAdvancedConfig,
            setShowApiKey,
            handleDetectTopics,
            onSaveCustomTags: handleSaveCustomTags,
            window: window,
          }}
        />
      </Suspense>

      <Header
        apiKeyStatus={apiKeyStatus}
        isCloudReady={isAuthReady}
        onHome={handleGoHome}
        creatorName={config.creatorName}
        appMode={appMode}
        tokenUsage={tokenUsage}
        onRestartTutorial={handleRestartTutorial}
        onStartTutorial={handleStartTutorial}
        isAdmin={isAdmin}
        user={user}
      />

      <Suspense fallback={<LoadingSpinner />}>
        <MainLayout
          appMode={appMode}
          setAppMode={setAppMode}
          effectiveApiKey={effectiveApiKey}
          isAdmin={isAdmin}
          sidebarProps={{
            showGenSettings,
            setShowGenSettings,
            config,
            handleChange,
            allQuestionsMap,
            approvedCounts,
            overallPercentage,
            totalApproved,
            isTargetMet,
            maxBatchSize,
            batchSizeWarning,
            handleGenerate,
            isGenerating,
            isApiReady,
            handleBulkTranslateMissing,
            isProcessing,
            setShowSettings,
            handleSelectCategory,
            customTags,
            status,
            showMessage,
            isAdmin,
          }}
          handleModeSelect={handleModeSelect}
          handleViewDatabase={handleViewDatabase}
          pendingCount={totalPendingQuestions} // Show pending questions needing review
          toolbarProps={{
            mode: appMode,
            counts: contextCounts,
            filterMode,
            setFilterMode,
            filterByCreator,
            setFilterByCreator,
            filterTags,
            setFilterTags,
            filterScoreTier,
            setFilterScoreTier,
            customTags,
            searchTerm,
            setSearchTerm,
            sortBy,
            setSortBy,
            isProcessing,
            status,
            isAuthReady,
            config,
            onLoadSheets: handleLoadFromSheets,
            onLoadFirestore: handleLoadFromFirestore,
            onBulkExport: () => setShowBulkExportModal(true),
            onClearPending: handleClearPending,
            onBulkAcceptHighScores:
              appMode === APP_MODES.REVIEW
                ? handleBulkAcceptHighScores
                : undefined,
            onBulkCritiqueAll:
              appMode === APP_MODES.REVIEW ? handleBulkCritiqueAll : undefined,
            onTrimExcess: handleTrimExcess,
            onAutoTagAll: handleAutoTagAll, // Added
            effectiveApiKey: effectiveApiKey,
            handleChange, // Pass config handler for Discipline selector
          }}
          showHistory={showHistory}
          uniqueFilteredQuestions={uniqueFilteredQuestions}
          questions={questions}
          status={status}
          databaseQuestions={databaseQuestions}
          config={config}
          isProcessing={isProcessing}
          allQuestionsMap={allQuestionsMap}
          viewRouterHandlers={viewRouterHandlers}
          viewRouterState={{
            currentReviewIndex,
            translationMap,
            filterByCreator,
            filteredQuestions,
            questions,
            status,
            filterMode,
            sortBy,
            searchTerm,
            showHistory,
            currentUser: user,
            userRole, // Add role for component restrictions
          }}
          viewRouterSetters={{
            setCurrentReviewIndex,
            setFilterByCreator,
            showMessage,
          }}
          handleGoHome={handleGoHome}
          onStartTutorial={handleStartTutorial}
        />
      </Suspense>

      {/* API Key Modal - Simple popup for Configure Now button */}

      {/* Footer */}
      <Footer />

      {/* TOAST NOTIFICATIONS */}
      <ToastContainer toasts={toasts} onRemove={removeToast} />

      {/* CONCURRENT EDITING CONFLICT MODAL */}
      {showConflictModal && conflictData && (
        <ConflictModal
          isOpen={showConflictModal}
          onClose={() => setShowConflictModal(false)}
          conflictData={conflictData}
          onResolve={async (action) => {
            if (action === "DISCARD") {
              // Reload the latest version from server
              const { loadAgent } = await import("./agents").then((m) =>
                m.getAgents()
              );
              if (loadAgent) {
                const result = await loadAgent.loadQuestion(
                  conflictData.serverQuestion.id
                );
                if (result.success) {
                  handleUpdateQuestion(result.question.id, result.question);
                  showMessage(
                    "Γ£ô Reloaded latest version",
                    TOAST_DURATION.MEDIUM
                  );
                }
              }
            } else if (action === "OVERWRITE") {
              // Force save local changes
              const { saveGuardAgent } = await import("./agents").then((m) =>
                m.getAgents()
              );
              if (saveGuardAgent) {
                await saveGuardAgent.saveQuestion(
                  conflictData.serverQuestion.id,
                  conflictData.localChanges,
                  conflictData.serverVersion, // Use server version to force overwrite
                  user?.uid || "unknown",
                  user?.email || "unknown@example.com"
                );
                showMessage("Γ£ô Overwrote server changes", 2000);
              }
            }
            setShowConflictModal(false);
          }}
        />
      )}

      {/* TUTORIAL OVERLAY */}

      {/* COMPLIANCE MODALS */}
    </div>
  );
};

export default App;
// Force rebuild

/**
 * Integration Tests for Feedback Loop (Rejected Questions)
 * Tests that rejected questions are fed back into the AI Prompt.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { renderHook, act } from "@testing-library/react";
import { useGeneration } from "../hooks/useGeneration";
import * as geminiMock from "./mocks/gemini.mock";

// Mock the gemini service
vi.mock("../services/gemini", async () => {
  return await import("./mocks/gemini.mock");
});

// Mock the firebase service to prevent initialization side-effects
// Mock Firebase SDKs to allow service logic to run without initialization errors
vi.mock("firebase/app", () => ({
  initializeApp: vi.fn(() => ({})),
}));

vi.mock("firebase/analytics", () => ({
  getAnalytics: vi.fn(),
  logEvent: vi.fn(),
}));

vi.mock("firebase/auth", () => ({
  getAuth: vi.fn(() => ({ currentUser: null })),
  GoogleAuthProvider: vi.fn(),
  signInWithPopup: vi.fn(),
  signInWithEmailAndPassword: vi.fn(),
  createUserWithEmailAndPassword: vi.fn(),
  signOut: vi.fn(),
  onAuthStateChanged: vi.fn(),
}));

vi.mock("firebase/firestore", () => ({
  getFirestore: vi.fn(() => ({})),
  collection: vi.fn(),
  doc: vi.fn(),
  setDoc: vi.fn(),
  getDoc: vi.fn(),
  getDocs: vi.fn(),
  deleteDoc: vi.fn(),
  query: vi.fn(),
  where: vi.fn(),
  orderBy: vi.fn(),
  limit: vi.fn(),
  startAfter: vi.fn(),
  Timestamp: { now: vi.fn(() => 12345) },
}));

vi.mock("firebase/functions", () => ({
  getFunctions: vi.fn(() => ({})),
  httpsCallable: vi.fn(() => vi.fn()),
}));

// Mock the analytics store
vi.mock("../utils/analyticsStore", () => ({
  logGeneration: vi.fn(),
  logQuestion: vi.fn(),
}));

describe("Feedback Loop Integration Tests", () => {
  let mockConfig;
  const mockSetConfig = vi.fn();
  const mockShowMessage = vi.fn();
  const mockSetStatus = vi.fn();
  const mockHandlers = {
    mockSetShowNameModal: vi.fn(),
    mockSetShowAdvancedConfig: vi.fn(), // Kept in handlers obj but not passed
    mockSetShowApiError: vi.fn(),
    mockSetShowHistory: vi.fn(),
    mockCheckAndStoreQuestions: vi.fn(async (q) => q),
    mockAddQuestionsToState: vi.fn(),
    mockUpdateQuestionInState: vi.fn(),
    mockHandleLanguageSwitch: vi.fn(),
    mockGetFileContext: vi.fn(() => ""),
  };
  const translationMap = new Map();
  let allQuestionsMap = new Map();

  beforeEach(() => {
    geminiMock.resetMock();
    mockConfig = {
      creatorName: "TestUser",
      discipline: "Technical Art", // Must match rejected question discipline
      difficulty: "Medium",
      type: "Multiple Choice",
      language: "English",
      batchSize: 2,
      temperature: 0.7,
      model: "gemini-1.5-flash",
    };
    allQuestionsMap = new Map();
  });

  afterEach(() => {
    vi.clearAllMocks();
  });

  it("should include rejected questions in the system prompt", async () => {
    // 1. Seed a rejected question
    const rejectedQuestion = {
      id: "rejected-1",
      uniqueId: "rejected-1",
      question: "What is the capital of Mars?",
      rejectionReason: "hallucination", // Uses our specific label
      critique: "Mars has no capital city.", // Context
      status: "rejected",
      discipline: "Technical Art", // Must match config
    };

    allQuestionsMap.set("rejected-1", [rejectedQuestion]);

    const { result } = renderHook(() =>
      useGeneration(
        mockConfig,
        mockSetConfig,
        "test-api-key",
        true,
        false,
        5,
        mockHandlers.mockGetFileContext,
        mockHandlers.mockCheckAndStoreQuestions,
        mockHandlers.mockAddQuestionsToState,
        mockHandlers.mockUpdateQuestionInState,
        vi.fn(), // updateAllVariantsInState
        mockHandlers.mockHandleLanguageSwitch,
        mockShowMessage,
        mockSetStatus,
        mockHandlers.mockSetShowNameModal,
        // Removed mockSetShowAdvancedConfig here
        mockHandlers.mockSetShowApiError,
        mockHandlers.mockSetShowHistory,
        translationMap,
        allQuestionsMap
      )
    );

    // 2. Trigger Generation
    await act(async () => {
      await result.current.handleGenerate();
    });

    // 3. Verify Prompt Content
    const lastCall = geminiMock.getLastCall();
    expect(lastCall.systemPrompt).toContain("CRITICAL: FAILURE AVOIDANCE");
    expect(lastCall.systemPrompt).toContain("What is the capital of Mars?");
    expect(lastCall.systemPrompt).toContain(
