          </select>
        </div>

        <div>
          <label
            htmlFor="expires"
            className="block text-sm text-slate-400 mb-1"
          >
            Expires In
          </label>
          <select
            id="expires"
            value={expiresInDays}
            onChange={(e) => setExpiresInDays(parseInt(e.target.value))}
            className="w-full px-3 py-2 bg-slate-700 border border-slate-600 rounded text-white"
