import { useState, useMemo } from "react";
import {
  AreaChart,
  Area,
  BarChart,
  Bar,
  PieChart as RechartsPieChart,
  Pie,
  Cell,
  CartesianGrid,
  XAxis,
  YAxis,
  Tooltip,
} from "recharts";
import SafeResponsiveContainer from "./analytics/SafeResponsiveContainer";
import { format } from "date-fns";
import { TIME } from "../utils/constants";
import {
  BarChart2,
  Download,
  X,
  Activity,
  TrendingUp,
  PieChart,
} from "lucide-react";
import { getAnalytics } from "../utils/analyticsStore";
import { TAGS_BY_DISCIPLINE } from "../utils/tagTaxonomy";
import { QUALITY_THRESHOLDS } from "../utils/constants";

const MetricCard = ({ title, value, icon, color }) => {
  const colors = {
    blue: "bg-blue-500/10 text-blue-400 border-blue-500/20",
    green: "bg-emerald-500/10 text-emerald-400 border-emerald-500/20",
    orange: "bg-orange-500/10 text-orange-400 border-orange-500/20",
    purple: "bg-purple-500/10 text-purple-400 border-purple-500/20",
  };

  return (
    <div
      className={`p-4 rounded-xl border ${colors[color]} flex items-center justify-between`}
    >
      <div>
        <p className="text-xs font-medium opacity-80 uppercase tracking-wider">
          {title}
        </p>
        <p className="text-2xl font-bold mt-1">{value}</p>
      </div>
      <div className={`p-3 rounded-lg bg-slate-900/50`}>{icon}</div>
    </div>
  );
};

const AnalyticsDashboard = ({ isOpen, onClose }) => {
  const [timeRange, setTimeRange] = useState("7d"); // 24h, 7d, 15d, 30d, 90d, all

  // Re-fetch analytics data whenever modal opens (removes useMemo dependency issue)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const allAnalyticsData = isOpen
    ? getAnalytics()
    : { generations: [], questions: [], summary: {} };

  // Filter data based on time range
  const analyticsData = useMemo(() => {
    if (!isOpen || timeRange === "all") return allAnalyticsData;

    const now = new Date();
    let cutoffDate;

    switch (timeRange) {
      case "24h":
        cutoffDate = new Date(now.getTime() - TIME.DAY);
        break;
      case "7d":
        cutoffDate = new Date(now.getTime() - TIME.WEEK);
        break;
      case "15d":
        cutoffDate = new Date(now.getTime() - 15 * TIME.DAY);
        break;
      case "30d":
        cutoffDate = new Date(now.getTime() - TIME.MONTH);
        break;
      case "90d":
        cutoffDate = new Date(now.getTime() - TIME.QUARTER);
        break;
      default:
        return allAnalyticsData;
    }

    return {
      generations: allAnalyticsData.generations.filter(
        (g) => new Date(g.timestamp) >= cutoffDate
      ),
      questions: allAnalyticsData.questions.filter(
        (q) => new Date(q.created || q.timestamp || q.dateAdded) >= cutoffDate
      ),
      summary: allAnalyticsData.summary, // Keep overall summary
    };
  }, [isOpen, timeRange, allAnalyticsData]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-slate-900 border border-slate-700 w-full max-w-6xl h-[90vh] rounded-xl shadow-2xl flex flex-col overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-slate-700 bg-slate-800/50">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-indigo-500/20 rounded-lg">
              <BarChart2 className="w-6 h-6 text-indigo-400" />
            </div>
            <div>
              <h2 className="text-xl font-bold text-white">
                Analytics Dashboard
              </h2>
              <p className="text-xs text-slate-400">
                Track generation performance and costs
              </p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <select
              value={timeRange}
              onChange={(e) => setTimeRange(e.target.value)}
              className="bg-slate-950 border border-slate-700 text-slate-300 text-sm rounded px-3 py-1.5 outline-none focus:border-indigo-500"
            >
              <option value="24h">Last 24 Hours</option>
              <option value="7d">Last 7 Days</option>
              <option value="15d">Last 15 Days</option>
              <option value="30d">Last 30 Days</option>
              <option value="90d">Last 90 Days</option>
              <option value="all">All Time</option>
            </select>

            <button className="flex items-center gap-2 px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-300 text-sm rounded border border-slate-700 transition-colors">
              <Download size={14} />
              Export CSV
            </button>

            <button
              onClick={onClose}
              className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 hover:text-white transition-colors"
            >
              <X size={20} />
            </button>
          </div>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6">
          {/* Key Metrics */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <MetricCard
              title="Total Questions"
              value={analyticsData.summary?.totalQuestions || 0}
              icon={<Activity size={18} />}
              color="blue"
            />
            <MetricCard
              title="Success Rate"
              value={`${Math.round(
                (analyticsData.generations.filter((g) => g.success).length /
                  (analyticsData.summary?.totalGenerations || 1)) *
                  100
              )}%`}
              icon={<TrendingUp size={18} />}
              color="green"
            />
            <MetricCard
              title="Est. Cost"
              value={`$${(analyticsData.summary?.estimatedCost || 0).toFixed(
                4
              )}`}
              icon={<PieChart size={18} />}
              color="orange"
            />
            <MetricCard
              title="Avg Quality"
              value={`${analyticsData.summary?.averageQuality || 0}/100`}
              icon={<BarChart2 size={18} />}
              color="purple"
            />
          </div>

          {/* Charts Grid */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Token Usage Chart */}
            <div className="bg-slate-950/50 border border-slate-800 rounded-xl p-4 h-80 flex flex-col min-w-0">
              <h3 className="text-sm font-bold text-slate-400 mb-4 flex items-center gap-2">
                <Activity size={16} /> Token Usage History
              </h3>
              <div className="flex-1 min-h-0 w-full" style={{ minHeight: 200 }}>
                <SafeResponsiveContainer
                  width="100%"
                  height="100%"
                  minWidth={1}
                  minHeight={200}
                >
                  <AreaChart data={analyticsData.generations.slice(-20)}>
                    <defs>
                      <linearGradient
                        id="colorTokens"
                        x1="0"
                        y1="0"
                        x2="0"
                        y2="1"
                      >
                        <stop
                          offset="5%"
                          stopColor="#6366f1"
                          stopOpacity={0.3}
                        />
                        <stop
                          offset="95%"
                          stopColor="#6366f1"
                          stopOpacity={0}
                        />
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
                    <XAxis
                      dataKey="timestamp"
                      tickFormatter={(t) => format(new Date(t), "MM/dd")}
                      stroke="#475569"
                      fontSize={10}
                    />
                    <YAxis stroke="#475569" fontSize={10} />
                    <Tooltip
                      contentStyle={{
                        backgroundColor: "#0f172a",
                        borderColor: "#334155",
                      }}
                      labelFormatter={(t) => format(new Date(t), "PP pp")}
                    />
                    <Area
                      type="monotone"
                      dataKey="tokensUsed.input"
                      stackId="1"
                      stroke="#818cf8"
                      fill="url(#colorTokens)"
                      name="Input Tokens"
                    />
                    <Area
                      type="monotone"
                      dataKey="tokensUsed.output"
                      stackId="1"
                      stroke="#34d399"
                      fill="#34d399"
                      name="Output Tokens"
                    />
                  </AreaChart>
                </SafeResponsiveContainer>
              </div>
            </div>

            {/* Quality Distribution */}
            <div className="bg-slate-950/50 border border-slate-800 rounded-xl p-4 h-80 flex flex-col min-w-0">
              <h3 className="text-sm font-bold text-slate-400 mb-4 flex items-center gap-2">
                <BarChart2 size={16} /> Quality Score Distribution
              </h3>
              <div className="flex-1 min-h-0 w-full" style={{ minHeight: 200 }}>
                <SafeResponsiveContainer
                  width="100%"
                  height="100%"
                  minWidth={1}
                  minHeight={200}
                >
                  <BarChart
                    data={[
                      {
                        range: "90-100",
                        count: analyticsData.questions.filter(
                          (q) => q.qualityScore >= QUALITY_THRESHOLDS.EXCELLENT
                        ).length,
                      },
                      {
                        range: "70-89",
                        count: analyticsData.questions.filter(
                          (q) =>
                            q.qualityScore >= QUALITY_THRESHOLDS.PASS &&
                            q.qualityScore < QUALITY_THRESHOLDS.EXCELLENT
                        ).length,
                      },
                      {
                        range: "50-69",
                        count: analyticsData.questions.filter(
                          (q) =>
                            q.qualityScore >= QUALITY_THRESHOLDS.MEDIOCRE &&
                            q.qualityScore < QUALITY_THRESHOLDS.PASS
                        ).length,
                      },
                      {
                        range: "< 50",
                        count: analyticsData.questions.filter(
                          (q) =>
                            q.qualityScore < QUALITY_THRESHOLDS.MEDIOCRE &&
                            q.qualityScore != null
                        ).length,
                      },
                    ]}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
                    <XAxis dataKey="range" stroke="#475569" fontSize={10} />
                    <YAxis stroke="#475569" fontSize={10} />
                    <Tooltip
                      cursor={{ fill: "#1e293b" }}
                      contentStyle={{
                        backgroundColor: "#0f172a",
                        borderColor: "#334155",
                      }}
                    />
                    <Bar
                      cursor="default"
                      activeBar={false}
                      dataKey="count"
                      fill="#f59e0b"
                      radius={[4, 4, 0, 0]}
                    />
                  </BarChart>
                </SafeResponsiveContainer>
              </div>
            </div>

            {/* Acceptance Rate by Discipline */}
            <div className="bg-slate-950/50 border border-slate-800 rounded-xl p-4 h-80 flex flex-col lg:col-span-2 min-w-0">
              <h3 className="text-sm font-bold text-slate-400 mb-4 flex items-center gap-2">
                <PieChart size={16} /> Acceptance Rate by Discipline
              </h3>
              <div className="flex-1 min-h-0 w-full" style={{ minHeight: 200 }}>
                <SafeResponsiveContainer
                  width="100%"
                  height="100%"
                  minWidth={1}
                  minHeight={200}
                >
                  <BarChart
                    data={Object.entries(
                      analyticsData.questions.reduce((acc, q) => {
                        if (!acc[q.discipline])
                          acc[q.discipline] = { total: 0, accepted: 0 };
                        acc[q.discipline].total++;
                        if (q.status === "accepted")
                          acc[q.discipline].accepted++;
                        return acc;
                      }, {})
                    ).map(([name, stats]) => ({
                      name,
                      rate:
                        Math.round((stats.accepted / stats.total) * 100) || 0,
                      total: stats.total,
                    }))}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
                    <XAxis dataKey="name" stroke="#475569" fontSize={10} />
                    <YAxis stroke="#475569" fontSize={10} unit="%" />
                    <Tooltip
                      cursor={{ fill: "#1e293b" }}
                      contentStyle={{
                        backgroundColor: "#0f172a",
                        borderColor: "#334155",
                      }}
                    />
                    <Bar
                      cursor="default"
                      activeBar={false}
                      dataKey="rate"
                      fill="#6366f1"
                      radius={[4, 4, 0, 0]}
                      name="Acceptance Rate"
                    />
                  </BarChart>
                </SafeResponsiveContainer>
              </div>
            </div>

            {/* Rejection Reasons Breakdown */}
            <div className="bg-slate-950/50 border border-slate-800 rounded-xl p-4 h-80 flex flex-col min-w-0">
              <h3 className="text-sm font-bold text-slate-400 mb-4 flex items-center gap-2">
                <PieChart size={16} /> Rejection Reasons
              </h3>
              <div className="flex-1 min-h-0 w-full flex items-center justify-center">
                {(() => {
                  const rejectionData = Object.entries(
                    analyticsData.questions
                      .filter(
                        (q) => q.status === "rejected" && q.rejectionReason
                      )
                      .reduce((acc, q) => {
                        const reason = q.rejectionReason || "other";
                        acc[reason] = (acc[reason] || 0) + 1;
                        return acc;
                      }, {})
                  ).map(([reason, count]) => ({
                    name:
                      {
                        too_easy: "Too Easy",
                        too_hard: "Too Difficult",
                        incorrect: "Incorrect",
                        unclear: "Unclear",
                        duplicate: "Duplicate",
                        poor_quality: "Poor Quality",
                        bad_source: "Bad Source",
                        other: "Other",
                      }[reason] || reason,
                    value: count,
                  }));
                  const COLORS = [
                    "#ef4444",
                    "#f97316",
                    "#eab308",
                    "#22c55e",
                    "#06b6d4",
                    "#6366f1",
                    "#a855f7",
                    "#ec4899",
                  ];
                  return rejectionData.length > 0 ? (
                    <SafeResponsiveContainer
                      width="100%"
                      height="100%"
                      minWidth={1}
                      minHeight={200}
                    >
                      <RechartsPieChart>
                        <Pie
                          data={rejectionData}
                          cx="50%"
                          cy="50%"
                          labelLine={false}
                          label={({ name, percent }) =>
                            `${name} (${(percent * 100).toFixed(0)}%)`
                          }
                          outerRadius={80}
                          fill="#8884d8"
                          dataKey="value"
                        >
                          {rejectionData.map((_, index) => (
                            <Cell
                              key={`cell-${index}`}
                              fill={COLORS[index % COLORS.length]}
                            />
                          ))}
                        </Pie>
                        <Tooltip
                          contentStyle={{
                            backgroundColor: "#0f172a",
                            borderColor: "#334155",
                          }}
                        />
                      </RechartsPieChart>
                    </SafeResponsiveContainer>
                  ) : (
                    <div className="text-slate-500 text-sm">
                      No rejection data yet
                    </div>
                  );
                })()}
              </div>
            </div>
          </div>

          {/* Training Data Progress */}
          <div className="grid grid-cols-1 gap-6">
            <div className="bg-slate-950/50 border border-slate-800 rounded-xl p-4 h-80 flex flex-col">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-sm font-bold text-slate-400 flex items-center gap-2">
                  <Activity size={16} /> Training Data Readiness
                </h3>
                <div className="text-xs font-mono text-slate-500">
                  Target: 500 Questions
                </div>
              </div>

              <div className="flex-1 flex flex-col justify-center gap-6">
                {/* Progress Bar */}
                <div>
                  <div className="flex justify-between text-xs mb-2">
                    <span className="text-slate-300 font-bold">
                      Total Progress
                    </span>
                    <span className="text-indigo-400 font-bold">
                      {analyticsData.questions.length} / 500
                    </span>
                  </div>
                  <div className="w-full h-4 bg-slate-900 rounded-full overflow-hidden border border-slate-800">
                    <div
                      className="h-full bg-gradient-to-r from-indigo-600 to-purple-600 transition-all duration-1000"
                      style={{
                        width: `${Math.min(
                          (analyticsData.questions.length / 500) * 100,
                          100
                        )}%`,
                      }}
                    ></div>
                  </div>
                </div>

                {/* Breakdown */}
                <div className="grid grid-cols-3 gap-4">
                  <div className="p-3 bg-slate-900 rounded-lg border border-slate-800 text-center">
                    <div className="text-2xl font-bold text-emerald-400">
                      {
                        analyticsData.questions.filter(
                          (q) => q.status === "accepted"
                        ).length
                      }
                    </div>
                    <div className="text-[10px] text-slate-500 uppercase tracking-wider">
                      Positive Examples
                    </div>
                  </div>
                  <div className="p-3 bg-slate-900 rounded-lg border border-slate-800 text-center">
                    <div className="text-2xl font-bold text-red-400">
                      {
                        analyticsData.questions.filter(
                          (q) => q.status === "rejected"
                        ).length
                      }
                    </div>
                    <div className="text-[10px] text-slate-500 uppercase tracking-wider">
                      Negative Examples
                    </div>
                  </div>
                  <div className="p-3 bg-slate-900 rounded-lg border border-slate-800 text-center">
                    <div className="text-2xl font-bold text-blue-400">
                      {
                        analyticsData.questions.filter((q) => q.wasRewritten)
                          .length
                      }
                    </div>
                    <div className="text-[10px] text-slate-500 uppercase tracking-wider">
                      Rewritten (High Value)
                    </div>
                  </div>
                </div>

                <div className="text-xs text-slate-500 text-center italic">
                  "A balanced dataset with both good and bad examples produces
                  the best fine-tuned models."
                </div>
              </div>
            </div>
          </div>
          {/* Topic Coverage Analysis */}
          <div className="bg-slate-950/50 border border-slate-800 rounded-xl p-4 min-w-0">
            <h3 className="text-sm font-bold text-slate-400 mb-4 flex items-center gap-2">
              <TrendingUp size={16} /> Topic Coverage Analysis
            </h3>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {Object.entries(TAGS_BY_DISCIPLINE).map(([discipline, tags]) => {
                // Calculate coverage for this discipline
                const disciplineQuestions = analyticsData.questions.filter(
                  (q) => q.discipline === discipline
                );
                const coverageStats = tags
                  .map((tag) => {
                    // Normalized match
                    const normalize = (t) => t.toLowerCase();
                    const count = disciplineQuestions.filter((q) =>
                      (q.tags || []).some(
                        (qt) => normalize(qt) === normalize(tag)
                      )
                    ).length;
                    return { tag, count };
                  })
                  .sort((a, b) => b.count - a.count); // Most covered first

                return (
                  <div
                    key={discipline}
                    className="bg-slate-900 rounded-lg p-3 border border-slate-800"
                  >
                    <h4 className="text-xs font-bold text-slate-300 uppercase mb-3 border-b border-slate-800 pb-2">
                      {discipline}{" "}
                      <span className="text-slate-500">
                        ({disciplineQuestions.length})
                      </span>
                    </h4>
                    <div className="space-y-2 max-h-40 overflow-y-auto pr-2 custom-scrollbar">
                      {coverageStats.map(({ tag, count }) => {
                        const coveragePercent = Math.min(
                          (count / 5) * 100,
                          100
                        ); // Goal: 5 questions per tag
                        return (
                          <div key={tag} className="flex flex-col gap-1">
                            <div className="flex justify-between text-[10px]">
                              <span
                                className={
                                  count === 0
                                    ? "text-slate-500"
                                    : "text-slate-300"
                                }
                              >
                                {tag}
                              </span>
                              <span
                                className={
                                  count === 0
                                    ? "text-red-400 font-bold"
                                    : "text-emerald-400 font-mono"
                                }
                              >
                                {count}
                              </span>
                            </div>
                            <div className="w-full h-1 bg-slate-800 rounded-full overflow-hidden">
                              <div
                                className={`h-full ${
                                  count === 0
                                    ? "bg-transparent"
                                    : count < 3
                                    ? "bg-orange-500"
                                    : "bg-emerald-500"
                                }`}
                                style={{ width: `${coveragePercent}%` }}
                              />
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AnalyticsDashboard;

import { useState, useMemo, useEffect } from "react";
import Icon from "./Icon";
import { format } from "date-fns";
import { getAnalytics, getTokenStats } from "../utils/analyticsStore";
import { TAGS_BY_DISCIPLINE } from "../utils/tagTaxonomy";

// Import extracted tab components
import OverviewTab from "./analytics/OverviewTab";
import DisciplinesTab from "./analytics/DisciplinesTab";
import QualityTab from "./analytics/QualityTab";

// Define discipline list from tagTaxonomy
const DISCIPLINES = Object.keys(TAGS_BY_DISCIPLINE);

const TIME_RANGES = [
  { id: "24h", label: "24h", days: 1 },
  { id: "7d", label: "7d", days: 7 },
  { id: "15d", label: "15d", days: 15 },
  { id: "30d", label: "30d", days: 30 },
  { id: "90d", label: "90d", days: 90 },
  { id: "all", label: "All", days: null },
];

// Color palettes - using highly distinct, contrasting colors
const DISCIPLINE_COLORS = {
  // Full names
  "Technical Art": "#f97316",
  "Lighting & Rendering": "#eab308",
  "Look Development (Materials)": "#facc15",
  "Animation & Rigging": "#a855f7",
  "VFX (Niagara)": "#22d3ee",
  "World Building & Level Design": "#6366f1",
  Blueprints: "#8b5cf6",
  "Game Logic & Systems": "#ec4899",
  "C++ Programming": "#dc2626",
  Networking: "#8b5cf6",
  // Abbreviated names
  "Tech Art": "#f97316",
  "Look Dev": "#facc15",
  Animation: "#a855f7",
  VFX: "#22d3ee",
  Worldbuilding: "#6366f1",
  "Game Dev": "#ec4899",
  Programming: "#dc2626",
};

/**
 * AnalyticsView - Dedicated full-page analytics dashboard
 * Replaces the modal-based analytics with a standalone view
 */
const AnalyticsView = ({
  onBack,
  onStartTutorial,
  allQuestionsMap = new Map(),
}) => {
  const [activeTab, setActiveTab] = useState("overview");
  const [timeRange, setTimeRange] = useState("all");
  const analytics = getAnalytics();
  const tokenStats = getTokenStats();

  // PERFORMANCE: Stable reference for allQuestions - only update when map size actually changes
  const mapSize = allQuestionsMap?.size || 0;
  const allQuestions = useMemo(() => {
    if (!allQuestionsMap || mapSize === 0) return [];
    return Array.from(allQuestionsMap.values()).flat();
  }, [allQuestionsMap, mapSize]);

  // Auto-start tutorial if not completed (only runs once on mount)
  useEffect(() => {
    const isCompleted = localStorage.getItem(
      "ue5_tutorial_analytics_completed"
    );
    if (!isCompleted && onStartTutorial) {
      // Small delay to ensure view is rendered
      setTimeout(() => onStartTutorial("analytics"), 500);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []); // Empty deps - run only once on mount

  const tabs = [
    {
      id: "overview",
      label: "Overview",
      icon: "layout-dashboard",
      dataTour: "overview-tab",
    },
    {
      id: "disciplines",
      label: "Disciplines",
      icon: "layers",
      dataTour: "disciplines-tab",
    },
    {
      id: "quality",
      label: "Quality",
      icon: "target",
      dataTour: "quality-tab",
    },
  ];

  const {
    disciplineData,
    difficultyData,
    statusData,
    qualityDistribution,
    recentGenerations,
    filteredSummary,
    filteredQuestions,
  } = useMemo(() => {
    let questions = allQuestions;
    let generations = analytics.generations || [];

    // Filter by Time Range
    if (timeRange !== "all") {
      const range = TIME_RANGES.find((r) => r.id === timeRange);
      if (range && range.days) {
        const cutoff = new Date();
        cutoff.setDate(cutoff.getDate() - range.days);
        questions = questions.filter(
          (q) => new Date(q.created || q.timestamp || q.dateAdded) >= cutoff
        );
        generations = generations.filter(
          (g) => new Date(g.timestamp) >= cutoff
        );
      }
    }

    // Calculate summary for the filtered view
    const filteredSummary = {
      totalQuestions: questions.length,
      totalGenerations: generations.length,
      acceptanceRate: 0,
      averageQuality: 0,
      estimatedCost: generations.reduce(
        (sum, g) => sum + (g.estimatedCost || 0),
        0
      ),
    };

    // Recalculate Acceptance Rate
    const decidedQuestions = questions.filter(
      (q) => q.status === "accepted" || q.status === "rejected"
    );
    if (decidedQuestions.length > 0) {
      const accepted = decidedQuestions.filter(
        (q) => q.status === "accepted"
      ).length;
      filteredSummary.acceptanceRate = Math.round(
        (accepted / decidedQuestions.length) * 100
      );
    }

    // Recalculate Average Quality
    const questionsWithQuality = questions.filter(
      (q) => q.qualityScore != null
    );
    if (questionsWithQuality.length > 0) {
      const totalQuality = questionsWithQuality.reduce(
        (sum, q) => sum + q.qualityScore,
        0
      );
      filteredSummary.averageQuality = Math.round(
        totalQuality / questionsWithQuality.length
      );
    }

    // Discipline breakdown
    const disciplineCounts = DISCIPLINES.reduce((acc, disc) => {
      acc[disc] = questions.filter((q) => q.discipline === disc).length;
      return acc;
    }, {});

    const disciplineData = Object.entries(disciplineCounts)
      .map(([name, value]) => ({
        name: name.replace(" & ", "\n"),
        fullName: name,
        value,
        fill: DISCIPLINE_COLORS[name] || "#64748b",
      }))
      .filter((d) => d.value > 0)
      .sort((a, b) => b.value - a.value);

    // Difficulty breakdown - normalize all difficulty values to base type
    const getDifficultyBase = (difficulty) => {
      if (!difficulty) return null;
      const d = difficulty.toString().toLowerCase().trim();
      if (d.includes("easy") || d.includes("beginner")) return "Beginner";
      if (d.includes("medium") || d.includes("intermediate"))
        return "Intermediate";
      if (d.includes("hard") || d.includes("expert") || d.includes("advanced"))
        return "Expert";
      return null;
    };

    // Count questions by normalized difficulty
    const difficultyCounts = questions.reduce((acc, q) => {
      const base = getDifficultyBase(q.difficulty);
      if (base) {
        acc[base] = (acc[base] || 0) + 1;
      }
      return acc;
    }, {});

    const difficultyData = [
      {
        name: "Beginner",
        value: difficultyCounts["Beginner"] || 0,
        fill: "#22c55e",
      },
      {
        name: "Intermediate",
        value: difficultyCounts["Intermediate"] || 0,
        fill: "#eab308",
      },
      {
        name: "Expert",
        value: difficultyCounts["Expert"] || 0,
        fill: "#ef4444",
      },
    ].filter((d) => d.value > 0);

    // Status breakdown
    const statusCounts = {
      accepted: questions.filter((q) => q.status === "accepted").length,
      pending: questions.filter((q) => !q.status || q.status === "pending")
        .length,
      rejected: questions.filter((q) => q.status === "rejected").length,
    };

    const statusData = [
      { name: "Accepted", value: statusCounts.accepted, fill: "#22c55e" },
      { name: "Pending", value: statusCounts.pending, fill: "#f59e0b" },
      { name: "Rejected", value: statusCounts.rejected, fill: "#ef4444" },
    ].filter((d) => d.value > 0);

    // Quality distribution (for questions with scores)
    const qualityBuckets = [
      { range: "90-100", min: 90, max: 100, fill: "#22c55e" },
      { range: "70-89", min: 70, max: 89, fill: "#84cc16" },
      { range: "50-69", min: 50, max: 69, fill: "#eab308" },
      { range: "30-49", min: 30, max: 49, fill: "#f97316" },
      { range: "0-29", min: 0, max: 29, fill: "#ef4444" },
    ];

    const qualityDistribution = qualityBuckets
      .map((bucket) => ({
        ...bucket,
        count: questions.filter(
          (q) => q.critiqueScore >= bucket.min && q.critiqueScore <= bucket.max
        ).length,
      }))
      .filter((b) => b.count > 0);

    // Recent generations for trend
    const recentGenerations = generations.slice(-10).map((gen, idx) => ({
      name: `Gen ${idx + 1}`,
      tokens: (gen.tokensUsed?.input || 0) + (gen.tokensUsed?.output || 0),
      questions: gen.questionsGenerated || 0,
      quality: gen.averageQuality || 0,
    }));

    return {
      disciplineData,
      difficultyData,
      statusData,
      qualityDistribution,
      recentGenerations,
      filteredSummary,
      filteredQuestions: questions, // Time-filtered questions for consistent counting
    };
  }, [analytics, timeRange, allQuestions]);

  const summary = filteredSummary || analytics.summary || {};

  return (
    <div className="min-h-screen bg-slate-950 text-white">
      {/* Header */}
      <div className="bg-slate-900 border-b border-slate-800 px-6 py-4">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-4 w-full md:w-auto">
            <button
              onClick={onBack}
              className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg transition-colors"
            >
              <Icon name="arrow-left" size={16} />
              Back
            </button>
            <div className="w-px h-6 bg-slate-700 hidden md:block" />
            <div className="flex items-center gap-3">
              <div className="p-2 bg-emerald-900/30 rounded-lg">
                <Icon
                  name="bar-chart-2"
                  size={24}
                  className="text-emerald-400"
                />
              </div>
              <div>
                <h1 className="text-xl font-bold">Analytics Dashboard</h1>
                <p className="text-xs text-slate-400 hidden sm:block">
                  Generation metrics ΓÇó Quality trends ΓÇó Discipline breakdown
                </p>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-4 w-full md:w-auto justify-between md:justify-end">
            {/* Time Range Selector */}
            <div className="flex bg-slate-800 rounded-lg p-1 border border-slate-700 overflow-x-auto">
              {TIME_RANGES.map((range) => (
                <button
                  key={range.id}
                  onClick={() => setTimeRange(range.id)}
                  className={`px-3 py-1.5 text-xs font-medium rounded-md whitespace-nowrap transition-colors ${
                    timeRange === range.id
                      ? "bg-emerald-600 text-white shadow-sm"
                      : "text-slate-400 hover:text-white hover:bg-slate-700"
                  }`}
                >
                  {range.label}
                </button>
              ))}
            </div>

            {/* Date Range Display */}
            {timeRange !== "all" && (
              <div className="text-xs text-slate-500">
                {(() => {
                  const range = TIME_RANGES.find((r) => r.id === timeRange);
                  if (range && range.days) {
                    const endDate = new Date();
                    const startDate = new Date();
                    startDate.setDate(startDate.getDate() - range.days);
                    return `${format(startDate, "MMM d")} - ${format(
                      endDate,
                      "MMM d, yyyy"
                    )}`;
                  }
                  return "";
                })()}
              </div>
            )}

            {/* Tab Navigation */}
            <div className="flex items-center gap-1 bg-slate-800/50 rounded-lg p-1">
              {tabs.map((tab) => (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`flex items-center gap-2 px-3 py-2 text-sm font-medium rounded-md transition-all ${
                    activeTab === tab.id
                      ? "bg-emerald-600 text-white shadow-lg"
                      : "text-slate-400 hover:text-white hover:bg-slate-700"
                  }`}
                  title={tab.label}
                >
                  <Icon name={tab.icon} size={14} />
                  <span className="hidden sm:inline">{tab.label}</span>
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="max-w-7xl mx-auto p-6">
        {activeTab === "overview" && (
          <OverviewTab
            summary={summary}
            statusData={statusData}
            difficultyData={difficultyData}
            recentGenerations={recentGenerations}
          />
        )}

        {activeTab === "disciplines" && (
          <DisciplinesTab
            disciplineData={disciplineData}
            allQuestions={filteredQuestions}
            disciplines={DISCIPLINES}
          />
        )}

        {activeTab === "quality" && (
          <QualityTab
            qualityDistribution={qualityDistribution}
            tokenStats={tokenStats}
            summary={summary}
          />
        )}
      </div>
    </div>
  );
};

export default AnalyticsView;

import Icon from './Icon';

const BlockingProcessModal = ({ isProcessing, status, translationProgress }) => {
    if (!isProcessing) return null;

    return (
        <div className="fixed inset-0 bg-black/70 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
            <div className="bg-slate-900 border border-orange-600 p-8 rounded-xl shadow-2xl max-w-sm w-full animate-in zoom-in-95 duration-300 space-y-4 text-center">
                <Icon name="loader" size={32} className="text-orange-500 mx-auto animate-spin mb-4" />
                <h3 className="text-xl font-bold text-white">Working on Data...</h3>
                <p className="text-sm text-slate-300">{status}</p>
                {translationProgress > 0 && translationProgress < 100 && (
                    <div className="relative h-2 w-full bg-indigo-900 rounded-lg overflow-hidden mt-4">
                        <div className="h-full bg-indigo-500 transition-all duration-300" style={{ width: `${translationProgress}%` }}></div>
                    </div>
                )}
                {translationProgress > 0 && <span className="text-xs text-indigo-400 font-bold">{translationProgress}% Complete</span>}
            </div>
        </div>
    );
};

export default BlockingProcessModal;

import React from "react";
import Icon from "./Icon";

import { LANGUAGE_FLAGS } from "../utils/constants";

// Helper to get icon name for export format (avoids nested ternary)
const getFormatIcon = (fmt) => {
  if (fmt === "sheets") return "table";
  if (fmt === "json") return "code";
  if (fmt === "markdown") return "file-code";
  return "file-text";
};

const BulkExportModal = ({ onClose, onExport, questionCount }) => {
  const [exportOptions, setExportOptions] = React.useState({
    format: "sheets",
    includeRejected: false,
    languages: ["English"],
    disciplines: "all",
    scope: "all",
    segmentFiles: false,
    limit: null,
  });

  const availableLanguages = Object.keys(LANGUAGE_FLAGS);

  const handleLanguageToggle = (lang) => {
    setExportOptions((prev) => ({
      ...prev,
      languages: prev.languages.includes(lang)
        ? prev.languages.filter((l) => l !== lang)
        : [...prev.languages, lang],
    }));
  };

  const handleExport = () => {
    onExport(exportOptions);
    onClose();
  };

  return (
    <>
      {/* Backdrop */}
      <div
        className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4"
        onClick={onClose}
      >
        <div
          className="bg-slate-900 border border-slate-700 rounded-lg shadow-2xl max-w-2xl w-full p-6 space-y-6"
          onClick={(e) => e.stopPropagation()}
        >
          {/* Header */}
          <div className="flex items-center justify-between border-b border-slate-800 pb-4">
            <div className="flex items-center gap-3">
              <div className="bg-green-600 p-2 rounded-lg">
                <Icon name="download" size={20} className="text-white" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-white">Bulk Export</h2>
                <p className="text-xs text-slate-400">
                  Export {questionCount} questions with custom options
                </p>
              </div>
            </div>
            <button
              onClick={onClose}
              className="text-slate-400 hover:text-white transition-colors"
            >
              <Icon name="x" size={24} />
            </button>
          </div>

          {/* Export Options */}
          <div className="space-y-6">
            {/* Scope Selection */}
            <div className="space-y-3">
              <label className="text-xs font-bold uppercase text-slate-400 tracking-wider">
                1. Select Scope
              </label>
              <div className="flex flex-col gap-2">
                <label className="flex items-center gap-3 p-3 rounded border border-slate-700 bg-slate-800/50 hover:bg-slate-800 cursor-pointer transition-colors">
                  <div
                    className={`w-5 h-5 rounded border flex items-center justify-center transition-colors ${
                      exportOptions.scope === "all"
                        ? "bg-green-600 border-green-500"
                        : "border-slate-600 bg-slate-900"
                    }`}
                  >
                    {exportOptions.scope === "all" && (
                      <Icon name="check" size={14} className="text-white" />
                    )}
                  </div>
                  <input
                    type="radio"
                    name="scope"
                    className="hidden"
                    checked={exportOptions.scope === "all"}
                    onChange={() =>
                      setExportOptions((prev) => ({ ...prev, scope: "all" }))
                    }
                  />
                  <div>
                    <span className="text-sm font-bold text-slate-200">
                      All Questions
                    </span>
                    <p className="text-xs text-slate-500">
                      Export everything in the database ({questionCount}{" "}
                      questions)
                    </p>
                  </div>
                </label>
                <label className="flex items-center gap-3 p-3 rounded border border-slate-700 bg-slate-800/50 hover:bg-slate-800 cursor-pointer transition-colors">
                  <div
                    className={`w-5 h-5 rounded border flex items-center justify-center transition-colors ${
                      exportOptions.scope === "filtered"
                        ? "bg-green-600 border-green-500"
                        : "border-slate-600 bg-slate-900"
                    }`}
                  >
                    {exportOptions.scope === "filtered" && (
                      <Icon name="check" size={14} className="text-white" />
                    )}
                  </div>
                  <input
                    type="radio"
                    name="scope"
                    className="hidden"
                    checked={exportOptions.scope === "filtered"}
                    onChange={() =>
                      setExportOptions((prev) => ({
                        ...prev,
                        scope: "filtered",
                      }))
                    }
                  />
                  <div>
                    <span className="text-sm font-bold text-slate-200">
                      Current Filtered View
                    </span>
                    <p className="text-xs text-slate-500">
                      Export only questions currently visible in the list
                    </p>
                  </div>
                </label>
              </div>
            </div>

            {/* Format Selection */}
            <div className="space-y-3">
              <label className="text-xs font-bold uppercase text-slate-400 tracking-wider">
                2. Select Format
              </label>
              <div className="grid grid-cols-2 gap-2">
                {["sheets", "csv", "json", "markdown"].map((fmt) => (
                  <label
                    key={fmt}
                    className={`flex items-center gap-3 p-3 rounded border cursor-pointer transition-all ${
                      exportOptions.format === fmt
                        ? "bg-indigo-900/30 border-indigo-500"
                        : "bg-slate-800/50 border-slate-700 hover:bg-slate-800"
                    }`}
                  >
                    <div
                      className={`w-5 h-5 rounded-full border flex items-center justify-center transition-colors ${
                        exportOptions.format === fmt
                          ? "bg-indigo-500 border-indigo-400"
                          : "border-slate-600 bg-slate-900"
                      }`}
                    >
                      {exportOptions.format === fmt && (
                        <div className="w-2 h-2 bg-white rounded-full" />
                      )}
                    </div>
                    <input
                      type="radio"
                      name="format"
                      className="hidden"
                      checked={exportOptions.format === fmt}
                      onChange={() =>
                        setExportOptions((prev) => ({ ...prev, format: fmt }))
                      }
                    />
                    <span className="text-sm font-bold text-slate-200 uppercase flex items-center gap-2">
                      <Icon name={getFormatIcon(fmt)} size={14} />
                      {fmt === "sheets" ? "Google Sheets" : fmt}
                    </span>
                  </label>
                ))}
              </div>
              {exportOptions.format === "sheets" && (
                <p className="text-xs text-amber-400 flex items-center gap-1 mt-2">
                  <Icon name="alert-circle" size={12} />
                  <span>
                    Tip: If columns look wrong, delete the top header row in
                    your Sheet and try again.
                  </span>
                </p>
              )}
            </div>

            {/* Additional Options */}
            <div className="space-y-3">
              <label className="text-xs font-bold uppercase text-slate-400 tracking-wider">
                3. Options
              </label>
              <div className="flex flex-col gap-2">
                <label className="flex items-center gap-3 p-2 rounded hover:bg-slate-800/50 cursor-pointer">
                  <div
                    className={`w-5 h-5 rounded border flex items-center justify-center transition-colors ${
                      exportOptions.includeRejected
                        ? "bg-green-600 border-green-500"
                        : "border-slate-600 bg-slate-900"
                    }`}
                  >
                    {exportOptions.includeRejected && (
                      <Icon name="check" size={14} className="text-white" />
                    )}
                  </div>
                  <input
                    type="checkbox"
                    className="hidden"
                    checked={exportOptions.includeRejected}
                    onChange={() =>
                      setExportOptions((prev) => ({
                        ...prev,
                        includeRejected: !prev.includeRejected,
                      }))
                    }
                  />
                  <span className="text-sm text-slate-300">
                    Include Rejected Questions
                  </span>
                </label>

                {exportOptions.format === "csv" && (
                  <label className="flex items-center gap-3 p-2 rounded hover:bg-slate-800/50 cursor-pointer">
                    <div
                      className={`w-5 h-5 rounded border flex items-center justify-center transition-colors ${
                        exportOptions.segmentFiles
                          ? "bg-green-600 border-green-500"
                          : "border-slate-600 bg-slate-900"
                      }`}
                    >
                      {exportOptions.segmentFiles && (
                        <Icon name="check" size={14} className="text-white" />
                      )}
                    </div>
                    <input
                      type="checkbox"
                      className="hidden"
                      checked={exportOptions.segmentFiles}
                      onChange={() =>
                        setExportOptions((prev) => ({
                          ...prev,
                          segmentFiles: !prev.segmentFiles,
                        }))
                      }
                    />
                    <span className="text-sm text-slate-300">
                      Segment Files (Separate by Language/Discipline)
                    </span>
                  </label>
                )}

                <div className="flex items-center gap-3 p-2">
                  <div className="w-5 flex justify-center">
                    <Icon name="hash" size={14} className="text-slate-500" />
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="text-sm text-slate-300">Limit to:</span>
                    <input
                      type="number"
                      min="1"
                      max={questionCount}
                      placeholder="All"
                      className="w-20 bg-slate-900 border border-slate-700 rounded px-2 py-1 text-xs text-white focus:border-indigo-500 outline-none"
                      value={exportOptions.limit || ""}
                      onChange={(e) =>
                        setExportOptions((prev) => ({
                          ...prev,
                          limit: e.target.value
                            ? parseInt(e.target.value)
                            : null,
                        }))
                      }
                    />
                    <span className="text-xs text-slate-500">questions</span>
                  </div>
                </div>
              </div>
            </div>

            {/* Language Selection */}
            <div className="space-y-3">
              <label className="text-xs font-bold uppercase text-slate-400 tracking-wider">
                4. Languages
              </label>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                {availableLanguages.map((lang) => (
                  <label
                    key={lang}
                    className={`flex items-center gap-2 p-2 rounded border cursor-pointer transition-all ${
                      exportOptions.languages.includes(lang)
                        ? "bg-slate-800 border-slate-600"
                        : "bg-slate-900/50 border-slate-800 opacity-60 hover:opacity-100"
                    }`}
                  >
                    <div
                      className={`w-4 h-4 rounded border flex items-center justify-center transition-colors ${
                        exportOptions.languages.includes(lang)
                          ? "bg-indigo-600 border-indigo-500"
                          : "border-slate-600 bg-slate-900"
                      }`}
                    >
                      {exportOptions.languages.includes(lang) && (
                        <Icon name="check" size={10} className="text-white" />
                      )}
                    </div>
                    <input
                      type="checkbox"
                      className="hidden"
                      checked={exportOptions.languages.includes(lang)}
                      onChange={() => handleLanguageToggle(lang)}
                    />
                    <span className="text-xs font-medium text-slate-300">
                      {LANGUAGE_FLAGS[lang]} {lang}
                    </span>
                  </label>
                ))}
              </div>
            </div>
          </div>

          {/* Action Buttons */}
          <div className="flex gap-3 pt-4 border-t border-slate-800">
            <button
              onClick={onClose}
              className="flex-1 py-3 px-4 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-lg font-medium transition-colors"
            >
              Cancel
            </button>
            <button
              onClick={handleExport}
              disabled={exportOptions.languages.length === 0}
              className={`flex-1 py-3 px-4 rounded-lg font-bold flex items-center justify-center gap-2 transition-all ${
                exportOptions.languages.length === 0
                  ? "bg-slate-700 text-slate-500 cursor-not-allowed"
                  : "bg-green-600 hover:bg-green-700 text-white"
              }`}
            >
              <Icon name="download" size={16} />
              Export {exportOptions.format.toUpperCase()}
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

export default BulkExportModal;

/**
 * ConflictModal Component
 *
 * Displays version conflict resolution UI when two users edit the same question.
 *
 * Resolution Options:
 * 1. Discard Local Changes (reload server version) - SAFE
 * 2. Overwrite Server Changes (force local version) - DANGEROUS
 * 3. Manual Merge (review field-by-field) - ADVANCED
 */

import React, { useState } from "react";
import Icon from "./Icon";
import CollapsibleSection from "./CollapsibleSection";

const ConflictModal = ({ isOpen, onClose, conflictData, onResolve }) => {
  const [selectedOption, setSelectedOption] = useState(null);
  const [showDiff, setShowDiff] = useState(false);

  /**
   * Returns styles for the resolution button based on selected option
   */
  const getResolveButtonStyles = () => {
    if (selectedOption === "DISCARD") {
      return "bg-green-600 hover:bg-green-500 text-white";
    }
    if (selectedOption === "OVERWRITE") {
      return "bg-red-600 hover:bg-red-500 text-white";
    }
    return "bg-slate-700 text-slate-400 cursor-not-allowed";
  };

  /**
   * Returns text for the resolution button based on selected option
   */
  const getResolveButtonText = () => {
    if (selectedOption === "DISCARD") {
      return "Reload Latest Version";
    }
    if (selectedOption === "OVERWRITE") {
      return "Force Overwrite";
    }
    return "Select an Option";
  };

  if (!isOpen || !conflictData) return null;

  const { serverQuestion, serverVersion, localChanges, expectedVersion } =
    conflictData;

  const handleResolve = (action) => {
    if (onResolve) {
      onResolve(action);
    }
    onClose();
  };

  // Generate a simple diff view
  const renderDiff = () => {
    if (!serverQuestion || !localChanges) return null;

    const changedFields = Object.keys(localChanges).filter((key) => {
      return (
        JSON.stringify(localChanges[key]) !==
        JSON.stringify(serverQuestion[key])
      );
    });

    if (changedFields.length === 0) {
      return (
        <p className="text-slate-400 text-sm italic">No changes detected</p>
      );
    }

    return (
      <div className="space-y-4">
        {changedFields.map((field) => (
          <div
            key={field}
            className="border border-slate-700 rounded-lg p-4 bg-slate-900/50"
          >
            <h4 className="text-sm font-bold text-cyan-400 mb-2 uppercase tracking-wide">
              {field}
            </h4>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <p className="text-xs text-red-400 font-semibold mb-1">
                  SERVER (v{serverVersion})
                </p>
                <pre className="text-xs text-slate-300 bg-red-900/20 p-2 rounded border border-red-800/50 overflow-auto max-h-32">
                  {JSON.stringify(serverQuestion[field], null, 2)}
                </pre>
              </div>
              <div>
                <p className="text-xs text-yellow-400 font-semibold mb-1">
                  YOUR CHANGES (v{expectedVersion})
                </p>
                <pre className="text-xs text-slate-300 bg-yellow-900/20 p-2 rounded border border-yellow-800/50 overflow-auto max-h-32">
                  {JSON.stringify(localChanges[field], null, 2)}
                </pre>
              </div>
            </div>
          </div>
        ))}
      </div>
    );
  };

  return (
    <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-50 p-4">
      <div className="bg-slate-900 rounded-xl border-2 border-red-500/50 shadow-2xl max-w-3xl w-full max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="bg-gradient-to-r from-red-900/30 to-orange-900/30 p-6 border-b border-red-500/30">
          <div className="flex items-start justify-between">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-full bg-red-500/20 flex items-center justify-center">
                <Icon
                  name="alert-triangle"
                  size={24}
                  className="text-red-400"
                />
              </div>
              <div>
                <h2 className="text-2xl font-bold text-red-400">
                  Version Conflict Detected
                </h2>
                <p className="text-sm text-slate-400 mt-1">
                  Another user saved changes while you were editing
                </p>
              </div>
            </div>
            <button
              onClick={onClose}
              className="text-slate-400 hover:text-white transition-colors"
            >
              <Icon name="x" size={24} />
            </button>
          </div>
        </div>

        {/* Content */}
        <div className="p-6 space-y-6">
          {/* Conflict Info */}
          <div className="bg-slate-800/50 rounded-lg p-4 border border-slate-700">
            <div className="flex items-center gap-2 text-sm">
              <Icon name="info" size={16} className="text-cyan-400" />
              <span className="text-slate-300">
                You were editing version{" "}
                <span className="font-bold text-white">{expectedVersion}</span>,
                but the server is now at version{" "}
                <span className="font-bold text-white">{serverVersion}</span>.
              </span>
            </div>
          </div>

          {/* Resolution Options */}
          <div className="space-y-4">
            <h3 className="text-lg font-semibold text-white">
              Choose how to resolve:
            </h3>

            {/* Option 1: Discard (Recommended) */}
            <div
              className={`border-2 rounded-lg p-4 cursor-pointer transition-all ${
                selectedOption === "DISCARD"
                  ? "border-green-500 bg-green-900/20"
                  : "border-slate-700 bg-slate-800/30 hover:border-green-500/50"
              }`}
              onClick={() => setSelectedOption("DISCARD")}
            >
              <div className="flex items-start gap-3">
                <div
                  className={`w-5 h-5 rounded-full border-2 mt-1 flex items-center justify-center ${
                    selectedOption === "DISCARD"
                      ? "border-green-500 bg-green-500"
                      : "border-slate-600"
                  }`}
                >
                  {selectedOption === "DISCARD" && (
                    <Icon name="check" size={12} className="text-white" />
                  )}
                </div>
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <h4 className="font-bold text-green-400">
                      Reload and Discard My Changes
                    </h4>
                    <span className="text-xs bg-green-500/20 text-green-400 px-2 py-0.5 rounded-full border border-green-500/30">
                      RECOMMENDED
                    </span>
                  </div>
                  <p className="text-sm text-slate-400 mt-1">
                    Safely reload the latest server version. Your changes will
                    be lost, but you can re-edit the updated question.
                  </p>
                </div>
              </div>
            </div>

            {/* Option 2: Overwrite (Dangerous) */}
            <div
              className={`border-2 rounded-lg p-4 cursor-pointer transition-all ${
                selectedOption === "OVERWRITE"
                  ? "border-red-500 bg-red-900/20"
                  : "border-slate-700 bg-slate-800/30 hover:border-red-500/50"
              }`}
              onClick={() => setSelectedOption("OVERWRITE")}
            >
              <div className="flex items-start gap-3">
                <div
                  className={`w-5 h-5 rounded-full border-2 mt-1 flex items-center justify-center ${
                    selectedOption === "OVERWRITE"
                      ? "border-red-500 bg-red-500"
                      : "border-slate-600"
                  }`}
                >
                  {selectedOption === "OVERWRITE" && (
                    <Icon name="check" size={12} className="text-white" />
                  )}
                </div>
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <h4 className="font-bold text-red-400">
                      Overwrite Server Changes
                    </h4>
                    <span className="text-xs bg-red-500/20 text-red-400 px-2 py-0.5 rounded-full border border-red-500/30">
                      DANGEROUS
                    </span>
                  </div>
                  <p className="text-sm text-slate-400 mt-1">
                    Force save your changes.{" "}
                    <span className="text-red-400 font-semibold">
                      This will delete the other user's changes permanently.
                    </span>
                  </p>
                </div>
              </div>
            </div>

            <CollapsibleSection
              title={`${showDiff ? "Hide" : "View"} Detailed Changes`}
              icon="eye"
              isCollapsed={!showDiff}
              onToggle={() => setShowDiff(!showDiff)}
              variant="slate"
              className="!border-2 !border-slate-700 hover:!border-cyan-500/50 !p-1"
            >
              <div className="p-3 border border-slate-700 rounded-lg bg-slate-900/50">
                {renderDiff()}
              </div>
            </CollapsibleSection>
          </div>

          {/* Action Buttons */}
          <div className="flex gap-3 pt-4 border-t border-slate-700">
            <button
              onClick={onClose}
              className="flex-1 px-4 py-3 bg-slate-700 hover:bg-slate-600 text-white rounded-lg font-semibold transition-colors"
            >
              Cancel
            </button>
            <button
              onClick={() => handleResolve(selectedOption)}
              disabled={!selectedOption}
              className={`flex-1 px-4 py-3 rounded-lg font-semibold transition-all ${getResolveButtonStyles()}`}
            >
              {getResolveButtonText()}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ConflictModal;

import { useState, useRef, useEffect } from "react";
import Icon from "./Icon";
import FilterButton from "./FilterButton";
import { getMergedTags } from "../utils/tagTaxonomy";

const ContextToolbar = ({
  mode,
  counts = {},
  filterMode,
  setFilterMode,
  filterByCreator,
  setFilterByCreator,
  searchTerm,
  setSearchTerm,
  sortBy,
  setSortBy,
  isProcessing,
  status,
  isAuthReady,
  config,
  onLoadSheets,
  onLoadFirestore,
  onBulkExport,
  _onClearPending,
  _onBulkAcceptHighScores,
  _onBulkCritiqueAll,
  filterTags = [],
  setFilterTags,
  filterScoreTier: _filterScoreTier = "",
  setFilterScoreTier: _setFilterScoreTier,
  customTags = {},
  isAdmin = false, // Admin-only features
  handleChange, // Added prop for config updates
}) => {
  const [dataMenuOpen, setDataMenuOpen] = useState(false);
  const dataMenuRef = useRef(null);
  const [tagMenuOpen, setTagMenuOpen] = useState(false);
  const tagMenuRef = useRef(null);

  // Click outside handler for Data menu
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dataMenuRef.current && !dataMenuRef.current.contains(event.target)) {
        setDataMenuOpen(false);
      }
      if (tagMenuRef.current && !tagMenuRef.current.contains(event.target)) {
        setTagMenuOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // ------------------------------------------------------------------------
  // RENDERERS FOR EACH MODE
  // ------------------------------------------------------------------------

  const renderCreateToolbar = () => (
    <div className="flex justify-between items-center w-full">
      <div className="flex items-center gap-4">
        {/* Status Indicator */}
        {isAuthReady ? (
          <>
            {status ? (
              <span className="text-xs text-orange-500 font-medium flex items-center gap-1 animate-pulse">
                <Icon name="loader" size={12} className="animate-spin" />{" "}
                {status}
              </span>
            ) : (
              <span className="text-xs font-bold text-slate-500 uppercase flex items-center gap-2">
                <Icon
                  name="check-circle"
                  size={14}
                  className="text-green-500"
                />{" "}
                Ready to Generate
              </span>
            )}
          </>
        ) : (
          <span className="text-xs text-yellow-500 font-medium flex items-center gap-1 animate-pulse">
            <Icon name="plug" size={12} className="animate-pulse" /> Connecting
            to DB...
          </span>
        )}
      </div>

      <div className="flex items-center gap-2">
        {/* Data Menu */}
        <div className="relative" ref={dataMenuRef}>
          <button
            onClick={() => setDataMenuOpen(!dataMenuOpen)}
            disabled={isProcessing}
            className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all flex items-center gap-2 ${
              dataMenuOpen
                ? "bg-slate-700 text-white"
                : "bg-slate-800 text-slate-400 hover:bg-slate-700 hover:text-white"
            } disabled:opacity-50 border border-slate-700`}
            data-tour="export-menu"
          >
            <Icon name="folder" size={14} />
            Data Operations
            <Icon
              name="chevron-down"
              size={10}
              className={`transition-transform ${
                dataMenuOpen ? "rotate-180" : ""
              }`}
            />
          </button>

          {dataMenuOpen && (
            <div className="absolute right-0 top-full mt-1 w-56 bg-slate-800 border border-slate-700 rounded-lg shadow-xl z-50 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
              <div className="py-1">
                <button
                  onClick={() => {
                    onLoadSheets();
                    setDataMenuOpen(false);
                  }}
                  disabled={isProcessing || !config.sheetUrl}
                  className="w-full text-left px-4 py-2 text-xs text-blue-300 hover:bg-slate-700 flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <Icon name="table" size={14} />
                  Load from Sheets
                </button>
                <button
                  onClick={() => {
                    onLoadFirestore();
                    setDataMenuOpen(false);
                  }}
                  disabled={isProcessing}
                  className="w-full text-left px-4 py-2 text-xs text-indigo-300 hover:bg-slate-700 flex items-center gap-2 disabled:opacity-50"
                >
                  <Icon name="cloud-lightning" size={14} />
                  Load from Firestore
                </button>
                <div className="h-px bg-slate-700 my-1"></div>
                {isAdmin && (
                  <button
                    onClick={() => {
                      onBulkExport();
                      setDataMenuOpen(false);
                    }}
                    className="w-full text-left px-4 py-2 text-xs text-green-300 hover:bg-slate-700 flex items-center gap-2"
                  >
                    <Icon name="download" size={14} />
                    Export Questions
                  </button>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );

