 *
 * NOTE: Regex patterns are for parsing markdown/list formats.
 * Input is AI-generated critique text - controlled, no DoS risk.
 */
/* eslint-disable sonarjs/slow-regex */
import Icon from "./Icon";
import DiffText from "./DiffText";
import DOMPurify from "dompurify";
import { QUALITY_PASS_THRESHOLD } from "../utils/constants";
import { useThemeColors } from "../hooks/useThemeColors";

// Simple markdown to HTML converter with XSS protection
const parseMarkdown = (text) => {
  if (!text) return "";

  // Convert **bold** to <strong>
  let html = text.replace(
    /\*\*(.+?)\*\*/g,
    '<strong class="font-semibold text-white">$1</strong>'
  );

  // Convert *italic* to <em> (must be done after bold to avoid conflicts)
  html = html.replace(
    /\*([^*]+)\*/g,
    '<em class="italic text-slate-200">$1</em>'
  );

  // Convert `code` to <code>
  html = html.replace(
    /`([^`]+)`/g,
    '<code class="bg-slate-800 px-1 rounded text-orange-300">$1</code>'
  );

  // SECURITY: Sanitize output to prevent XSS from AI-generated content
  return DOMPurify.sanitize(html, {
    ALLOWED_TAGS: ["strong", "em", "code"],
    ALLOWED_ATTR: ["class"],
  });
};

// DiffText imported from shared component

const CritiqueDisplay = ({
  critique,
  onRewrite,
  isProcessing,
  suggestedRewrite,
  rewriteChanges,
  onApplyRewrite,
  onApplyAndAccept: _onApplyAndAccept,
  originalQuestion,
  onExplain,
  onVariate,
}) => {
  if (!critique) return null;

  // Helper function to get button text (eliminates nested ternary)
  const getApplyButtonText = (isLoading, qualityScore, threshold) => {
    if (isLoading) return "Applying...";
    if (qualityScore >= threshold) return "NO FIX NEEDED";
    return "APPLY FIX";
  };

  // Handle both old (string) and new (object with score) formats
  const isNewFormat =
    typeof critique === "object" && critique.score !== undefined;
  const score = isNewFormat ? critique.score : null;
  const text = (isNewFormat ? critique.text : critique) || "";

  // Get colorblind-safe colors from centralized theme
  const { scoreColorByValue } = useThemeColors();

  // Process text into structured sections
  const renderContent = () => {
    const lines = text.split("\n").filter((line) => line.trim());
    const elements = [];
    let currentList = [];
    let listType = null; // 'bullet' or 'number'

    const flushList = () => {
      if (currentList.length > 0) {
        const ListTag = listType === "number" ? "ol" : "ul";
        const listClassName =
          listType === "number"
            ? "list-decimal list-inside space-y-0.5 ml-2"
            : "list-disc list-inside space-y-0.5 ml-2";

        elements.push(
          <ListTag key={`list-${elements.length}`} className={listClassName}>
            {currentList.map((item, i) => (
              <li
                key={i}
                dangerouslySetInnerHTML={{ __html: parseMarkdown(item) }}
              />
            ))}
          </ListTag>
        );
        currentList = [];
        listType = null;
      }
    };

    lines.forEach((line, index) => {
      const trimmed = line.trim();

      // Check for bullet points (* item or - item)
      const bulletMatch = trimmed.match(/^[*-]\s+(.+)$/);
      if (bulletMatch) {
        if (listType !== "bullet") flushList();
        listType = "bullet";
        currentList.push(bulletMatch[1]);
        return;
      }

      // Check for numbered lists (1. item)
      const numberMatch = trimmed.match(/^\d+\.\s+(.+)$/);
      if (numberMatch) {
        if (listType !== "number") flushList();
        listType = "number";
        currentList.push(numberMatch[1]);
        return;
      }

      // Regular paragraph - flush any pending list first
      flushList();

      // Check if it's a heading (ends with :)
      if (trimmed.endsWith(":") && trimmed.length < 50) {
        elements.push(
          <p
            key={index}
            className="font-semibold text-white mt-2 first:mt-0"
            dangerouslySetInnerHTML={{ __html: parseMarkdown(trimmed) }}
          />
        );
      } else {
        elements.push(
          <p
            key={index}
            className="text-current"
            dangerouslySetInnerHTML={{ __html: parseMarkdown(trimmed) }}
          />
        );
      }
    });

    // Flush any remaining list
    flushList();

    return elements;
  };

  const questionChanged =
    suggestedRewrite &&
    originalQuestion &&
    suggestedRewrite.question !== originalQuestion.question;

  return (
    <div
      className={`mb-3 p-3 border rounded-lg animate-in fade-in slide-in-from-top-2 ${
        isNewFormat
          ? scoreColorByValue(score)
          : "bg-red-950/30 border-red-500/30"
      }`}
    >
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-2 text-xs font-bold uppercase">
          <Icon name="zap" size={12} />
          AI Critique
        </div>
        <div className="flex items-center gap-3">
          {onRewrite && !suggestedRewrite && (
            <button
              onClick={onRewrite}
              disabled={isProcessing}
              className="px-3 py-1 rounded bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-bold transition-all flex items-center gap-1 disabled:opacity-50 disabled:cursor-not-allowed"
              title="Auto-rewrite this question based on critique"
            >
              <Icon name="edit" size={12} />
              {isProcessing ? "Rewriting..." : "Rewrite"}
            </button>
          )}
        </div>
      </div>
      <div className="text-xs text-slate-300 leading-relaxed space-y-1.5">
        {renderContent()}
      </div>

      {/* Suggested Rewrite Section with Word-Level Diff */}
      {suggestedRewrite && (
        <div className="mt-3 pt-3 border-t border-white/10">
          <div className="flex items-center justify-between mb-2">
            <div className="flex items-center gap-2">
              <span className="text-xs font-bold uppercase text-indigo-300 flex items-center gap-1">
                <Icon name="sparkles" size={12} /> Suggested Improvement
              </span>
              <span className="text-[10px] px-2 py-0.5 rounded-full bg-blue-900/30 text-blue-300 border border-blue-700/50 flex items-center gap-1">
                <Icon name="git-compare" size={10} />
                Word Diff
              </span>
            </div>
            <div className="flex items-center gap-3">
              {/* FIX IT button - applies rewrite but keeps question PENDING for human review */}
              {/* Only enabled when score < 60 (needs improvement) */}
              {onApplyRewrite && (
                <button
                  onClick={onApplyRewrite}
                  disabled={isProcessing || score >= QUALITY_PASS_THRESHOLD}
                  className={`px-5 py-2.5 rounded-lg text-white text-sm font-bold transition-all flex items-center gap-2 shadow-lg ${
                    isProcessing || score >= QUALITY_PASS_THRESHOLD
                      ? "bg-slate-700 cursor-not-allowed opacity-50"
                      : "bg-gradient-to-r from-green-600 to-emerald-600 hover:from-green-500 hover:to-emerald-500 shadow-green-900/50"
                  }`}
                  title={
                    score >= QUALITY_PASS_THRESHOLD
                      ? "Score is acceptable - no fix needed"
                      : "Apply AI improvements (question stays pending for your review)"
                  }
                >
                  <Icon name="zap" size={16} />
                  {getApplyButtonText(
                    isProcessing,
                    score,
                    QUALITY_PASS_THRESHOLD
                  )}
                </button>
              )}

              {/* Secondary options */}
              <div className="flex items-center gap-2 opacity-70 hover:opacity-100 transition-opacity">
                {onExplain && (
                  <button
                    onClick={onExplain}
                    disabled={isProcessing}
                    className="px-2 py-1 rounded border border-slate-600 text-slate-400 text-xs hover:text-white hover:border-slate-400 transition-colors disabled:opacity-50"
                    title="Why is this the answer?"
                  >
                    WHY?
                  </button>
                )}
                {onVariate && (
                  <button
                    onClick={onVariate}
                    disabled={isProcessing}
                    className="px-2 py-1 rounded border border-slate-600 text-slate-400 text-xs hover:text-white hover:border-slate-400 transition-colors disabled:opacity-50"
                    title="Generate alternative question variations"
                  >
                    ALTERNATIVES
                  </button>
                )}
              </div>
            </div>
          </div>

          {rewriteChanges && (
            <div className="mb-2 text-xs text-indigo-200 bg-indigo-900/20 p-2 rounded border border-indigo-500/30 flex items-start gap-2">
              <Icon name="info" size={14} className="flex-shrink-0 mt-0.5" />
              <span>
                <span className="font-bold text-indigo-100">Why:</span>{" "}
                {rewriteChanges}
              </span>
            </div>
          )}

          <div className="text-xs space-y-3 bg-black/20 p-3 rounded border border-white/5">
            {/* Question with word-level diff */}
            <div>
              <div className="text-[10px] font-bold uppercase text-slate-500 mb-1 flex items-center gap-1">
                <Icon name="message-square" size={10} />
                Question
              </div>
              <div className="text-sm">
                {questionChanged && originalQuestion ? (
                  <DiffText
                    oldText={originalQuestion.question}
                    newText={suggestedRewrite.question}
                  />
                ) : (
                  <span className="text-white">
                    {suggestedRewrite.question}
                  </span>
                )}
              </div>
            </div>

            {/* Options with word-level diff */}
            <div>
              <div className="text-[10px] font-bold uppercase text-slate-500 mb-1 flex items-center gap-1">
                <Icon name="list" size={10} />
                Options
              </div>
              <div className="grid grid-cols-1 gap-1.5 pl-2 border-l-2 border-indigo-500/30">
                {["A", "B", "C", "D"].map((letter) => {
                  const newVal = suggestedRewrite.options?.[letter];
                  if (!newVal) return null;

                  const oldVal = originalQuestion?.options?.[letter];
                  const isChanged = oldVal && oldVal !== newVal;
                  const isCorrect = suggestedRewrite.correct === letter;

                  return (
                    <div
                      key={letter}
                      className={`flex items-start gap-2 ${
                        isCorrect ? "text-green-400 font-bold" : ""
                      }`}
                    >
                      <span
                        className={`flex-shrink-0 w-5 h-5 rounded text-center text-[10px] leading-5 font-bold ${
                          isChanged
                            ? "bg-blue-900/50 text-blue-300 border border-blue-700/50"
                            : "bg-slate-800 text-slate-400"
                        }`}
                      >
                        {letter}
                      </span>
                      <span className="flex-1">
                        {isChanged ? (
                          <DiffText oldText={oldVal} newText={newVal} />
                        ) : (
                          <span
                            className={
                              isCorrect ? "text-green-400" : "text-slate-300"
                            }
                          >
                            {newVal}
                          </span>
                        )}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Correct answer change indicator */}
            {originalQuestion &&
              suggestedRewrite.correct !== originalQuestion.correct && (
                <div className="flex items-center gap-2 text-xs text-yellow-200 bg-yellow-950/30 border border-yellow-700/50 rounded p-2">
                  <Icon name="alert-triangle" size={14} />
                  <span>
                    Correct answer changed:
                    <span className="ml-1 bg-red-900/50 text-red-300 line-through px-1.5 py-0.5 rounded">
                      {originalQuestion.correct}
                    </span>
                    <span className="mx-1">ΓåÆ</span>
                    <span className="bg-green-900/50 text-green-300 font-bold px-1.5 py-0.5 rounded">
                      {suggestedRewrite.correct}
                    </span>
                  </span>
                </div>
              )}
          </div>
        </div>
      )}
    </div>
  );
};

export default CritiqueDisplay;

import { sanitizeText } from "../utils/sanitize";
import Icon from "./Icon";
import { renderMarkdown } from "../utils/stringHelpers";
import DiffText from "./DiffText";
import { QUALITY_THRESHOLDS } from "../utils/constants";
import { useThemeColors } from "../hooks/useThemeColors";

// DiffText imported from shared component

const CritiqueModal = ({
  isOpen,
  onClose,
  q,
  text,
  score,
  loading,
  onFix,
  isFixing,
  onAccept,
  rewrite,
  changes,
  onApplySuggestions,
}) => {
  if (!isOpen || !q) return null;

  // Get centralized theme colors with colorblind support
  const { severityStyles } = useThemeColors();

  // Use centralized severity styles
  const styles = severityStyles(score);
  const isFailing = score !== null && score < QUALITY_THRESHOLDS.MEDIOCRE;

  // Check if question was changed
  const questionChanged = rewrite?.question && rewrite.question !== q.question;

  // Check which options changed
  const optionChanges = ["A", "B", "C", "D"].filter((letter) => {
    const oldVal = q.options?.[letter];
    const newVal = rewrite?.options?.[letter];
    return newVal && oldVal !== newVal;
  });

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-in fade-in">
      <div className="bg-slate-900 border border-slate-700 rounded-xl shadow-2xl max-w-3xl w-full flex flex-col max-h-[90vh]">
        <div
          className={`p-4 border-b ${styles.border} flex justify-between items-center bg-slate-950/50 rounded-t-xl`}
        >
          <div
            className={`flex items-center gap-2 ${styles.icon} font-bold uppercase tracking-wider text-sm`}
          >
            <Icon name="zap" size={18} />
            <span>AI Critique {score !== null && `ΓÇó Score: ${score}/100`}</span>
          </div>
          <button
            onClick={onClose}
            className="text-slate-500 hover:text-white transition-colors"
          >
            <Icon name="x" size={20} />
          </button>
        </div>

        <div className="p-6 overflow-y-auto space-y-6 flex-1">
          {/* Original Question */}
          <div className="space-y-2">
            <div className="text-[10px] font-bold uppercase text-slate-500">
              Original Question
            </div>
            <div
              className="p-4 bg-slate-950 border border-slate-800 rounded text-sm text-slate-300"
              dangerouslySetInnerHTML={{ __html: sanitizeText(q.question) }}
            />
          </div>

          {/* Feedback */}
          <div className="space-y-2">
            <div className="text-[10px] font-bold uppercase text-slate-500">
              Feedback
            </div>
            {loading ? (
              <div className="flex items-center gap-2 text-sm text-slate-400 animate-pulse p-4">
                <Icon name="loader" className="animate-spin" /> Analyzing Logic
                & Syntax...
              </div>
            ) : (
              <div
                className={`p-4 ${styles.bg} border ${styles.border} rounded text-sm ${styles.text} leading-relaxed`}
                dangerouslySetInnerHTML={{ __html: renderMarkdown(text) }}
              />
            )}
          </div>

          {/* Suggested Changes with Word-Level Diff */}
          {rewrite && (
            <div className="space-y-3">
              <div className="flex items-center gap-2">
                <div className="text-[10px] font-bold uppercase text-slate-500">
                  AI Improvements
                </div>
                <div className="flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full bg-blue-900/30 text-blue-300 border border-blue-700/50">
                  <Icon name="git-compare" size={10} />
                  <span>Word-Level Diff</span>
                </div>
              </div>

              {/* Change Summary */}
              {changes && (
                <div className="p-3 bg-indigo-950/30 border border-indigo-700/50 rounded text-xs text-indigo-200 italic flex items-start gap-2">
                  <Icon
                    name="info"
                    size={14}
                    className="flex-shrink-0 mt-0.5"
                  />
                  <span>{changes}</span>
                </div>
              )}

              <div className="p-4 bg-slate-950/50 border border-slate-700 rounded space-y-4">
                {/* Question Diff */}
                {questionChanged && (
                  <div className="space-y-2">
                    <div className="flex items-center gap-2 text-[10px] font-bold text-slate-400 uppercase">
                      <Icon name="message-square" size={12} />
                      Question Text
                    </div>
                    <div className="p-3 bg-slate-900 border border-slate-800 rounded text-sm">
                      <DiffText
                        oldText={q.question}
                        newText={rewrite.question}
                      />
                    </div>
                  </div>
                )}

                {/* Options Diff */}
                {optionChanges.length > 0 && (
                  <div className="space-y-2">
                    <div className="flex items-center gap-2 text-[10px] font-bold text-slate-400 uppercase">
                      <Icon name="list" size={12} />
                      Answer Options
                    </div>
                    <div className="space-y-2">
                      {optionChanges.map((letter) => (
                        <div
                          key={letter}
                          className="flex items-start gap-3 p-3 bg-slate-900 border border-slate-800 rounded"
                        >
                          <div className="text-[10px] font-bold text-slate-500 bg-slate-800 px-2 py-1 rounded">
                            {letter}
                          </div>
                          <div className="flex-1 text-sm">
                            <DiffText
                              oldText={q.options?.[letter]}
                              newText={rewrite.options?.[letter]}
                            />
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Correct Answer Change */}
                {rewrite.correct && rewrite.correct !== q.correct && (
                  <div className="flex items-center gap-2 text-xs text-yellow-200 bg-yellow-950/30 border border-yellow-700/50 rounded p-3">
                    <Icon name="alert-triangle" size={14} />
                    <span>
                      Correct answer changed:
                      <span className="ml-1 bg-red-900/50 text-red-300 line-through px-1.5 py-0.5 rounded">
                        {q.correct}
                      </span>
                      <span className="mx-1">ΓåÆ</span>
                      <span className="bg-green-900/50 text-green-300 font-bold px-1.5 py-0.5 rounded">
                        {rewrite.correct}
                      </span>
                    </span>
                  </div>
                )}

                {/* No Changes Detected */}
                {!questionChanged &&
                  optionChanges.length === 0 &&
                  rewrite.correct === q.correct && (
                    <div className="text-xs text-slate-400 text-center py-2">
                      <Icon
                        name="check-circle"
                        size={14}
                        className="inline mr-1"
                      />
                      No structural changes suggested - question is already
                      well-formed
                    </div>
                  )}
              </div>
            </div>
          )}
        </div>

        <div className="p-4 border-t border-slate-800 bg-slate-950/50 rounded-b-xl flex justify-center gap-3 flex-wrap">
          <button
            onClick={onClose}
            className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 hover:text-white font-bold rounded flex items-center gap-2 text-xs uppercase transition-all shadow-lg hover:shadow-slate-900/20"
          >
            Dismiss
          </button>

          {rewrite && onApplySuggestions && (
            <button
              onClick={() => onApplySuggestions(rewrite)}
              disabled={loading}
              className="px-4 py-2 bg-blue-600 hover:bg-blue-500 disabled:bg-slate-800 disabled:text-slate-500 text-white font-bold rounded flex items-center gap-2 text-xs uppercase transition-all shadow-lg hover:shadow-blue-900/20"
            >
              <Icon name="check-circle" size={14} />
              Apply All Suggestions
            </button>
          )}

          <button
            onClick={onFix}
            disabled={loading || isFixing}
            className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-800 disabled:text-slate-500 text-white font-bold rounded flex items-center gap-2 text-xs uppercase transition-all shadow-lg hover:shadow-indigo-900/20"
          >
            {isFixing ? (
              <Icon name="loader" className="animate-spin" size={14} />
            ) : (
              <Icon name="sparkles" size={14} />
            )}
            Regenerate
          </button>

          <button
            onClick={onAccept}
            disabled={isFailing || loading}
            title={isFailing ? "Score too low to accept" : "Accept Question"}
            className={`px-4 py-2 font-bold rounded flex items-center gap-2 text-xs uppercase transition-all shadow-lg ${
              isFailing || loading
                ? "bg-slate-800 text-slate-500 cursor-not-allowed opacity-50"
                : "bg-green-600 hover:bg-green-500 text-white hover:shadow-green-900/20"
            }`}
          >
            <Icon name="check" size={14} /> Accept
          </button>
        </div>
      </div>
    </div>
  );
};

export default CritiqueModal;

import { useState } from "react";
import Icon from "./Icon";
import ConfirmDialog from "./ConfirmDialog";
import PromptDialog from "./PromptDialog";
import { clearQuestionsFromSheets } from "../services/googleSheets";
import {
  clearAllQuestionsFromFirestore,
  auth,
  deleteQuestionFromFirestore,
  getDb, // Changed: Replaced 'db' with 'getDb'
} from "../services/firebase";
import { collection, getDocs, doc, updateDoc } from "firebase/firestore";
import { logger } from "../utils/logger";
import { MAINTENANCE } from "../utils/constants";

/**
 * DangerZoneModal - Separate modal for destructive operations
 * Isolated from Settings to prevent accidental data loss
 */
const DangerZoneModal = ({
  isOpen,
  onClose,
  config,
  onClearData,
  isAdmin = false,
}) => {
  const [isResetting, setIsResetting] = useState(false);
  const [showFactoryResetConfirm, setShowFactoryResetConfirm] = useState(false);
  const [showFactoryResetPrompt, setShowFactoryResetPrompt] = useState(false);
  const [isMigrating, setIsMigrating] = useState(false);
  const [migrationResult, setMigrationResult] = useState(null);
  const [isNuking, setIsNuking] = useState(false);
  const [nukeProgress, setNukeProgress] = useState({ current: 0, total: 0 });

  const handleFactoryResetClick = () => {
    setShowFactoryResetConfirm(true);
  };

  const handleFirstConfirm = () => {
    setShowFactoryResetConfirm(false);
    setShowFactoryResetPrompt(true);
  };

  const handlePromptConfirm = async (typedValue) => {
    if (typedValue !== "DELETE EVERYTHING") {
      alert(
        "Factory reset cancelled. You must type 'DELETE EVERYTHING' exactly."
      );
      setShowFactoryResetPrompt(false);
      return;
    }

    logger.log("ΓÜá∩╕Å FACTORY RESET INITIATED");
    setShowFactoryResetPrompt(false);
    setIsResetting(true);

    try {
      let deletedCount = 0;

      // 1. Clear Firestore FIRST (critical)
      logger.log("Clearing Firestore...");
      try {
        deletedCount = await clearAllQuestionsFromFirestore();
        logger.log(`Γ£à Deleted ${deletedCount} questions from Firestore`);
      } catch (firestoreError) {
        logger.error("Γ¥î Firestore deletion failed:", firestoreError);
        throw new Error(`Firestore deletion failed: ${firestoreError.message}`);
      }

      // 2. Clear Google Spreadsheet
      if (config.sheetUrl) {
        logger.log("Clearing Google Spreadsheet...");
        try {
          clearQuestionsFromSheets(config.sheetUrl);
          logger.log("Γ£à Spreadsheet clear request sent (check new tab)");
        } catch (sheetsError) {
          logger.error("Γ¥î Sheets clearing failed:", sheetsError);
        }
      }

      // 3. Clear localStorage
      logger.log("Clearing localStorage...");
      localStorage.clear();
      logger.log("Γ£à Local storage cleared");

      // 4. Reload
      alert(
        `Factory Reset Complete!\n\nΓÇó Firestore: ${deletedCount} questions deleted\nΓÇó Spreadsheet: ${
          config.sheetUrl ? "Clearing in new tab" : "Skipped"
        }\nΓÇó Local Storage: Cleared\n\nPage will reload.`
      );
      window.location.reload();
    } catch (error) {
      logger.error("Γ¥î Factory reset error:", error);
      alert(
        "Error during factory reset:\n\n" +
          error.message +
          "\n\nCheck console for details."
      );
      setIsResetting(false);
    }
  };

  const handleBackfillCreatorNames = async () => {
    if (
      !confirm(
        'This will add your creator name to all questions that currently show "N/A". Continue?'
      )
    ) {
      return;
    }

    setIsMigrating(true);
    setMigrationResult(null);

    try {
      const creatorName = config.creatorName || "Unknown";
      const querySnapshot = await getDocs(collection(getDb(), "questions")); // Changed: Used getDb()

      const questionsToUpdate = [];
      querySnapshot.forEach((docSnap) => {
        const data = docSnap.data();
        const creator = data.creatorName;
        // Catch: null, undefined, empty string, 'N/A', or whitespace-only
        if (
          !creator ||
          creator.trim() === "" ||
          creator === "N/A" ||
          creator === "Unknown"
        ) {
          questionsToUpdate.push({
            firestoreId: docSnap.id, // Use Firestore document ID
            ...data,
          });
        }
      });

      if (questionsToUpdate.length === 0) {
        setMigrationResult({
          success: 0,
          total: 0,
          message: "All questions already have creator names!",
        });
        setIsMigrating(false);
        return;
      }

      let successCount = 0;
      for (const question of questionsToUpdate) {
        try {
          logger.log(
            "Updating question:",
            question.firestoreId,
            "Creator:",
            question.creatorName
          );
          const questionRef = doc(getDb(), "questions", question.firestoreId); // Changed: Used getDb()
          await updateDoc(questionRef, {
            creatorName: creatorName,
            backfilledAt: new Date().toISOString(),
          });
          successCount++;
          logger.log("Γ£ô Successfully updated:", question.firestoreId);
        } catch (err) {
          logger.error(
            `Failed to update question ${question.firestoreId}:`,
            err.message,
            err
          );
        }
      }

      setMigrationResult({
        success: successCount,
        total: questionsToUpdate.length,
        message: `Successfully updated ${successCount} of ${questionsToUpdate.length} questions!`,
      });
    } catch (error) {
      logger.error("Migration failed:", error);
      alert("Migration failed: " + error.message);
    } finally {
      setIsMigrating(false);
    }
  };

  // Admin-only: Nuke ALL questions from Firestore (any user's questions)
  const handleNukeAllQuestions = async () => {
    if (!auth.currentUser) {
      alert("You must be signed in to use this feature.");
      return;
    }

    if (
      !confirm(
        "ΓÜá∩╕Å ADMIN NUKE: This will delete ALL questions from ALL users. Are you sure?"
      )
    ) {
      return;
    }
    if (!confirm("ΓÜá∩╕Å FINAL WARNING: This is IRREVERSIBLE. Continue?")) {
      return;
    }

    setIsNuking(true);
    setNukeProgress({ current: 0, total: 0 });

    try {
      logger.log("≡ƒöÑ Admin nuke initiated by:", auth.currentUser.email);

      // Fetch ALL questions without filter
      const snapshot = await getDocs(collection(getDb(), "questions")); // Changed: Used getDb()
      const allQuestions = snapshot.docs.map((doc) => ({
        uniqueId: doc.id,
        ...doc.data(),
      }));

      if (allQuestions.length === 0) {
        alert("No questions found in the database.");
        setIsNuking(false);
        return;
      }

      setNukeProgress({ current: 0, total: allQuestions.length });

      let deletedCount = 0;
      let errorCount = 0;
      const BATCH_SIZE = MAINTENANCE.NUKE_BATCH_SIZE || 10;

      for (let i = 0; i < allQuestions.length; i += BATCH_SIZE) {
        const batch = allQuestions.slice(i, i + BATCH_SIZE);

        await Promise.all(
          batch.map(async (q) => {
            try {
              await deleteQuestionFromFirestore(q.uniqueId);
              deletedCount++;
            } catch (e) {
              logger.error("Delete failed for", q.uniqueId, e);
              errorCount++;
            }
          })
        );

        setNukeProgress({
          current: Math.min(i + BATCH_SIZE, allQuestions.length),
          total: allQuestions.length,
        });
      }

      alert(
        `Nuke complete!\n\nDeleted: ${deletedCount}\nFailed: ${errorCount}`
      );

      // Clear local storage and reload
      localStorage.clear();
      window.location.reload();
    } catch (error) {
      logger.error("Nuke failed:", error);
      alert("Nuke failed: " + error.message);
    } finally {
      setIsNuking(false);
    }
  };

  if (!isOpen) return null;

  return (
    <>
      <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center z-50 p-4">
        <div className="bg-red-950/50 border-2 border-red-500 rounded-xl shadow-2xl w-full max-w-md overflow-hidden animate-in fade-in zoom-in-95 duration-200">
          <div className="p-4 border-b border-red-900 flex justify-between items-center bg-red-900/50">
            <h2 className="text-lg font-bold text-red-300 flex items-center gap-2">
              <Icon name="alert-triangle" className="text-red-500" /> DANGER
              ZONE
            </h2>
            <button
              onClick={onClose}
              className="text-red-400 hover:text-white transition-colors"
              aria-label="Close Danger Zone"
            >
              <Icon name="x" />
            </button>
          </div>

          <div className="p-6 space-y-6">
            <div className="bg-red-900/20 p-4 rounded-lg border border-red-900/50">
              <p className="text-sm text-red-300 mb-4">
                ΓÜá∩╕Å <strong>WARNING:</strong> These operations are{" "}
                <strong>PERMANENT</strong> and cannot be undone. Your data will
                be lost forever.
              </p>

              <div className="space-y-3">
                {/* Migration Tools */}
                <div className="bg-blue-900/20 p-3 rounded border border-blue-900/50 mb-3">
                  <p className="text-xs text-blue-300 mb-2 font-semibold">
                    ≡ƒöº Data Migration
                  </p>
                  <button
                    onClick={handleBackfillCreatorNames}
                    disabled={isMigrating}
                    className="w-full px-4 py-2 bg-blue-900/20 hover:bg-blue-900/40 text-blue-400 text-xs font-bold rounded border border-blue-900/50 transition-colors flex items-center justify-center gap-2 disabled:opacity-50"
                  >
                    {isMigrating ? (
                      <>
                        <Icon
                          name="loader"
                          size={14}
                          className="animate-spin"
                        />{" "}
                        Migrating...
                      </>
                    ) : (
                      <>
                        <Icon name="user-check" size={14} /> Backfill Creator
                        Names
                      </>
                    )}
                  </button>
                  {migrationResult && (
                    <p className="text-xs text-green-400 mt-2 text-center">
                      Γ£ô {migrationResult.message}
                    </p>
                  )}
                  <p className="text-[9px] text-blue-400/60 mt-1">
                    Adds your name to questions showing "N/A"
                  </p>
                </div>

                {/* Destructive Operations */}
                <button
