import React from "react";
import NameEntryModal from "./NameEntryModal";
import ClearConfirmationModal from "./ClearConfirmationModal";
import BlockingProcessModal from "./BlockingProcessModal";
import ApiKeyModal from "./ApiKeyModal";
import TermsOfUseModal from "./TermsOfUseModal";
import CookieConsentBanner from "./CookieConsentBanner";
import AgeGateModal from "./AgeGateModal";
import DeleteConfirmationModal from "./DeleteConfirmationModal";
import TutorialOverlay from "./TutorialOverlay";

import BulkExportModal from "./BulkExportModal";
import AnalyticsDashboard from "./AnalyticsDashboard";
import DangerZoneModal from "./DangerZoneModal";
import { Suspense } from "react";

// Standard Modals
// Lazy Modals
// Standard Modals
// Lazy Modals

const GlobalModals = ({ visibility, state, handlers }) => {
  const {
    showNameModal,
    showClearModal,
    showBulkExportModal,
    showAnalytics,
    showDangerZone,
    showApiKeyModal,
    showTerms,
    showAgeGate,
    tutorialActive,
    deleteConfirmId,
  } = visibility;

  const {
    config,
    isProcessing,
    status,
    translationProgress,
    allQuestionsMap,
    currentStep,
    tutorialSteps,
    activeScenario,

    isAdmin, // passed for SettingsModal
  } = state;

  const {
    handleNameSave,
    handleDeleteAllQuestions,
    handleBulkExport,
    confirmDelete,
    setDeleteConfirmId,
    onCloseBulkExport,
    onCloseAnalytics,
    onCloseDangerZone,
    onCloseApiKey,
    handleSaveApiKey,
    setShowTerms,
    setTermsAccepted,
    setShowAgeGate,
    handleTutorialNext,
    handleTutorialPrev,
    handleTutorialSkip,
    handleTutorialComplete,
    onHardReset,
    window, // needed for reloads/redirects?
  } = handlers;

  return (
    <>
      {/* Blocking Process - Highest Priority */}
      {isProcessing && (
        <BlockingProcessModal
          isProcessing={isProcessing}
          status={status}
          translationProgress={translationProgress}
        />
      )}

      {/* Critical Entry/Exit Modals */}
      {config.creatorName === "" && showNameModal && (
        <NameEntryModal onSave={handleNameSave} />
      )}

      {showClearModal && (
        <ClearConfirmationModal
          onConfirm={handleDeleteAllQuestions}
          onCancel={() => handlers.setShowClearModal(false)}
        />
      )}

      <DeleteConfirmationModal
        deleteConfirmId={deleteConfirmId}
        onConfirm={confirmDelete}
        onCancel={() => setDeleteConfirmId(null)}
      />

      <ApiKeyModal
        isOpen={showApiKeyModal}
        onClose={onCloseApiKey}
        onSave={handleSaveApiKey}
        currentKey={config.apiKey}
      />

      <AgeGateModal
        isOpen={showAgeGate}
        onConfirm={() => {
          setShowAgeGate(false);
          setShowTerms(true);
        }}
        onExit={() => {
          window.location.href = "about:blank";
        }}
      />

      <TermsOfUseModal
        isOpen={showTerms}
        onAccept={() => {
          localStorage.setItem("ue5_terms_accepted", "true");
          setShowTerms(false);
          setTermsAccepted(true);
        }}
        onDecline={() => {
          window.location.href = "about:blank";
        }}
      />

      <CookieConsentBanner />

      {/* Lazy Loaded Modals */}
      <Suspense fallback={null}>
        {showBulkExportModal && (
          <BulkExportModal
            onClose={onCloseBulkExport}
            onExport={handleBulkExport}
            questionCount={allQuestionsMap?.size || 0}
          />
        )}

        <AnalyticsDashboard isOpen={showAnalytics} onClose={onCloseAnalytics} />

        {showDangerZone && (
          <DangerZoneModal
            isOpen={showDangerZone}
            onClose={onCloseDangerZone}
            onClearData={handleDeleteAllQuestions}
            onHardReset={onHardReset}
            config={config}
            isAdmin={isAdmin}
          />
        )}
      </Suspense>

      {/* Tutorial Overlay */}
      {tutorialActive && (
        <TutorialOverlay
          steps={tutorialSteps}
          currentStepIndex={currentStep}
          onNext={handleTutorialNext}
          onPrev={handleTutorialPrev}
          onSkip={handleTutorialSkip}
          onComplete={handleTutorialComplete}
          activeScenario={activeScenario}
        />
      )}
    </>
  );
};

export default GlobalModals;

import { useState, useEffect, useRef } from "react";
import Icon from "./Icon";
import Button from "./ui/Button";
import useConnectionStatus from "../hooks/useConnectionStatus";
import { useAccessibility } from "../contexts/AccessibilityContext";
import { signOutUser, triggerManualSync } from "../services/firebase";
import { APP_VERSION, APP_MODES } from "../utils/constants";
import { logger } from "../utils/logger";

const getVersionDisplay = () => {
  const projectId = import.meta.env.VITE_FIREBASE_PROJECT_ID || "";
  logger.log(
    "≡ƒöì [Header] Project ID:",
    projectId,
    "| isProd:",
    projectId.includes("prod")
  );
  const isProd = projectId.includes("prod");
  // Get git commit hash from build-time define (set in vite.config.js)
  const gitCommit = typeof __GIT_COMMIT__ !== "undefined" ? __GIT_COMMIT__ : "";
  const commitSuffix = gitCommit ? `-${gitCommit}` : "";
  return {
    version: `${APP_VERSION}${commitSuffix}-${isProd ? "PROD" : "DEV"}`,
    isProd,
  };
};

const Header = ({
  apiKeyStatus,
  isCloudReady,
  onHome,
  creatorName,
  appMode,
  tokenUsage = { inputTokens: 0, outputTokens: 0, totalCost: 0 },
  onStartTutorial,
  isAdmin,
  onSignOut,
  user, // Add user prop for super admin check
}) => {
  // Tutorial center state removed - was unused

  // Super Admin check - case-insensitive with trim
  const userEmail = user?.email?.toLowerCase();
  const envSuperAdmin =
    import.meta.env.VITE_SUPER_ADMIN_EMAIL?.trim()?.toLowerCase();
  const isSuperAdmin = userEmail === envSuperAdmin && envSuperAdmin;
  const connectionStatus = useConnectionStatus();
  const { colorblindMode, toggleColorblindMode } = useAccessibility();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const menuRef = useRef(null);

  // Close mobile menu on ESC key or click outside
  useEffect(() => {
    const handleEsc = (e) => {
      if (e.key === "Escape") setMobileMenuOpen(false);
    };
    const handleClickOutside = (e) => {
      if (menuRef.current && !menuRef.current.contains(e.target)) {
        setMobileMenuOpen(false);
      }
    };
    if (mobileMenuOpen) {
      document.addEventListener("keydown", handleEsc);
      document.addEventListener("mousedown", handleClickOutside);
    }
    return () => {
      document.removeEventListener("keydown", handleEsc);
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [mobileMenuOpen]);
  const isReview = appMode === APP_MODES.REVIEW;
  const isAnalytics = appMode === APP_MODES.ANALYTICS;

  // Get mode-specific styles using object lookup instead of nested ternaries
  const getModeStyles = () => {
    if (isReview) {
      return {
        border: "border-indigo-600",
        title: "text-indigo-50",
        bg: "bg-slate-950 bg-gradient-to-r from-indigo-950/30 to-slate-950",
      };
    }
    if (isAnalytics) {
      return {
        border: "border-emerald-600",
        title: "text-emerald-50",
        bg: "bg-slate-950 bg-gradient-to-r from-emerald-950/30 to-slate-950",
      };
    }
    return {
      border: "border-orange-600",
      title: "text-orange-50",
      bg: "bg-slate-950",
    };
  };

  const modeStyles = getModeStyles();
  const borderColor = modeStyles.border;
  const titleColor = modeStyles.title;
  const headerBg = modeStyles.bg;

  const totalTokens =
    (tokenUsage.inputTokens || 0) + (tokenUsage.outputTokens || 0);
  const formattedTokens =
    totalTokens >= 1000 ? `${(totalTokens / 1000).toFixed(1)}k` : totalTokens;
  const formattedCost = (tokenUsage.totalCost || 0).toFixed(4);

  const getTitle = () => {
    if (isReview) return "Review & Audit Console";
    if (isAnalytics) return "Analytics Dashboard";
    return "UE5 Question Generator";
  };

  const getSubtitle = () => {
    if (isReview) return "Quality Assurance ΓÇó Translation ΓÇó Verification";
    if (isAnalytics)
      return "Generation Metrics ΓÇó Quality Trends ΓÇó URL Validation";
    return "Universal Scenario-Based Generator ΓÇó Official Docs Only";
  };

  const getBadgeStyle = () => {
    if (isReview)
      return "bg-indigo-500/20 text-indigo-300 border-indigo-500/50";
    if (isAnalytics)
      return "bg-emerald-500/20 text-emerald-300 border-emerald-500/50";
    if (appMode === APP_MODES.DATABASE)
      return "bg-blue-500/20 text-blue-300 border-blue-500/50";
    return "bg-orange-500/20 text-orange-300 border-orange-500/50";
  };

  const getBadgeText = () => {
    if (isReview) return "REVIEW MODE";
    if (isAnalytics) return "ANALYTICS";
    if (appMode === APP_MODES.DATABASE) return "DATABASE VIEW";
    return "CREATE MODE";
  };

  return (
    <header
      className={`${headerBg} text-white p-6 shadow-xl border-b ${borderColor} relative z-20 transition-all duration-500`}
      role="banner"
      aria-label="Application header"
    >
      <div className="max-w-7xl mx-auto flex items-center justify-between">
        <div
          className="flex items-center gap-3 cursor-pointer"
          onClick={onHome}
          title="Back to Home"
        >
          <div className="p-2 transition-colors duration-500">
            <img
              src="/UE5QuestionGenerator/logos/UE-Icon-2023-White.svg"
              alt="UE5 Logo"
              className="w-10 h-10 object-contain"
            />
          </div>
          <div>
            <h1
              className={`text-xl font-bold tracking-tight uppercase ${titleColor} transition-colors duration-500`}
            >
              {getTitle()}
            </h1>
            <p className="text-slate-400 text-xs mt-0.5">{getSubtitle()}</p>
          </div>
        </div>
        <div className="hidden lg:flex items-center gap-2 text-xs font-mono">
          {/* Mode Badge */}
          <span
            className={`flex items-center h-7 px-2 rounded text-[10px] font-semibold uppercase tracking-wider border whitespace-nowrap ${getBadgeStyle()}`}
          >
            {getBadgeText()}
          </span>
          {/* Colorblind Mode Toggle */}
          <Button
            onClick={toggleColorblindMode}
            variant={colorblindMode ? "primary" : "secondary"}
            size="xs"
            className={`flex items-center gap-1 font-bold whitespace-nowrap ${
              colorblindMode
                ? "bg-blue-600 hover:bg-blue-500 shadow-lg shadow-blue-900/50"
                : "bg-slate-700 hover:bg-slate-600 text-slate-300"
            }`}
            title={
              colorblindMode ? "Colorblind mode ON" : "Enable colorblind mode"
            }
            aria-pressed={colorblindMode}
            aria-label="Toggle colorblind mode"
          >
            <Icon name="eye" size={12} />
            {colorblindMode ? "Colorblind Γ£ô" : "Colorblind"}
          </Button>
          {/* Tutorial Button - First */}
          {onStartTutorial &&
            [
              APP_MODES.CREATE,
              APP_MODES.REVIEW,
              APP_MODES.DATABASE,
              APP_MODES.ANALYTICS,
            ].includes(appMode) && (
              <Button
                onClick={() => onStartTutorial(appMode)}
                size="xs"
                className="flex items-center gap-1 font-bold bg-indigo-600 hover:bg-indigo-500 text-white shadow-lg shadow-indigo-900/50 whitespace-nowrap"
                title={`Start ${appMode} tutorial`}
              >
                <Icon name="help-circle" size={12} />
                Tutorial
              </Button>
            )}
          {/* User Info */}
          {creatorName && (
            <div className="flex items-center h-7 gap-1.5 font-medium text-slate-300 px-2 bg-slate-800/50 rounded-lg whitespace-nowrap text-[10px]">
              <Icon
                name={isAdmin ? "shield-check" : "user"}
                size={12}
                className={isAdmin ? "text-orange-500" : "text-green-500"}
              />
              <span>{creatorName}</span>
              {isAdmin && (
                <span
                  className={`text-[9px] font-semibold px-1 py-0.5 rounded border ml-0.5 ${
                    isSuperAdmin
                      ? "bg-purple-900/50 text-purple-400 border-purple-800"
                      : "bg-orange-900/50 text-orange-400 border-orange-800"
                  }`}
                >
                  {isSuperAdmin ? "SUPER" : "ADMIN"}
                </span>
              )}
              <button
                onClick={async () => {
                  if (onSignOut) onSignOut();
                  await signOutUser();
                }}
                className="ml-1 p-1 text-slate-400 hover:text-red-400 hover:bg-red-900/20 rounded transition-colors"
                title="Sign Out"
                aria-label="Sign out of application"
              >
                <Icon name="log-out" size={12} />
              </button>
            </div>
          )}
          {/* Consolidated Status Box: Tokens | Cost | Connection | API Key | CLOUD v2.0-DEV */}
          <div
            className="flex items-center h-7 gap-1.5 px-2 rounded border border-slate-700 whitespace-nowrap text-[10px]"
            role="status"
            aria-live="polite"
            title={`Input: ${tokenUsage.inputTokens || 0} | Output: ${
              tokenUsage.outputTokens || 0
            }`}
          >
            {/* Token Display */}
            <div className="flex items-center gap-1 text-purple-400">
              <Icon name="zap" size={10} />
              <span className="font-semibold">{formattedTokens}</span>
            </div>
            <div className="w-px h-3 bg-slate-700"></div>
            {/* Cost Display */}
            <div className="flex items-center gap-1 text-emerald-400">
              <span className="text-slate-500">$</span>
              <span className="font-semibold">{formattedCost}</span>
            </div>
            {/* Connection Status (only if needed) */}
            {(!connectionStatus.isOnline ||
              connectionStatus.queuedCount > 0 ||
              connectionStatus.syncInProgress) && (
              <>
                <div className="w-px h-3 bg-slate-700"></div>
                {!connectionStatus.isOnline && (
                  <div
                    className="flex items-center gap-1 text-yellow-400 font-bold animate-pulse"
                    title="You are offline. Changes will sync when connection is restored."
                  >
                    <Icon name="wifi-off" size={12} />
                    <span>OFFLINE</span>
                  </div>
                )}
                {connectionStatus.queuedCount > 0 && (
                  <div className="flex items-center gap-1.5 px-1 bg-slate-800/80 rounded-lg group relative">
                    <button
                      onClick={triggerManualSync}
                      className="flex items-center gap-0.5 text-orange-400 font-bold hover:text-orange-300 transition-colors py-0.5"
                      aria-label={`${connectionStatus.queuedCount} items queued. Click to sync now.`}
                    >
                      <Icon name="upload-cloud" size={12} />
                      <span>{connectionStatus.queuedCount}</span>
                      <span className="text-[8px] ml-0.5">SYNC</span>
                    </button>
                    {/* Tooltip for queue details */}
                    <div className="absolute top-full right-0 mt-2 w-48 bg-slate-900 border border-slate-700 rounded-lg shadow-2xl p-3 opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity z-50">
                      <div className="text-[10px] font-bold text-slate-300 border-b border-slate-800 pb-1.5 mb-2 flex justify-between items-center">
                        PENDING SYNC
                        <span className="text-orange-500 font-mono">
                          {connectionStatus.queuedCount}
                        </span>
                      </div>
                      <div className="space-y-1.5">
                        {connectionStatus.queueDetails?.items
                          ?.slice(0, 5)
                          .map((item, idx) => (
                            <div key={idx} className="flex flex-col gap-0.5">
                              <div className="flex justify-between items-center">
                                <span className="text-[9px] text-slate-400 truncate max-w-[100px]">
                                  {item.text || item.id}
                                </span>
                                <span className="text-[8px] font-bold px-1 rounded bg-slate-800 text-slate-500 uppercase">
                                  {item.status || "draft"}
                                </span>
                              </div>
                              <div className="text-[8px] text-slate-600 font-mono">
                                {item.timestamp
                                  ? new Date(item.timestamp).toLocaleTimeString(
                                      [],
                                      { hour: "2-digit", minute: "2-digit" }
                                    )
                                  : "Pending..."}
                              </div>
                            </div>
                          ))}
                        {connectionStatus.queuedCount > 5 && (
                          <div className="text-[8px] text-slate-500 italic pt-1 text-right">
                            ...and {connectionStatus.queuedCount - 5} more
                          </div>
                        )}
                      </div>
                      <div className="mt-2 text-[8px] text-slate-500 pt-1.5 border-t border-slate-800 text-center uppercase tracking-widest font-bold">
                        Click sync button to flush
                      </div>
                    </div>
                  </div>
                )}
                {connectionStatus.syncInProgress && (
                  <div
                    className="flex items-center gap-0.5 text-blue-400 font-bold px-1"
                    title="Synchronization in progress..."
                  >
                    <Icon
                      name="refresh-cw"
                      size={12}
                      className="animate-spin"
                    />
                    <span>SYNC</span>
                  </div>
                )}
              </>
            )}
            <div className="w-px h-3 bg-slate-700"></div>
            {/* API Key Status - Shortened */}
            <span
              className={`font-semibold ${
                apiKeyStatus.includes("Loaded") ||
                apiKeyStatus.includes("Auto") ||
                apiKeyStatus.includes("Cloud")
                  ? "text-green-400"
                  : "text-red-400"
              }`}
            >
              API: {apiKeyStatus}
            </span>
            <div className="w-px h-3 bg-slate-700"></div>
            {/* Cloud/Local indicator (version moved to footer) */}
            {(() => {
              if (isCloudReady) {
                return (
                  <div className="flex items-center gap-1 font-semibold whitespace-nowrap">
                    <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></div>
                    <span className="text-green-400">CLOUD</span>
                  </div>
                );
              } else {
                return (
                  <div className="flex items-center gap-1 font-semibold whitespace-nowrap">
                    <span className="text-orange-400">LOCAL</span>
                  </div>
                );
              }
            })()}
          </div>
        </div>

        {/* Mobile Hamburger Button */}
        <Button
          variant="ghost"
          size="icon"
          className="lg:hidden flex items-center justify-center w-10 h-10 rounded-lg bg-slate-800 hover:bg-slate-700 transition-colors"
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          aria-expanded={mobileMenuOpen}
          aria-controls="mobile-menu"
          aria-label={mobileMenuOpen ? "Close menu" : "Open menu"}
        >
          <Icon name={mobileMenuOpen ? "x" : "menu"} size={20} />
        </Button>
      </div>

      {/* Mobile Menu Dropdown */}
      {mobileMenuOpen && (
        <div
          id="mobile-menu"
          ref={menuRef}
          className="lg:hidden absolute left-0 right-0 top-full bg-slate-900 border-b border-slate-700 shadow-xl z-30 animate-in slide-in-from-top-2 duration-200"
          role="menu"
        >
          <div className="max-w-7xl mx-auto p-4 flex flex-col gap-3 text-xs font-mono">
            {/* Mode Badge */}
            <div className="flex items-center justify-between">
              <span
                className={`flex items-center h-7 px-2.5 rounded text-[11px] font-semibold uppercase tracking-wider border whitespace-nowrap ${getBadgeStyle()}`}
              >
                {getBadgeText()}
              </span>
              {/* Version/Cloud Status */}
              {(() => {
                const { version, isProd } = getVersionDisplay();
                const versionColor = isProd ? "text-red-400" : "text-green-400";
                return (
                  <div className="flex items-center gap-1.5 font-semibold">
                    {isCloudReady ? (
                      <>
                        <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
                        <span className="text-green-400">CLOUD</span>
                      </>
                    ) : (
                      <span className="text-orange-400">LOCAL</span>
                    )}
                    <span className={versionColor}>{version}</span>
                  </div>
                );
              })()}
            </div>

            {/* User Info */}
            {creatorName && (
              <div className="flex items-center justify-between py-2 border-t border-slate-700">
                <div className="flex items-center gap-2 font-medium text-slate-300">
                  <Icon
                    name={isAdmin ? "shield-check" : "user"}
                    size={14}
                    className={isAdmin ? "text-orange-500" : "text-green-500"}
                  />
                  <span>{creatorName}</span>
                  {isAdmin && (
                    <span
                      className={`text-[11px] font-semibold px-1.5 py-0.5 rounded border ${
                        isSuperAdmin
                          ? "bg-purple-900/50 text-purple-400 border-purple-800"
                          : "bg-orange-900/50 text-orange-400 border-orange-800"
                      }`}
                    >
                      {isSuperAdmin ? "SUPER" : "ADMIN"}
                    </span>
                  )}
                </div>
                <button
                  onClick={async () => {
                    setMobileMenuOpen(false);
                    if (onSignOut) onSignOut();
                    await signOutUser();
                  }}
                  className="p-2 text-slate-400 hover:text-red-400 hover:bg-red-900/20 rounded transition-colors"
                  aria-label="Sign out of application"
                >
                  <Icon name="log-out" size={16} />
                </button>
              </div>
            )}

            {/* Tutorial Button */}
            {onStartTutorial &&
              [
                APP_MODES.CREATE,
                APP_MODES.REVIEW,
                APP_MODES.DATABASE,
                APP_MODES.ANALYTICS,
              ].includes(appMode) && (
                <Button
                  onClick={() => {
                    setMobileMenuOpen(false);
                    onStartTutorial(appMode);
                  }}
                  size="sm"
                  variant="primary"
                  className="w-full flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-500 text-white shadow-lg shadow-indigo-900/50"
                >
                  <Icon name="help-circle" size={16} />
                  Start Tutorial
                </Button>
              )}

            {/* Stats Row */}
            <div className="flex items-center justify-between py-2 border-t border-slate-700 text-[11px]">
              <div className="flex items-center gap-3">
                {/* Tokens */}
                <div className="flex items-center gap-1 text-purple-400">
                  <Icon name="zap" size={12} />
                  <span className="font-semibold">{formattedTokens}</span>
                  <span className="text-slate-500">tok</span>
                </div>
                {/* Cost */}
                <div className="flex items-center gap-1 text-emerald-400">
                  <span className="text-slate-500">$</span>
                  <span className="font-semibold">{formattedCost}</span>
                </div>
              </div>
              {/* API Status */}
              <span
                className={`font-semibold ${
                  apiKeyStatus.includes("Loaded") ||
                  apiKeyStatus.includes("Auto") ||
                  apiKeyStatus.includes("Cloud")
                    ? "text-green-400"
                    : "text-red-400"
                }`}
              >
                API: {apiKeyStatus}
              </span>
            </div>

            {/* Connection Status (if offline or syncing) */}
            {(!connectionStatus.isOnline ||
              connectionStatus.queuedCount > 0 ||
              connectionStatus.syncInProgress) && (
              <div className="flex items-center gap-3 py-2 border-t border-slate-700">
                {!connectionStatus.isOnline && (
                  <div className="flex items-center gap-1.5 text-yellow-400 font-bold animate-pulse">
                    <Icon name="wifi-off" size={14} />
                    <span>OFFLINE</span>
                  </div>
                )}
                {connectionStatus.queuedCount > 0 && (
                  <div className="flex items-center gap-1 text-orange-400 font-bold">
                    <Icon name="upload-cloud" size={14} />
                    <span>{connectionStatus.queuedCount} queued</span>
                  </div>
                )}
                {connectionStatus.syncInProgress && (
                  <div className="flex items-center gap-1 text-blue-400 font-bold animate-pulse">
                    <Icon
                      name="refresh-cw"
                      size={14}
                      className="animate-spin"
                    />
                    <span>SYNCING</span>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      )}
    </header>
  );
};

export default Header;

import * as LucideIcons from 'lucide-react';
import { logger } from "../utils/logger";

const Icon = ({ name, size = 16, className = "", ariaLabel, role }) => {
    // Convert kebab-case to PascalCase for Lucide component name
    const pascalName = name.split('-').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join('');

    // Access the icon component from the imported object
    // Note: lucide-react exports icons as named exports, so we use the namespace import
    const LucideIcon = LucideIcons[pascalName];

    if (!LucideIcon) {
        logger.warn(`Icon "${name}" (mapped to "${pascalName}") not found in lucide-react.`);
        return <span style={{ width: size, height: size, display: 'inline-block' }} />;
    }

    return (
        <LucideIcon
            size={size}
            className={className}
            aria-label={ariaLabel}
            aria-hidden={!ariaLabel}
            role={role || (ariaLabel ? 'img' : 'presentation')}
        />
    );
};

export default Icon;

import { useState } from "react";
import Icon from "./Icon";
import { sanitizeText } from "../utils/sanitize";
import { logger } from "../utils/logger";
import { useThemeColors } from "../hooks/useThemeColors";

/**
 * Comprehensive Critique Modal - Shows critique + side-by-side improvements
 * Combines AI feedback with visual comparison in one view
 */
const ImprovementModal = ({
  originalQuestion,
  improvedQuestion,
  changesExplanation,
  critiqueText,
  critiqueScore,
  improvedScore, // Score the question would get AFTER applying improvements
  onApply,
  onDismiss,
}) => {
  const [isApplying, setIsApplying] = useState(false);
  const { scoreColorByValue } = useThemeColors();

  const handleApply = async () => {
    setIsApplying(true);
    try {
      await onApply(improvedQuestion);
    } catch (err) {
      logger.error("[ImprovementModal] onApply error:", err);
    }
    setIsApplying(false);
  };

  const scoreDelta =
    improvedScore && critiqueScore ? improvedScore - critiqueScore : 0;

  const originalTags = originalQuestion?.tags || [];
  const improvedTags = improvedQuestion?.tags || [];
  const newTags = improvedQuestion
    ? improvedTags.filter((tag) => !originalTags.includes(tag))
    : [];

  return (
    <div className="fixed inset-0 bg-black/80 z-[10000] flex items-start justify-center pt-4 p-4 overflow-y-auto pointer-events-auto">
      <div
        className="bg-slate-900 rounded-xl border-2 border-green-500/50 shadow-2xl max-w-6xl w-full max-h-[90vh] overflow-hidden flex flex-col pointer-events-auto relative"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="bg-gradient-to-r from-green-900/30 to-blue-900/30 border-b border-green-600/30 px-4 py-2">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Icon name="sparkles" size={20} className="text-green-400" />
              <h2 className="text-lg font-bold text-white">AI Critique</h2>
              <span
                className={`px-3 py-1 rounded text-sm font-bold border ${scoreColorByValue(
                  critiqueScore
                )}`}
              >
                Score: {critiqueScore}/100
              </span>
              {scoreDelta > 0 && (
                <span className="px-2 py-1 bg-green-600/20 border border-green-500/50 rounded text-xs font-bold text-green-300">
                  +{scoreDelta} pts improvement
                </span>
              )}
            </div>
          </div>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3 scrollbar-thin scrollbar-thumb-slate-600 scrollbar-track-transparent hover:scrollbar-thumb-slate-500">
          {/* AI Critique Feedback */}
          <div className="bg-orange-900/20 border border-orange-700/30 rounded-lg p-3">
            <div className="flex items-start gap-2 mb-2">
              <Icon
                name="message-square"
                size={16}
                className="text-orange-400 mt-0.5 flex-shrink-0"
              />
              <div className="text-xs font-bold text-orange-400 uppercase tracking-wide">
                AI Critique
              </div>
            </div>
            <div className="text-sm text-slate-200 leading-relaxed">
              {critiqueText}
            </div>
          </div>

          {/* Suggested Improvement Section */}
          {changesExplanation && (
            <div>
              <div className="flex items-center gap-2 mb-3">
                <Icon name="zap" size={16} className="text-green-400" />
                <div className="text-sm font-bold text-green-400 uppercase tracking-wide">
                  Suggested Improvement
                </div>
              </div>

              {/* Why Explanation */}
              <div className="bg-blue-900/15 border border-blue-700/30 rounded-lg p-2.5 mb-3">
                <div className="flex items-start gap-2">
                  <Icon
                    name="lightbulb"
                    size={14}
                    className="text-blue-400 mt-0.5 flex-shrink-0"
                  />
                  <div className="text-xs text-slate-200 leading-relaxed">
                    <strong className="text-blue-400">Why:</strong>{" "}
                    {changesExplanation}
                  </div>
                </div>
              </div>

              {/* Column Headers with Scores */}
              <div className="grid grid-cols-2 gap-4 mb-3">
                <div className="flex items-center justify-between px-2">
                  <h3 className="text-xs font-bold text-slate-400 flex items-center gap-1.5 uppercase tracking-wide">
                    <Icon name="file-text" size={14} />
                    Original
                  </h3>
                  <span
                    className={`px-2 py-0.5 rounded text-xs font-bold border ${scoreColorByValue(
                      critiqueScore
                    )}`}
                  >
                    {critiqueScore}/100
                  </span>
                </div>
                <div className="flex items-center justify-between px-2">
                  <h3 className="text-xs font-bold text-green-400 flex items-center gap-1.5 uppercase tracking-wide">
                    <Icon name="check-circle" size={14} />
                    Improved
                  </h3>
                  {improvedScore ? (
                    <span
                      className={`px-2 py-0.5 rounded text-xs font-bold border ${scoreColorByValue(
                        improvedScore
                      )}`}
                    >
                      {improvedScore}/100
                      {scoreDelta > 0 && (
                        <span className="ml-1 text-green-400">
                          (+{scoreDelta})
                        </span>
                      )}
                    </span>
                  ) : (
                    <span className="px-2 py-0.5 bg-slate-700/50 rounded text-xs text-slate-500 italic">
                      Not scored
                    </span>
                  )}
                </div>
              </div>

              {/* Question Text */}
              <div className="grid grid-cols-2 gap-4 mb-4">
                <div className="bg-slate-800/40 p-3 rounded">
                  <div
                    className="text-sm text-white leading-relaxed"
                    dangerouslySetInnerHTML={sanitizeText(
                      originalQuestion.question
                    )}
                  />
                </div>
                <div className="bg-green-900/20 p-3 rounded border border-green-700/30">
                  <div
                    className="text-sm text-white leading-relaxed"
                    dangerouslySetInnerHTML={sanitizeText(
                      improvedQuestion?.question || originalQuestion.question
                    )}
                  />
                </div>
              </div>

              {/* Answer Options */}
              <div className="text-xs font-bold text-slate-400 uppercase tracking-wide mb-2">
                Answer Options
              </div>
              <div className="space-y-1.5 mb-4">
                {["A", "B", "C", "D"].map((letter) => {
                  const originalOpt =
                    originalQuestion.options?.[letter] ||
                    originalQuestion[`option${letter}`] ||
                    "";
                  const improvedOpt = improvedQuestion
                    ? improvedQuestion.options?.[letter] ||
                      improvedQuestion[`option${letter}`] ||
                      ""
                    : originalOpt; // Fall back to original if no improvement
                  const originalCorrect =
                    originalQuestion.correctLetter === letter ||
                    originalQuestion.correct === letter;
                  const improvedCorrect = improvedQuestion
                    ? improvedQuestion.correctLetter === letter ||
                      improvedQuestion.correct === letter
                    : originalCorrect; // Fall back to original if no improvement

                  return (
                    <div key={letter} className="grid grid-cols-2 gap-4">
                      {/* Original Option */}
                      <div
                        className={`p-2 rounded text-xs border ${
                          originalCorrect
                            ? "bg-green-600/10 border-green-500/40"
                            : "bg-slate-800/40 border-slate-700/40"
                        }`}
                      >
                        <span className="font-bold text-slate-400 mr-1.5">
                          {letter})
                        </span>
                        <span className="text-white">
                          {originalOpt || "(empty)"}
                        </span>
                      </div>

                      {/* Improved Option */}
                      <div
                        className={`p-2 rounded text-xs border ${
                          improvedCorrect
                            ? "bg-green-600/10 border-green-500/40"
                            : "bg-slate-800/40 border-slate-700/40"
                        }`}
                      >
                        <span className="font-bold text-slate-400 mr-1.5">
                          {letter})
                        </span>
                        <span className="text-white">
                          {improvedOpt || "(empty)"}
                        </span>
                      </div>
                    </div>
                  );
                })}
              </div>

              {/* Tags */}
              {(originalTags.length > 0 || improvedTags.length > 0) && (
                <div>
                  <div className="text-xs font-bold text-slate-400 uppercase tracking-wide mb-2">
                    Tags
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    {/* Original Tags */}
                    <div className="flex flex-wrap gap-1.5">
                      {originalTags.length > 0 ? (
                        originalTags.map((tag, idx) => (
                          <span
                            key={idx}
                            className="px-2 py-1 bg-slate-700/50 border border-slate-600/50 rounded text-xs text-slate-300"
                          >
                            #{tag}
                          </span>
                        ))
                      ) : (
                        <span className="text-xs text-slate-500 italic">
                          No tags
                        </span>
                      )}
                    </div>

                    {/* Improved Tags */}
                    <div className="flex flex-wrap gap-1.5">
                      {improvedTags.length > 0 ? (
                        improvedTags.map((tag, idx) => {
                          const isNew = newTags.includes(tag);
                          return (
                            <span
                              key={idx}
                              className={`px-2 py-1 rounded text-xs ${
                                isNew
                                  ? "bg-green-600/30 border border-green-500/50 text-green-200"
                                  : "bg-slate-700/50 border border-slate-600/50 text-slate-300"
                              }`}
                            >
                              #{tag}
                            </span>
                          );
                        })
                      ) : (
                        <span className="text-xs text-slate-500 italic">
                          No tags
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="border-t border-slate-700 bg-slate-900/90 px-4 py-2 flex items-center justify-center gap-2.5 relative z-10 pointer-events-auto">
          <div className="flex gap-2.5">
            <button
              onClick={(e) => {
                e.stopPropagation();
                onDismiss();
              }}
              className="px-4 py-1.5 rounded-lg font-bold text-xs bg-slate-800 text-slate-300 hover:bg-slate-700 border border-slate-600 transition-all pointer-events-auto cursor-pointer"
            >
              {changesExplanation ? "Keep Original" : "Close"}
            </button>
            {changesExplanation && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  handleApply();
                }}
                disabled={isApplying}
                className="px-4 py-1.5 rounded-lg font-bold text-xs bg-green-600 text-white hover:bg-green-500 shadow-lg shadow-green-900/50 transition-all disabled:opacity-50 pointer-events-auto cursor-pointer"
              >
                {isApplying ? "Applying..." : "Apply Improvements"}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ImprovementModal;

import { useState, useEffect, useCallback } from "react";
import {
  validateInvite,
  consumeInvite,
  getInviteFromUrl,
  clearInviteFromUrl,
} from "../services/inviteService";
import {
  signInWithGoogle,
  signUpWithEmail,
  signInWithEmail,
} from "../services/firebase";
import Icon from "./Icon";
import EmailLogin from "./EmailLogin";

/**
 * InviteSignUp - Registration with invite code validation
 *
 * @param {Object} props
 * @param {Function} props.onSuccess - Called when registration completes
 * @param {Function} props.onCancel - Called when user cancels
 */
const InviteSignUp = ({ onSuccess, onCancel }) => {
  const [inviteCode, setInviteCode] = useState("");
  const [validationStatus, setValidationStatus] = useState(null);
  const [validationError, setValidationError] = useState("");
  const [inviteRole, setInviteRole] = useState("user");
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [authError, setAuthError] = useState("");

  // Email auth state
  const [showEmailAuth, setShowEmailAuth] = useState(false);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [isNewUser, setIsNewUser] = useState(true);

  // NEW: Toggle for existing user login (no invite needed)
  const [showExistingUserLogin, setShowExistingUserLogin] = useState(false);

  const handleValidate = useCallback(
    async (code) => {
      const codeToValidate = code || inviteCode;
      if (!codeToValidate.trim()) {
        setValidationError("Please enter an invite code");
        return;
      }

      setValidationStatus("validating");
      setValidationError("");

      try {
        const result = await validateInvite(codeToValidate.trim());
        if (result.valid) {
          setValidationStatus("valid");
          setInviteRole(result.role);
        }
      } catch (error) {
        setValidationStatus("invalid");
        setValidationError(error.message || "Invalid invite code");
      }
    },
    [inviteCode]
  );

  useEffect(() => {
    const urlInvite = getInviteFromUrl();
    if (urlInvite) {
      setInviteCode(urlInvite);
      handleValidate(urlInvite);
    }
  }, [handleValidate]);

  const handleGoogleSignIn = async () => {
    setIsAuthenticating(true);
    setAuthError("");
    try {
      await signInWithGoogle();
      const result = await consumeInvite(inviteCode.trim());
      clearInviteFromUrl();
      onSuccess?.(result.role);
    } catch (error) {
      let message = error.message || "Authentication failed";
      if (error.code === "auth/user-disabled") {
        message =
          "Your account has been disabled by an administrator. Please contact support if you believe this is an error.";
      }
      setAuthError(message);
      setIsAuthenticating(false);
    }
  };

  const handleEmailAuth = async (e) => {
    e.preventDefault();
    setIsAuthenticating(true);
    setAuthError("");
    try {
      if (isNewUser) {
        await signUpWithEmail(email, password);
      } else {
        await signInWithEmail(email, password);
      }
      const result = await consumeInvite(inviteCode.trim());
      clearInviteFromUrl();
      onSuccess?.(result.role);
    } catch (error) {
      let message = error.message || "Authentication failed";
      if (error.code === "auth/email-already-in-use") {
        message = "Email already registered. Try signing in instead.";
        setIsNewUser(false);
      } else if (error.code === "auth/weak-password") {
        message = "Password should be at least 6 characters.";
      } else if (error.code === "auth/wrong-password") {
        message = "Incorrect password. Try again.";
      } else if (error.code === "auth/user-disabled") {
        message =
          "Your account has been disabled by an administrator. Please contact support if you believe this is an error.";
      }
      setAuthError(message);
      setIsAuthenticating(false);
    }
  };

  const getAuthButtonText = () => {
    if (isAuthenticating) return "Please wait...";
    return isNewUser ? "Create Account" : "Sign In";
  };

  // If existing user login is toggled, show EmailLogin component
  if (showExistingUserLogin) {
    return (
      <EmailLogin
        onSuccess={() => onSuccess?.()}
        onBack={() => setShowExistingUserLogin(false)}
      />
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-8 max-w-md w-full shadow-2xl">
        {/* Header */}
        <div className="text-center mb-6">
          <div className="w-16 h-16 bg-orange-600/20 rounded-full flex items-center justify-center mx-auto mb-4">
            <Icon name="key" size={32} className="text-orange-500" />
          </div>
          <h1 className="text-2xl font-bold text-white">
            Join UE5 Question Generator
          </h1>
          <p className="text-slate-400 text-sm mt-2">
            Enter your invite code to get started
          </p>
        </div>

        <div className="space-y-4">
          {/* Invite Code Input */}
          <div>
            <label
              htmlFor="invite-code"
              className="block text-sm font-medium text-slate-300 mb-2"
            >
              Invite Code
            </label>
            <input
              id="invite-code"
              type="text"
              value={inviteCode}
              onChange={(e) => setInviteCode(e.target.value.toUpperCase())}
              placeholder="Enter your invite code"
              className="w-full px-4 py-3 bg-slate-800 border border-slate-700 rounded-lg text-white placeholder-slate-500 focus:outline-none focus:border-orange-500 font-mono tracking-wider"
              disabled={validationStatus === "valid"}
              aria-invalid={validationStatus === "invalid"}
            />
          </div>

          {/* Status Messages */}
          {validationStatus === "validating" && (
            <div className="flex items-center gap-2 text-blue-400">
              <Icon name="loader" size={16} className="animate-spin" />
              <span>Validating invite code...</span>
            </div>
          )}
          {validationStatus === "valid" && (
            <div className="flex items-center gap-2 text-green-400 bg-green-900/20 p-3 rounded-lg">
              <Icon name="check-circle" size={16} />
              <span>
                Valid invite! Role: <strong>{inviteRole}</strong>
              </span>
            </div>
          )}
          {validationError && (
            <div className="flex items-center gap-2 text-red-400 bg-red-900/20 p-3 rounded-lg">
              <Icon name="x-circle" size={16} />
              <span>{validationError}</span>
            </div>
          )}
          {authError && (
            <div className="flex items-center gap-2 text-red-400 bg-red-900/20 p-3 rounded-lg">
              <Icon name="alert-triangle" size={16} />
              <span>{authError}</span>
            </div>
          )}

          {/* Actions - Refactored to avoid nested ternaries for linting */}
          {validationStatus !== "valid" && (
            <button
              onClick={() => handleValidate()}
              disabled={validationStatus === "validating" || !inviteCode.trim()}
              className="w-full py-3 bg-orange-600 hover:bg-orange-500 disabled:bg-slate-700 disabled:cursor-not-allowed text-white font-bold rounded-lg transition-colors"
            >
              Validate Invite Code
            </button>
          )}

          {validationStatus === "valid" && showEmailAuth && (
            /* Email/Password Form */
            <form onSubmit={handleEmailAuth} className="space-y-3">
              <input
                type="email"
                placeholder="Email address"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-3 bg-slate-800 border border-slate-700 rounded-lg text-white placeholder-slate-500 focus:outline-none focus:border-orange-500"
                required
              />
              <input
                type="password"
                placeholder="Password (6+ characters)"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-3 bg-slate-800 border border-slate-700 rounded-lg text-white placeholder-slate-500 focus:outline-none focus:border-orange-500"
                required
                minLength={6}
              />
              <button
                type="submit"
                disabled={isAuthenticating}
                className="w-full py-3 bg-orange-600 hover:bg-orange-500 disabled:opacity-50 text-white font-bold rounded-lg transition-colors"
              >
                {getAuthButtonText()}
              </button>
              <button
                type="button"
                onClick={() => setIsNewUser(!isNewUser)}
                className="w-full text-sm text-slate-400 hover:text-white"
              >
                {isNewUser
                  ? "Already have an account? Sign in"
                  : "New user? Create account"}
              </button>
              <button
                type="button"
                onClick={() => setShowEmailAuth(false)}
                className="w-full text-sm text-slate-500 hover:text-slate-300"
              >
                ΓåÉ Back to sign-in options
              </button>
            </form>
          )}

          {validationStatus === "valid" && !showEmailAuth && (
            /* Auth Options */
            <div className="space-y-3">
              <button
                onClick={handleGoogleSignIn}
                disabled={isAuthenticating}
                className="w-full flex items-center justify-center gap-3 py-3 bg-white hover:bg-slate-100 text-slate-900 font-bold rounded-lg transition-colors disabled:opacity-50"
              >
                {isAuthenticating ? (
                  <Icon name="loader" size={20} className="animate-spin" />
                ) : (
                  <img
                    src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg"
                    alt="Google"
                    className="w-5 h-5"
                  />
                )}
                <span>Continue with Google</span>
              </button>
              <div className="relative py-2">
                <div className="absolute inset-0 flex items-center">
                  <div className="w-full border-t border-slate-700"></div>
                </div>
                <div className="relative flex justify-center text-xs uppercase">
                  <span className="bg-slate-900 px-2 text-slate-500">Or</span>
                </div>
              </div>
              <button
                onClick={() => setShowEmailAuth(true)}
                disabled={isAuthenticating}
                className="w-full py-3 bg-slate-800 hover:bg-slate-700 text-white font-bold rounded-lg border border-slate-700 transition-colors disabled:opacity-50"
              >
                Continue with Email
              </button>
              <p className="text-xs text-slate-500 text-center">
                Any Google or email account works. No Epic Games login required.
              </p>
            </div>
          )}

          {onCancel && !showEmailAuth && (
            <button
              onClick={onCancel}
              className="w-full py-2 text-slate-400 hover:text-white transition-colors"
            >
              Cancel
            </button>
          )}

          {/* Existing User Login Link */}
          {!showEmailAuth && (
            <div className="mt-4 pt-4 border-t border-slate-800 text-center">
              <p className="text-slate-500 text-sm mb-2">
                Already have an account?
              </p>
              <button
                onClick={() => setShowExistingUserLogin(true)}
                className="text-blue-400 hover:text-blue-300 font-medium transition-colors"
              >
                Sign in with email ΓåÆ
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

