  const userEmail = user?.email;

  const handleLockExpired = useCallback(() => {
    if (showMessage) showMessage("ΓÜá∩╕Å Edit lock expired - refreshing...", 3000);
  }, [showMessage]);

  // Auto-lock on view (review mode)
