                    question: q.suggestedRewrite.question || q.question,
                    options: q.suggestedRewrite.options || q.options,
                    optionA: q.suggestedRewrite.options?.A || q.options?.A,
                    optionB: q.suggestedRewrite.options?.B || q.options?.B,
                    optionC: q.suggestedRewrite.options?.C || q.options?.C,
                    optionD: q.suggestedRewrite.options?.D || q.options?.D,
                    correct: q.suggestedRewrite.correct || q.correct,
                    correctLetter:
                      q.suggestedRewrite.correct || q.correctLetter,
                    tags: q.suggestedRewrite.tags || q.tags,
                    critiqueScore: q.improvedScore, // AI's estimated score for the improved version
                  }
                : null
            }
            changesExplanation={
              q.suggestedRewrite?.changesExplanation ||
              q.rewriteChanges ||
              "AI improvements applied"
            }
            critiqueText={q.suggestedRewrite?.critiqueText || q.critique || ""}
            critiqueScore={q.critiqueScore || 0} // Original question's score
            improvedScore={q.improvedScore || 0} // Score AFTER applying improvements
            onApply={async (improved) => {
              // FIRST: Mark as processed to prevent useEffect from re-opening
              lastProcessedCritiqueRef.current = `applied-${
                q.id
              }-${Date.now()}`;

              // CAPTURE TRAINING DATA: Save original vs. improved for fine-tuning
              if (improved) {
                try {
                  await saveTrainingPair(q, improved, "ai_improvement");
                  logger.log("Γ£à Training pair saved for question:", q.id);
                } catch (err) {
                  logger.warn("Failed to save training pair:", err);
                }
              }

              // Apply improvements to question - keep critiqueScore for display
              await onUpdateQuestion(q.id, {
                question: improved?.question || q.question,
                options: improved?.options || q.options,
                optionA: improved?.optionA || q.optionA,
                optionB: improved?.optionB || q.optionB,
                optionC: improved?.optionC || q.optionC,
                optionD: improved?.optionD || q.optionD,
                tags: improved?.tags || q.tags,
                // Update score to the improved version immediately
                critiqueScore: q.improvedScore || q.critiqueScore,
                suggestedRewrite: null, // Clear suggestion after apply
                improvedScore: null, // Clear after applying
                improvementsApplied: true, // Mark that improvements were applied (enables Verify, prevents modal re-open)
              });

              // THEN: Close modal after update completes
              setShowImprovementModal(false);
              if (showMessage) {
                showMessage(
                  "Γ£à Improvement applied! Now verify and accept.",
                  3000
                );
              }
            }}
            onDismiss={handleModalDismiss}
          />
        )}
      </div>
    </div>
  );
};

// Custom comparison for memoization that detects critique changes
const arePropsEqual = (prevProps, nextProps) => {
  // Always re-render if critique data changed
  if (prevProps.q?.critiqueScore !== nextProps.q?.critiqueScore) return false;
  if (prevProps.q?.critique !== nextProps.q?.critique) return false;
  if (prevProps.q?.suggestedRewrite !== nextProps.q?.suggestedRewrite)
    return false;
  if (prevProps.q?.status !== nextProps.q?.status) return false;

  // Standard shallow comparison for other props
  const prevKeys = Object.keys(prevProps);
  const nextKeys = Object.keys(nextProps);
  if (prevKeys.length !== nextKeys.length) return false;

  return prevKeys.every((key) => {
    if (key === "q") {
      // For 'q' prop, compare by id/uniqueId only (content already checked above)
      return (
        prevProps.q?.id === nextProps.q?.id &&
        prevProps.q?.uniqueId === nextProps.q?.uniqueId
      );
    }
    if (key === "availableVariants") {
      // Compare variants array length and first item ID for quick check
      if (
        prevProps.availableVariants?.length !==
        nextProps.availableVariants?.length
      )
        return false;
      return true; // Deep compare omitted for perf, length + key change usually sufficient
    }
    return prevProps[key] === nextProps[key];
  });
};

export default React.memo(QuestionItem, arePropsEqual);

import { useState } from "react";
import Icon from "../Icon";
import FlagIcon from "../FlagIcon";
import { LANGUAGE_CODES, LANGUAGE_FLAGS } from "../../utils/constants";
import { logger } from "../../utils/logger";

/**
 * Get button title text based on language state
 */
const getButtonTitle = (
  lang,
  isLocked,
  lockedBy,
  isCurrent,
  exists,
  canTranslate,
  qStatus
) => {
  if (isLocked) return `Locked by ${lockedBy?.userEmail || "another user"}`;
  if (isCurrent) return `Current: ${lang}`;
  if (exists) return `Switch to ${lang}`;
  if (canTranslate) return `Translate to ${lang}`;
  if (!exists && qStatus !== "accepted")
    return `${lang} (Accept question first)`;
  return `${lang} (Unavailable)`;
};

const LanguageControls = ({
  q,
  availableVariants = [], // RENAMED from availableLanguages
  onSwitchLanguage,
  onTranslateSingle,
  isProcessing,
  userRole, // NEW: Check role for restrictions
  isLocked = false, // NEW: Lock state from concurrent editing
  lockedBy = null, // NEW: Lock owner info
  appMode, // NEW
}) => {
  const [loadingLang, setLoadingLang] = useState(null);
  // Translation generation: Only admins can create new translations
  // Non-admins (reviewers, users) can only view/switch existing translations
  const canTranslate =
    (q.language || "English") === "English" &&
    (q.status === "accepted" || appMode === "translate") && // Relax restriction in dedicated view
    q.sourceUrl &&
    !q.invalidUrl &&
    userRole === "admin";

  const allLanguages = Object.keys(LANGUAGE_FLAGS);

  return (
    <div className="flex flex-wrap gap-2 items-center pt-1 mb-3">
      {allLanguages.map((lang) => {
        const isCurrent = (q.language || "English").trim() === lang;
        const langCode =
          LANGUAGE_CODES[lang] || lang.substring(0, 2).toUpperCase();

        // Check if translation exists for THIS specific language
        // Use the variants array passed from parent
        const exists =
          isCurrent ||
          lang === "English" ||
          availableVariants.some((v) => (v.language || "English") === lang);

        const isLoading = loadingLang === lang;

        // Interaction logic
        const handleClick = (e) => {
          e.stopPropagation();

          // LOCK ENFORCEMENT: Exit immediately if locked by another user
          if (isLocked) {
            logger.log(
              "≡ƒöÆ [LanguageControls] Translation blocked - question is locked"
            );
            return;
          }

          if (isCurrent) return; // Do nothing if clicking current

          if (exists) {
            // Trigger local toggle in QuestionItem
            onSwitchLanguage(lang);
          } else if (canTranslate) {
            setLoadingLang(lang);
            onTranslateSingle(q, lang)
              .then(() => {
                setLoadingLang(null);
              })
              .catch((err) => {
                logger.error("Γ¥î [LanguageControls] Translation failed:", err);
                setLoadingLang(null);
              });
          }
        };

        // Style logic
        let containerClass =
          "relative group flex items-center justify-center p-0.5 rounded transition-all duration-200 ";

        if (isLocked) {
          // Locked state - grayed out regardless of other conditions
          containerClass +=
            "border border-slate-800 opacity-30 grayscale cursor-not-allowed";
        } else if (isCurrent) {
          containerClass +=
            "border-2 border-indigo-500 bg-indigo-500/20 shadow-[0_0_10px_rgba(99,102,241,0.5)] scale-110 z-10";
        } else if (exists) {
          containerClass +=
            "border border-slate-600 hover:border-green-500 hover:scale-110 cursor-pointer opacity-100";
        } else if (canTranslate) {
          containerClass +=
            "border border-slate-700 hover:border-orange-500 hover:bg-slate-800 cursor-pointer opacity-40 hover:opacity-100 grayscale hover:grayscale-0";
        } else {
          containerClass +=
            "border border-slate-800 opacity-20 grayscale cursor-not-allowed";
        }

        return (
          <button
            key={lang}
            onClick={handleClick}
            disabled={
              isProcessing ||
              isLoading ||
              isLocked ||
              (!exists && !canTranslate)
            }
            className={containerClass}
            title={getButtonTitle(
              lang,
              isLocked,
              lockedBy,
              isCurrent,
              exists,
              canTranslate,
              q.status
            )}
          >
            {isLoading ? (
              <Icon
                name="loader"
                size={16}
                className="animate-spin text-orange-500"
              />
            ) : (
              <>
                <FlagIcon code={langCode} size={18} />
                {/* Plus icon overlay for missing but available translations */}
                {!exists && canTranslate && !isLoading && (
                  <div className="absolute -top-1 -right-1 bg-slate-900 rounded-full p-[1px] border border-slate-700 text-orange-500 shadow-sm group-hover:scale-110 transition-transform">
                    <Icon name="plus" size={8} />
                  </div>
                )}
              </>
            )}
          </button>
        );
      })}
    </div>
  );
};

