          <Icon name="alert-octagon" size={16} />
          <span className="text-xs font-bold">
            ΓÜá∩╕Å ANSWER MAY BE WRONG - Check Source!
          </span>
        </div>
      )}

      {/* Source Verification Badge */}
      {q.sourceVerified !== undefined && (
        <div
          className={`flex items-center gap-2 px-2 py-1 rounded text-[10px] font-bold uppercase ${verification.bg} ${verification.color} mb-2`}
          title={verification.title}
        >
          <Icon name={verification.icon} size={12} />
          <span>{verification.label}</span>
        </div>
      )}

      {/* Tags Display with Auto-Tag Button */}
      <div className="flex items-center gap-2 mb-2">
        {q.tags && q.tags.length > 0 && (
          <div className="flex items-center gap-1 text-[9px] text-slate-500 flex-1">
            <span className="text-slate-600">Tags:</span>
            {[...new Set(q.tags)].map((tag, idx) => (
              <span
                key={`${idx}-${tag}`}
                className="px-1.5 py-0.5 rounded bg-slate-800/50 text-slate-400 border border-slate-700/50 hover:text-slate-300 transition-colors"
              >
                {tag}
              </span>
            ))}
            {/* AI Score as a Tag (as user requested) */}
            {q.critiqueScore !== undefined && q.critiqueScore !== null && (
              <span className="px-1.5 py-0.5 rounded bg-indigo-950/40 text-indigo-300 border border-indigo-700/50 font-bold">
                AI Score: {q.critiqueScore}
              </span>
            )}
          </div>
        )}

        {/* Auto-Tag Button */}
        {onAutoTag && (hasLowTags || q.status === "pending") && (
          <button
            onClick={() => onAutoTag(q)}
            disabled={isProcessing}
            className={`px-2 py-1 text-[10px] font-medium rounded border transition-all flex items-center gap-1 ${
              hasLowTags
                ? "bg-cyan-900/30 border-cyan-700/50 text-cyan-400 hover:bg-cyan-800/40 hover:border-cyan-600"
                : "bg-slate-800/50 border-slate-600 text-slate-400 hover:bg-slate-700 hover:border-slate-500"
            } ${isProcessing ? "opacity-50 cursor-not-allowed" : ""}`}
            title={
              hasLowTags
                ? `Add tags (current: ${q.tags?.length || 0}/3)`
                : "Generate AI tags for this question"
            }
          >
            <Icon name="tag" size={12} />
            {hasLowTags ? `Add Tags (${q.tags?.length || 0}/3)` : "Auto-Tag"}
          </button>
        )}
      </div>

      {/* Grounding Sources (if available) */}
      {q.groundingSources && q.groundingSources.length > 0 && (
        <div className="mt-2 p-2 bg-indigo-950/20 border border-indigo-800/30 rounded">
          <div className="text-[10px] text-indigo-400 font-bold uppercase mb-1 flex items-center gap-1">
            <Icon name="search" size={10} />
            Grounding Sources Used:
          </div>
          <div className="flex flex-col gap-1">
            {q.groundingSources.map((src, i) => (
              <a
                key={i}
                href={src.url}
                target="_blank"
                rel="noopener noreferrer"
                className="text-[10px] text-indigo-300 hover:text-indigo-200 hover:underline truncate"
                title={src.url}
              >
                {src.title || getDisplayUrl(src.url)}
              </a>
            ))}
          </div>
        </div>
      )}

      {/* Generation Metrics Footer */}
      <div className="mt-3 pt-2 border-t border-slate-800/50 flex items-center justify-between text-[10px] text-slate-600 font-mono">
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-1" title="Estimated Cost">
            <Icon name="dollar-sign" size={10} />
            <span>${(q.estimatedCost || 0).toFixed(5)}</span>
          </div>
          <div className="flex items-center gap-1" title="Generation Time">
            <Icon name="clock" size={10} />
            <span>
              {q.generationTime ? (q.generationTime / 1000).toFixed(2) : "0.00"}
              s
            </span>
          </div>
        </div>
        <div className="flex items-center gap-1" title="AI Model">
          <Icon name="cpu" size={10} />
          <span className="uppercase">{q.model || "Gemini 2.0 Flash"}</span>
        </div>
      </div>
    </>
  );
};

export default QuestionMetadata;

import React, { useState } from "react";
import { logger } from "../../utils/logger";

const QuestionNotesField = ({ question, onUpdateQuestion, showMessage }) => {
  const [notes, setNotes] = useState(question.notes || "");
  const [isSaving, setIsSaving] = useState(false);

  const handleSave = async () => {
    if (notes === (question.notes || "")) {
      // No changes
      return;
    }

    setIsSaving(true);
    try {
      await onUpdateQuestion(question.id, { notes });
      if (showMessage) {
        showMessage("Γ£ô Notes saved", 2000);
      }
    } catch (error) {
      logger.error("Failed to save notes:", error);
      if (showMessage) {
        showMessage("ΓÜá∩╕Å Failed to save notes", 3000);
      }
    } finally {
      setIsSaving(false);
    }
  };

  const handleBlur = () => {
    if (notes !== (question.notes || "")) {
      handleSave();
    }
  };

  return (
    <div className="mt-3 border-t border-slate-700 pt-3">
      <label className="block text-xs font-semibold text-slate-400 mb-1">
        Internal Notes
      </label>
      <textarea
        value={notes}
        onChange={(e) => setNotes(e.target.value)}
        onBlur={handleBlur}
        placeholder="Add notes about this question (internal use only)..."
        className="w-full px-3 py-2 bg-slate-800/50 border border-slate-700 rounded-lg text-sm text-slate-300 placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-purple-500/50 focus:border-purple-500 transition-all resize-y min-h-[60px]"
        disabled={isSaving}
        maxLength={500}
      />
      <div className="flex justify-between items-center mt-1">
        {isSaving && <p className="text-xs text-slate-500">Saving...</p>}
        <div className="flex-1"></div>
        <span
          className={`text-xs text-right ${
            notes.length >= 500
              ? "text-red-400"
              : notes.length >= 450
              ? "text-orange-400"
              : "text-slate-500"
          }`}
        >
          {notes.length} / 500 characters
        </span>
      </div>
    </div>
  );
};

export default QuestionNotesField;

import React from "react";
import Icon from "../Icon";

const ValidationWarnings = ({ q }) => {
  if (!q._validation?.isValid && !q.answerMismatch && !q.invalidUrl) {
    return null;
  }

  const hasAnswerWarning =
    q.answerMismatch ||
    (q._validation &&
      !q._validation.isValid &&
      q._validation.warnings.some((w) => w.includes("Answer")));

  const hasUrlWarning =
    q.invalidUrl ||
    (q._validation &&
      !q._validation.isValid &&
      q._validation.warnings.some((w) => w.includes("URL")));

  const hasTagWarning = !q.tags || q.tags.length < 3;

  const criticalWarnings =
    q._validation && !q._validation.isValid
      ? q._validation.warnings.filter((w) => w.startsWith("Critical"))
      : [];

  const hasCriticalWarnings = criticalWarnings.length > 0;

  if (
    !hasAnswerWarning &&
    !hasUrlWarning &&
    !hasTagWarning &&
    !hasCriticalWarnings
  ) {
    return null;
  }

  return (
    <div className="pl-6 mb-3 flex flex-col gap-2">
      {/* Critical Validation Errors */}
      {hasCriticalWarnings && (
        <div className="flex flex-col gap-1 p-2 bg-red-950/60 border border-red-600/60 rounded text-red-200 text-xs animate-in fade-in slide-in-from-top-1">
          <div className="flex items-center gap-2 font-bold text-red-400">
            <Icon name="x-circle" size={14} />
            <span>Critical Validation Failed:</span>
          </div>
          <ul className="list-disc list-inside pl-1 opacity-90">
            {criticalWarnings.map((w, i) => (
              <li key={i}>{w.replace("Critical: ", "")}</li>
            ))}
          </ul>
        </div>
      )}
      {/* Answer Mismatch Warning */}
      {hasAnswerWarning && (
        <div className="flex items-center gap-2 p-2 bg-yellow-950/40 border border-yellow-700/40 rounded text-yellow-200 text-xs animate-in fade-in slide-in-from-top-1">
          <Icon name="alert-triangle" size={14} className="text-yellow-500" />
          <span>
            <strong>Warning:</strong> Answer may not match source excerpt.
            Verify carefully.
          </span>
        </div>
      )}

      {/* Invalid URL Warning */}
      {hasUrlWarning && (
        <div className="flex items-center gap-2 p-2 bg-red-950/40 border border-red-700/40 rounded text-red-200 text-xs animate-in fade-in slide-in-from-top-1">
          <Icon name="link" size={14} className="text-red-500" />
          <span>
            <strong>Warning:</strong> Source URL may be invalid or generic.
          </span>
        </div>
      )}

      {/* Low Tag Count Warning */}
      {hasTagWarning && (
        <div className="flex items-center gap-2 p-2 bg-blue-950/40 border border-blue-700/40 rounded text-blue-200 text-xs animate-in fade-in slide-in-from-top-1">
          <Icon name="tag" size={14} className="text-blue-500" />
          <span>
            <strong>Suggestion:</strong> Question has fewer than 3 tags.
            Consider adding more.
          </span>
        </div>
      )}
    </div>
  );
};

export default ValidationWarnings;

import { useState } from 'react';
import Icon from '../Icon';

/**
 * QuestionVariationCarousel
 * Shows original question + its alternatives in a carousel interface
 */
const QuestionVariationCarousel = ({ originalQuestion, alternatives, onSelectVariation }) => {
    const allVersions = [originalQuestion, ...alternatives];
    const [currentIndex, setCurrentIndex] = useState(0);
    const currentQuestion = allVersions[currentIndex];

    const canGoPrev = currentIndex > 0;
    const canGoNext = currentIndex < allVersions.length - 1;

    const handlePrev = () => {
        if (canGoPrev) setCurrentIndex(prev => prev - 1);
    };

    const handleNext = () => {
        if (canGoNext) setCurrentIndex(prev => prev + 1);
    };

    const handleSelect = () => {
        if (onSelectVariation) {
            onSelectVariation(currentQuestion);
        }
    };

    return (
        <div className="border-2 border-purple-500/50 rounded-lg p-4 bg-purple-950/20">
            {/* Navigation Header */}
            <div className="flex items-center justify-between mb-4 pb-3 border-b border-purple-500/30">
                <button
                    onClick={handlePrev}
                    disabled={!canGoPrev}
                    className="flex items-center gap-2 px-3 py-2 rounded bg-slate-800 hover:bg-slate-700 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                    title="Previous variation"
                >
                    <Icon name="arrow-left" size={16} />
                    <span className="text-sm font-bold">PREV</span>
                </button>

                <div className="flex flex-col items-center">
                    <span className="text-xs uppercase tracking-widest text-purple-400 font-bold mb-1">
                        {currentIndex === 0 ? '≡ƒô¥ Original' : `≡ƒöä Alternative ${currentIndex}`}
                    </span>
                    <span className="text-lg font-bold">
                        <span className="text-white">{currentIndex + 1}</span>
                        <span className="text-slate-600 mx-1">/</span>
                        <span className="text-slate-400">{allVersions.length}</span>
                    </span>
                </div>

                <button
                    onClick={handleNext}
                    disabled={!canGoNext}
                    className="flex items-center gap-2 px-3 py-2 rounded bg-slate-800 hover:bg-slate-700 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                    title="Next variation"
                >
                    <span className="text-sm font-bold">NEXT</span>
                    <Icon name="arrow-right" size={16} />
                </button>
            </div>

            {/* Question Display */}
            <div className="mb-4">
                <h3 className="text-base font-medium text-slate-200 leading-relaxed mb-3">
                    {currentQuestion.question}
                </h3>

                {/* Options */}
                {currentQuestion.type === 'Multiple Choice' && (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                        {Object.entries(currentQuestion.options || {}).map(([key, val]) => {
                            const isCorrect = currentQuestion.correct === key;
                            return (
                                <div 
                                    key={key} 
                                    className={`text-sm p-2 rounded border transition-all ${
                                        isCorrect 
                                            ? 'bg-green-700/50 border-green-400 text-white' 
                                            : 'bg-slate-950 border-slate-800 text-slate-400'
                                    }`}
                                >
                                    <span className={`font-bold mr-2 ${isCorrect ? 'text-white' : 'text-slate-600'}`}>
                                        {key})
                                    </span>
                                    <span>{val}</span>
                                </div>
                            );
                        })}
                    </div>
                )}

                {currentQuestion.type === 'True/False' && (
                    <div className="flex gap-4">
                        <div className={`px-3 py-1 rounded text-xs border transition-all ${
                            currentQuestion.correct === 'A' 
                                ? 'bg-green-700/50 border-green-400 text-white' 
                                : 'bg-slate-950 border-slate-800 text-slate-500'
                        }`}>
                            TRUE
                        </div>
                        <div className={`px-3 py-1 rounded text-xs border transition-all ${
                            currentQuestion.correct === 'B' 
                                ? 'bg-red-700/50 border-red-400 text-white' 
                                : 'bg-slate-950 border-slate-800 text-slate-500'
                        }`}>
                            FALSE
                        </div>
                    </div>
                )}
            </div>

            {/* Action: Select This Version */}
            {currentIndex > 0 && (
                <div className="flex justify-center pt-3 border-t border-purple-500/30">
                    <button
                        onClick={handleSelect}
                        className="px-6 py-2 rounded-lg bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-500 hover:to-indigo-500 text-white font-bold transition-all shadow-lg"
                    >
                        <Icon name="check" size={16} className="inline mr-2" />
                        Use This Alternative
                    </button>
                </div>
            )}
        </div>
    );
};

export default QuestionVariationCarousel;

