/**
 * QuizPreview - Interactive quiz component with SCORM reporting
 *
 * NOTE: Regex patterns are for HTML tag stripping in accessibility announcements.
 * Input is question text from app database - controlled, no DoS risk.
 */
/* eslint-disable sonarjs/slow-regex */
import { useState, useEffect, useCallback, useMemo } from "react";
import Icon from "./Icon";
import { sanitizeText } from "../utils/sanitize";
import {
  generateGUID,
  createSeededRandom,
  seededShuffle,
  reportToSCORM,
} from "../utils/quizUtils";
import { logger } from "../utils/logger";

/**
 * QuizPreview - Simplified interactive quiz component
 *
 * Features:
 * - Balanced difficulty distribution (interleaves Easy/Medium/Hard)
 * - Confidence boost: gives easy question after 2 wrong in a row
 * - Fixed question count and timer
 * - Static A, B, C, D answer display
 */
const QuizPreview = ({ questions, config, onClose }) => {
  // Core quiz state
  const [quizGuid, setQuizGuid] = useState(null); // Unique GUID for this quiz instance
  const [quizQuestions, setQuizQuestions] = useState([]); // Built once at start
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState({}); // Simple: { questionId: "A" }
  const [wrongStreak, setWrongStreak] = useState(0);
  const [showResults, setShowResults] = useState(false);
  const [timeRemaining, setTimeRemaining] = useState(config.timeLimit * 60);
  const [quizStarted, setQuizStarted] = useState(false);
  const [showAnswerWarning, setShowAnswerWarning] = useState(false);
  const [quizStartTime, setQuizStartTime] = useState(null);

  // Accessibility state
  const [focusedOptionIndex, setFocusedOptionIndex] = useState(0);
  const [announceMessage, setAnnounceMessage] = useState("");

  // Derived state - must be before useEffect hooks that use them
  const currentQuestion = quizQuestions[currentIndex];
  const totalQuestions = quizQuestions.length;
  const questionId = currentQuestion?.id || currentQuestion?.uniqueId;
  const selectedAnswer = answers[questionId];
  const isAnswered = selectedAnswer !== undefined;

  /**
   * Build a balanced question list at quiz start
   * Uses seeded randomization for reproducibility
   * Interleaves Easy, Medium, Hard to avoid clustering
   */
  const buildBalancedQuestionList = useCallback(
    (guid) => {
      const randomFn = createSeededRandom(guid);

      // Filter to English-only questions first
      const englishQuestions = questions.filter((q) => {
        const lang = (q.language || "").toLowerCase();
        return lang === "" || lang === "english" || lang === "en";
      });

      const easy = englishQuestions.filter((q) =>
        (q.difficulty || "").toLowerCase().includes("easy")
      );
      const medium = englishQuestions.filter((q) =>
        (q.difficulty || "").toLowerCase().includes("medium")
      );
      const hard = englishQuestions.filter((q) =>
        (q.difficulty || "").toLowerCase().includes("hard")
      );

      // Shuffle each pool using seeded random
      const shuffledEasy = seededShuffle(easy, randomFn);
      const shuffledMedium = seededShuffle(medium, randomFn);
      const shuffledHard = seededShuffle(hard, randomFn);

      // Interleave: E-M-H-E-M-H...
      const distributed = [];
      const maxLen = Math.max(
        shuffledEasy.length,
        shuffledMedium.length,
        shuffledHard.length
      );

      for (let i = 0; i < maxLen; i++) {
        if (shuffledEasy[i]) distributed.push(shuffledEasy[i]);
        if (shuffledMedium[i]) distributed.push(shuffledMedium[i]);
        if (shuffledHard[i]) distributed.push(shuffledHard[i]);
      }

      // Take only what we need
      return distributed.slice(0, config.questionCount || distributed.length);
    },
    [questions, config.questionCount]
  );

  // Generate GUID and build question list when quiz starts
  useEffect(() => {
    if (quizStarted && !quizGuid) {
      const guid = generateGUID();
      setQuizGuid(guid);
      setQuizStartTime(Date.now());
      setQuizQuestions(buildBalancedQuestionList(guid));
      logger.log("Quiz started with GUID:", guid);
    }
  }, [quizStarted, quizGuid, buildBalancedQuestionList]);

  // Anti-cheating: Block keyboard shortcuts and track tab visibility
  useEffect(() => {
    if (!quizStarted || showResults) return;

    const handleKeydown = (e) => {
      // Block common cheating shortcuts
      if (
        (e.ctrlKey || e.metaKey) &&
        (e.key === "c" || // Copy
          e.key === "v" || // Paste
          e.key === "f" || // Find
          e.key === "p" || // Print
          e.key === "s") // Save
      ) {
        e.preventDefault();
        logger.log("Anti-cheat: Blocked keyboard shortcut");
      }
    };

    const handleCopy = (e) => {
      e.preventDefault();
      logger.log("Anti-cheat: Blocked copy attempt");
    };

    const handleVisibilityChange = () => {
      if (document.hidden) {
        logger.log("Anti-cheat: Quiz tab lost focus", {
          quizGuid,
          timestamp: new Date().toISOString(),
          questionIndex: currentIndex,
        });
      }
    };

    document.addEventListener("keydown", handleKeydown);
    document.addEventListener("copy", handleCopy);
    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      document.removeEventListener("keydown", handleKeydown);
      document.removeEventListener("copy", handleCopy);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [quizStarted, showResults, quizGuid, currentIndex]);

  // Accessibility: Keyboard navigation for quiz questions
  useEffect(() => {
    if (!quizStarted || showResults || !currentQuestion) return;

    const optionKeys = Object.keys(getOptions(currentQuestion));

    const handleKeyDown = (e) => {
      // Arrow key navigation between options
      if (e.key === "ArrowDown" || e.key === "ArrowRight") {
        e.preventDefault();
        setFocusedOptionIndex((prev) => {
          const newIndex = (prev + 1) % optionKeys.length;
          setAnnounceMessage(
            `Option ${optionKeys[newIndex]}, ${
              optionKeys.length - newIndex
            } of ${optionKeys.length}`
          );
          return newIndex;
        });
      } else if (e.key === "ArrowUp" || e.key === "ArrowLeft") {
        e.preventDefault();
        setFocusedOptionIndex((prev) => {
          const newIndex = prev === 0 ? optionKeys.length - 1 : prev - 1;
          setAnnounceMessage(
            `Option ${optionKeys[newIndex]}, ${newIndex + 1} of ${
              optionKeys.length
            }`
          );
          return newIndex;
        });
      }
      // Enter or Space to select focused option
      else if ((e.key === "Enter" || e.key === " ") && !selectedAnswer) {
        e.preventDefault();
        const selectedKey = optionKeys[focusedOptionIndex];
        handleAnswer(selectedKey);
        setAnnounceMessage(`Selected option ${selectedKey}`);
      }
      // N key for Next Question (when answer is selected)
      else if (e.key === "n" && selectedAnswer) {
        e.preventDefault();
        handleNext();
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [
    quizStarted,
    showResults,
    currentQuestion,
    focusedOptionIndex,
    selectedAnswer,
    handleAnswer,
    handleNext,
    getOptions,
  ]);

  // Reset focused option when question changes
  useEffect(() => {
    setFocusedOptionIndex(0);
    if (currentQuestion) {
      setAnnounceMessage(
        `Question ${
          currentIndex + 1
        } of ${totalQuestions}: ${currentQuestion.question.replace(
          /<[^>]*>/g,
          ""
        )}`
      );
    }
  }, [currentIndex, currentQuestion, totalQuestions]);

  // Timer
  useEffect(() => {
    if (!quizStarted || showResults) return;

    const timer = setInterval(() => {
      setTimeRemaining((prev) => {
        if (prev <= 1) {
          setShowResults(true);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [quizStarted, showResults]);

  // Format time display
  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, "0")}`;
  };

  // Handle answer selection
  const handleAnswer = useCallback(
    (selectedKey) => {
      if (!currentQuestion) return;

      const questionId = currentQuestion.id || currentQuestion.uniqueId;
      const isCorrect = selectedKey === currentQuestion.correct;

      // Store just the key
      setAnswers((prev) => ({ ...prev, [questionId]: selectedKey }));

      // Update wrong streak
      if (isCorrect) {
        setWrongStreak(0);
      } else {
        setWrongStreak((prev) => prev + 1);
      }
    },
    [currentQuestion]
  );

  // Handle next question with confidence boost
  const handleNext = useCallback(() => {
    setShowAnswerWarning(false);

    if (currentIndex + 1 >= totalQuestions) {
      setShowResults(true);
      return;
    }

    // Confidence boost: if 2+ wrong in a row, try to give an easy question next
    if (wrongStreak >= 2) {
      const answeredIds = new Set(Object.keys(answers));
      const upcomingQuestions = quizQuestions.slice(currentIndex + 1);

      // Find first easy question in upcoming that hasn't been answered
      const easyIndex = upcomingQuestions.findIndex(
        (q) =>
          (q.difficulty || "").toLowerCase().includes("easy") &&
          !answeredIds.has(q.id || q.uniqueId)
      );

      if (easyIndex > 0) {
        // Swap the easy question to be next
        const newQuestions = [...quizQuestions];
        const easyQ = newQuestions[currentIndex + 1 + easyIndex];
        const nextQ = newQuestions[currentIndex + 1];
        newQuestions[currentIndex + 1] = easyQ;
        newQuestions[currentIndex + 1 + easyIndex] = nextQ;
        setQuizQuestions(newQuestions);
      }
    }

    setCurrentIndex((prev) => prev + 1);
  }, [currentIndex, totalQuestions, wrongStreak, answers, quizQuestions]);

  // Calculate results
  const results = useMemo(() => {
    let correct = 0;
    const total = Object.keys(answers).length;

    quizQuestions.forEach((q) => {
      const qId = q.id || q.uniqueId;
      if (answers[qId] === q.correct) {
        correct++;
      }
    });

    const percentage = total > 0 ? Math.round((correct / total) * 100) : 0;
    const passed = percentage >= config.passingScore;

    return { correct, total, percentage, passed };
  }, [answers, quizQuestions, config.passingScore]);

  // Get options for display (static A, B, C, D - always in order)
  const getOptions = (question) => {
    if (!question?.options) return {};
    return Object.entries(question.options)
      .filter(([, value]) => value)
      .sort(([a], [b]) => a.localeCompare(b)) // Ensure A, B, C, D order
      .reduce((acc, [key, value]) => {
        // Normalize TRUE/FALSE to proper capitalization
        let displayValue = value;
        if (value === "TRUE") displayValue = "True";
        if (value === "FALSE") displayValue = "False";
        acc[key] = displayValue;
        return acc;
      }, {});
  };

  // Report results to SCORM when quiz completes
  useEffect(() => {
    if (showResults && quizGuid && quizStartTime) {
      const timeSpent = Math.floor((Date.now() - quizStartTime) / 1000);
      reportToSCORM(results, quizGuid, timeSpent);
    }
  }, [showResults, results, quizGuid, quizStartTime]);

  // ========== UI RENDERING (unchanged from before) ==========

  // Start screen
  if (!quizStarted) {
    return (
      <div
        className="fixed inset-0 bg-slate-900 z-[9999] flex items-center justify-center p-4 select-none"
        onContextMenu={(e) => e.preventDefault()}
      >
        <div className="max-w-lg w-full text-center">
          <div className="mb-8">
            {/* Unreal Engine Logo */}
            <img
              src="/UE5QuestionGenerator/logos/UE-Secondary-Logo-2023-Horizontal-White.svg"
              alt="Unreal Engine"
              className="h-12 mx-auto mb-6"
            />
            <h2 className="text-2xl font-bold text-white mb-2">
              Assessment Preview
            </h2>
            <p className="text-slate-400">
              Test your knowledge with{" "}
              {config.questionCount || questions.length} questions
            </p>
          </div>

          {/* Quiz info */}
          <div className="bg-slate-800 rounded-lg p-6 mb-8 text-left">
            <div className="space-y-4">
              <div className="flex justify-between items-center">
                <span className="text-slate-400">Questions</span>
                <span className="text-white font-medium">
                  {config.questionCount || questions.length}
                </span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-slate-400">Time Limit</span>
                <span className="text-white font-medium">
                  {config.timeLimit} minutes
                </span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-slate-400">Passing Score</span>
                <span className="text-white font-medium">
                  {config.passingScore}%
                </span>
              </div>
            </div>
          </div>

          {/* Instructions */}
          <div
            className="bg-slate-800/50 rounded-lg p-4 mb-8 text-left"
            role="region"
            aria-label="Assessment instructions"
          >
            <h3 className="text-sm font-semibold text-slate-300 mb-3">
              How This Assessment Works
            </h3>
            <ul className="text-sm text-slate-400 space-y-2">
              <li className="flex items-start gap-2">
                <span className="text-blue-400">ΓÇó</span>
                Read each question carefully before selecting your answer
              </li>
              <li className="flex items-start gap-2">
                <span className="text-blue-400">ΓÇó</span>
                Click on your chosen answer to select it
              </li>
              <li className="flex items-start gap-2">
                <span className="text-blue-400">ΓÇó</span>
                Use the &quot;Next Question&quot; button to proceed
              </li>
              <li className="flex items-start gap-2">
                <span className="text-blue-400">ΓÇó</span>
                Keep an eye on the timer in the top right
              </li>
              <li className="flex items-start gap-2">
                <span className="text-blue-400">ΓÇó</span>
                Your results will be shown at the end
              </li>
            </ul>
          </div>

          {/* Actions */}
          <div className="flex gap-4 justify-center">
            <button
              onClick={onClose}
              className="px-6 py-3 bg-slate-700 hover:bg-slate-600 text-white rounded-lg font-medium transition-colors"
            >
              Go Back
            </button>
            <button
              onClick={() => setQuizStarted(true)}
              className="px-8 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-semibold transition-colors"
            >
              Start Assessment
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Results screen
  if (showResults) {
    return (
      <div
        className="fixed inset-0 bg-slate-900 z-[9999] flex items-center justify-center p-4 select-none"
        onContextMenu={(e) => e.preventDefault()}
      >
        <div className="max-w-lg w-full text-center">
          {/* UE Branding */}
          <img
            src="/UE5QuestionGenerator/logos/UE-Secondary-Logo-2023-Horizontal-White.svg"
            alt="Unreal Engine"
            className="h-8 mx-auto mb-8 opacity-60"
          />

          <div
            className={`text-6xl mb-4 ${
              results.passed ? "text-green-400" : "text-red-400"
            }`}
          >
            {results.passed ? (
              <Icon name="check-circle" size={64} className="mx-auto" />
            ) : (
              <Icon name="x-circle" size={64} className="mx-auto" />
            )}
          </div>

          <h2 className="text-2xl font-bold text-white mb-2">
            {results.passed ? "Assessment Passed!" : "Assessment Not Passed"}
          </h2>

          <p className="text-slate-400 mb-8">
            You scored {results.percentage}% ({results.correct} of{" "}
            {results.total} correct)
          </p>

          <div className="bg-slate-800 rounded-lg p-6 mb-8">
            <div className="grid grid-cols-2 gap-4 text-center">
              <div>
                <div className="text-3xl font-bold text-white">
                  {results.correct}
                </div>
                <div className="text-sm text-slate-400">Correct</div>
              </div>
              <div>
                <div className="text-3xl font-bold text-white">
                  {results.total - results.correct}
                </div>
                <div className="text-sm text-slate-400">Incorrect</div>
              </div>
            </div>
          </div>

          <button
            onClick={onClose}
            className="px-8 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-semibold transition-colors"
          >
            Close Preview
          </button>

          <p className="text-xs text-slate-500 mt-6">
            ┬⌐ 2025 Epic Games, Inc. Unreal and its logo are registered
            trademarks.
          </p>
        </div>
      </div>
    );
  }

  // No questions available
  if (!currentQuestion) {
    return (
      <div
        className="fixed inset-0 bg-slate-900 z-[9999] flex items-center justify-center select-none"
        onContextMenu={(e) => e.preventDefault()}
      >
        <div className="bg-slate-800 p-8 rounded-lg text-center max-w-sm">
          <Icon
            name="alert-triangle"
            size={48}
            className="mx-auto text-yellow-500 mb-4"
          />
          <h3 className="text-xl font-bold text-white mb-2">
            No questions available
          </h3>
          <p className="text-slate-400 mb-6">
            There are no questions in the selection.
          </p>
          <button
            onClick={onClose}
            className="px-6 py-2 bg-slate-700 hover:bg-slate-600 text-white rounded font-medium transition-colors"
          >
            Go Back
          </button>
        </div>
      </div>
    );
  }

  const options = getOptions(currentQuestion);

  // Question screen
  return (
    <div
      className="fixed inset-0 bg-slate-900 z-[9999] flex flex-col select-none"
      onContextMenu={(e) => e.preventDefault()}
    >
      {/* Screen reader announcements */}
      <div
        role="status"
        aria-live="polite"
        aria-atomic="true"
        className="sr-only"
      >
        {announceMessage}
      </div>

      {/* Header */}
      <div className="bg-slate-800 border-b border-slate-700 px-6 py-4">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-4">
            {/* UE Icon */}
            <img
              src="/UE5QuestionGenerator/logos/UE-Icon-2023-White.svg"
              alt="Unreal Engine"
              className="h-6 w-6 opacity-80"
            />
            <span className="text-white font-semibold">
              Question {currentIndex + 1} of {totalQuestions}
            </span>
          </div>

          <div className="flex items-center gap-4">
            <div
              className={`flex items-center gap-2 ${
                timeRemaining < 60 ? "text-red-400" : "text-slate-300"
              }`}
            >
              <Icon name="clock" size={18} />
              <span className="font-mono">{formatTime(timeRemaining)}</span>
            </div>
            <button
              onClick={onClose}
              className="text-slate-400 hover:text-white transition-colors"
              aria-label="Close quiz"
            >
              <Icon name="x" size={24} />
            </button>
          </div>
        </div>
      </div>

      {/* Progress bar */}
      <div
        className="h-1 bg-slate-700"
        role="progressbar"
        aria-valuenow={currentIndex + 1}
        aria-valuemin={1}
        aria-valuemax={totalQuestions}
      >
        <div
          className="h-full bg-blue-500 transition-all duration-300"
          style={{
            width: `${((currentIndex + 1) / totalQuestions) * 100}%`,
          }}
        />
      </div>

      {/* Question content */}
      <div className="flex-1 overflow-auto p-6">
        <div className="max-w-2xl mx-auto">
          {/* Question type badge */}
          <div className="mb-4">
            <span
              className={`px-3 py-1 rounded-full text-xs font-medium ${
                currentQuestion.type === "True/False" ||
                Object.keys(options).length === 2
                  ? "bg-purple-900/50 text-purple-300 border border-purple-700"
                  : "bg-blue-900/50 text-blue-300 border border-blue-700"
              }`}
            >
              {currentQuestion.type === "True/False" ||
              Object.keys(options).length === 2
                ? "Γ£ôΓ£ù True/False"
                : "ΓùÄ Multiple Choice"}
            </span>
          </div>

          <h2
            className="text-xl text-white mb-6 leading-relaxed"
            dangerouslySetInnerHTML={sanitizeText(currentQuestion.question)}
          />

          {/* Calming instruction */}
          <p className="text-sm text-slate-400 mb-4">
            {currentQuestion.type === "True/False" ||
            Object.keys(options).length === 2
              ? "Select True or False:"
              : "Select the best answer:"}
          </p>

          {/* Keyboard navigation hint */}
          <p className="text-xs text-slate-500 mb-4 italic">
            Use arrow keys to navigate, Enter/Space to select, N for next
            question
          </p>

          {/* Options */}
          <div className="space-y-4" role="listbox" aria-label="Answer options">
            {Object.entries(options).map(([key, text], index) => {
              const isSelected = selectedAnswer === key;
              const isFocused = index === focusedOptionIndex;

              return (
                <button
                  key={key}
                  onClick={() => !isAnswered && handleAnswer(key)}
                  disabled={isAnswered}
                  role="option"
                  aria-selected={isSelected}
                  aria-label={`Option ${key}: ${text}${
                    isSelected ? ", selected" : ""
                  }`}
                  className={`w-full text-left p-4 rounded-lg border-2 transition-all focus:outline-none ${
                    isFocused
                      ? "ring-4 ring-yellow-400 ring-offset-2 ring-offset-slate-900"
                      : ""
                  } ${
                    isSelected
                      ? "border-blue-500 bg-blue-900/30"
                      : "border-slate-600 hover:border-slate-500 bg-slate-800"
                  }`}
                >
                  <div className="flex items-center gap-4">
                    <span
                      className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold ${
                        isSelected
                          ? "bg-blue-500 text-white"
                          : "bg-slate-700 text-slate-300"
                      }`}
                    >
                      {key}
                    </span>
                    <span
                      className="text-white flex-1"
                      dangerouslySetInnerHTML={sanitizeText(text)}
                    />
                  </div>
                </button>
              );
            })}
          </div>

          {/* Next button - always visible */}
          <div className="mt-8 text-center">
            {/* Warning message */}
            {!isAnswered && showAnswerWarning && (
              <p className="text-red-400 text-sm mb-3 animate-bounce">
                ΓÜá∩╕Å Please select an answer before continuing
              </p>
            )}
            <button
              onClick={() => {
                if (!isAnswered) {
                  setShowAnswerWarning(true);
                  return;
                }
                handleNext();
              }}
              className={`px-8 py-3 rounded-lg font-semibold transition-colors ${
                isAnswered
                  ? "bg-blue-600 hover:bg-blue-700 text-white"
                  : "bg-slate-700 hover:bg-slate-600 text-slate-300"
              }`}
            >
              {currentIndex + 1 >= totalQuestions
                ? "See Results"
                : "Next Question"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default QuizPreview;

import React, { useEffect } from "react";
import Icon from "./Icon";
import QuestionItem from "./QuestionItem";
import { logger } from "../utils/logger";

const ReviewMode = ({
  questions,
  currentIndex,
  setCurrentIndex,
  onUpdateStatus,
  onExplain,
  onVariate,
  onCritique,
  onApplyRewrite,
  onTranslateSingle,
  onSwitchLanguage,
  onDelete,
  onUpdateQuestion,
  translationMap,
  isProcessing,
  showMessage,
  onStartTutorial,
  onKickBack, // For restoring rejected questions
  userRole, // NEW
  allQuestionsMap,
}) => {
  // Auto-start tutorial if not completed (and compliance modals are done)
  useEffect(() => {
    const isCompleted = localStorage.getItem("ue5_tutorial_review_completed");
    const ageVerified = localStorage.getItem("ue5_age_verified");
    const termsAccepted = localStorage.getItem("ue5_terms_accepted");

    // Only start tutorial if compliance modals are complete
    if (
      !isCompleted &&
      onStartTutorial &&
      questions.length > 0 &&
      ageVerified &&
      termsAccepted
    ) {
      // Small delay to ensure view is rendered
      setTimeout(() => onStartTutorial("review"), 500);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  // Auto-adjust index if out of bounds (e.g. after accepting an item and list shrinks)
  React.useEffect(() => {
    if (questions && questions.length > 0 && currentIndex >= questions.length) {
      setCurrentIndex(questions.length - 1);
    }
  }, [questions, currentIndex, setCurrentIndex]);

  // Create a wrapper that handles navigation after language switch
  // This finds the translated variant by uniqueId and navigates to its index
  const handleLanguageSwitchWithNavigation = React.useCallback(
    (targetLang, uniqueId) => {
      logger.log("≡ƒöä [ReviewMode] Language switch with navigation:", {
        targetLang,
        uniqueId,
      });

      // First, call the global language switch to re-filter questions
      onSwitchLanguage(targetLang, uniqueId);

      // Schedule navigation after the re-render with new language filter
      // We use setTimeout to ensure the questions array is updated
      if (uniqueId) {
        setTimeout(() => {
          // Find the question with this uniqueId in the new filtered list
          // Note: questions prop will be updated after re-render, so we need to query the DOM or use a ref
          // For now, we'll trust the filter and just stay at the same position
          // The parent needs to handle the navigation after filter update
          logger.log(
            "≡ƒöä [ReviewMode] Navigation scheduled - parent should handle index update via pendingNavigationUniqueId"
          );
        }, 100);
      }
    },
    [onSwitchLanguage]
  );

  if (!questions || questions.length === 0) return null;

  const currentQuestion = questions[currentIndex];

  if (!currentQuestion) {
    return (
      <div className="text-center p-10 text-slate-500">
        No question selected.
      </div>
    );
  }
  const canGoPrev = currentIndex > 0;
  const canGoNext = currentIndex < questions.length - 1;

  return (
    <div className="flex flex-col items-center justify-start h-full max-w-4xl mx-auto w-full pt-4">
      <div
        className="w-full mb-6 flex justify-between items-center text-slate-400 text-xs font-mono bg-slate-900/50 p-2 rounded-lg border border-slate-800"
        data-tour="review-nav"
      >
        <button
          onClick={() => setCurrentIndex((prev) => Math.max(prev - 1, 0))}
          disabled={!canGoPrev}
          className="flex items-center gap-2 px-4 py-2 rounded hover:bg-slate-800 disabled:opacity-30 disabled:hover:bg-transparent transition-colors font-bold"
          data-tour="prev-button"
        >
          <Icon name="arrow-left" size={16} /> PREV
        </button>
        <div className="flex flex-col items-center">
          <span className="text-slate-500 uppercase text-[10px] tracking-widest">
            Review Progress
          </span>
          <span className="text-lg">
            <span className="text-white font-bold">{currentIndex + 1}</span>{" "}
            <span className="text-slate-600">/</span>{" "}
            <span className="text-slate-400 font-bold">{questions.length}</span>
          </span>
        </div>
        <button
          onClick={() =>
            setCurrentIndex((prev) => Math.min(prev + 1, questions.length - 1))
          }
          disabled={!canGoNext}
          className="flex items-center gap-2 px-4 py-2 rounded hover:bg-slate-800 disabled:opacity-30 disabled:hover:bg-transparent transition-colors font-bold"
          data-tour="next-button"
        >
          NEXT <Icon name="arrow-right" size={16} />
        </button>
      </div>

      <div
        className="w-full transform transition-all duration-300"
        data-tour="review-card"
      >
        <QuestionItem
          key={currentQuestion.uniqueId}
          q={currentQuestion}
          onUpdateStatus={onUpdateStatus}
          onExplain={onExplain}
          onVariate={onVariate}
          onCritique={onCritique}
          onApplyRewrite={onApplyRewrite}
          onTranslateSingle={onTranslateSingle}
          onSwitchLanguage={onSwitchLanguage}
          onDelete={onDelete}
          onUpdateQuestion={onUpdateQuestion}
          availableVariants={
            translationMap.get(currentQuestion.uniqueId)
              ? Array.from(allQuestionsMap.get(currentQuestion.uniqueId) || [])
              : []
          }
          isProcessing={isProcessing}
          appMode="review"
          showMessage={showMessage}
          onKickBack={onKickBack}
          userRole={userRole} // NEW
        />
      </div>
    </div>
  );
};

export default ReviewMode;

import Icon from "./Icon";
import { QUALITY_PASS_THRESHOLD } from "../utils/constants";

// Helper functions to compute step styling without nested ternaries
const getCircleClass = (step) => {
  if (step.completed) return "bg-green-600 text-white";
  if (step.failed) return "bg-red-600 text-white";
  if (step.active)
    return "bg-orange-500 text-white animate-pulse shadow-lg shadow-orange-500/50 group-hover:bg-orange-400";
  if (step.ready)
    return "bg-blue-600/70 text-white cursor-pointer hover:bg-blue-500";
  return "bg-slate-700 text-slate-400 border-2 border-slate-600";
};

const getLabelClass = (step) => {
  if (step.completed) return "text-green-400";
  if (step.failed) return "text-red-400";
  if (step.active) return "text-orange-400";
  if (step.ready) return "text-blue-400";
  return "text-slate-500";
};

const getSublabelClass = (step) => {
  if (step.completed) return "text-green-400/70";
  if (step.failed) return "text-red-400/70";
  if (step.active) return "text-orange-400/70";
  if (step.ready) return "text-blue-400/70";
  return "text-slate-600";
};

const getLineClass = (step) => {
  if (step.completed) return "bg-green-600";
  if (step.failed) return "bg-red-600/50";
  return "bg-slate-700";
};

const getButtonTitle = (step, isLocked, lockedBy) => {
  if (isLocked) return `Locked by ${lockedBy?.userEmail || "another user"}`;
  if (step.locked) return "Complete previous step first";
  return step.sublabel;
};

// Helper to render circle content
const renderCircleContent = (step, critiqueScore) => {
  if (step.completed) return <Icon name="check" size={18} />;
  if (step.failed) return <span>{critiqueScore}</span>;
  return <span>{step.num}</span>;
};

/**
 * ReviewProgressBar - Visual stepper workflow for the review process
 * Shows 3 steps: CRITIQUE ΓåÆ VERIFY ΓåÆ ACCEPT with connecting lines
 */
const ReviewProgressBar = ({
  question,
  isLocked = false,
  lockedBy = null,
  onCritique,
  onVerify,
  onAccept,
  onFix,
  isProcessing,
}) => {
  const q = question;

  // Determine step states
  // Check if critique was done (either score exists OR improvements were applied)
  const hasCritique =
    (q.critiqueScore !== undefined && q.critiqueScore !== null) ||
    q.improvementsApplied === true;
  // Pass if score >= threshold OR if improvements were applied (which means they passed review)
  const critiquePass =
    (hasCritique && q.critiqueScore >= QUALITY_PASS_THRESHOLD) ||
    q.improvementsApplied === true;
  const critiqueFail =
    q.critiqueScore !== null &&
    q.critiqueScore !== undefined &&
    q.critiqueScore < QUALITY_PASS_THRESHOLD &&
    !q.improvementsApplied;
  const isVerified = q.humanVerified === true;
  const isAccepted = q.status === "accepted";
  const isRejected = q.status === "rejected";

  if (isRejected) {
    const reasons = {
      low_score_after_retries:
        "Could not reach quality threshold after multiple attempts",
      factually_incorrect: "Contains factual errors",
      unclear: "Question or answers are unclear",
      duplicate: "Duplicate of another question",
      off_topic: "Not relevant to the topic",
      other: "Rejected by reviewer",
    };
    const reasonText =
      reasons[q.rejectionReason] ||
      q.rejectionReason?.replace(/_/g, " ") ||
      "Rejected";

    return (
      <div className="py-5 px-6 bg-red-950/50 border-2 border-red-600/50 rounded-lg">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 rounded-full bg-red-600 flex items-center justify-center flex-shrink-0 animate-pulse">
            <Icon name="x" size={24} className="text-white" />
          </div>
          <div className="flex-1">
            <div className="text-lg font-bold text-red-400 mb-1">
              Γ¥î QUESTION REJECTED
            </div>
            <div className="text-sm text-red-300/80">{reasonText}</div>
            <div className="text-xs text-red-400/60 mt-2">
              This question will not be exported. You can delete it or move on
              to the next question.
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (isAccepted) {
    return (
      <div className="flex items-center justify-center gap-3 py-3 px-4 bg-green-950/30 border border-green-900/50 rounded-lg">
        <div className="w-8 h-8 rounded-full bg-green-600 flex items-center justify-center">
          <Icon name="check" size={18} className="text-white" />
        </div>
        <div>
          <span className="text-sm font-bold text-green-400">ACCEPTED</span>
          <span className="text-xs text-green-400/70 ml-2">
            Ready for export
          </span>
        </div>
      </div>
    );
  }

  const steps = [
    {
      num: 1,
      label: "Critique",
      sublabel: hasCritique
        ? `Score: ${q.critiqueScore}/100`
        : "Run AI analysis",
      completed: hasCritique && critiquePass,
      failed: critiqueFail,
      active: !hasCritique,
      ready: false,
      icon: "zap",
      onClick: onCritique,
    },
    {
      num: 2,
      label: "Verify",
      sublabel: isVerified ? "Source confirmed" : "Check source & answer",
      completed: isVerified,
      // For high scores, Verify is the next step (flash it)
      active: hasCritique && !isVerified,
      ready: false,
      locked: !hasCritique, // FIX: Locked until critique EXISTS (not just passes)
      icon: "eye",
      onClick: onVerify,
    },
    {
      num: 3,
      label: "Accept",
      sublabel: "Approve for export",
      completed: false,
      // Accept becomes active AFTER verification
      active: isVerified && !isAccepted,
      ready: false,
      locked: !isVerified, // Must verify first
      icon: "check-circle",
      onClick: onAccept,
    },
  ];

  return (
    <div className="py-4 px-6 bg-slate-900/70 border border-slate-700/50 rounded-lg">
      <div className="flex items-center justify-between">
        {steps.map((step, index) => (
          <div key={step.num} className="flex items-center flex-1">
            {/* Step Circle + Content */}
            <button
              onClick={() =>
                !isLocked &&
                !step.locked &&
                !step.completed &&
                !isProcessing &&
                step.onClick?.()
              }
              disabled={
                isLocked || step.locked || step.completed || isProcessing
              }
              className={`
                                flex items-center gap-3 transition-all
                                ${
                                  step.active && !isProcessing && !isLocked
                                    ? "cursor-pointer group"
                                    : ""
                                }
                                ${
                                  step.locked || isLocked
                                    ? "opacity-40 cursor-not-allowed"
                                    : ""
                                }
                            `}
              title={getButtonTitle(step, isLocked, lockedBy)}
              data-tour={step.num === 1 ? "critique-button" : undefined}
            >
              {/* Circle */}
              <div
                className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-sm transition-all ${getCircleClass(
                  step
                )}`}
              >
                {renderCircleContent(step, q.critiqueScore)}
              </div>

              {/* Label */}
              <div className="flex flex-col">
                <span className={`text-sm font-bold ${getLabelClass(step)}`}>
                  {step.label}
                </span>
                <span className={`text-xs ${getSublabelClass(step)}`}>
                  {step.sublabel}
                </span>
              </div>
            </button>

            {/* Connecting Line */}
            {index < steps.length - 1 && (
              <div
                className={`flex-1 h-0.5 mx-4 rounded ${getLineClass(step)}`}
              />
            )}
          </div>
        ))}
      </div>

      {/* Help Text */}
      {critiqueFail && (
        <div className="mt-3 text-center text-xs text-red-400/80 bg-red-950/30 py-2 rounded flex items-center justify-center gap-2">
          <Icon name="alert-triangle" size={12} />
          <span>Score below {QUALITY_PASS_THRESHOLD}.</span>
          {onFix && q.suggestedRewrite ? (
            <button
              onClick={onFix}
              disabled={isProcessing}
              className="px-2 py-0.5 bg-red-800 hover:bg-red-700 text-white text-[10px] font-bold rounded shadow-sm border border-red-600 transition-colors uppercase"
            >
              Fix & Re-run
            </button>
          ) : (
            <span>Check critique below.</span>
          )}
        </div>
      )}
      {critiquePass && !isVerified && (
        <div className="mt-3 text-center text-xs text-green-400/80 bg-green-950/30 py-2 rounded">
          <Icon name="check-circle" size={12} className="inline mr-1" />
          <strong>Good score!</strong> Click <strong>Verify</strong> to check
          the source and answer before accepting.
        </div>
      )}
      {isVerified && !isAccepted && (
        <div className="mt-3 text-center text-xs text-blue-400/80 bg-blue-950/30 py-2 rounded animate-pulse">
          <Icon name="check-circle" size={12} className="inline mr-1" />
          <strong>Verified!</strong> Click <strong>Accept</strong> to approve
          this question for export.
        </div>
      )}
    </div>
  );
};

export default ReviewProgressBar;

import { useState } from "react";
import Icon from "./Icon";
import {
  exportToScorm,
  validateQuestionsForExport,
} from "../services/scormExporter";
import { logger } from "../utils/logger";

/**
 * SCORM Export Modal
 * Allows users to configure and export selected questions as SCORM 1.2 package
 */
const ScormExportModal = ({ questions, onClose }) => {
  const [config, setConfig] = useState({
    title: "UE5 Knowledge Assessment",
    description: "Test your Unreal Engine 5 knowledge",
    passingScore: 80,
    timeLimit: 30, // minutes
  });

  const [isExporting, setIsExporting] = useState(false);
  const [error, setError] = useState(null);

  const handleExport = async () => {
    setError(null);

    // Validate questions
    const validation = validateQuestionsForExport(questions);

    if (!validation.valid) {
      setError(validation.errors.join(", "));
      return;
    }

    // Show warnings if any
    if (validation.warnings.length > 0) {
      logger.warn("SCORM Export Warnings:", validation.warnings);
    }

    setIsExporting(true);

    try {
      const result = await exportToScorm(questions, config);
      logger.log("SCORM export successful:", result);

      // Close modal after successful export
      setTimeout(() => {
        onClose();
      }, 1000);
    } catch (err) {
      setError(err.message);
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-slate-900 rounded-lg shadow-2xl max-w-md w-full border border-slate-700">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-slate-700">
          <h2 className="text-xl font-bold text-white flex items-center gap-2">
            <Icon name="download" size={20} />
            Export to SCORM 1.2
          </h2>
          <button
            onClick={onClose}
            className="text-slate-400 hover:text-white transition-colors"
            disabled={isExporting}
          >
            <Icon name="x" size={20} />
          </button>
        </div>

        {/* Body */}
        <div className="p-6 space-y-4">
          {/* Quiz Title */}
          <div>
            <label className="block text-sm font-bold text-slate-300 mb-2">
              Quiz Title
            </label>
            <input
              type="text"
              value={config.title}
              onChange={(e) => setConfig({ ...config, title: e.target.value })}
              className="w-full px-3 py-2 bg-slate-800 border border-slate-700 rounded text-white focus:border-blue-500 outline-none"
              placeholder="UE5 Knowledge Assessment"
              disabled={isExporting}
            />
          </div>

          {/* Description */}
          <div>
            <label className="block text-sm font-bold text-slate-300 mb-2">
              Description (Optional)
            </label>
            <textarea
              value={config.description}
              onChange={(e) =>
                setConfig({ ...config, description: e.target.value })
              }
              className="w-full px-3 py-2 bg-slate-800 border border-slate-700 rounded text-white focus:border-blue-500 outline-none resize-none"
              rows={2}
              placeholder="Brief description of the assessment"
              disabled={isExporting}
            />
          </div>

          {/* Passing Score */}
          <div>
            <label className="block text-sm font-bold text-slate-300 mb-2">
              Passing Score: {config.passingScore}%
            </label>
            <input
              type="range"
              min="50"
              max="100"
              step="5"
              value={config.passingScore}
              onChange={(e) =>
                setConfig({ ...config, passingScore: parseInt(e.target.value) })
              }
              className="w-full"
              disabled={isExporting}
            />
            <div className="flex justify-between text-xs text-slate-500 mt-1">
              <span>50%</span>
              <span>100%</span>
            </div>
          </div>

          {/* Time Limit */}
          <div>
            <label className="block text-sm font-bold text-slate-300 mb-2">
              Time Limit
            </label>
            <select
              value={config.timeLimit}
              onChange={(e) =>
                setConfig({ ...config, timeLimit: parseInt(e.target.value) })
              }
              className="w-full px-3 py-2 bg-slate-800 border border-slate-700 rounded text-white focus:border-blue-500 outline-none"
              disabled={isExporting}
            >
              <option value={15}>15 minutes</option>
              <option value={30}>30 minutes</option>
              <option value={45}>45 minutes</option>
              <option value={60}>60 minutes</option>
              <option value={90}>90 minutes</option>
            </select>
          </div>

          {/* Question Count */}
          <div className="bg-slate-800 rounded p-3 border border-slate-700">
            <div className="flex items-center justify-between text-sm">
              <span className="text-slate-400">Selected Questions:</span>
              <span className="font-bold text-blue-400">
                {questions.length}
              </span>
            </div>
          </div>

          {/* Error Display */}
          {error && (
            <div className="bg-red-900/20 border border-red-500 rounded p-3">
              <p className="text-sm text-red-400">{error}</p>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-end gap-3 p-6 border-t border-slate-700">
          <button
            onClick={onClose}
            className="px-4 py-2 text-slate-400 hover:text-white transition-colors"
            disabled={isExporting}
          >
            Cancel
          </button>
          <button
            onClick={handleExport}
            disabled={isExporting || questions.length === 0}
            className="px-6 py-2 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-700 disabled:text-slate-500 text-white rounded font-semibold transition-colors flex items-center gap-2"
          >
            {isExporting ? (
              <>
                <Icon name="loader" size={16} className="animate-spin" />
                Generating...
              </>
            ) : (
              <>
                <Icon name="download" size={16} />
                Generate Package
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ScormExportModal;

import { useState } from "react";
import {
  signInWithGoogle,
  signInWithEmail,
  resetPassword,
} from "../services/firebase";
import Icon from "./Icon";
import { logger } from "../utils/logger";

const SignIn = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [showEmailAuth, setShowEmailAuth] = useState(false);
  const [showPasswordReset, setShowPasswordReset] = useState(false);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [resetSuccess, setResetSuccess] = useState(false);

  const handleGoogleSignIn = async () => {
    setIsLoading(true);
    setError(null);
    try {
      await signInWithGoogle();
    } catch (err) {
      logger.error(err);
      if (err.code === "auth/configuration-not-found") {
        setError(
          "Google Sign-In is not enabled. Please enable it in the Firebase Console > Authentication > Sign-in method."
        );
      } else if (err.code === "auth/popup-closed-by-user") {
        setError("Sign-in cancelled.");
      } else if (err.code === "auth/user-disabled") {
        setError(
          "Your account has been disabled by an administrator. Please contact support if you believe this is an error."
        );
      } else {
        setError("Failed to sign in. Please try again.");
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleEmailAuth = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);
    try {
      // Sign in only - new accounts need invite codes via InviteSignUp
      await signInWithEmail(email, password);
    } catch (err) {
      logger.error(err);
      const getErrorMessage = (code) => {
        switch (code) {
          case "auth/wrong-password":
          case "auth/invalid-credential":
            return "Incorrect email or password.";
          case "auth/user-not-found":
            return "No account found. You may need an invite code to register.";
          case "auth/invalid-email":
            return "Invalid email address format.";
          case "auth/user-disabled":
            return "Your account has been disabled. Please contact support.";
          case "auth/too-many-requests":
            return "Too many attempts. Please try again later.";
          default:
            return err.message || "Sign in failed.";
        }
      };
      setError(getErrorMessage(err.code));
    } finally {
      setIsLoading(false);
    }
  };

  const handlePasswordReset = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);
    setResetSuccess(false);

    try {
      await resetPassword(email);
      setResetSuccess(true);
    } catch (err) {
      logger.error(err);
      let message = err.message || "Failed to send reset email";
      if (err.code === "auth/user-not-found") {
        message = "No account found with this email address.";
      } else if (err.code === "auth/invalid-email") {
        message = "Invalid email address format.";
      } else if (err.code === "auth/too-many-requests") {
        message = "Too many requests. Please try again later.";
      }
      setError(message);
    } finally {
      setIsLoading(false);
    }
  };
  // Render content based on current view state
  const renderContent = () => {
    if (showPasswordReset) {
      return (
        // Password Reset Form
        <form onSubmit={handlePasswordReset} className="space-y-3 text-left">
          <div>
            <label
              htmlFor="reset-email"
              className="block text-sm font-medium text-slate-300 mb-2"
            >
              Email Address
            </label>
            <input
              id="reset-email"
              type="email"
              placeholder="your.email@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full px-4 py-3 bg-slate-800 border border-slate-700 rounded-lg text-white placeholder-slate-500 focus:outline-none focus:border-blue-500"
              required
            />
          </div>
          <button
            type="submit"
            disabled={isLoading}
            className="w-full py-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold rounded-xl transition-colors"
          >
            {isLoading ? "Sending..." : "Send Reset Email"}
          </button>
          <button
            type="button"
            onClick={() => {
              setShowPasswordReset(false);
              setResetSuccess(false);
              setError(null);
            }}
            className="w-full text-sm text-slate-500 hover:text-slate-300 transition-colors"
          >
            ΓåÉ Back to sign in
          </button>
        </form>
      );
    }

    if (!showEmailAuth) {
      return (
        // Auth Options
        <div className="space-y-3">
          <button
            onClick={handleGoogleSignIn}
            disabled={isLoading}
            className="w-full flex items-center justify-center gap-3 bg-white hover:bg-slate-100 text-slate-900 font-bold py-3 px-6 rounded-xl transition-all transform hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isLoading ? (
              <Icon name="loader" className="animate-spin" />
            ) : (
              <GoogleIcon />
            )}
            {isLoading ? "Signing in..." : "Sign in with Google"}
          </button>

          <div className="flex items-center gap-3 text-slate-500 text-sm">
            <div className="flex-1 h-px bg-slate-700" />
            <span>or</span>
            <div className="flex-1 h-px bg-slate-700" />
          </div>

          <button
            onClick={() => setShowEmailAuth(true)}
            className="w-full flex items-center justify-center gap-3 py-3 bg-slate-800 hover:bg-slate-700 text-white font-bold rounded-xl transition-all border border-slate-700"
          >
            <Icon name="mail" size={20} />
            Continue with Email
          </button>

          <p className="text-xs text-slate-600">
            Sign in with any Google or email account.
          </p>
        </div>
      );
    }

    // Email/Password Form
    return (
      <form onSubmit={handleEmailAuth} className="space-y-3 text-left">
        <div>
          <label
            htmlFor="email"
            className="block text-sm font-medium text-slate-300 mb-2"
          >
            Email Address
          </label>
          <input
            id="email"
            type="email"
            placeholder="your.email@example.com"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="w-full px-4 py-3 bg-slate-800 border border-slate-700 rounded-lg text-white placeholder-slate-500 focus:outline-none focus:border-blue-500"
            required
          />
        </div>
        <div>
          <label
            htmlFor="password"
            className="block text-sm font-medium text-slate-300 mb-2"
          >
            Password
          </label>
          <input
            id="password"
            type="password"
            placeholder="6+ characters"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="w-full px-4 py-3 bg-slate-800 border border-slate-700 rounded-lg text-white placeholder-slate-500 focus:outline-none focus:border-blue-500"
            required
            minLength={6}
          />
        </div>
        <button
          type="submit"
          disabled={isLoading}
          className="w-full py-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold rounded-xl transition-colors"
        >
          {isLoading ? "Signing in..." : "Sign In"}
        </button>
        <button
          type="button"
          onClick={() => {
            setShowPasswordReset(true);
            setShowEmailAuth(false);
          }}
          className="w-full text-sm text-blue-400 hover:text-blue-300 transition-colors"
        >
          Forgot password?
        </button>
        <button
          type="button"
          onClick={() => setShowEmailAuth(false)}
          className="w-full text-sm text-slate-500 hover:text-slate-300 transition-colors"
        >
          ΓåÉ Back to sign-in options
        </button>
        <p className="text-xs text-slate-600 text-center pt-2">
          Need an account? Contact an admin for an invite code.
        </p>
      </form>
    );
  };

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-8 max-w-md w-full shadow-2xl text-center space-y-6">
        <div className="flex justify-center mb-4">
          <div className="w-20 h-20 bg-blue-600/20 rounded-full flex items-center justify-center">
            <Icon name="database" size={40} className="text-blue-500" />
          </div>
        </div>

        <div className="space-y-2">
          <h1 className="text-3xl font-bold text-white tracking-tight">
            UE5 Question Generator
          </h1>
          <p className="text-slate-400">
            Sign in to generate, manage, and export your question bank.
          </p>
        </div>

        {error && (
          <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-3 rounded-lg text-sm">
            {error}
          </div>
        )}

        {resetSuccess && (
          <div className="bg-green-500/10 border border-green-500/20 text-green-400 p-3 rounded-lg text-sm">
            Password reset email sent! Check your inbox and spam folder.
          </div>
        )}

        {renderContent()}
      </div>
    </div>
  );
};

