import { useEffect, useState } from 'react';
import Icon from './Icon';

const Toast = ({ message, type = 'info', onClose, action = null, duration = 5000, sticky = false, progress = null }) => {
    const [isExiting, setIsExiting] = useState(false);

    useEffect(() => {
        // Don't auto-dismiss if sticky or has action
        if (sticky || action || !duration) {
            return;
        }
        
        const timer = setTimeout(() => {
            setIsExiting(true);
            setTimeout(onClose, 200); // Wait for exit animation
        }, duration);
        
        return () => clearTimeout(timer);
    }, [onClose, action, duration, sticky]);

    const bgColors = {
        success: 'bg-emerald-900/95 border-emerald-500/50 shadow-emerald-900/20',
        error: 'bg-red-950/95 border-red-500/50 shadow-red-900/20',
        warning: 'bg-amber-900/95 border-amber-500/50 shadow-amber-900/20',
        info: 'bg-slate-900/95 border-slate-600/50 shadow-slate-900/20',
        progress: 'bg-blue-950/95 border-blue-500/50 shadow-blue-900/20',
    };

    const iconNames = {
        success: 'check-circle',
        error: 'x-circle',
        warning: 'alert-triangle',
        info: 'info',
        progress: 'loader',
    };

    const progressColors = {
        success: 'bg-emerald-500',
        error: 'bg-red-500',
        warning: 'bg-amber-500',
        info: 'bg-blue-500',
        progress: 'bg-blue-500',
    };

    return (
        <div 
            className={`
                ${bgColors[type] || bgColors.info} 
                border rounded-lg shadow-2xl p-4 max-w-lg backdrop-blur-sm 
                transition-all duration-200
                ${isExiting ? 'opacity-0 translate-x-4' : 'animate-in slide-in-from-right'}
            `}
            role="alert"
        >
            <div className="flex items-center justify-between gap-4">
                <div className="flex items-center gap-3 flex-1 min-w-0">
                    <Icon 
                        name={iconNames[type] || iconNames.info} 
                        size={20} 
                        className={`text-white flex-shrink-0 ${type === 'progress' ? 'animate-spin' : ''}`} 
                    />
                    <span className="text-white font-medium text-sm leading-snug">{message}</span>
                </div>
                
                <div className="flex items-center gap-2 flex-shrink-0">
                    {action && (
                        <button
                            onClick={action.onClick}
                            className="px-3 py-1 bg-white/20 hover:bg-white/30 text-white rounded transition-colors text-sm font-medium"
                        >
                            {action.label}
                        </button>
                    )}
                    <button
                        onClick={() => {
                            setIsExiting(true);
                            setTimeout(onClose, 200);
                        }}
                        className="text-white/70 hover:text-white transition-colors"
                        aria-label="Close notification"
                    >
                        <Icon name="x" size={18} />
                    </button>
                </div>
            </div>

            {/* Progress bar */}
            {progress !== null && progress !== undefined && (
                <div className="mt-3 h-1.5 bg-white/20 rounded-full overflow-hidden">
                    <div 
                        className={`h-full ${progressColors[type] || progressColors.info} transition-all duration-300 rounded-full`}
                        style={{ width: `${Math.min(100, Math.max(0, progress))}%` }}
                    />
                </div>
            )}
        </div>
    );
};

export default Toast;

const TokenUsageDisplay = ({ tokenUsage }) => {
    if (!tokenUsage) return null;

    const { inputTokens, outputTokens, totalCost } = tokenUsage;

    return (
        <div className="bg-slate-800/50 border border-slate-700 rounded-lg p-3 flex flex-col gap-1 text-xs">
            <div className="flex justify-between items-center">
                <span className="text-slate-400 font-bold uppercase">Session Usage</span>
                <span className="text-emerald-400 font-mono font-bold">${totalCost.toFixed(4)}</span>
            </div>
            <div className="flex justify-between items-center text-[10px] text-slate-500">
                <span title="Input Tokens">In: {inputTokens.toLocaleString()}</span>
                <span title="Output Tokens">Out: {outputTokens.toLocaleString()}</span>
            </div>
        </div>
    );
};

export default TokenUsageDisplay;

import React, { useState, useMemo } from "react";
import Icon from "./Icon";
import QuestionItem from "./QuestionItem";
import { Virtuoso } from "react-virtuoso";
import { LANGUAGE_FLAGS } from "../utils/constants";
import { useBulkTranslation } from "../hooks/useBulkTranslation";

const TranslationManagementView = ({
  questions,
  allQuestionsMap,
  translationMap,
  onTranslateSingle,
  onSwitchLanguage,
  onUpdateStatus,
  onDelete,
  onUpdateQuestion,
  isProcessing,
  showMessage,
  userRole,
}) => {
  const [targetLang, setTargetLang] = useState("Japanese");
  const [viewFilter, setViewFilter] = useState("missing"); // 'missing', 'all-accepted', or 'all'

  const { handleBulkTranslate, isBulkProcessing, progress } =
    useBulkTranslation(onTranslateSingle, showMessage);

  // Filter logic: Only show English questions (base variants) that are Accepted
  const eligibleQuestions = useMemo(() => {
    return questions.filter(
      (q) => (q.language || "English") === "English" && q.status === "accepted"
    );
  }, [questions]);

  // Sub-filter logic
  const filteredList = useMemo(() => {
    // 1. Everything: All English base questions (regardless of status)
    if (viewFilter === "all") {
      return questions.filter((q) => {
        const isEnglish = (q.language || "English") === "English";
        return isEnglish;
      });
    }

    // 2. Accepted: Only English base questions that are 'accepted'
    if (viewFilter === "all-accepted") {
      return eligibleQuestions;
    }

    // 3. Missing (Default): Accepted English questions lacking targetLang variant
    return eligibleQuestions.filter((q) => {
      const variants = allQuestionsMap.get(q.uniqueId) || [];
      return !variants.some((v) => (v.language || "English") === targetLang);
    });
  }, [eligibleQuestions, questions, viewFilter, targetLang, allQuestionsMap]);

  const handleBulkAction = () => {
    handleBulkTranslate(filteredList, targetLang);
  };

  return (
    <div className="flex flex-col h-full bg-slate-950">
      {/* Action Bar */}
      <div className="p-4 bg-slate-900/50 border-b border-slate-800 flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium text-slate-400">Target:</span>
            <select
              value={targetLang}
              onChange={(e) => setTargetLang(e.target.value)}
              className="bg-slate-800 border border-slate-700 text-white rounded px-2 py-1 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
            >
              {Object.keys(LANGUAGE_FLAGS)
                .filter((l) => l !== "English")
                .map((lang) => (
                  <option key={lang} value={lang}>
                    {lang}
                  </option>
                ))}
            </select>
          </div>

          <div className="flex items-center gap-2">
            <span className="text-sm font-medium text-slate-400">View:</span>
            <div className="flex bg-slate-800 p-0.5 rounded-lg border border-slate-700">
              <button
                onClick={() => setViewFilter("missing")}
                className={`px-3 py-1 text-xs rounded-md transition-all ${
                  viewFilter === "missing"
                    ? "bg-indigo-600 text-white"
                    : "text-slate-400 hover:text-white"
                }`}
              >
                Missing
              </button>
              <button
                onClick={() => setViewFilter("all-accepted")}
                className={`px-3 py-1 text-xs rounded-md transition-all ${
                  viewFilter === "all-accepted"
                    ? "bg-indigo-600 text-white"
                    : "text-slate-400 hover:text-white"
                }`}
              >
                Accepted
              </button>
              <button
                onClick={() => setViewFilter("all")}
                className={`px-3 py-1 text-xs rounded-md transition-all ${
                  viewFilter === "all"
                    ? "bg-indigo-600 text-white"
                    : "text-slate-400 hover:text-white"
                }`}
              >
                Everything
              </button>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          {isBulkProcessing ? (
            <div className="flex items-center gap-3 bg-indigo-950/30 border border-indigo-500/50 px-4 py-2 rounded-xl">
              <Icon
                name="loader"
                size={18}
                className="animate-spin text-indigo-400"
              />
              <div className="flex flex-col">
                <span className="text-xs font-bold text-indigo-300">
                  Translating... {progress.current} / {progress.total}
                </span>
                <div className="w-32 h-1 bg-slate-800 rounded-full mt-1">
                  <div
                    className="h-full bg-indigo-500 rounded-full transition-all duration-300"
                    style={{
                      width: `${(progress.current / progress.total) * 100}%`,
                    }}
                  />
                </div>
              </div>
            </div>
          ) : (
            <button
              onClick={handleBulkAction}
              disabled={filteredList.length === 0 || isProcessing}
              className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-amber-500 to-orange-600 hover:from-amber-600 hover:to-orange-700 disabled:from-slate-800 disabled:to-slate-800 disabled:text-slate-600 text-white font-bold rounded-lg shadow-lg transition-all transform hover:scale-105 active:scale-95"
            >
              <Icon name="languages" size={18} />
              Bulk Translate {filteredList.length} Items to {targetLang}
            </button>
          )}
        </div>
      </div>

      {/* List Header/Stats */}
      <div className="px-6 py-2 bg-slate-900 border-b border-slate-800 flex justify-between items-center">
        <span className="text-xs text-slate-500">
          Showing{" "}
          <span className="text-indigo-400 font-bold">
            {filteredList.length}
          </span>{" "}
          {viewFilter === "all"
            ? "total database items"
            : "accepted English questions"}
          {viewFilter === "missing"
            ? ` missing ${targetLang} translations`
            : ""}
        </span>
      </div>

      {/* Virtualized List */}
      <div className="flex-1 overflow-hidden">
        {filteredList.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-slate-600">
            <Icon
              name="check-circle"
              size={48}
              className="mb-4 text-green-900/40"
            />
            <p className="font-medium text-slate-500">
              {viewFilter === "missing"
                ? `All accepted questions have been translated to ${targetLang}!`
                : "No accepted questions found."}
            </p>
          </div>
        ) : (
          <Virtuoso
            style={{ height: "100%" }}
            data={filteredList}
            itemContent={(index, q) => (
              <div className="px-6 py-4">
                <QuestionItem
                  key={q.uniqueId}
                  q={q}
                  onUpdateStatus={onUpdateStatus}
                  onTranslateSingle={onTranslateSingle}
                  onSwitchLanguage={onSwitchLanguage}
                  onDelete={onDelete}
                  onUpdateQuestion={onUpdateQuestion}
                  availableVariants={Array.from(
                    allQuestionsMap.get(q.uniqueId) || []
                  )}
                  isProcessing={
                    isProcessing ||
                    (isBulkProcessing && index === progress.current - 1)
                  }
                  appMode="translate"
                  showMessage={showMessage}
                  userRole={userRole}
                />
              </div>
            )}
          />
        )}
      </div>
    </div>
  );
};

export default TranslationManagementView;

import { useState, useEffect, useRef } from "react";
import Icon from "./Icon";
import { throttle, trapFocus } from "../utils/tutorial/domHelpers";
import { logTutorialEvent, TUTORIAL_EVENTS } from "../utils/tutorialAnalytics";
import { TUTORIAL } from "../utils/constants";

const TutorialOverlay = ({
  steps,
  currentStepIndex,
  onNext,
  onPrev,
  onSkip,
  onComplete,
  activeScenario,
}) => {
  const [targetRect, setTargetRect] = useState(null);
  const [elementNotFound, setElementNotFound] = useState(false);
  const overlayRef = useRef(null);
  const step = steps[currentStepIndex];

  // Element detection and positioning
  useEffect(() => {
    let pollInterval;
    let resizeObserver;
    let attemptCount = 0;
    const MAX_ATTEMPTS = TUTORIAL.MAX_ATTEMPT_COUNT || 20;

    setElementNotFound(false);

    const updatePosition = () => {
      // If no target specified, center the tooltip (this is intentional)
      if (!step.target) {
        setTargetRect(null);
        setElementNotFound(false);
        return;
      }

      const element = document.querySelector(step.target);
      if (element) {
        // Verify element has dimensions (is visible)
        const rect = element.getBoundingClientRect();
        if (rect.width === 0 && rect.height === 0) {
          attemptCount++;
          if (attemptCount >= MAX_ATTEMPTS) {
            setElementNotFound(true);
            if (pollInterval) clearInterval(pollInterval);

            // Log element not found
            logTutorialEvent(TUTORIAL_EVENTS.ELEMENT_NOT_FOUND, {
              scenarioId: activeScenario,
              stepId: step.id,
              target: step.target,
            });
          }
          return;
        }

        // Element found and visible - stop polling, clear error state
        setElementNotFound(false);
        if (pollInterval) clearInterval(pollInterval);

        // Calculate position with padding for highlight
        setTargetRect({
          top: rect.top - 10,
          left: rect.left - 10,
          width: rect.width + 20,
          height: rect.height + 20,
        });

        // Observe element for resize/movement (throttled)
        if (!resizeObserver) {
          const throttledUpdate = throttle(updatePosition, 100);
          resizeObserver = new ResizeObserver(throttledUpdate);
          resizeObserver.observe(element);
        }
      } else {
        attemptCount++;

        if (attemptCount >= MAX_ATTEMPTS) {
          setElementNotFound(true);
          setTargetRect(null);
          if (pollInterval) clearInterval(pollInterval);

          // Log element not found
          logTutorialEvent(TUTORIAL_EVENTS.ELEMENT_NOT_FOUND, {
            scenarioId: activeScenario,
            stepId: step.id,
            target: step.target,
          });
        } else {
          setTargetRect(null);
        }
      }
    };

    // Initial check
    updatePosition();

    // Scroll into view ONCE when step changes
    const element = document.querySelector(step.target);
    if (element) {
      element.scrollIntoView({ behavior: "smooth", block: "center" });
    } else if (step.target) {
      // Poll for element existence (handles conditionally rendered elements)
      pollInterval = setInterval(updatePosition, 100);

      // Try scrolling again after a delay if found
      setTimeout(() => {
        const el = document.querySelector(step.target);
        if (el) el.scrollIntoView({ behavior: "smooth", block: "center" });
      }, 500);
    }

    // Throttled event listeners
    const throttledUpdate = throttle(
      updatePosition,
      TUTORIAL.RESIZE_THROTTLE || 100
    );
    window.addEventListener("resize", throttledUpdate);
    window.addEventListener("scroll", throttledUpdate, true);

    return () => {
      if (pollInterval) clearInterval(pollInterval);
      if (resizeObserver) resizeObserver.disconnect();
      window.removeEventListener("resize", throttledUpdate);
      window.removeEventListener("scroll", throttledUpdate, true);
    };
  }, [currentStepIndex, step.target, step.id, activeScenario]);

  const isLastStep = currentStepIndex === steps.length - 1;

  // Focus trapping
  useEffect(() => {
    if (!overlayRef.current) return;

    const cleanup = trapFocus(overlayRef.current);
    return cleanup;
  }, [currentStepIndex]);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyPress = (e) => {
      if (e.key === "Escape") onSkip();
      if (e.key === "ArrowRight" && !isLastStep) onNext();
      if (e.key === "ArrowLeft" && currentStepIndex > 0) onPrev();
    };
    document.addEventListener("keydown", handleKeyPress);
    return () => document.removeEventListener("keydown", handleKeyPress);
  }, [onSkip, onNext, onPrev, currentStepIndex, isLastStep]);

  const handleSkipStep = () => {
    logTutorialEvent(TUTORIAL_EVENTS.STEP_SKIPPED, {
      scenarioId: activeScenario,
      stepId: step.id,
      reason: "element_not_found",
    });
    onNext();
  };

  return (
    <div className="fixed inset-0 z-[9999] overflow-hidden">
      {/* Dimmed Background with Cutout */}
      {targetRect ? (
        <div
          className="absolute inset-0 bg-black/70"
          style={{
            clipPath: `polygon(
                        0% 0%, 
                        0% 100%, 
                        100% 100%, 
                        100% 0%, 
                        0% 0%, 
                        ${targetRect.left}px ${targetRect.top}px, 
                        ${targetRect.left + targetRect.width}px ${
              targetRect.top
            }px, 
                        ${targetRect.left + targetRect.width}px ${
              targetRect.top + targetRect.height
            }px, 
                        ${targetRect.left}px ${
              targetRect.top + targetRect.height
            }px, 
                        ${targetRect.left}px ${targetRect.top}px
                    )`,
          }}
        ></div>
      ) : (
        <div className="absolute inset-0 bg-black/70 backdrop-blur-sm"></div>
      )}

      {/* Highlight Border */}
      {targetRect && (
        <div
          className="absolute border-2 border-indigo-500 rounded-lg shadow-[0_0_20px_rgba(99,102,241,0.5)] pointer-events-none"
          style={{
            top: targetRect.top,
            left: targetRect.left,
            width: targetRect.width,
            height: targetRect.height,
          }}
        />
      )}

      {/* Tooltip Card - always centered using flex wrapper */}
      <div className="fixed inset-0 flex items-center justify-center pointer-events-none z-[10000]">
        <div
          ref={overlayRef}
          role="dialog"
          aria-labelledby="tutorial-title"
          aria-describedby="tutorial-content"
          aria-live="polite"
          aria-modal="true"
          className="w-80 bg-slate-900 border border-slate-700 rounded-xl shadow-2xl p-6 flex flex-col gap-4 transition-all duration-300 ease-in-out animate-in zoom-in-95 pointer-events-auto"
        >
          <div className="flex justify-between items-start">
            <h3 id="tutorial-title" className="text-lg font-bold text-white">
              {step.title}
            </h3>
            <button
              onClick={onSkip}
              className="text-slate-500 hover:text-slate-300"
              aria-label="Close tutorial"
            >
              <Icon name="x" size={20} />
            </button>
          </div>

          {/* Parse content for **highlighted** keywords and ![images](url) */}
          <div
            id="tutorial-content"
            className="text-slate-300 text-sm leading-relaxed space-y-2"
          >
            {step.content.split("\n").map((line, lineIdx) => {
              if (!line.trim()) return <div key={lineIdx} className="h-2" />;

              // Robust Image Parsing
              const imgRegex = /!\[([^\]]*)\]\(([^)]+)\)/g;
              const lineParts = [];
              let lastIndex = 0;
              let match;

              while ((match = imgRegex.exec(line)) !== null) {
                // Push text before image
                if (match.index > lastIndex) {
                  lineParts.push({
                    type: "text",
                    content: line.substring(lastIndex, match.index),
                  });
                }

                // Push image
                const src = match[2];
                // Ensure BASE_URL ends with / and src doesn't start with / to avoid //
                const base = import.meta.env.BASE_URL || "/";
                const cleanBase = base.endsWith("/") ? base : `${base}/`;
                const cleanSrc = src.startsWith("/") ? src.substring(1) : src;
                const processedSrc = src.startsWith("http")
                  ? src
                  : `${cleanBase}${cleanSrc}`;

                lineParts.push({
                  type: "image",
                  alt: match[1],
                  src: processedSrc,
                });
                lastIndex = match.index + match[0].length;
              }

              // Push remaining text
              if (lastIndex < line.length) {
                lineParts.push({
                  type: "text",
                  content: line.substring(lastIndex),
                });
              }

              return (
                <div key={lineIdx} className="flex flex-col gap-2">
                  {lineParts.map((part, partIdx) => {
                    if (part.type === "image") {
                      return (
                        <img
                          key={partIdx}
                          src={part.src}
                          alt={part.alt}
                          className="w-full rounded-lg border border-slate-700 mt-1 shadow-md"
                        />
                      );
                    }

                    // Parse text for bold markers
                    return (
                      <p key={partIdx}>
                        {part.content
                          .split(/(\*\*[^*]+\*\*)/)
                          .map((subPart, subIdx) => {
                            if (
                              subPart.startsWith("**") &&
                              subPart.endsWith("**")
                            ) {
                              return (
                                <span
                                  key={subIdx}
                                  className="text-orange-400 font-semibold"
                                >
                                  {subPart.slice(2, -2)}
                                </span>
                              );
                            }
                            return subPart;
                          })}
                      </p>
                    );
                  })}
                </div>
              );
            })}
          </div>

          {/* Warning when element cannot be found */}
          {elementNotFound && step.target && (
            <div className="flex flex-col gap-2">
              <div className="flex items-center gap-2 px-3 py-2 bg-amber-900/30 border border-amber-700/50 rounded-lg text-amber-300 text-xs">
                <Icon name="alert-triangle" size={14} />
                <span>
                  Element not visible in current view. Try scrolling or skip to
                  continue.
                </span>
              </div>
              <button
                onClick={handleSkipStep}
                className="px-3 py-1.5 text-xs font-medium bg-amber-600 hover:bg-amber-500 text-white rounded transition-colors"
                aria-label="Skip this step"
              >
                Skip This Step
              </button>
            </div>
          )}

          <div className="flex items-center justify-between mt-2 pt-4 border-t border-slate-800">
            <div className="flex items-center gap-2">
              <div
                className="flex gap-1"
                role="progressbar"
                aria-valuenow={currentStepIndex + 1}
                aria-valuemin="1"
                aria-valuemax={steps.length}
              >
                {steps.map((_, idx) => (
                  <div
                    key={idx}
                    className={`w-2 h-2 rounded-full ${
                      idx === currentStepIndex
                        ? "bg-indigo-500"
                        : "bg-slate-700"
                    }`}
                    aria-label={`Step ${idx + 1}${
                      idx === currentStepIndex ? " (current)" : ""
                    }`}
                  />
                ))}
              </div>
              <span className="text-xs text-slate-500 ml-1" aria-live="polite">
                {currentStepIndex + 1} / {steps.length}
              </span>
            </div>

            <div className="flex gap-2">
              {currentStepIndex > 0 && (
                <button
                  onClick={onPrev}
                  className="px-3 py-1.5 text-xs font-medium text-slate-400 hover:text-white hover:bg-slate-800 rounded transition-colors"
                  aria-label="Previous step"
                >
                  Back
                </button>
              )}
              <button
                onClick={isLastStep ? onComplete : onNext}
                className="px-4 py-1.5 text-xs font-bold bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg shadow-lg shadow-indigo-900/50 transition-all flex items-center gap-2"
                aria-label={isLastStep ? "Finish tutorial" : "Next step"}
              >
                {isLastStep ? "Finish" : "Next"}{" "}
                <Icon name="arrow-right" size={14} />
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TutorialOverlay;

import React from "react";
import { Suspense } from "react";
import Icon from "./Icon";
import { SuspenseSpinner as LoadingSpinner } from "./LoadingSpinner";
// Lazy load heavy views - most views are lazy for better navigation perf
const AnalyticsView = React.lazy(() => import("./AnalyticsView"));
const DatabaseView = React.lazy(() => import("./DatabaseView"));
// ReviewMode is eagerly loaded to prevent remount issues with edit locks
import ReviewMode from "./ReviewMode";
const TestView = React.lazy(() => import("./TestView"));
const PromptPlayground = React.lazy(() => import("./PromptPlayground"));
const AdminPanel = React.lazy(() => import("./AdminPanel"));
const TranslationManagementView = React.lazy(() =>
  import("./TranslationManagementView")
);
import QuestionList from "./QuestionList";
import { APP_MODES } from "../utils/constants";

/**
 * EmptyReviewState - Illustrated empty state with CTA
 * Guides users to generate questions when Review is empty
 */
const EmptyReviewState = ({
  onNavigateToCreate,
  hasQuestionsInOtherFilters = false,
  isAdmin = false,
}) => {
  const getMessage = () => {
    if (hasQuestionsInOtherFilters) {
      return "All questions in this filter have been reviewed! Check other filters or generate more.";
    }
    if (isAdmin) {
      return "Generate your first batch of questions to start reviewing and approving them for your assessments.";
    }
    return "No questions are pending review. Ask an administrator to generate more questions.";
  };

  return (
    <div className="flex flex-col items-center justify-center h-full py-16 px-8">
      {/* Illustration */}
      <div className="relative mb-8">
        <div className="w-24 h-24 bg-gradient-to-br from-indigo-500/20 to-purple-500/20 rounded-full flex items-center justify-center">
          <Icon name="clipboard-list" size={48} className="text-indigo-400" />
        </div>
        <div className="absolute -bottom-2 -right-2 w-10 h-10 bg-orange-500/20 rounded-full flex items-center justify-center animate-bounce">
          <Icon name="sparkles" size={20} className="text-orange-400" />
        </div>
      </div>

      {/* Message */}
      <h3 className="text-xl font-bold text-white mb-2">
        {hasQuestionsInOtherFilters
          ? "No Pending Questions"
          : "Ready to Review"}
      </h3>
      <p className="text-slate-400 text-center max-w-md mb-6">{getMessage()}</p>

      {/* CTA Button - Admin only */}
      {isAdmin && (
        <button
          onClick={onNavigateToCreate}
          className="flex items-center gap-3 px-6 py-3 bg-gradient-to-r from-orange-500 to-orange-600 hover:from-orange-600 hover:to-orange-700 text-white font-bold rounded-xl shadow-lg shadow-orange-500/25 transition-all hover:scale-105 active:scale-95"
        >
          <Icon name="plus-circle" size={20} />
          Generate Your First Batch
        </button>
      )}

      {/* Keyboard shortcut hint - Admin only */}
      {isAdmin && (
        <p className="text-xs text-slate-600 mt-4">
          or press{" "}
          <kbd className="px-1.5 py-0.5 bg-slate-800 rounded text-slate-400 font-mono">
            Ctrl
          </kbd>{" "}
          +{" "}
          <kbd className="px-1.5 py-0.5 bg-slate-800 rounded text-slate-400 font-mono">
            Enter
          </kbd>{" "}
          in Create mode
        </p>
      )}
    </div>
  );
};

const ViewRouter = ({
  appMode,
  uniqueFilteredQuestions,
  databaseQuestions,

  config,
  effectiveApiKey,
  isAdmin,
  isProcessing,
  handlers,
  state,
  setters,
  onNavigateToCreate, // callback to switch to Create mode
  onNavigateHome, // callback to go back to landing page
  onStartTutorial, // callback to start tutorial scenario
  allQuestionsMap, // all questions for analytics
}) => {
  const {
    handleLoadFromSheets,
    handleLoadFromFirestore,
    handleUpdateDatabaseQuestion,
    handleKickBackToReview,
    handleUpdateStatus,
    handleExplain,
    handleVariate,
    handleCritique,
    handleApplyRewrite,
    handleTranslateSingle,
    handleLanguageSwitch,
    handleDelete,
    handleManualUpdate,
  } = handlers;

  const {
    currentReviewIndex,
    translationMap,
    filterByCreator,
    filteredQuestions,
    questions,
    status,
    userRole, // NEW
  } = state;
  const { setCurrentReviewIndex, setFilterByCreator, showMessage } = setters;

  /**
   * Render the appropriate view based on appMode
   * Uses early returns instead of nested ternaries for clarity
   */
  const renderView = () => {
    if (appMode === APP_MODES.ANALYTICS) {
      return (
        <AnalyticsView
          onBack={onNavigateHome}
          onStartTutorial={() => onStartTutorial(APP_MODES.ANALYTICS)}
          allQuestionsMap={allQuestionsMap}
        />
      );
    }

    if (appMode === APP_MODES.DATABASE) {
      return (
        <DatabaseView
          questions={databaseQuestions}
          sheetUrl={config.sheetUrl}
          onLoad={handleLoadFromSheets}
          onLoadFirestore={handleLoadFromFirestore}
          onUpdateQuestion={handleUpdateDatabaseQuestion}
          onKickBack={handleKickBackToReview}
          isProcessing={isProcessing}
          showMessage={showMessage}
          filterMode={state.filterMode}
          sortBy={state.sortBy}
          searchTerm={state.searchTerm}
          onStartTutorial={() => onStartTutorial(APP_MODES.DATABASE)}
          isAdmin={isAdmin}
          userRole={userRole}
        />
      );
    }

    if (appMode === APP_MODES.TEST && isAdmin) {
      return (
        <TestView
          questions={[...questions, ...databaseQuestions]}
          config={config}
          isAdmin={isAdmin}
          showMessage={showMessage}
        />
      );
    }

    if (appMode === APP_MODES.PLAYGROUND && isAdmin) {
      return (
        <PromptPlayground
          config={config}
          apiKeyReady={!!effectiveApiKey}
          effectiveApiKey={effectiveApiKey}
        />
      );
    }

    if (appMode === APP_MODES.ADMIN && isAdmin) {
      return (
        <AdminPanel
          showMessage={showMessage}
          config={config}
          handleChange={handlers.handleConfigChange}
          showApiKey={state.showApiKey}
          setShowApiKey={setters.setShowApiKey}
          files={state.files}
          handleDetectTopics={handlers.handleDetectTopics}
          isDetecting={state.isDetecting}
          fileInputRef={state.fileInputRef}
          handleFileChange={handlers.handleFileChange}
          removeFile={handlers.removeFile}
          isApiReady={!!effectiveApiKey}
          customTags={state.customTags}
          onSaveCustomTags={handlers.handleSaveCustomTags}
          currentUser={state.currentUser}
        />
      );
    }

    if (appMode === APP_MODES.TRANSLATE && isAdmin) {
      return (
        <TranslationManagementView
          questions={questions} // Use all raw questions for custom management filtering
          allQuestionsMap={allQuestionsMap}
          translationMap={translationMap}
          onTranslateSingle={handleTranslateSingle}
          onSwitchLanguage={handleLanguageSwitch}
          onUpdateStatus={handleUpdateStatus}
          onDelete={handleDelete}
          onUpdateQuestion={handleManualUpdate}
          isProcessing={isProcessing}
          showMessage={showMessage}
          userRole={userRole}
        />
      );
    }

    if (appMode === APP_MODES.REVIEW && uniqueFilteredQuestions.length > 0) {
      return (
        <ReviewMode
          questions={uniqueFilteredQuestions}
          currentIndex={currentReviewIndex}
          setCurrentIndex={setCurrentReviewIndex}
          onUpdateStatus={handleUpdateStatus}
          onExplain={handleExplain}
          onVariate={handleVariate}
          onCritique={handleCritique}
          onApplyRewrite={handleApplyRewrite}
          onTranslateSingle={handleTranslateSingle}
          onSwitchLanguage={handleLanguageSwitch}
          onDelete={handleDelete}
          onUpdateQuestion={handleManualUpdate}
          translationMap={translationMap}
          onStartTutorial={() => onStartTutorial(APP_MODES.REVIEW)}
          onKickBack={handleKickBackToReview}
          userRole={userRole}
          allQuestionsMap={allQuestionsMap}
        />
      );
    }

    if (appMode === APP_MODES.REVIEW && uniqueFilteredQuestions.length === 0) {
      return (
        <EmptyReviewState
          onNavigateToCreate={onNavigateToCreate}
          hasQuestionsInOtherFilters={
            filteredQuestions.length > 0 || questions.length > 0
          }
          isAdmin={isAdmin}
        />
      );
    }

    // Default: QuestionList for create mode
    return (
      <QuestionList
        questions={uniqueFilteredQuestions}
        translationMap={translationMap}
        appMode={appMode}
        isProcessing={isProcessing}
        onUpdateStatus={handleUpdateStatus}
        onExplain={handleExplain}
        onVariate={handleVariate}
        onCritique={handleCritique}
        onApplyRewrite={handleApplyRewrite}
        onTranslateSingle={handleTranslateSingle}
        onSwitchLanguage={handleLanguageSwitch}
        onDelete={handleDelete}
        onUpdateQuestion={handleManualUpdate}
        showMessage={showMessage}
        userRole={userRole}
        allQuestionsMap={allQuestionsMap}
      />
    );
  };

  return (
    <Suspense fallback={<LoadingSpinner />}>
      {renderView()}

      {uniqueFilteredQuestions.length === 0 &&
        filteredQuestions.length > 0 &&
        appMode !== APP_MODES.REVIEW && (
          <div className="flex flex-col items-center justify-center h-full text-slate-600 pt-10">
            <Icon name="filter" size={32} className="mb-3 text-slate-800" />
            <p className="font-medium text-slate-500">
              No questions match current filters.
            </p>
            {filterByCreator && (
              <p className="text-xs text-slate-600 mt-2">
                Filtering by Creator:{" "}
                <span className="text-blue-500 font-bold">
                  {config.creatorName}
                </span>
                .
                <button
                  onClick={() => setFilterByCreator(false)}
                  className="ml-2 underline hover:text-blue-400"
                >
                  Show All Creators?
                </button>
              </p>
            )}
          </div>
        )}

      {!state.showHistory &&
        uniqueFilteredQuestions.length === 0 &&
        questions.length === 0 &&
        !status &&
        appMode === APP_MODES.CREATE && (
          <div className="flex flex-col items-center justify-center h-full text-slate-600">
            <Icon name="terminal" size={48} className="mb-4 text-slate-800" />
            <p className="font-medium text-slate-500">
              Ready. Click 'GENERATE QUESTIONS' to begin or upload a source
              file.
            </p>
          </div>
        )}
    </Suspense>
  );
};

