import { TAGS_BY_DISCIPLINE } from "../../utils/tagTaxonomy";
import Icon from "../Icon";

const CoverageGapSuggester = ({
  allQuestionsMap,
  config,
  handleChange,
  showMessage,
  setShowGenSettings,
}) => {
  // 1. Get stats for the current selected discipline
  const currentDiscipline = config.discipline || "Technical Art";
  const availableTags = TAGS_BY_DISCIPLINE[currentDiscipline] || [];

  // 2. Count usage
  const tagCounts = {};
  availableTags.forEach((t) => (tagCounts[t] = 0));

  Array.from(allQuestionsMap.values())
    .flat()
    .forEach((q) => {
      if (q.tags && Array.isArray(q.tags)) {
        q.tags.forEach((t) => {
          const norm = t.startsWith("#") ? t : `#${t}`;
          // relaxed matching
          const key = availableTags.find(
            (at) => at.toLowerCase() === norm.toLowerCase()
          );
          if (key) tagCounts[key]++;
        });
      }
    });

  // 3. Find gaps (0 questions)
  const zeroCoverageTags = availableTags.filter((t) => tagCounts[t] === 0);
  const lowCoverageTags = availableTags.filter(
    (t) => tagCounts[t] > 0 && tagCounts[t] < 3
  );

  // Calculate total questions for this discipline
  const totalQuestions = Array.from(allQuestionsMap.values())
    .flat()
    .filter(
      (q) => q.discipline === currentDiscipline && q.status !== "rejected"
    ).length;

  // SMART VISIBILITY: Only show alert when:
  // 1. User has generated ~50% of target (100+ questions), OR
  // 2. Extreme mismatch: more than half the tags have ZERO coverage
  const TARGET_HALF = 100; // 50% of 198 target
  const hasReachedThreshold = totalQuestions >= TARGET_HALF;
  const hasExtremeMismatch = zeroCoverageTags.length > availableTags.length / 2;

  // Don't show if not enough questions yet AND no extreme mismatch
  if (!hasReachedThreshold && !hasExtremeMismatch) return null;

  // Also don't show if no gaps at all
  if (zeroCoverageTags.length === 0 && lowCoverageTags.length === 0)
    return null;

  const targetTags =
    zeroCoverageTags.length > 0
      ? zeroCoverageTags.slice(0, 3)
      : lowCoverageTags.slice(0, 3);
  const gapType =
    zeroCoverageTags.length > 0 ? "Missing Topics" : "Low Coverage";

  const handleTagClick = (tag) => {
    const currentTags = config.tags || [];
    let newTags;
    if (currentTags.includes(tag)) {
      newTags = currentTags.filter((t) => t !== tag);
    } else {
      newTags = [...currentTags, tag];
    }
    handleChange({ target: { name: "tags", value: newTags } });
  };

  const handleAutoFill = () => {
    // SMART SELECTION: Only select tags that need more questions
    // Unselect tags that already have sufficient coverage (3+ questions)
    const tagsNeedingQuestions =
      zeroCoverageTags.length > 0 ? zeroCoverageTags : lowCoverageTags;

    // Start fresh with ONLY the tags that need questions (unselects others)
    handleChange({ target: { name: "tags", value: tagsNeedingQuestions } });

    // Provide feedback showing what was selected
    const count = tagsNeedingQuestions.length;
    if (showMessage)
      showMessage(
        `Selected ${count} topic${
          count > 1 ? "s" : ""
        } needing questions. Tags with sufficient coverage unselected.`,
        4000
      );
    if (setShowGenSettings) setShowGenSettings(true);
  };

  return (
    <div className="bg-orange-500/10 border border-orange-500/30 rounded-lg p-3 animate-in fade-in slide-in-from-left-4">
      <div className="flex items-start gap-2">
        <div className="p-1.5 bg-orange-500/20 rounded text-orange-400 mt-0.5">
          <Icon name="alert-triangle" size={14} />
        </div>
        <div className="flex-1">
          <h4 className="text-xs font-bold text-orange-200 uppercase tracking-wide mb-1">
            {gapType} Detected
          </h4>
          <p className="text-[10px] text-orange-200/70 mb-2 leading-relaxed">
            The following areas in <strong>{currentDiscipline}</strong> have{" "}
            {zeroCoverageTags.length > 0 ? "no" : "few"} questions:
          </p>
          <div className="flex flex-wrap gap-1 mb-3">
            {targetTags.map((tag) => {
              const isSelected = (config.tags || []).includes(tag);
              return (
                <button
                  key={tag}
                  onClick={() => handleTagClick(tag)}
                  className={`text-[9px] px-1.5 py-0.5 rounded border transition-colors ${
                    isSelected
                      ? "bg-orange-500 text-white border-orange-600"
                      : "bg-orange-500/20 text-orange-300 border-orange-500/30 hover:bg-orange-500/30"
                  }`}
                >
                  {tag}
                </button>
              );
            })}
            {(zeroCoverageTags.length > 3 || lowCoverageTags.length > 3) && (
              <span className="text-[9px] px-1.5 py-0.5 text-orange-400/70">
                +{(zeroCoverageTags.length || lowCoverageTags.length) - 3} more
              </span>
            )}
          </div>

          <button
            onClick={handleAutoFill}
            className="w-full py-1.5 bg-orange-500 hover:bg-orange-600 text-white text-[10px] font-bold uppercase tracking-wider rounded transition-colors flex items-center justify-center gap-2 shadow-lg shadow-orange-900/20"
          >
            Focus on Suggestions <Icon name="arrow-right" size={10} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default CoverageGapSuggester;

import React, { useState } from "react";
import { listModels } from "../../services/gemini";
import Icon from "../Icon";
import CollapsibleSection from "../CollapsibleSection";
import InfoTooltip from "../InfoTooltip";
import { getMergedTags } from "../../utils/tagTaxonomy";
import CoverageGapSuggester from "./CoverageGapSuggester";
import { TARGET_PER_CATEGORY } from "../../utils/constants";

/**
 * GenerationSettings - Configuration panel with progressive disclosure
 * Basic settings always visible, Advanced collapsed by default
 */
const GenerationSettings = ({
  config,
  handleChange,
  customTags = {},
  isOpen,
  onToggle,
  allQuestionsMap = {},
  showMessage,
  setShowGenSettings,
}) => {
  const [showAdvanced, setShowAdvanced] = useState(false);
  const availableTags = getMergedTags(config.discipline, customTags);

  // Helper for progress colors to avoid nested ternaries
  const getProgressColorClass = (value, target) => {
    if (value >= target) return "text-green-400";
    if (value >= target - 5) return "text-yellow-400";
    return "text-slate-400";
  };

  const getTagCountColorClass = (count) => {
    if (count === 0) return "text-slate-500";
    if (count >= 5) return "text-green-400 font-bold";
    return "text-orange-300";
  };

  // Compute counts for each tag to show coverage
  const tagCounts = React.useMemo(() => {
    const counts = {};
    availableTags.forEach((tag) => (counts[tag] = 0));

    // Refactored to reduce function nesting depth for linting
    const allQuestions = Array.from(allQuestionsMap.values()).flat();

    for (const question of allQuestions) {
      if (!question.tags || !Array.isArray(question.tags)) continue;

      for (const t of question.tags) {
        const normalizedTag = t.startsWith("#") ? t : `#${t}`;
        // Find match in availableTags
        let match = null;
        for (const at of availableTags) {
          if (at.toLowerCase() === normalizedTag.toLowerCase()) {
            match = at;
            break;
          }
        }
        if (match) counts[match] = (counts[match] || 0) + 1;
      }
    }
    return counts;
  }, [allQuestionsMap, availableTags]);

  // Compute inventory stats for chart - show questions for selected discipline
  // SIMPLIFIED: Use uniqueId for deduplication, cleaner difficulty/type detection
  const chartData = React.useMemo(() => {
    const stats = {
      Beginner: { name: "Beginner", mc: 0, tf: 0 },
      Intermediate: { name: "Intermediate", mc: 0, tf: 0 },
      Expert: { name: "Expert", mc: 0, tf: 0 },
    };

    // Flatten and deduplicate by uniqueId (the true unique identifier)
    const allQuestions = Array.from(allQuestionsMap.values()).flat();
    const seenIds = new Set();
    const uniqueQuestions = allQuestions.filter((q) => {
      const id = q.uniqueId;
      if (!id || seenIds.has(id)) return false;
      seenIds.add(id);
      return true;
    });

    // Filter to selected discipline (non-rejected only)
    const selectedDiscipline = config.discipline?.toLowerCase().trim();
    const filtered = uniqueQuestions.filter((q) => {
      if (q.status === "rejected") return false;
      return (q.discipline || "").toLowerCase().trim() === selectedDiscipline;
    });

    // Count by difficulty and type
    filtered.forEach((q) => {
      // Normalize difficulty: EasyΓåÆBeginner, MediumΓåÆIntermediate, HardΓåÆExpert
      const rawDiff = (q.difficulty || "").split(" ")[0]; // Get first word
      let diff = rawDiff;
      if (rawDiff === "Easy") diff = "Beginner";
      else if (rawDiff === "Medium") diff = "Intermediate";
      else if (rawDiff === "Hard") diff = "Expert";

      if (!stats[diff]) return; // Skip unknown difficulties

      // Determine type: T/F or MC (default)
      const isTF = q.type === "True/False" || q.type === "T/F";
      if (isTF) stats[diff].tf++;
      else stats[diff].mc++;
    });

    return [stats["Beginner"], stats["Intermediate"], stats["Expert"]];
  }, [allQuestionsMap, config.discipline]);

  // Auto-expand Focus & Model if tags are selected or custom model is used
  // Removed showAdvanced from dependency to allow manual collapse
  React.useEffect(() => {
    if (
      (config.tags?.length > 0 || config.model !== "gemini-2.0-flash") &&
      !showAdvanced
    ) {
