import { useCallback } from "react";
import {
  generateCritiqueSecure as generateCritique,
  generateTagsSecure,
} from "../../services/geminiSecure";
import { QUALITY_THRESHOLDS, TOAST_DURATION } from "../../utils/constants";
import { logger } from "../../utils/logger";

/**
 * Hook for handling question critique and feedback loop logic.
 * Extracted from useGeneration to reduce complexity.
 */
export const useQuestionCritique = ({
  effectiveApiKey,
  isApiReady,
  showMessage,
  setStatus,
  setIsProcessing,
  updateQuestionInState,
  updateAllVariantsInState,
}) => {
  /**
   * Generates a critique and suggested rewrite for a question.
   */
  const handleCritique = useCallback(
    async (q) => {
      if (!isApiReady) {
        showMessage(
          "API key is required for critique. Please enter it in the settings panel.",
          TOAST_DURATION.LONG
        );
        return;
      }

      setIsProcessing(true);
      setStatus("Critiquing...");

      try {
        const { score, text, rewrite, improvedScore, changes } =
          await generateCritique(effectiveApiKey, q);

        // Generate tags if question has fewer than 3
        let suggestedTags = Array.isArray(q.tags) ? q.tags : [];
        if (suggestedTags.length < 3) {
          try {
            const questionForTags = rewrite
              ? {
                  question: rewrite.question || q.question,
                  optionA: rewrite.optionA || q.options?.A,
                  optionB: rewrite.optionB || q.options?.B,
                  optionC: rewrite.optionC || q.options?.C,
                  optionD: rewrite.optionD || q.options?.D,
                }
              : {
                  question: q.question,
                  optionA: q.options?.A,
                  optionB: q.options?.B,
                  optionC: q.options?.C,
                  optionD: q.options?.D,
                };

            const newTags = await generateTagsSecure(
              effectiveApiKey,
              questionForTags
            );
            if (newTags && newTags.length > 0) {
              suggestedTags = [
                ...new Set([
                  ...suggestedTags,
                  ...newTags.map((t) => t.replace(/^#/, "")),
                ]),
              ].slice(0, 5);
            }
          } catch (error) {
            logger.error("Tag generation failed during critique:", error);
          }
        }

        const updatedRewrite = rewrite
          ? {
              question: rewrite.question || q.question,
              options: {
                A: rewrite.optionA || q.options?.A || "",
                B: rewrite.optionB || q.options?.B || "",
                C: rewrite.optionC || q.options?.C || "",
                D: rewrite.optionD || q.options?.D || "",
              },
              correct: rewrite.correctLetter || q.correct || "A",
              improvements: Array.isArray(changes)
                ? changes
                : changes
                ? [changes]
                : [],
              critiqueScore: improvedScore,
              critiqueText: text,
              tags: suggestedTags,
              changesExplanation:
                rewrite.explanation ||
                "AI-suggested improvements to enhance question quality",
            }
          : null;

        const previousAttempts = q.critiqueAttempts || 0;
        const newAttemptCount = previousAttempts + 1;
        const PASSING_SCORE = QUALITY_THRESHOLDS.PASS;
        const MAX_ATTEMPTS = 3;

        const critiqueUpdate = (item) => ({
          ...item,
          critique: text,
          critiqueScore: score,
          improvedScore: improvedScore,
          suggestedRewrite: updatedRewrite,
          rewriteChanges: changes,
          critiqueAttempts: newAttemptCount,
          ...(score < PASSING_SCORE && newAttemptCount >= MAX_ATTEMPTS
            ? {
                status: "rejected",
                rejectionReason: "low_score_after_retries",
                rejectedAt: new Date().toISOString(),
              }
            : {}),
        });

        if (q.uniqueId) {
          updateAllVariantsInState(q.uniqueId, critiqueUpdate);
          updateQuestionInState(q.id, critiqueUpdate);
        } else {
          updateQuestionInState(q.id, critiqueUpdate);
        }

        if (score < PASSING_SCORE && newAttemptCount >= MAX_ATTEMPTS) {
          showMessage(
            `\u26D4 Auto-rejected: Score ${score}/100 after ${newAttemptCount} attempts. Quality too low.`,
            TOAST_DURATION.EXTENDED
          );
        } else {
          showMessage(
            `Critique Ready! Score: ${score}/100`,
            TOAST_DURATION.MEDIUM
          );
        }
      } catch (e) {
        logger.error("Critique failed:", e);
        setStatus("Fail");
        showMessage(`Critique Failed: ${e.message}`, TOAST_DURATION.LONG);
      } finally {
        setIsProcessing(false);
      }
    },
    [
      isApiReady,
      showMessage,
      effectiveApiKey,
      updateQuestionInState,
      updateAllVariantsInState,
      setStatus,
      setIsProcessing,
    ]
  );

  /**
   * Applies the suggested rewrite to the question.
   */
  const handleApplyRewrite = useCallback(
    (q) => {
      if (!q.suggestedRewrite) return;

      const updatedQ = {
        ...q,
        question: q.suggestedRewrite.question,
        options: q.suggestedRewrite.options,
        correct: q.suggestedRewrite.correct,
        suggestedRewrite: null,
        rewriteChanges: null,
        critique: null,
        critiqueScore: null,
        humanVerified: false,
        status: "pending",
        rejectionReason: null,
      };

      updateQuestionInState(q.id, () => updatedQ);
      showMessage("Γ£ô Applied! Re-critiquing...", TOAST_DURATION.SHORT);

      // Re-trigger critique after a short delay
      setTimeout(() => {
        handleCritique({ ...updatedQ, id: q.id });
      }, 300);
    },
    [updateQuestionInState, showMessage, handleCritique]
  );

  return {
    handleCritique,
    handleApplyRewrite,
  };
};

import { useState, useCallback } from "react";
import {
  generateContentSecure as generateContent,
  generateCritiqueSecure as generateCritique,
  generateTagsSecure,
} from "../../services/geminiSecure";
import { constructSystemPrompt } from "../../services/promptBuilder";
import { parseQuestions, convertMCtoTF } from "../../utils/parserUtils";
import { validateQuestion } from "../../utils/questionValidator";
import { analyzeRequest, estimateTokens } from "../../utils/tokenCounter";
import { logGeneration, logQuestion } from "../../utils/analyticsStore";
import { validateGeneration } from "../../utils/quotaEnforcement";
import {
  TOAST_DURATION,
  GENERATION_LIMITS,
  CONTEXT_LIMITS,
  QUALITY_THRESHOLDS,
} from "../../utils/constants";
import {
  calculateCoverageGaps,
  enrichGeneratedQuestions,
  filterForbiddenSources,
  verifyAndProcessQuestions,
} from "../../utils/generationUtils";
import { logger } from "../../utils/logger";

/**
 * Hook to handle question generation, explanation, and variation.
 */
export const useQuestionGenerator = ({
  config,
  effectiveApiKey,
  isApiReady,
  isTargetMet,
  allQuestionsMap,
  showMessage,
  setStatus,
  setShowNameModal,
  setShowApiError,
  setShowHistory,
  getFileContext,
  checkAndStoreQuestions,
  addQuestionsToState,
  updateQuestionInState,
  setIsProcessing,
}) => {
  const [isGenerating, setIsGenerating] = useState(false);

  const handleAutoCritique = useCallback(
    async (questions) => {
      setStatus("Auto-critiquing...");
      showMessage(
        `Running AI critique on ${questions.length} questions...`,
        TOAST_DURATION.MEDIUM
      );

      const critiqueQuestion = async (question) => {
        try {
          const { score, text, rewrite, changes } = await generateCritique(
            effectiveApiKey,
            question
          );

          let suggestedTags = question.tags || [];
          if (
            suggestedTags.length < GENERATION_LIMITS.MIN_TAGS_PER_QUESTION &&
            rewrite
          ) {
            const improvedQuestion = {
              question: rewrite.question || question.question,
              optionA: rewrite.optionA || question.options?.A,
              optionB: rewrite.optionB || question.options?.B,
              optionC: rewrite.optionC || question.options?.C,
              optionD: rewrite.optionD || question.options?.D,
            };
            const newTags = await generateTagsSecure(
              effectiveApiKey,
              improvedQuestion
            );
            if (newTags) {
              suggestedTags = [
                ...new Set([
                  ...suggestedTags,
                  ...newTags.map((t) => t.replace(/^#/, "")),
                ]),
              ];
            }
          }

          updateQuestionInState(question.id, (item) => ({
            ...item,
            critique: text,
            critiqueScore: score,
            suggestedRewrite: rewrite
              ? { ...rewrite, tags: suggestedTags }
              : null,
            rewriteChanges: changes,
          }));
          return score;
        } catch {
          return null;
        }
      };

      const batchSize = GENERATION_LIMITS.BATCH_SIZE_PARALLEL_CRITIQUE;
      const scores = [];
      for (let i = 0; i < questions.length; i += batchSize) {
        const batch = questions.slice(i, i + batchSize);
        const batchScores = await Promise.all(batch.map(critiqueQuestion));
        scores.push(...batchScores.filter((s) => s !== null));
      }

      const avgScore =
        scores.length > 0
          ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length)
          : 0;

      const highScoreCount = scores.filter(
        (s) => s >= QUALITY_THRESHOLDS.PASS
      ).length;
      const lowScoreCount = scores.filter(
        (s) => s < QUALITY_THRESHOLDS.MEDIOCRE
      ).length;

      if (lowScoreCount > 0) {
        showMessage(
          `Critique complete! Avg: ${avgScore}/100. ΓÜá∩╕Å ${lowScoreCount} need improvement.`,
          TOAST_DURATION.EXTENDED
        );
      } else {
        showMessage(
          `Critique complete! Avg: ${avgScore}/100. ${highScoreCount} ready to accept!`,
          TOAST_DURATION.LONG
        );
      }
      setStatus("");
    },
    [effectiveApiKey, setStatus, showMessage, updateQuestionInState]
  );

  const handlePerformGeneration = useCallback(
    async ({
      effectiveApiKey,
      systemPrompt,
      userPrompt,
      effectiveType,
      startTime,
      tokenAnalysis,
    }) => {
      const text = await generateContent(
        effectiveApiKey,
        systemPrompt,
        userPrompt,
        setStatus,
        config.temperature,
        config.model
      );
      const duration = Date.now() - startTime;

      const groundingSources = window.__lastGroundingSources || [];
      const groundedUrls = new Set(
        groundingSources.map((s) => s.url.toLowerCase())
      );

      let genQuestions = parseQuestions(text);
      if (genQuestions.length === 0) {
        throw new Error("Failed to parse questions.");
      }

      genQuestions = filterForbiddenSources(genQuestions);

      const expectedType =
        effectiveType === "T/F" || effectiveType === "True/False"
          ? "True/False"
          : "Multiple Choice";

      genQuestions = verifyAndProcessQuestions(
        genQuestions,
        { groundedUrls, expectedType, config },
        convertMCtoTF
      );

      window.__lastGroundingSources = [];

      const valQuestions = [];
      let rejCount = 0;

      genQuestions.forEach((q) => {
        const validation = validateQuestion(q);
        if (validation.isCriticalFailure) {
          rejCount++;
        } else {
          valQuestions.push({ ...q, _validation: validation });
        }
      });

      if (rejCount > 0) {
        showMessage(
          `Auto-rejected ${rejCount} questions with invalid metadata.`,
          TOAST_DURATION.EXTENDED
        );
      }

      const enriched = enrichGeneratedQuestions(valQuestions, {
        config,
        duration,
        costPerQuestion:
          valQuestions.length > 0
            ? tokenAnalysis.cost.estimated / valQuestions.length
            : 0,
        groundingSources,
        expectedType,
        requestedDifficulty: config.difficulty,
      });

      const uniqueQs = await checkAndStoreQuestions(enriched);

      const avgQual =
        uniqueQs.reduce((sum, q) => sum + (q.qualityScore || 0), 0) /
        (uniqueQs.length || 1);

      const genId = logGeneration({
        discipline: config.discipline,
        difficulty: config.difficulty,
        batchSize: config.batchSize,
        tokensUsed: {
          input: tokenAnalysis.input.total,
          output: estimateTokens(text),
        },
        duration,
        questionsGenerated: uniqueQs.length,
        averageQuality: Math.round(avgQual),
        success: true,
        model: config.model || "gemini-2.0-flash",
        estimatedCost: tokenAnalysis.cost.estimated,
      });

      uniqueQs.forEach((q) => {
        logQuestion({
          id: q.id,
          generationId: genId,
          created: q.dateAdded,
          status: "pending",
          qualityScore: q.qualityScore,
          discipline: q.discipline,
          difficulty: q.difficulty,
          type: q.type,
          questionText: q.question,
        });
      });

      addQuestionsToState(uniqueQs, false);
      return uniqueQs;
    },
    [
      config,
      setStatus,
      checkAndStoreQuestions,
      addQuestionsToState,
      showMessage,
    ]
  );

  const prepareGenerationContext = useCallback(async () => {
    // QUOTA ENFORCEMENT
    const allQuestions = Array.from(allQuestionsMap.values()).flat();
    const quotaCheck = validateGeneration(
      config.discipline,
      config.difficulty,
      config.batchSize,
      allQuestions,
      config.type || "Multiple Choice"
    );

    if (!quotaCheck.allowed) {
      showMessage(quotaCheck.reason, TOAST_DURATION.EXTENDED);
      return null;
    }

    let effectiveBatchSize = config.batchSize;
    if (quotaCheck.warning && quotaCheck.maxAllowed < config.batchSize) {
      effectiveBatchSize = quotaCheck.maxAllowed;
      showMessage(
        `Batch size reduced to ${quotaCheck.maxAllowed} (quota limit). ${quotaCheck.reason}`,
        TOAST_DURATION.EXTENDED
      );
    }

    const effectiveType =
      quotaCheck.forceType || config.type || "Multiple Choice";

    setIsGenerating(true);
    setShowHistory(false);
    setStatus("Drafting Scenarios...");
    const startTime = Date.now();

    // Collect rejected examples
    const rejectedExamples = Array.from(allQuestionsMap.values())
      .flat()
      .filter(
        (q) =>
          q.status === "rejected" &&
          q.rejectionReason &&
          q.discipline === config.discipline
      )
      .slice(-GENERATION_LIMITS.REJECTED_EXAMPLES_COUNT);

    // AUTO-DETECT COVERAGE GAPS
    const { TAGS_BY_DISCIPLINE } = await import("../../utils/tagTaxonomy");
    const availableTags = TAGS_BY_DISCIPLINE[config.discipline] || [];
    const coverageGaps = calculateCoverageGaps(
      config.discipline,
      availableTags,
      allQuestions
    );

    const adjustedConfig = {
      ...config,
      type: effectiveType,
      batchSize: effectiveBatchSize,
    };
    const systemPrompt = constructSystemPrompt(
      adjustedConfig,
      getFileContext(),
      rejectedExamples,
      coverageGaps
    );

    let typeInstruction = "";
    if (effectiveType === "True/False" || effectiveType === "T/F") {
      typeInstruction =
        " Generate ONLY True/False questions (no Multiple Choice).";
    } else if (effectiveType === "Multiple Choice" || effectiveType === "MC") {
      typeInstruction =
        " Generate ONLY Multiple Choice questions (no True/False).";
    }
    const userPrompt = `Generate ${effectiveBatchSize} scenario-based questions for ${config.discipline} in ${config.language}. Focus: ${config.difficulty}.${typeInstruction} Ensure links work for UE 5.7 or latest available.`;

    const tokenAnalysis = analyzeRequest(
      systemPrompt,
      userPrompt,
      CONTEXT_LIMITS.MAX_TOKENS,
      config.model || "gemini-2.0-flash"
    );

    return {
      systemPrompt,
      userPrompt,
      effectiveType,
      startTime,
      tokenAnalysis,
    };
  }, [
    config,
    allQuestionsMap,
    getFileContext,
    showMessage,
    setStatus,
    setIsGenerating,
    setShowHistory,
  ]);

  const handleGenerate = useCallback(async () => {
    if (!config.creatorName) {
      showMessage(
        "Please enter your Creator Name to start generating.",
        TOAST_DURATION.LONG
      );
      setShowNameModal(true);
      return;
    }
    if (!isApiReady) {
      setShowApiError(true);
      showMessage(
        "API key is required. Please enter it in Settings.",
        TOAST_DURATION.LONG
      );
      return;
    }

    if (isTargetMet) {
      showMessage(
        `Quota met for ${config.difficulty}! Change difficulty/type or discipline to continue.`,
        TOAST_DURATION.LONG
      );
      return;
    }

    const context = await prepareGenerationContext();
    if (!context) return;

    const {
      systemPrompt,
      userPrompt,
      effectiveType,
      startTime,
      tokenAnalysis,
    } = context;

    try {
      const uniqueNewQuestions = await handlePerformGeneration({
        effectiveApiKey,
        systemPrompt,
        userPrompt,
        effectiveType,
        startTime,
        tokenAnalysis,
      });

      // AUTO-CRITIQUE
      const autoCritiqueEnabled =
        localStorage.getItem("ue5_auto_critique") === "true";

      if (autoCritiqueEnabled && uniqueNewQuestions.length > 0) {
        handleAutoCritique(uniqueNewQuestions);
      }

      setStatus("");
    } catch (err) {
      const duration = Date.now() - startTime;
      logGeneration({
        discipline: config.discipline,
        difficulty: config.difficulty,
        batchSize: config.batchSize,
        tokensUsed: { input: tokenAnalysis?.input?.total || 0, output: 0 },
        duration,
        questionsGenerated: 0,
        averageQuality: 0,
        success: false,
        errorMessage: err.message,
        model: config.model || "gemini-2.0-flash",
        estimatedCost: tokenAnalysis?.cost?.estimated || 0,
      });
      setStatus("Error");
      showMessage(`Error: ${err.message}`, TOAST_DURATION.EXTENDED);
    } finally {
      setIsGenerating(false);
    }
  }, [
    config,
    effectiveApiKey,
    isApiReady,
    isTargetMet,
    showMessage,
    setStatus,
    setShowNameModal,
    setShowApiError,
    setIsGenerating,
    handleAutoCritique,
    handlePerformGeneration,
    prepareGenerationContext,
  ]);

  const handleExplain = useCallback(
    async (q) => {
      if (!isApiReady) {
        showMessage("API key required.", TOAST_DURATION.LONG);
        return;
      }

      setIsProcessing(true);
      setStatus("Explaining...");
      const prompt = `Explain WHY the answer is correct in simple terms: "${
        q.question
      }" Answer: "${q.correct === "A" ? q.options.A : q.options.B}"`;

      try {
        const exp = await generateContent(
          effectiveApiKey,
          "Technical Assistant",
          prompt,
          setStatus
        );
        updateQuestionInState(q.id, (item) => ({ ...item, explanation: exp }));
        setStatus("");
      } catch (error) {
        logger.error("Explanation failed:", error);
        setStatus("Fail");
      } finally {
        setIsProcessing(false);
      }
    },
    [
      effectiveApiKey,
      isApiReady,
      setStatus,
      showMessage,
      updateQuestionInState,
      setIsProcessing,
    ]
  );

  const handleVariate = useCallback(
    async (q) => {
      if (!isApiReady) {
        showMessage("API key required.", TOAST_DURATION.LONG);
        return;
      }

      setIsProcessing(true);
      setStatus("Creating improved variations...");

      // Build context-aware prompt that leverages critique feedback
      const hasCritique = q.critique && q.critiqueScore !== undefined;
      const critiqueContext = hasCritique
        ? `\n\nCRITIQUE FEEDBACK (Score: ${q.critiqueScore}/100):\n${q.critique}\n\nYour task: Generate 2 IMPROVED variations that ADDRESS the critique feedback above.`
        : `\n\nYour task: Generate 2 IMPROVED variations that are MORE CHALLENGING and PROFESSIONAL than the original.`;

      const sys = constructSystemPrompt(config, getFileContext());
      const prompt = `ORIGINAL QUESTION TO IMPROVE:
Discipline: ${q.discipline}
Difficulty: ${q.difficulty}
Type: ${q.type}
Question: "${q.question}"
Options:
A) ${q.options.A}
B) ${q.options.B}
${q.options.C ? `C) ${q.options.C}` : ""}
${q.options.D ? `D) ${q.options.D}` : ""}
Correct Answer: ${q.correct}
${critiqueContext}

REQUIREMENTS FOR VARIATIONS:
1. Address any weaknesses mentioned in the critique (if provided)
2. Increase depth and professional relevance
3. Use scenario-based or application-focused phrasing
4. Avoid trivial or overly simple questions
5. Maintain the same difficulty level: ${q.difficulty}
6. Keep the same type: ${q.type}

Output in Markdown Table format.`;

      try {
        const text = await generateContent(
          effectiveApiKey,
          sys,
          prompt,
          setStatus
        );
        const newQs = parseQuestions(text);
        if (newQs.length > 0) {
          const uniqueNewQuestions = await checkAndStoreQuestions(newQs);
          addQuestionsToState(uniqueNewQuestions, false);
          showMessage(
            `Added ${uniqueNewQuestions.length} improved variations.`,
            TOAST_DURATION.SHORT
          );
        }
      } catch (e) {
        logger.error("Variation generation failed:", e);
        setStatus("Fail");
        showMessage(
          `Failed to generate variations: ${e.message}`,
          TOAST_DURATION.EXTENDED
        );
      } finally {
        setIsProcessing(false);
      }
    },
    [
      config,
      effectiveApiKey,
      isApiReady,
      setStatus,
      showMessage,
      addQuestionsToState,
      checkAndStoreQuestions,
      setIsProcessing,
      getFileContext,
    ]
  );

  return {
    isGenerating,
    handleGenerate,
    handleExplain,
    handleVariate,
    handlePerformGeneration,
    handleAutoCritique,
  };
};

import { useState, useCallback } from "react";
import { generateContentSecure as generateContent } from "../../services/geminiSecure";
import { parseQuestions } from "../../utils/questionHelpers";
import { TOAST_DURATION } from "../../utils/constants";
import {
  getTranslationSystemPrompt,
  getTranslationUserPrompt,
} from "../../services/prompts/translationPrompts";
import { logger } from "../../utils/logger";

/**
 * Hook for handling question translation logic.
 * Extracted from useGeneration to reduce complexity.
 */
export const useQuestionTranslation = ({
  effectiveApiKey,
  isApiReady,
  showMessage,
  setStatus,
  setIsProcessing,
  checkAndStoreQuestions,
  addQuestionsToState,
  updateQuestionInState,
  handleLanguageSwitch,
  translationMap,
  allQuestionsMap,
  setShowHistory,
}) => {
  const [translationProgress, setTranslationProgress] = useState(0);

  /**
   * Translates a single question to a target language.
   */
  const handleTranslateSingle = useCallback(
    async (q, targetLang) => {
      if (!isApiReady) {
        showMessage(
          "API key is required for translation. Please enter it in the settings panel.",
          TOAST_DURATION.LONG
        );
        return;
      }

      setIsProcessing(true);
      setStatus(`Translating question to ${targetLang}...`);

      const systemPrompt = getTranslationSystemPrompt(q.language, targetLang);
      const userPrompt = getTranslationUserPrompt(q);

      try {
        const text = await generateContent(
          effectiveApiKey,
          systemPrompt,
          userPrompt,
          setStatus
        );

        // Attempt to parse JSON response
        let translatedData = null;
        try {
          const cleanText = text.replace(/```json\n?|\n?```/g, "").trim();
          translatedData = JSON.parse(cleanText);
        } catch (e) {
          logger.warn("JSON parse failed, trying parseQuestions fallback", e);
        }

        const translatedQs = translatedData
          ? parseQuestions(JSON.stringify(translatedData))
          : parseQuestions(text);

        if (translatedQs.length > 0) {
          const tq = translatedQs[0];

          // Ensure original has uniqueId
          if (!q.uniqueId) {
            const newUniqueId = crypto.randomUUID();
            const updatedOriginal = {
              ...q,
              uniqueId: newUniqueId,
              language: q.language || "English",
            };

            updateQuestionInState(q.id, () => updatedOriginal);
            await checkAndStoreQuestions([updatedOriginal]);
            q = updatedOriginal;
          }

          const translatedVariant = {
            ...tq,
            id: Date.now(),
            uniqueId: q.uniqueId,
            discipline: q.discipline,
            type: q.type,
            difficulty: q.difficulty,
            language: targetLang,
            status: q.status,
            dateAdded: new Date().toISOString(),
            tags: q.tags,
            critiqueScore: q.critiqueScore,
            sourceUrl: q.sourceUrl,
            translatedAt: new Date().toISOString(),
            translatedFrom: q.language || "English",
          };

          addQuestionsToState([translatedVariant], false);
          await checkAndStoreQuestions([translatedVariant]);
          handleLanguageSwitch(targetLang);

          showMessage(`Γ£à Translated to ${targetLang}`, TOAST_DURATION.MEDIUM);
        } else {
          throw new Error("Parser returned no questions from translation.");
        }
      } catch (e) {
        logger.error("Translation error:", e);
        setStatus("Translation Failed");
        showMessage(`Translation Failed: ${e.message}`, TOAST_DURATION.LONG);
      } finally {
        setIsProcessing(false);
      }
    },
    [
      isApiReady,
      showMessage,
      effectiveApiKey,
      setStatus,
      setIsProcessing,
      checkAndStoreQuestions,
      addQuestionsToState,
      updateQuestionInState,
      handleLanguageSwitch,
    ]
  );

  /**
   * Translates all accepted English questions to common target languages.
   */
  const handleBulkTranslateMissing = useCallback(async () => {
    if (!isApiReady) {
      showMessage(
        "API key is required for bulk translation. Please enter it in the settings panel.",
        TOAST_DURATION.LONG
      );
      return;
    }

    setIsProcessing(true);
    setShowHistory(false);

    const targetLangs = ["Chinese (Simplified)", "Japanese", "Korean"];
    const translationQueue = [];

    const baseQuestions = Array.from(allQuestionsMap.values()).map(
      (variants) => {
        const list = Array.isArray(variants) ? variants : [variants];
        return (
          list.find((v) => (v.language || "English") === "English") || list[0]
        );
      }
    );

    baseQuestions.forEach((q) => {
      const existingLangs = translationMap.get(q.uniqueId) || new Set();

      targetLangs.forEach((targetLang) => {
        if (
          q.status === "accepted" &&
          (q.language || "English") === "English" &&
          q.sourceUrl &&
          !q.invalidUrl &&
          !existingLangs.has(targetLang)
        ) {
          translationQueue.push({ question: q, targetLang });
        }
      });
    });

    if (translationQueue.length === 0) {
      showMessage(
        "All CN, JP, and KR translations already exist for all accepted questions.",
        TOAST_DURATION.LONG
      );
      setIsProcessing(false);
      return;
    }

    showMessage(
      `Found ${translationQueue.length} missing translations. Starting bulk generation...`
    );
    let generatedCount = 0;
    const totalQueueSize = translationQueue.length;

    const ID_SUBSTRING_LENGTH = 4;
    for (const { question: q, targetLang } of translationQueue) {
      const systemPrompt = getTranslationSystemPrompt(q.language, targetLang);
      const userPrompt = getTranslationUserPrompt(q);

      try {
        setStatus(
          `Translating: ${q.uniqueId.substring(
            0,
            ID_SUBSTRING_LENGTH
          )} -> ${targetLang}...`
        );
        const text = await generateContent(
          effectiveApiKey,
          systemPrompt,
          userPrompt,
          setStatus
        );

        let translatedData = null;
        try {
          const cleanText = text.replace(/```json\n?|\n?```/g, "").trim();
          translatedData = JSON.parse(cleanText);
        } catch {
          // ignore
        }

        const translatedQs = translatedData
          ? parseQuestions(JSON.stringify(translatedData))
          : parseQuestions(text);

        if (translatedQs.length > 0) {
          const tq = translatedQs[0];
          const newQuestion = {
            ...tq,
            id: Date.now() + generatedCount,
            uniqueId: q.uniqueId,
            discipline: q.discipline,
            type: q.type,
            difficulty: q.difficulty,
            language: targetLang,
            status: "pending",
            dateAdded: new Date().toISOString(),
          };

          await checkAndStoreQuestions([newQuestion]);
          addQuestionsToState([newQuestion], false);
          generatedCount++;
        }
      } catch (e) {
        logger.error(
          `Failed to generate translation for ${q.uniqueId} to ${targetLang}:`,
          e
        );
      }

      const PERCENT_CONVERSION = 100;
      setTranslationProgress(
        Math.floor((generatedCount / totalQueueSize) * PERCENT_CONVERSION)
      );
    }

    showMessage(
      `Bulk translation complete! Generated ${generatedCount} new translations.`,
      TOAST_DURATION.EXTENDED
    );
    setIsProcessing(false);
  }, [
    isApiReady,
    showMessage,
    allQuestionsMap,
    translationMap,
    effectiveApiKey,
    checkAndStoreQuestions,
    addQuestionsToState,
    setStatus,
    setShowHistory,
    setIsProcessing,
  ]);

  return {
    handleTranslateSingle,
    handleBulkTranslateMissing,
    translationProgress,
    setTranslationProgress,
  };
};

/**
 * Intelligently converts a Multiple Choice question to True/False format.
 * Creates a statement from the question + correct answer, randomly makes it TRUE or FALSE.
 *
 * @param {Object} mcQuestion - The multiple choice question object
 * @param {string} mcQuestion.question - The question text
 * @param {Object} mcQuestion.options - The answer options (A, B, C, D)
 * @param {string} mcQuestion.correct - The correct answer letter
 * @param {string} difficulty - The difficulty level to assign
 * @returns {Object} The converted True/False question
 */
export const convertMCtoTF = (mcQuestion, difficulty) => {
  const correctAnswerText = mcQuestion.options[mcQuestion.correct];
  const wrongAnswers = Object.entries(mcQuestion.options)
    .filter(([key, val]) => key !== mcQuestion.correct && val && val.trim())
    .map(([, val]) => val);

  // Check if the original question is already effectively True/False
  const lowerCorrect = correctAnswerText
    .trim()
    .toLowerCase()
    .replace(/[.,!]$/, "");
  const isBooleanAnswer = ["true", "false", "yes", "no"].includes(lowerCorrect);

  let newStatement = mcQuestion.question.trim().replace(/\?$/, "");

  // Determine truthiness and target answer based on question type
  // NOTE: Using Math.random here is acceptable - this is for educational quiz variety,
  // not cryptographic security. No security implications.
  // eslint-disable-next-line sonarjs/pseudo-random
  const randomBool = Math.random() > 0.5;

  // Declare variables with proper initial values based on condition
  const makeItTrue = isBooleanAnswer
    ? ["true", "yes"].includes(lowerCorrect)
    : randomBool;

  // Determine target answer based on question type and mode
  // eslint-disable-next-line sonarjs/pseudo-random
  const getTargetAnswer = () => {
    if (isBooleanAnswer) return correctAnswerText;
    if (makeItTrue) return correctAnswerText;
    return (
      wrongAnswers[Math.floor(Math.random() * wrongAnswers.length)] ||
      "incorrect"
    );
  };
  const targetAnswer = getTargetAnswer();

  if (!isBooleanAnswer) {
    // 1. Handle "Can you..." -> "You can [stem] [answer]"
    if (/^Can you/i.test(newStatement)) {
      const stem = newStatement.replace(/^Can you\s+/i, "");
      newStatement = `You can ${stem} ${targetAnswer}`;
    }
    // 2. Handle "Is..." -> "[Subject] is [Answer]"
    else if (/^Is\s+/i.test(newStatement)) {
      const stem = newStatement.replace(/^Is\s+/i, "");
      newStatement = `${stem} is ${targetAnswer}`;
    }
    // 3. Handle "What/Which..." -> "[Stem] is [Answer]"
    else {
      // Check for WH- words
      const isWhQuestion = /^(What|Which|How|Where|When|Why)\s+/i.test(
        newStatement
      );

      if (isWhQuestion) {
        const stem = newStatement
          .replace(
            /^(What|Which|How|Where|When|Why)\s+(is|are|does|do|can|should|would)\s+/i,
            ""
          )
          .trim();
        newStatement = `${stem} is ${targetAnswer}`;
      } else {
        // Fallback for other structures: append answer
        newStatement = `${newStatement} is ${targetAnswer}`;
      }
    }
  }

  // Cleanup: Remove double spaces, capitalize, add period
  newStatement = newStatement.replace(/\s+/g, " ").trim();
  newStatement = newStatement.charAt(0).toUpperCase() + newStatement.slice(1);
  if (!newStatement.endsWith(".")) newStatement += ".";

  return {
    ...mcQuestion,
    type: "True/False",
    difficulty: difficulty,
    question: newStatement,
    options: { A: "TRUE", B: "FALSE", C: "", D: "" },
    correct: makeItTrue ? "A" : "B",
    originalMC: mcQuestion.question, // Keep original for reference
  };
};

