import { useState, useCallback } from "react";
import { filterDuplicateQuestions } from "../../utils/questionHelpers";
import {
  PROCESSING,
  QUESTION_SOURCES,
  QUESTION_STATUS,
} from "../../utils/constants";
import {
  saveQuestionToFirestore,
  deleteQuestionFromFirestore,
} from "../../services/firebase";
import { logQuestion } from "../../utils/analyticsStore";
import { completeReviewTracking } from "../../utils/normalizeQuestion";
import { getAgents } from "../../agents";
import { logger } from "../../utils/logger";

/**
 * Hook for managing interactive actions on questions.
 */
export const useQuestionActions = (
  allQuestions,
  setAllQuestions,
  backupToCloud,
  showMessage,
  config
) => {
  // Conflict resolution state
  const [conflictData, setConflictData] = useState(null);
  const [showConflictModal, setShowConflictModal] = useState(false);

  // Delete confirmation state
  const [deleteConfirmId, setDeleteConfirmId] = useState(null);
  const [showClearModal, setShowClearModal] = useState(false);

  // Version tracking for concurrent editing
  const [questionVersions, setQuestionVersions] = useState(new Map());

  // CRUD Helpers
  const addQuestions = useCallback(
    async (newItems, source = QUESTION_SOURCES.SESSION) => {
      let targetSource =
        source === true
          ? QUESTION_SOURCES.IMPORT
          : source === false
          ? QUESTION_SOURCES.SESSION
          : source;
      await backupToCloud(newItems, targetSource);
      setAllQuestions((prev) => {
        const tagged = newItems.map((q) => ({ ...q, _source: targetSource }));
        const current = prev.filter((q) => q._source === targetSource);
        const unique = filterDuplicateQuestions(tagged, current, []);
        return [...prev, ...unique];
      });
    },
    [backupToCloud, setAllQuestions]
  );

  const updateQuestionInState = useCallback(
    (id, updates) => {
      setAllQuestions((prev) => {
        const idx = prev.findIndex((q) => q.id === id);
        if (idx === -1) return prev;
        const updated =
          typeof updates === "function" ? updates(prev[idx]) : updates;
        const newList = [...prev];
        newList[idx] = { ...updated, _source: prev[idx]._source };
        return newList;
      });
    },
    [setAllQuestions]
  );

  const updateAllVariantsInState = useCallback(
    (uniqueId, updateFn) => {
      if (!uniqueId) return;
      setAllQuestions((prev) =>
        prev.map((q) => (q.uniqueId === uniqueId ? updateFn(q) : q))
      );
    },
    [setAllQuestions]
  );

  // Status handler
  const handleUpdateStatus = useCallback(
    async (id, newStatus, rejectionReason = null) => {
      // Linear search instead of map lookup
      const currentQ = allQuestions.find((q) => q.id === id);
      if (!currentQ) return;

      if (newStatus === QUESTION_STATUS.DELETED) {
        try {
          await deleteQuestionFromFirestore(currentQ.uniqueId || currentQ.id);
          setAllQuestions((prev) => prev.filter((q) => q.id !== id));
          logQuestion({
            ...currentQ,
            status: QUESTION_STATUS.DELETED,
            deletionReason: rejectionReason || "Status update to deleted",
            deletedAt: new Date().toISOString(),
          });
        } catch (err) {
          logger.error("Failed to delete:", err);
          if (showMessage)
            showMessage("Failed to delete question from cloud.", 3000);
        }
        return;
      }

      let updatedQ = { ...currentQ, status: newStatus };
      if (
        newStatus === QUESTION_STATUS.ACCEPTED ||
        newStatus === QUESTION_STATUS.REJECTED
      ) {
        if (!updatedQ.reviewStartedAt) {
          const estimatedDurationMs =
            (PROCESSING.ESTIMATED_REVIEW_SECONDS || 30) * 1000;
          updatedQ.reviewStartedAt = new Date(
            Date.now() - estimatedDurationMs
          ).toISOString();
        }
        updatedQ = completeReviewTracking(updatedQ, config.creatorName);
      }

      updatedQ = {
        ...updatedQ,
        critique:
          newStatus === QUESTION_STATUS.ACCEPTED ? null : updatedQ.critique,
        rejectionReason:
          newStatus === QUESTION_STATUS.REJECTED ? rejectionReason : null,
        rejectedAt:
          newStatus === QUESTION_STATUS.REJECTED
            ? new Date().toISOString()
            : null,
        acceptedAt:
          newStatus === QUESTION_STATUS.ACCEPTED
            ? new Date().toISOString()
            : updatedQ.acceptedAt,
      };

      try {
        const result = await saveQuestionToFirestore(updatedQ);
        updateQuestionInState(id, updatedQ);
        if (result.queued && showMessage)
          showMessage("ΓÜá∩╕Å Connection issue - queued.", 6000);
        else if (
          showMessage &&
          (newStatus === QUESTION_STATUS.ACCEPTED ||
            newStatus === QUESTION_STATUS.REJECTED)
        ) {
          showMessage(`Γ£ô Question ${newStatus} and saved to cloud`, 2000);
        }
      } catch (err) {
        if (err.message?.startsWith("QUESTION_DELETED:")) {
          setAllQuestions((prev) => prev.filter((q) => q.id !== id));
        } else if (showMessage) {
          showMessage(`ΓÜá∩╕Å Failed to save: ${err.message}`, 5000);
        }
      }
    },
    [
      allQuestions,
      config.creatorName,
      setAllQuestions,
      updateQuestionInState,
      showMessage,
    ]
  );

  const handleUpdateQuestion = useCallback(
    async (id, updates) => {
      const currentQ = allQuestions.find((q) => q.id === id);
      if (!currentQ) return;

      const updatedQ = { ...currentQ, ...updates };
      const agents = getAgents();

      try {
        if (agents?.saveGuardAgent) {
          const baseVersion = questionVersions.get(id) || currentQ.version || 1;
          const result = await agents.saveGuardAgent.saveQuestion(
            currentQ.id,
            updates,
            baseVersion,
            config.userId,
            config.userEmail
          );

          if (!result.success) {
            if (result.errorType === "VERSION_CONFLICT") {
              setConflictData({
                serverQuestion: result.serverQuestion,
                serverVersion: result.serverVersion,
                localChanges: updates,
                expectedVersion: baseVersion,
              });
              setShowConflictModal(true);
              return;
            }
            throw new Error(result.error);
          }

          setQuestionVersions((prev) =>
            new Map(prev).set(id, result.newVersion)
          );
          updateQuestionInState(id, {
            ...updatedQ,
            version: result.newVersion,
          });
        } else {
          await saveQuestionToFirestore(updatedQ);
          updateQuestionInState(id, updatedQ);
        }
      } catch (err) {
        if (err.message?.startsWith("QUESTION_DELETED:")) {
          setAllQuestions((prev) => prev.filter((q) => q.id !== id));
        } else if (showMessage) {
          showMessage(`ΓÜá∩╕Å Failed to save: ${err.message}`, 4000);
        }
      }
    },
    [
      allQuestions,
      questionVersions,
      config.userId,
      config.userEmail,
      setAllQuestions,
      updateQuestionInState,
      showMessage,
    ]
  );

  const replaceQuestions = useCallback(
    (newItems, source) => {
      setAllQuestions((prev) => {
        const others = prev.filter((q) => q._source !== source);
        const tagged = newItems.map((q) => ({ ...q, _source: source }));
        return [...others, ...tagged];
      });
    },
    [setAllQuestions]
  );

  const bulkDeleteQuestions = useCallback(
    (idsToDelete) => {
      const idSet = new Set(idsToDelete);
      setAllQuestions((prev) => prev.filter((q) => !idSet.has(q.id)));
    },
    [setAllQuestions]
  );

  const moveQuestion = useCallback(
    async (id, targetSource, updates = {}) => {
      const currentQ = allQuestions.find((q) => q.id === id);
      if (!currentQ) return;

      const updatedQ = {
        ...currentQ,
        ...updates,
        _source: targetSource,
        modifiedAt: new Date().toISOString(),
      };

      try {
        await saveQuestionToFirestore(updatedQ);

        // Update local state
        updateQuestionInState(id, updatedQ);

        if (showMessage) {
          showMessage("Question moved successfully.", 2000);
        }
      } catch (err) {
        logger.error("Failed to move question:", err);
        if (showMessage) {
          showMessage(`Failed to move question: ${err.message}`, 3000);
        }
      }
    },
    [allQuestions, saveQuestionToFirestore, updateQuestionInState, showMessage]
  );

  const clearQuestions = useCallback(() => {
    setAllQuestions((prev) =>
      prev.filter((q) => q._source !== QUESTION_SOURCES.SESSION)
    );
    setShowClearModal(false);
    if (showMessage) showMessage("Session questions cleared", "success");
  }, [setAllQuestions, showMessage]);

  return {
    addQuestions,
    updateQuestionInState,
    updateAllVariantsInState,
    handleUpdateStatus,
    handleUpdateQuestion,
    replaceQuestions,
    bulkDeleteQuestions,
    moveQuestion,
    clearQuestions,
    conflictData,
    setConflictData,
    showConflictModal,
    setShowConflictModal,
    deleteConfirmId,
    setDeleteConfirmId,
    showClearModal,
    setShowClearModal,
    questionVersions,
    setQuestionVersions,
  };
};

import { useMemo } from "react";
// import { QUOTA_TARGETS } from "../useQuestionManager"; // Removed unused import causing circular dependency error
import { QUESTION_SOURCES, QUESTION_STATUS } from "../../utils/constants";
import {
  CATEGORY_KEYS,
  TARGET_TOTAL,
  TARGET_PER_CATEGORY,
} from "../../utils/constants";

/**
 * Hook for deriving various views, maps, and statistics from the main allQuestions state.
 */
export const useQuestionDerivedData = (allQuestions, config) => {
  // Derived arrays for specific sources
  const questions = useMemo(
    () => allQuestions.filter((q) => q._source === QUESTION_SOURCES.SESSION),
    [allQuestions]
  );

  const historicalQuestions = useMemo(
    () => allQuestions.filter((q) => q._source === QUESTION_SOURCES.IMPORT),
    [allQuestions]
  );

  const databaseQuestions = useMemo(
    () => allQuestions.filter((q) => q._source === QUESTION_SOURCES.DATABASE),
    [allQuestions]
  );

  // Central question storage map - memoized for performance
  const allQuestionsMap = useMemo(() => {
    const newMap = new Map();

    allQuestions.forEach((q) => {
      const id = q.uniqueId || q.id;
      if (!id) return;
      if (!newMap.has(id)) newMap.set(id, []);

      const variants = newMap.get(id);
      const lang = q.language || "English";

      if (!variants.some((v) => (v.language || "English") === lang)) {
        variants.push(q);
      }
    });

    return newMap;
  }, [allQuestions]);

  // Translation Map - derived from the stable allQuestionsMap
  const translationMap = useMemo(() => {
    const map = new Map();
    Array.from(allQuestionsMap.keys()).forEach((uniqueId) => {
      const variants = allQuestionsMap.get(uniqueId);
      const langSet = new Set(variants.map((v) => v.language || "English"));
      map.set(uniqueId, langSet);
    });
    return map;
  }, [allQuestionsMap]);

  // Unified List (Canonical view for counts)
  const unifiedQuestions = useMemo(() => {
    const all = [];
    Array.from(allQuestionsMap.keys()).forEach((uniqueId) => {
      const variants = allQuestionsMap.get(uniqueId);
      const canonical =
        variants.find((v) => (v.language || "English") === "English") ||
        variants[0];
      if (canonical) all.push(canonical);
    });

    return all.sort((a, b) => {
      const dateA = new Date(a.created || a.dateAdded || 0).getTime();
      const dateB = new Date(b.created || b.dateAdded || 0).getTime();
      if (dateB !== dateA) return dateB - dateA;
      return (a.uniqueId || "").localeCompare(b.uniqueId || "");
    });
  }, [allQuestionsMap]);

  // Statistics
  const approvedCounts = useMemo(() => {
    const counts = CATEGORY_KEYS.reduce(
      (acc, key) => ({ ...acc, [key]: 0 }),
      {}
    );

    unifiedQuestions.forEach((q) => {
      if (
        (q.status === QUESTION_STATUS.ACCEPTED ||
          q.status === QUESTION_STATUS.PENDING ||
          !q.status) &&
        q.discipline === config.discipline
      ) {
        const typeAbbrev = q.type === "True/False" ? "T/F" : "MC";
        const key = `${q.difficulty} ${typeAbbrev}`;
        if (counts.hasOwnProperty(key)) {
          counts[key]++;
        }
      }
    });
    return counts;
  }, [unifiedQuestions, config.discipline]);

  const approvedCount = useMemo(
    () =>
      unifiedQuestions.filter((q) => q.status === QUESTION_STATUS.ACCEPTED)
        .length,
    [unifiedQuestions]
  );
  const rejectedCount = useMemo(
    () =>
      unifiedQuestions.filter((q) => q.status === QUESTION_STATUS.REJECTED)
        .length,
    [unifiedQuestions]
  );
  const pendingCount = useMemo(
    () =>
      unifiedQuestions.filter(
        (q) => !q.status || q.status === QUESTION_STATUS.PENDING
      ).length,
    [unifiedQuestions]
  );
  const otherCount = useMemo(
    () =>
      unifiedQuestions.filter(
        (q) =>
          q.status && !["accepted", "rejected", "pending"].includes(q.status)
      ).length,
    [unifiedQuestions]
  );

  const totalApproved = useMemo(
    () => Object.values(approvedCounts).reduce((a, b) => a + b, 0),
    [approvedCounts]
  );
  const overallPercentage = useMemo(
    () => Math.min(100, (totalApproved / TARGET_TOTAL) * 100),
    [totalApproved]
  );

  const isTargetMet = useMemo(() => {
    const typeKey = config.type === "True/False" ? "T/F" : "MC";
    const categoryKey = `${config.difficulty} ${typeKey}`;
    return (approvedCounts[categoryKey] || 0) >= TARGET_PER_CATEGORY;
  }, [config.difficulty, config.type, approvedCounts]);

  return {
    questions,
    historicalQuestions,
    databaseQuestions,
    allQuestionsMap,
    translationMap,
    unifiedQuestions,
    approvedCounts,
    approvedCount,
    rejectedCount,
    pendingCount,
    otherCount,
    totalApproved,
    overallPercentage,
    isTargetMet,
  };
};

import { useState, useEffect } from "react";
import { getSecureItem, setSecureItem } from "../../utils/secureStorage";
import { logger } from "../../utils/logger";
import { STORAGE_KEYS, QUESTION_SOURCES } from "../../utils/constants";

/**
 * Hook for managing the raw question state and local persistence.
 * This is the lowest-level hook for question data.
 */
export const useQuestionState = (config) => {
  // Unified State: Single source of truth for ALL questions
  // Unified State: Single source of truth for ALL questions
  const [allQuestions, setAllQuestions] = useState([]);

  // Load questions asynchronously to unblock initial render
  useEffect(() => {
    const loadState = async () => {
      // Yield to main thread
      await new Promise((resolve) => setTimeout(resolve, 0));

      const saved = getSecureItem(STORAGE_KEYS.QUESTIONS);
      if (saved && Array.isArray(saved)) {
        // Hydrate saved questions as 'session' source
        setAllQuestions(
          saved.map((q) => ({ ...q, _source: QUESTION_SOURCES.SESSION }))
        );
      }
    };
    loadState();
  }, []);

  // Persist session questions ONLY to localStorage
  useEffect(() => {
    const sessionQuestions = allQuestions.filter(
      (q) => q._source === QUESTION_SOURCES.SESSION
    );
    // Strip the internal _source tag before saving to avoid cluttering storage/exports
    const cleanQuestions = sessionQuestions.map(({ _source, ...q }) => q);
    setSecureItem(STORAGE_KEYS.QUESTIONS, cleanQuestions);
  }, [allQuestions]);

  // Backfill creatorName on questions missing it (Session only)
  useEffect(() => {
    if (!config.creatorName) return;

    const needsBackfill = allQuestions.some(
      (q) =>
        q._source === QUESTION_SOURCES.SESSION &&
        (!q.creatorName ||
          q.creatorName === "N/A" ||
          q.creatorName === "Unknown")
    );

    if (needsBackfill) {
      setAllQuestions((prev) =>
        prev.map((q) => {
          if (
            q._source === QUESTION_SOURCES.SESSION &&
            (!q.creatorName ||
              q.creatorName === "N/A" ||
              q.creatorName === "Unknown")
          ) {
            return { ...q, creatorName: config.creatorName };
          }
          return q;
        })
      );
    }
  }, [config.creatorName, allQuestions]);

  return [allQuestions, setAllQuestions];
};

import { useEffect } from "react";
import { logger } from "../../utils/logger";
import { STORAGE_KEYS, QUESTION_SOURCES } from "../../utils/constants";
import { saveQuestionToFirestore } from "../../services/firebase";

/**
 * Hook for handling external synchronization (storage events, cloud auto-save).
 */
export const useQuestionSync = (allQuestions, setAllQuestions) => {
  // Sync questions across browser tabs via storage event
  useEffect(() => {
    const handleStorageChange = (e) => {
      if (e.key === STORAGE_KEYS.QUESTIONS && e.newValue) {
        try {
          const newSessionQuestions = JSON.parse(e.newValue).map((q) => ({
            ...q,
            _source: QUESTION_SOURCES.SESSION,
          }));
          logger.log(
            `≡ƒöä Syncing ${newSessionQuestions.length} questions from another tab...`
          );

          // Update ONLY the session questions in the unified state
          setAllQuestions((prev) => {
            const nonSession = prev.filter(
              (q) => q._source !== QUESTION_SOURCES.SESSION
            );
            return [...nonSession, ...newSessionQuestions];
          });
        } catch (err) {
          logger.error("Failed to sync questions from storage:", err);
        }
      }
    };

    window.addEventListener("storage", handleStorageChange);
    return () => window.removeEventListener("storage", handleStorageChange);
  }, [setAllQuestions]);

  /**
   * Helper to perform cloud backup
   */
  const backupToCloud = async (newItems, targetSource) => {
    if (
      targetSource === QUESTION_SOURCES.SESSION &&
      newItems &&
      newItems.length > 0
    ) {
      logger.log(`≡ƒÆ╛ Auto-saving ${newItems.length} questions to Firestore...`);
      const savePromises = newItems.map((q) =>
        saveQuestionToFirestore(q).catch((err) => {
          logger.warn(`ΓÜá∩╕Å Failed to auto-save question ${q.uniqueId}:`, err);
        })
      );
      await Promise.all(savePromises);
      logger.log(`Γ£ô Auto-saved ${newItems.length} questions to cloud`);
    }
  };

  return { backupToCloud };
};

import { useState, useEffect, useRef } from "react";
import { getSecureItem, setSecureItem } from "../utils/secureStorage";
import { logger } from "../utils/logger";
import { DEFAULT_CONFIG, STORAGE_KEYS, APP_MODES } from "../utils/constants";

export const useAppConfig = () => {
  // Application mode: 'landing' (home screen), 'create' (generation mode), 'review' (review mode), 'database' (view all)
  const [appMode, setAppMode] = useState(() => {
    // SECURITY: Get mode from localStorage if available to prevent flash-resets on hydrate
    if (typeof window === "undefined") return APP_MODES.LANDING;
    return localStorage.getItem(STORAGE_KEYS.APP_MODE) || APP_MODES.LANDING;
  });

  // Check if running in internal Canvas environment (has auto-injected API key)
  const isInternalEnvironment =
    typeof window !== "undefined" && typeof window.__app_id !== "undefined";

  // Authentication status - always ready for local/Sheets operations
  const isAuthReady = true;

  // SECURITY WARNING: Storing API keys in localStorage is insecure!
  // This is a temporary solution. For production:
  // 1. Move API calls to a backend proxy server
  // 2. Never expose API keys in client-side code
  // 3. Use server-side authentication with the Gemini API

  // Main application configuration (persisted to localStorage)
  const [config, setConfig] = useState(() => {
    const saved = getSecureItem(STORAGE_KEYS.CONFIG);

    // Merge saved config with defaults
    const initialConfig = saved
      ? { ...DEFAULT_CONFIG, ...saved }
      : { ...DEFAULT_CONFIG };

    // Ensure all required fields have default values (double-check)
    initialConfig.creatorName = initialConfig.creatorName || "";
    initialConfig.reviewerName = initialConfig.reviewerName || "";
    initialConfig.apiKey = initialConfig.apiKey || "";

    return initialConfig;
  });

  // API key status computed values
  // Cloud Functions are available when user is authenticated (checked via Firebase Auth in App.jsx)
  // We'll accept auth status as a prop to determine if Cloud Functions are available
  const hasClientKey = config.apiKey && config.apiKey.length > 5;
  const isApiReady = isInternalEnvironment || hasClientKey || isAuthReady; // Cloud Functions count as "ready"
  const effectiveApiKey = isInternalEnvironment ? "" : config.apiKey;

  // Status priority: Internal > Cloud Functions > Client Key > Not Set
  let apiKeyStatus;
  if (isInternalEnvironment) {
    apiKeyStatus = "Auto-Injected";
  } else if (hasClientKey) {
    apiKeyStatus = "Loaded";
  } else if (isAuthReady) {
    apiKeyStatus = "Cloud Functions"; // User is authenticated, can use server-side API
  } else {
    apiKeyStatus = "Not Set";
  }

  // UI States
  const [showNameModal, setShowNameModal] = useState(false);
  const [showGenSettings, setShowGenSettings] = useState(true);
  const [showApiError, setShowApiError] = useState(false);
  const [batchSizeWarning, setBatchSizeWarning] = useState("");
  const [showSettings, setShowSettings] = useState(false);
  const [showApiKey, setShowApiKey] = useState(false);

  // Track if this is the initial mount
  const hasInitialized = useRef(false);

  // Effects
  useEffect(() => {
    // Skip the first render to allow localStorage to hydrate
    if (!hasInitialized.current) {
      hasInitialized.current = true;
      // Only show modal if name is truly empty after initial load
      const savedConfig = getSecureItem(STORAGE_KEYS.CONFIG);
      if (!savedConfig?.creatorName && !config.creatorName) {
        setShowNameModal(true);
      }
      return;
    }
    // After initial mount, show modal if name becomes empty
    if (!config.creatorName) setShowNameModal(true);
  }, [config.creatorName]);

  useEffect(() => {
    setSecureItem(STORAGE_KEYS.CONFIG, config);
  }, [config]);

  // Persist appMode to localStorage independently for faster restoration
  useEffect(() => {
    if (typeof window !== "undefined") {
      localStorage.setItem(STORAGE_KEYS.APP_MODE, appMode);
    }
  }, [appMode]);

  // Handlers
  // pendingNavigationUniqueId tracks the uniqueId to navigate to after language switch
  const [pendingNavigationUniqueId, setPendingNavigationUniqueId] =
    useState(null);

  const handleLanguageSwitch = (lang, uniqueId = null) => {
    logger.log(
      "≡ƒîì [handleLanguageSwitch] Switching global language filter to:",
      lang,
      "| Navigate to uniqueId:",
      uniqueId
    );
    // Store the uniqueId for navigation after re-filter
    if (uniqueId) {
      setPendingNavigationUniqueId(uniqueId);
    }
    setConfig((prev) => ({ ...prev, language: lang }));
  };

  const handleChange = (e) => {
    const { name, value } = e.target;

    // Validate batch size
    if (name === "batchSize") {
      setBatchSizeWarning("");
    }

    setConfig((prev) => ({ ...prev, [name]: value }));

    if (name === "language") {
      handleLanguageSwitch(value);
    }
    if (name === "apiKey") {
      setShowApiError(false);
    }
  };

  const handleNameSave = (name) => {
    setConfig((prev) => ({ ...prev, creatorName: name, reviewerName: name }));
    setShowNameModal(false);
  };

  return {
    appMode,
    setAppMode,
    config,
    setConfig,
    isInternalEnvironment,
    isAuthReady,
    isApiReady,
    effectiveApiKey,
    apiKeyStatus,
    showNameModal,
    setShowNameModal,
    showGenSettings,
    setShowGenSettings,
    showApiError,
    setShowApiError,
    batchSizeWarning,
    setBatchSizeWarning,
    showSettings,
    setShowSettings,
    showApiKey,
    setShowApiKey,
    handleChange,
    handleNameSave,
    handleLanguageSwitch,
    pendingNavigationUniqueId,
    setPendingNavigationUniqueId,
  };
};

/**
 * useAuth Hook
 *
 * Manages authentication state, registration, custom tags, and compliance modals:
 * - Firebase authentication state
 * - User registration status (invite system)
 * - Admin status from Firestore (server-side only - security fix V-002)
 * - Custom tags from Firestore
 * - Token usage tracking
 * - Age verification and terms acceptance modals
 */
import { useState, useEffect } from "react";
import { onAuthStateChanged } from "firebase/auth";
import { auth, getCustomTags, saveCustomTags } from "../services/firebase";
import { getTokenUsage } from "../utils/analyticsStore";
import {
  checkUserRegistration,
  setupInitialAdmin,
} from "../services/inviteService";
import { logger } from "../utils/logger";

// SECURITY FIX V-002: Removed client-side FALLBACK_ADMIN_EMAILS
// Admin detection now happens entirely server-side via checkUserRegistration()
// and setupInitialAdmin() Cloud Functions

/**
 * Custom hook for managing authentication and compliance state.
 *
 * @param {Function} showMessage - Function to display toast messages
 * @returns {Object} Auth state, custom tags, compliance state and handlers
 */
export function useAuth(showMessage) {
  // ========================================================================
  // STATE
  // ========================================================================
  const [user, setUser] = useState(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState(false);
  const [userRole, setUserRole] = useState("user");
  const [isRegistered, setIsRegistered] = useState(false);
  const [registrationLoading, setRegistrationLoading] = useState(true);
  const [customTags, setCustomTags] = useState({});
  const [tokenUsage, setTokenUsage] = useState(() => getTokenUsage());

  // Compliance modals
  const [showTerms, setShowTerms] = useState(false);
  const [showAgeGate, setShowAgeGate] = useState(false);
  const [termsAccepted, setTermsAccepted] = useState(false);

  // ========================================================================
  // EFFECTS
  // ========================================================================

  // Listen for auth state changes and check registration
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);

      if (currentUser) {
        // Check registration status via Cloud Function (server-side admin detection)
        setRegistrationLoading(true);
        try {
          let regStatus = await checkUserRegistration();

          // If not registered, attempt server-side admin setup
          // Server validates email whitelist - client never sees the whitelist
          if (!regStatus.registered) {
            try {
              const adminResult = await setupInitialAdmin();
              if (adminResult.success) {
                logger.log("Γ£à Server-side admin setup successful");
                regStatus = {
                  registered: true,
                  role: adminResult.role || "admin",
                };
              }
            } catch {
              // setupInitialAdmin throws if email not whitelisted - this is expected
              logger.log("Γä╣∩╕Å Not a whitelisted admin email");
            }
          }

          setIsRegistered(regStatus.registered);
          setUserRole(regStatus.role || "user");
          setIsAdmin(regStatus.role === "admin");
        } catch (error) {
          logger.error("Failed to check registration:", error);
          // SECURITY: On error, default to no access (fail closed)
          setIsAdmin(false);
          setIsRegistered(false);
          setUserRole("user");
        } finally {
          setRegistrationLoading(false);
        }

        // Load custom tags from Firestore
        try {
          const tags = await getCustomTags();
          setCustomTags(tags);
        } catch (error) {
          logger.error("Failed to load custom tags:", error);
        }
      } else {
        setIsAdmin(false);
        setIsRegistered(false);
        setUserRole("user");
        setRegistrationLoading(false);
      }
    });
    return () => unsubscribe();
  }, []);

  // Refresh token usage periodically
  useEffect(() => {
    const interval = setInterval(() => setTokenUsage(getTokenUsage()), 5000);
    return () => clearInterval(interval);
  }, []);

  // Check compliance status on app load
  useEffect(() => {
    const ageVerified = localStorage.getItem("ue5_age_verified");
    const termsAcceptedStorage = localStorage.getItem("ue5_terms_accepted");

    if (!ageVerified) {
      setShowAgeGate(true);
    } else if (!termsAcceptedStorage) {
      setShowTerms(true);
    } else {
      setTermsAccepted(true);
    }
  }, []);

  // ========================================================================
  // HANDLERS
  // ========================================================================

  /**
   * Save custom tags to Firestore.
   *
   * @param {Object} newCustomTags - New custom tags object
   */
  const handleSaveCustomTags = async (newCustomTags) => {
    try {
      await saveCustomTags(newCustomTags);
      setCustomTags(newCustomTags);
      showMessage("Custom tags saved!", 2000);
    } catch (error) {
      logger.error("Failed to save custom tags:", error);
      showMessage("Failed to save tags", 3000);
    }
  };

  /**
   * Mark user as registered (called after successful invite consumption)
   */
  const markAsRegistered = (role = "user") => {
    setIsRegistered(true);
    setUserRole(role);
    if (role === "admin") {
      setIsAdmin(true);
    }
  };

  // ========================================================================
  // RETURN
  // ========================================================================
  return {
    // Auth state
    user,
    authLoading,
    isAdmin,
    userRole,

    // Registration state (invite system)
    isRegistered,
    registrationLoading,
    markAsRegistered,

    // Custom tags
    customTags,
    setCustomTags,
    handleSaveCustomTags,

    // Token usage
    tokenUsage,

    // Compliance
    showTerms,
    setShowTerms,
    showAgeGate,
    setShowAgeGate,
    termsAccepted,
    setTermsAccepted,
  };
}

import { useEffect, useCallback, useRef } from 'react';
import { logger } from "../utils/logger";

/**
 * Hook for auto-saving data to localStorage
 * @param {string} key - localStorage key
 * @param {any} data - Data to save
 * @param {number} interval - Save interval in milliseconds (default: 10000)
 * @param {boolean} enabled - Whether auto-save is enabled
 */
export const useAutoSave = (key, data, interval = 10000, enabled = true) => {
    const intervalRef = useRef(null);
    const lastSaveRef = useRef(null);

    const saveData = useCallback(() => {
        if (!enabled || !data) return;

        try {
            const savePayload = {
                data,
                timestamp: Date.now(),
                version: '1.0'
            };
            localStorage.setItem(key, JSON.stringify(savePayload));
            lastSaveRef.current = Date.now();
            logger.log(`Auto-saved: ${key}`);
        } catch (error) {
            logger.error('Auto-save failed:', error);
        }
    }, [key, data, enabled]);

    const loadData = useCallback(() => {
        try {
            const saved = localStorage.getItem(key);
            if (saved) {
                const { data: savedData, timestamp } = JSON.parse(saved);
                return { data: savedData, timestamp };
            }
        } catch (error) {
            logger.error('Failed to load saved data:', error);
        }
        return null;
    }, [key]);

    const clearSaved = useCallback(() => {
        localStorage.removeItem(key);
        lastSaveRef.current = null;
        logger.log(`Cleared saved data: ${key}`);
    }, [key]);

    const hasSavedData = useCallback(() => {
        return localStorage.getItem(key) !== null;
    }, [key]);

    // Auto-save effect
    useEffect(() => {
        if (enabled && data) {
            // Initial save
            saveData();

            // Set up interval
            intervalRef.current = setInterval(saveData, interval);

            return () => {
                if (intervalRef.current) {
                    clearInterval(intervalRef.current);
                }
            };
        }
    }, [enabled, data, interval, saveData]);

    return {
        saveData,
        loadData,
        clearSaved,
        hasSavedData,
        lastSaveTime: lastSaveRef.current
    };
};

export default useAutoSave;

import { useState, useCallback } from "react";
import { logger } from "../utils/logger";

/**
 * Hook for managing bulk translation operations.
 *
 * @param {Object} params - Hook parameters
 * @param {Function} params.onTranslateSingle - Function to translate a single question
 * @param {Function} params.showMessage - Function to display toast messages
 * @returns {Object} Bulk translation state and handlers
 */
export const useBulkTranslation = (onTranslateSingle, showMessage) => {
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);
  const [progress, setProgress] = useState({ current: 0, total: 0 });

  /**
   * Translates a list of questions to a target language sequentially.
   *
   * @param {Array} questions - Questions to translate
   * @param {string} targetLanguage - Language to translate into
   */
  const handleBulkTranslate = useCallback(
    async (questions, targetLanguage) => {
      if (!questions || questions.length === 0) {
        showMessage("No questions selected for translation.", 3000);
        return;
      }

      if (isBulkProcessing) return;

      const confirmed = window.confirm(
        `Are you sure you want to translate ${questions.length} questions to ${targetLanguage}? This will use Gemini API tokens.`
      );

      if (!confirmed) return;

      setIsBulkProcessing(true);
      setProgress({ current: 0, total: questions.length });

      let successCount = 0;
      let failCount = 0;

      for (let i = 0; i < questions.length; i++) {
        const q = questions[i];
        try {
          setProgress((prev) => ({ ...prev, current: i + 1 }));
          await onTranslateSingle(q, targetLanguage);
          successCount++;
        } catch (error) {
          logger.error(
            `Γ¥î [BulkTranslate] Failed for ID ${q.uniqueId}:`,
            error
          );
          failCount++;
          // Continue with next instead of failing entire batch
        }
      }

      setIsBulkProcessing(false);
      setProgress({ current: 0, total: 0 });

      if (failCount > 0) {
        showMessage(
          `Bulk translation complete: ${successCount} success, ${failCount} failed.`,
          5000
        );
      } else {
        showMessage(
          `Γ£ô Successfully translated ${successCount} questions to ${targetLanguage}!`,
          5000
        );
      }
    },
    [onTranslateSingle, showMessage, isBulkProcessing]
  );

  return {
    handleBulkTranslate,
    isBulkProcessing,
    progress,
  };
};

import { useState, useEffect } from "react";
import {
  getConnectionStatus,
  subscribeToConnectionStatus,
  getQueueDetails,
} from "../services/firebase";

/**
 * Hook to track connection status and sync queue state.
 * Provides real-time updates when connection changes or queue updates.
 */
export const useConnectionStatus = () => {
  const [status, setStatus] = useState(() => getConnectionStatus());
  const [queueDetails, setQueueDetails] = useState(() => getQueueDetails());

  useEffect(() => {
    // Subscribe to connection status changes from firebase
    const unsubscribe = subscribeToConnectionStatus((newStatus) => {
      setStatus(newStatus);
      setQueueDetails(getQueueDetails());
    });

    // Also listen for browser online/offline events directly
    const handleOnline = () => {
      const s = getConnectionStatus();
      setStatus(s);
      setQueueDetails(getQueueDetails());
    };
    const handleOffline = () => {
      const s = getConnectionStatus();
      setStatus(s);
      setQueueDetails(getQueueDetails());
    };

    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);

    return () => {
      unsubscribe();
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, []);

  return { ...status, queueDetails };
};

export default useConnectionStatus;

import { useState, useEffect, useCallback } from "react";
import { getQuestionsFromFirestore } from "../services/firebase";
import { logger } from "../utils/logger";

/**
 * useCrashRecovery - Detects potential data loss from crashes and offers to restore from Firestore
 *
 * Detection heuristics:
 * 1. LocalStorage has fewer questions than expected from last session
 * 2. Firestore has questions but localStorage is empty
 * 3. Session flag indicates unexpected termination
 */
export const useCrashRecovery = (
  localQuestions,
  addQuestionsToState,
  showMessage
) => {
  const [showRecoveryPrompt, setShowRecoveryPrompt] = useState(false);
  const [recoveryData, setRecoveryData] = useState(null);
  const [isRecovering, setIsRecovering] = useState(false);

  // Check for crash on mount
  useEffect(() => {
    const checkForCrash = async () => {
      try {
        // Skip if user already dismissed or recovered this session
        const alreadyHandled = sessionStorage.getItem("ue5_recovery_handled");
        const permanentlyDismissed = localStorage.getItem(
          "ue5_recovery_dismissed"
        );

        if (alreadyHandled === "true" || permanentlyDismissed === "true") {
          logger.log(
            "≡ƒöç Skipping recovery check (already handled this session)"
          );
          return;
        }

        // Get session info
        const lastSessionCount = parseInt(
          localStorage.getItem("ue5_last_session_count") || "0"
        );
        const sessionActive = localStorage.getItem("ue5_session_active");
        const currentLocalCount = localQuestions.length;

        // If session was marked active but we have fewer questions, might be a crash
        const possibleCrash =
          sessionActive === "true" && currentLocalCount < lastSessionCount;
        const localEmpty = currentLocalCount === 0;

        if (possibleCrash || localEmpty) {
          // Check Firestore for backup data
          logger.log("≡ƒöì Checking Firestore for recoverable data...");
          const firestoreQuestions = await getQuestionsFromFirestore();

          if (firestoreQuestions.length > currentLocalCount) {
            logger.log(
              `≡ƒôª Found ${firestoreQuestions.length} questions in Firestore (local has ${currentLocalCount})`
            );
            setRecoveryData({
              firestoreCount: firestoreQuestions.length,
              localCount: currentLocalCount,
              questions: firestoreQuestions,
            });
            setShowRecoveryPrompt(true);
          } else {
            // No recovery needed, mark as handled
            sessionStorage.setItem("ue5_recovery_handled", "true");
          }
        } else {
          // No recovery needed, mark as handled
          sessionStorage.setItem("ue5_recovery_handled", "true");
        }

        // Mark session as active
        localStorage.setItem("ue5_session_active", "true");
      } catch (error) {
        logger.warn("Crash recovery check failed:", error);
      }
    };

    // Delay check to allow auth to settle
    const timer = setTimeout(checkForCrash, 2000);
    return () => clearTimeout(timer);
  }, [localQuestions.length]);

  // Update session count periodically
  useEffect(() => {
    const interval = setInterval(() => {
      localStorage.setItem(
        "ue5_last_session_count",
        localQuestions.length.toString()
      );
    }, 10000); // Every 10 seconds

    return () => clearInterval(interval);
  }, [localQuestions.length]);

  // Clean up session flag on proper unload
  useEffect(() => {
    const handleBeforeUnload = () => {
      localStorage.setItem("ue5_session_active", "false");
      localStorage.setItem(
        "ue5_last_session_count",
        localQuestions.length.toString()
      );
    };

    window.addEventListener("beforeunload", handleBeforeUnload);
    return () => window.removeEventListener("beforeunload", handleBeforeUnload);
  }, [localQuestions.length]);

  // Recovery action
  const handleRecover = useCallback(async () => {
    if (!recoveryData) return;

    setIsRecovering(true);

    // Start time for minimum display duration
    const startTime = Date.now();
    const MIN_DISPLAY_MS = 1500; // Show progress for at least 1.5 seconds

    try {
      // Merge Firestore questions into local state
      const existingIds = new Set(localQuestions.map((q) => q.uniqueId));
      const newQuestions = recoveryData.questions.filter(
        (q) => !existingIds.has(q.uniqueId)
      );

      if (newQuestions.length > 0) {
        // Add questions to state IMMEDIATELY (fast path)
        addQuestionsToState(newQuestions, true);
        showMessage(
          `Γ£à Recovered ${newQuestions.length} questions from cloud backup!`,
          5000
        );

        // Log to analytics in background (non-blocking)
        // Use requestIdleCallback or setTimeout to not block the UI
        const logInBackground = async () => {
          try {
            const { logQuestion } = await import("../utils/analyticsStore");
            // Batch log - just log a summary instead of each question
            logger.log(
              `≡ƒôè Logging ${newQuestions.length} recovered questions to analytics...`
            );
            // Only log first 50 to analytics to avoid performance issues
            const samplesToLog = newQuestions.slice(0, 50);
            samplesToLog.forEach((q) => {
              logQuestion({
                id: q.uniqueId,
                created: q.createdAt || new Date().toISOString(),
                status: q.status || "pending",
                discipline: q.discipline,
                difficulty: q.difficulty,
                type: q.type,
                questionText: q.question,
                qualityScore: q.qualityScore || null,
              });
            });
          } catch (err) {
            logger.warn("Background analytics logging failed:", err);
          }
        };

        // Run in background after UI updates
        if ("requestIdleCallback" in window) {
          window.requestIdleCallback(logInBackground);
        } else {
          setTimeout(logInBackground, 100);
        }
      }

      // Ensure progress bar is visible for at least MIN_DISPLAY_MS
      const elapsed = Date.now() - startTime;
      if (elapsed < MIN_DISPLAY_MS) {
        await new Promise((resolve) =>
          setTimeout(resolve, MIN_DISPLAY_MS - elapsed)
        );
      }
      // Mark as handled for this session
      sessionStorage.setItem("ue5_recovery_handled", "true");

      setShowRecoveryPrompt(false);
      setRecoveryData(null);
    } catch (error) {
      logger.error("Recovery failed:", error);
      showMessage(
        "Γ¥î Recovery failed. Please try loading from Database View.",
        5000
      );
    } finally {
      setIsRecovering(false);
    }
  }, [recoveryData, localQuestions, addQuestionsToState, showMessage]);

  const dismissRecovery = useCallback(() => {
    setShowRecoveryPrompt(false);
    setRecoveryData(null);
    // Mark that user dismissed, don't prompt again this session
    sessionStorage.setItem("ue5_recovery_handled", "true");
    localStorage.setItem("ue5_recovery_dismissed", "true");
  }, []);

  return {
    showRecoveryPrompt,
    recoveryData,
    isRecovering,
    handleRecover,
    dismissRecovery,
  };
};

import { useCallback } from "react";

import { logger } from "../utils/logger";
import { QUESTION_STATUS, QUESTION_SOURCES } from "../utils/constants";

/**
 * Hook for managing database view actions.
 * Handles updating database questions and kicking questions back to review.
