        3000
      );
    },
    [updateQuestionInState, showMessage]
  );

  /**
   * Remove question from database and send it back to Review Mode.
   * Deletes from Firestore and adds to historical questions as pending.
   *
   * @param {Object} question - Question to kick back
   */
  const handleKickBackToReview = useCallback(
    async (question) => {
      if (moveQuestion) {
        logger.log("≡ƒöä [Kick Back] Using moveQuestion action");
        await moveQuestion(question.id, QUESTION_SOURCES.SESSION, {
          status: QUESTION_STATUS.PENDING,
          kickedBackAt: new Date().toISOString(),
          kickedBackBy: "user",
          kickedBackReason: "Moved from Database to Review",
        });

        if (handleLoadFromFirestore) {
          await handleLoadFromFirestore();
        }
        return;
      }
    },
    [showMessage, handleLoadFromFirestore, moveQuestion]
  );

  return {
    handleUpdateDatabaseQuestion,
    handleKickBackToReview,
  };
};

/**
 * useEditLock Hook
 *
 * Manages edit locks for concurrent editing protection.
 *
 * Features:
 * - Acquire lock on edit start (or after 1s viewing)
 * - Automatic heartbeat renewal every 30 seconds
 * - Release lock on save/cancel/unmount
 * - Track lock status and ownership
 * - Re-attempt lock acquisition when tab regains focus (if previously blocked)
 */

import { useState, useEffect, useRef, useCallback } from "react";
import { getAgents } from "../agents";
import { logger } from "../utils/logger";

// =========================================================================
// GLOBAL LOCK STATE - Persists across component remounts
// =========================================================================
// When components remount (e.g., due to parent re-renders), internal refs reset.
// This module-level state tracks active locks so we don't release on unmount
// and immediately re-acquire on remount.
const globalLockState = {
  activeLocks: new Map(), // questionId -> { userId, timeoutId }
};

// Mark lock as active and cancel any pending release
function markLockActive(questionId, userId) {
  const existing = globalLockState.activeLocks.get(questionId);
  if (existing?.timeoutId) {
    clearTimeout(existing.timeoutId);
  }
  globalLockState.activeLocks.set(questionId, { userId, timeoutId: null });
}

// Schedule delayed release - allows time for remount to cancel it
function scheduleLockRelease(questionId, releaseCallback) {
  const existing = globalLockState.activeLocks.get(questionId);
  if (existing?.timeoutId) {
    clearTimeout(existing.timeoutId);
  }
  
  const timeoutId = setTimeout(() => {
    logger.log(`[useEditLock] Executing delayed release for: ${questionId}`);
    globalLockState.activeLocks.delete(questionId);
    releaseCallback();
  }, 2000); // 2 second delay allows component to remount and cancel
  
  globalLockState.activeLocks.set(questionId, { 
    ...existing, 
    timeoutId 
  });
}

// Check if user already has an active lock
function hasActiveLock(questionId, userId) {
  const lock = globalLockState.activeLocks.get(questionId);
  return lock && lock.userId === userId;
}

// Clear lock state (on explicit release or navigation)
function _clearLockState(questionId) {
  const existing = globalLockState.activeLocks.get(questionId);
  if (existing?.timeoutId) {
    clearTimeout(existing.timeoutId);
  }
  globalLockState.activeLocks.delete(questionId);
}

/**
 * Hook for managing edit locks
 * @param {string} questionId - Question document ID
 * @param {string} userId - Firebase Auth UID
 * @param {string} userEmail - User's email
 * @param {boolean} isViewing - Whether user is currently viewing this question
 * @param {Function} onLockExpired - Callback when lock expires
 * @param {boolean} isProcessing - Guard to prevent lock release during active save
 * @returns {object} Lock state and control functions
 */
export function useEditLock(
  questionId,
  userId,
  userEmail,
  isViewing,
  onLockExpired,
  isProcessing = false
) {
  const [lockStatus, setLockStatus] = useState("none"); // 'none' | 'acquiring' | 'acquired' | 'locked_by_other' | 'expired'
  const [lockInfo, setLockInfo] = useState(null);
  const [lockedBy, setLockedBy] = useState(null);

  // Refs for interval/timer management
  const heartbeatRef = useRef(null);
  const lockAttemptedRef = useRef(false);
  const viewTimerRef = useRef(null);
  const consecutiveFailuresRef = useRef(0);

  // Refs ONLY for cleanup/unmount logic (closures can be stale)
  const lockStatusRef = useRef(lockStatus);
  const isProcessingRef = useRef(isProcessing);

  // Keep cleanup refs updated
  useEffect(() => {
    lockStatusRef.current = lockStatus;
    isProcessingRef.current = isProcessing;
  }, [lockStatus, isProcessing]);

  const agents = getAgents();

  /**
   * Acquire an edit lock
   */
  const acquireLock = useCallback(async () => {
    // Use ref to check current status (avoids stale closure)
    if (lockStatusRef.current === "acquired") {
      return { success: true };
    }

    if (!agents) {
      logger.warn("[useEditLock] Agents not initialized yet");
      return { success: false, error: "Agents not initialized" };
    }

    if (!questionId || !userId || !userEmail) {
      logger.warn("[useEditLock] Missing required parameters");
      return { success: false, error: "Missing required parameters" };
    }

    setLockStatus("acquiring");
    lockAttemptedRef.current = true;

    const { lockAgent, auditAgent } = agents;

    try {
      const result = await lockAgent.acquireLock(
        String(questionId),
        userId,
        userEmail
      );

      if (result.success) {
        setLockStatus("acquired");
        setLockInfo(result.lock);
        setLockedBy(null);
        
        // Mark lock active in global state to survive remounts
        markLockActive(questionId, userId);

        await auditAgent.logLockAcquired(
          String(questionId),
          userId,
          userEmail,
          result.action === "stolen"
        );
        logger.log(`[useEditLock] Lock acquired for question ${questionId}`);
        return { success: true };
      } else {
        setLockStatus("locked_by_other");
        // LockAgent.acquireLock returns { lockedBy: existingLock } on rejection
        setLockedBy(result.lockedBy);
        logger.warn(`[useEditLock] Lock acquisition failed:`, result.error);
        return { success: false, error: result.error };
      }
    } catch (error) {
      logger.error("[useEditLock] Lock acquisition error:", error);
      setLockStatus("none");
      return { success: false, error: error.message };
    }
  }, [questionId, userId, userEmail, agents]);

  /**
   * Renew the lock (heartbeat)
   */
  const renewLock = useCallback(async () => {
    if (!agents || !questionId) return { success: false };

    const { lockAgent } = agents;

    try {
      const result = await lockAgent.renewLock(String(questionId));

      if (!result.success) {
        if (result.isNetworkError) {
          consecutiveFailuresRef.current++;
          logger.warn(`[useEditLock] Lock renewal network failure (${consecutiveFailuresRef.current}):`, result.error);
          
          // Allow up to 3 consecutive network failures (approx 1.5 mins) before expiring
          if (consecutiveFailuresRef.current >= 3) {
            logger.error("[useEditLock] Persistent network failure (3 attempts). Expiring lock.");
            setLockStatus("expired");
            if (onLockExpired) onLockExpired();
            return result;
          }
          
          // Return special success-like state for network retry
          return { success: true, isRetrying: true };
        }

        logger.warn("[useEditLock] Lock renewal failed (logic error):", result.error);
        setLockStatus("expired");
        if (onLockExpired) onLockExpired();
      } else {
        // Reset failure counter on success
        consecutiveFailuresRef.current = 0;
      }

      return result;
    } catch (error) {
      // Uncaught errors still expire
      logger.error("[useEditLock] Lock renewal unexpected error:", error);
      setLockStatus("expired");
      if (onLockExpired) onLockExpired();
      return { success: false, error: error.message };
    }
  }, [agents, questionId, onLockExpired]);

  // Keep renewLock in a ref so heartbeat effect doesn't restart when callback changes
  const renewLockRef = useRef(renewLock);
  useEffect(() => {
    renewLockRef.current = renewLock;
  }, [renewLock]);

  /**
   * Release the lock
   */
  const releaseLock = useCallback(async () => {
    if (!agents || !questionId) return { success: false };

    const { lockAgent, auditAgent } = agents;

    try {
      const result = await lockAgent.releaseLock(String(questionId));

      if (result.success) {
        setLockStatus("none");
        setLockInfo(null);
        setLockedBy(null);
        await auditAgent.logLockReleased(String(questionId), userId, userEmail);
        logger.log(`[useEditLock] Lock released for question ${questionId}`);
      }

      return result;
    } catch (error) {
      logger.error("[useEditLock] Lock release error:", error);
      return { success: false, error: error.message };
    }
  }, [agents, questionId, userId, userEmail]);

  /**
   * Check current lock status
   */
  const checkLockStatus = useCallback(async () => {
    if (!agents || !questionId) return { locked: false };

    const { lockAgent } = agents;

    try {
      const result = await lockAgent.checkLockStatus(String(questionId));
      if (result.locked) {
        // LockAgent.checkLockStatus returns { lock: lockData } - this IS the lockedBy info
        setLockedBy(result.lock);
        setLockStatus("locked_by_other");
      } else {
        setLockStatus("none");
        setLockedBy(null);
      }
      return result;
    } catch (error) {
      logger.error("[useEditLock] Lock status check error:", error);
      return { locked: false, error: error.message };
    }
  }, [agents, questionId]);

  // Heartbeat Effect - Renew lock every 30s when acquired
  // Uses ref to avoid restarting when renewLock changes
  useEffect(() => {
    if (lockStatus !== "acquired") return;

    logger.log("[useEditLock] Starting heartbeat for", questionId);
    heartbeatRef.current = setInterval(async () => {
      const result = await renewLockRef.current();
      if (!result.success) {
        if (heartbeatRef.current) {
          clearInterval(heartbeatRef.current);
          heartbeatRef.current = null;
        }
      }
    }, 30000);

    return () => {
      if (heartbeatRef.current) {
        logger.log("[useEditLock] Stopping heartbeat for", questionId);
        clearInterval(heartbeatRef.current);
        heartbeatRef.current = null;
      }
    };
  }, [lockStatus, questionId]);

  // Keep releaseLock in a ref so cleanup effect doesn't restart when callback changes
  const releaseLockRef = useRef(releaseLock);
  useEffect(() => {
    releaseLockRef.current = releaseLock;
  }, [releaseLock]);

  // Keep acquireLock in a ref so auto-acquire effect doesn't restart
  const acquireLockRef = useRef(acquireLock);
  useEffect(() => {
    acquireLockRef.current = acquireLock;
  }, [acquireLock]);

  // Release lock on unmount OR when questionId changes
  // Uses delayed release to allow remounts to cancel and keep the lock
  useEffect(() => {
    const qId = String(questionId);
    
    // On mount/update: cancel any pending release for this question
    markLockActive(qId, userId);

    return () => {
      // Use refs to check latest values in cleanup (closures can be stale)
      if (lockStatusRef.current === "acquired" && !isProcessingRef.current) {
        logger.log(`[useEditLock] Scheduling delayed release for: ${qId}`);
        // Use delayed release - if component remounts quickly, it will be cancelled
        scheduleLockRelease(qId, () => {
          logger.log(`[useEditLock] Releasing lock on exit for: ${qId}`);
          releaseLockRef.current();
        });
      } else if (isProcessingRef.current) {
        logger.log(
          `[useEditLock] Delaying lock release for ${qId} - save in progress`
        );
      }
    };
  }, [questionId, userId]); // Removed releaseLock dependency

  // Auto-acquire lock after 1s view
  // Uses ref to avoid effect restart when callback identity changes
  useEffect(() => {
    // Skip if already have active lock in global state (survived remount)
    if (hasActiveLock(questionId, userId)) {
      logger.log("[useEditLock] Reusing existing lock from global state");
      setLockStatus("acquired");
      lockAttemptedRef.current = true;
      return;
    }
    
    if (
      !isViewing ||
      lockAttemptedRef.current ||
      !questionId ||
      !userId ||
      !userEmail
    ) {
      if (!isViewing && viewTimerRef.current) {
        clearTimeout(viewTimerRef.current);
        viewTimerRef.current = null;
      }
      return;
    }

    logger.log("[useEditLock] Starting 1s view timer");
    viewTimerRef.current = setTimeout(() => {
      logger.log("[useEditLock] Auto-acquiring lock");
      acquireLockRef.current();
    }, 1000);

    return () => {
      if (viewTimerRef.current) {
        clearTimeout(viewTimerRef.current);
        viewTimerRef.current = null;
      }
    };
  }, [isViewing, questionId, userId, userEmail]); // Removed acquireLock dependency

  // Reset lock attempt flag when questionId changes
  useEffect(() => {
    lockAttemptedRef.current = false;
  }, [questionId]);

  // Visibility-based retry: Re-attempt when tab regains focus if locked by other
  useEffect(() => {
    if (lockStatus !== "locked_by_other" || !isViewing) return;

    const handleVisibilityChange = () => {
      if (document.visibilityState === "visible") {
        logger.log("[useEditLock] Tab visible - retrying lock acquisition");
        lockAttemptedRef.current = false; // Allow retry
        acquireLock();
      }
    };

    document.addEventListener("visibilitychange", handleVisibilityChange);
    return () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [lockStatus, isViewing, acquireLock]);

  return {
    lockStatus,
    lockInfo,
    lockedBy,
    isLocked: lockStatus === "locked_by_other",
    hasLock: lockStatus === "acquired",
    isAcquiring: lockStatus === "acquiring",
    isExpired: lockStatus === "expired",
    acquireLock,
    renewLock,
    releaseLock,
    checkLockStatus,
  };
}

import { useCallback } from "react";
import { getCSVContent, segmentQuestions } from "../utils/exportUtils";
import {
  saveQuestionsToSheets,
  fetchQuestionsFromSheets,
} from "../services/googleSheets";
import {
  saveQuestionToFirestore,
  getAllQuestionsFromFirestore,
} from "../services/firebase";
import { downloadFile } from "../utils/questionHelpers";
import { formatDate } from "../utils/dateHelpers";
import { logger } from "../utils/logger";
import {
  QUESTION_SOURCES,
  QUESTION_STATUS,
  APP_MODES,
} from "../utils/constants";
import { validateQuestion } from "../utils/questionValidator";

export const useExport = (
  config,
  questions,
  historicalQuestions,
  uniqueFilteredQuestions,
  allQuestionsMap,
  showHistory,
  showMessage,
  setStatus,
  setIsProcessing,
  setAppMode,
  setShowExportMenu,
  setShowBulkExportModal,
  replaceQuestions // Added: new semantic action
) => {
  const handleExportByGroup = useCallback(() => {
    const sourceList = showHistory
      ? [...questions, ...historicalQuestions]
      : questions;
    const valid = sourceList.filter(
      (q) => q.status !== QUESTION_STATUS.REJECTED
    );

    if (valid.length === 0) {
      setStatus("No accepted questions to export.");
      setTimeout(() => setStatus(""), 3000);
      return;
    }

    const groupedData = segmentQuestions(valid);

    let filesGenerated = 0;
    const exportDate = new Date();
    const datePart = formatDate(exportDate).replace(/-/g, "");

    Object.keys(groupedData).forEach((groupKey) => {
      const groupQuestions = groupedData[groupKey];
      const csvContent = getCSVContent(
        groupQuestions,
        config.creatorName,
        config.reviewerName
      );

      const fileNameParts = groupKey.replace(/ & /g, "_").replace(/ /g, "_");
      const filename = `${fileNameParts}_${datePart}.csv`;

      downloadFile(csvContent, filename);
      filesGenerated++;
    });

    setStatus(`Exported ${filesGenerated} segmented files.`);
    setTimeout(() => setStatus(""), 5000);
    if (setShowExportMenu) setShowExportMenu(false);
  }, [
    showHistory,
    questions,
    historicalQuestions,
    setStatus,
    config.creatorName,
    config.reviewerName,
    setShowExportMenu,
  ]);

  const handleExportCurrentTarget = useCallback(() => {
    const sourceList = showHistory
      ? [...questions, ...historicalQuestions]
      : questions;

    const targetString = config.difficulty;
    const [targetDiff, targetTypeAbbrev] = targetString.split(" ");
    const targetType =
      targetTypeAbbrev === "MC" ? "Multiple Choice" : "True/False";

    const valid = sourceList.filter(
      (q) =>
        q.status !== QUESTION_STATUS.REJECTED &&
        (q.language || "English") === config.language &&
        q.discipline === config.discipline &&
        q.difficulty === targetDiff &&
        q.type === targetType
    );

    if (valid.length === 0) {
      setStatus(
        `No accepted questions found for target: ${config.language} - ${targetString}`
      );
      setTimeout(() => setStatus(""), 3000);
      return;
    }

    const typePart = targetString.replace(/\s/g, "_");
    const disciplinePart = config.discipline.replace(/\s/g, "_");
    const datePart = new Date().toISOString().split("T")[0].replace(/-/g, "");
    const langPart = (config.language || "English").replace(/ /g, "_");

    const csvContent = getCSVContent(
      valid,
      config.creatorName,
      config.reviewerName
    );
    const filename = `${langPart}_${disciplinePart}_${typePart}_${datePart}.csv`;
    downloadFile(csvContent, filename);
    setStatus(`Exported ${valid.length} questions for target ${targetString}`);
    setTimeout(() => setStatus(""), 5000);
    if (setShowExportMenu) setShowExportMenu(false);
  }, [
    showHistory,
    questions,
    historicalQuestions,
    config.difficulty,
    config.language,
    config.discipline,
    setStatus,
    config.creatorName,
    config.reviewerName,
    setShowExportMenu,
  ]);

  const handleExportToSheets = useCallback(async () => {
    if (!config.sheetUrl) {
      showMessage("Please enter a Google Apps Script URL in settings.", 5000);
      return;
    }

    const sourceList = showHistory
      ? [...questions, ...historicalQuestions]
      : questions;
    const validQuestions = sourceList.filter(
      (q) => q.status !== QUESTION_STATUS.REJECTED
    );

    if (validQuestions.length === 0) {
      showMessage("No accepted questions to export.", 3000);
      return;
    }

    setIsProcessing(true);
    setStatus("Sending data to Google Sheets...");
    if (setShowExportMenu) setShowExportMenu(false);

    try {
      // Dual Write: Save to Sheets AND Firestore
      await Promise.all([
        saveQuestionsToSheets(config.sheetUrl, validQuestions),
        Promise.all(validQuestions.map((q) => saveQuestionToFirestore(q))),
      ]);

      showMessage(
        `Export launched! Data synced to Sheets and Firestore.`,
        7000
      );
    } catch (e) {
      logger.error("Error pushing to Sheets endpoint:", e);
      showMessage(
        `Error connecting to endpoint. Check URL/Console: ${e.message}`,
        10000
      );
    } finally {
      setIsProcessing(false);
    }
  }, [
    config.sheetUrl,
    showMessage,
    showHistory,
    questions,
    historicalQuestions,
    setIsProcessing,
    setStatus,
    setShowExportMenu,
  ]);

  const handleLoadFromSheets = useCallback(async () => {
    if (!config.sheetUrl) {
      showMessage("Please enter a Google Apps Script URL first.", 3000);
      return;
    }

    setIsProcessing(true);
    setStatus("Loading from Google Sheets...");
    if (setShowExportMenu) setShowExportMenu(false);

    try {
      const data = await fetchQuestionsFromSheets(config.sheetUrl);
      const loadedQuestions = data.map((q, index) => ({
        // eslint-disable-next-line sonarjs/pseudo-random
        id: Date.now() + index + Math.random(),
        uniqueId: q["Unique ID"] || q.uniqueId || crypto.randomUUID(),
        discipline: q.Discipline || q.discipline || "Imported",
        difficulty: q.Difficulty || q.difficulty || "Easy",
        type: q["Question Type"] || q.Type || q.type || "Multiple Choice",
        question: q.Question || q.question || "",
        options: {
          A: q["Option A"] || q.OptionA || "",
          B: q["Option B"] || q.OptionB || "",
          C: q["Option C"] || q.OptionC || "",
          D: q["Option D"] || q.OptionD || "",
        },
        correct: q.Answer || q.correct || "",
        explanation: q.Explanation || q.explanation || "",
        language: q.Language || q.language || "English",
        sourceUrl: q.SourceFile || q.sourceUrl || "",
        sourceExcerpt: q.sourceExcerpt || "",
        creatorName: q.creator || q.creatorName || "",
        reviewerName: q.reviewer || q.reviewerName || "",
      }));

      // Validate loaded questions and set status
      const questionsWithValidation = loadedQuestions.map((q) => {
        const validation = validateQuestion(q);
        return {
          ...q,
          _validation: validation,
          status: validation.isCriticalFailure
            ? QUESTION_STATUS.REJECTED
            : QUESTION_STATUS.ACCEPTED,
        };
      });

      if (replaceQuestions) {
        // Use new semantic action to replace legacy QUESTION_SOURCES.DATABASE and QUESTION_SOURCES.IMPORT sources
        // Note: QUESTION_SOURCES.IMPORT source is used for both sheets and legacy history
        replaceQuestions(questionsWithValidation, QUESTION_SOURCES.DATABASE);
        replaceQuestions(questionsWithValidation, QUESTION_SOURCES.IMPORT);
      }

      setAppMode(APP_MODES.DATABASE);

      const totalRejected = questionsWithValidation.filter(
        (q) => q.status === QUESTION_STATUS.REJECTED
      ).length;
      const totalAccepted = loadedQuestions.length - totalRejected;

      if (totalRejected > 0) {
        showMessage(
          `Import Audit: ${totalAccepted} Success, ${totalRejected} Errors flagged for review.`,
          6000
        );
      } else {
        showMessage(
          `Loaded ${loadedQuestions.length} questions from Database View!`,
          3000
        );
      }
    } catch (e) {
      logger.error("Load Error:", e);
      showMessage(
        `Load Failed: ${e.message}. (Ensure Script Access is set to 'Anyone')`,
        7000
      );
    } finally {
      setIsProcessing(false);
      setStatus("");
    }
  }, [
    config.sheetUrl,
    showMessage,
    setIsProcessing,
    setStatus,
    setShowExportMenu,
    setShowExportMenu,
    setAppMode,
    replaceQuestions,
  ]);

  const handleLoadFromFirestore = useCallback(
    async (silent = false) => {
      setIsProcessing(true);
      setStatus(silent ? "" : "Loading from Firestore...");
      if (setShowExportMenu) setShowExportMenu(false);

      try {
        // Use getAllQuestionsFromFirestore for shared database view (all authenticated users can see all questions)
        const data = await getAllQuestionsFromFirestore();

        // PERFORMANCE: Load once to prevent re-render loops
        const loadedQuestions = data.map((q, index) => ({
          ...q,
          // eslint-disable-next-line sonarjs/pseudo-random
          id: q.id || Date.now() + index + Math.random(), // Ensure React key
          status: q.status || QUESTION_STATUS.PENDING, // CRITICAL: Preserve actual status
        }));

        if (replaceQuestions) {
          replaceQuestions(loadedQuestions, QUESTION_SOURCES.DATABASE);
          replaceQuestions(loadedQuestions, QUESTION_SOURCES.IMPORT); // Sync history
        }

        if (!silent) {
          showMessage(
            `Loaded ${loadedQuestions.length} questions from Firestore!`,
            3000
          );
        }
      } catch (e) {
        logger.error("Firestore Load Error:", e);
        if (!silent) {
          showMessage(`Firestore Load Failed: ${e.message}`, 7000);
        }
      } finally {
        setIsProcessing(false);
        setStatus("");
      }
    },
    [
      setIsProcessing,
      setStatus,
      setShowExportMenu,
      showMessage,
      replaceQuestions,
    ]
  );

  const handleBulkExport = useCallback(
    async (exportOptions) => {
      const { format, includeRejected, languages, scope, segmentFiles, limit } =
        exportOptions;

      let sourceQuestions = [];
      if (scope === "filtered") {
        const visibleIds = new Set(
          uniqueFilteredQuestions.map((q) => q.uniqueId)
        );
        sourceQuestions = Array.from(allQuestionsMap.values()).flatMap(
          (variants) => variants.filter((v) => visibleIds.has(v.uniqueId))
        );
      } else {
        sourceQuestions = Array.from(allQuestionsMap.values()).flat();
      }

      let questionsToExport = sourceQuestions.filter((q) => {
        const langMatch = languages.includes(q.language || "English");
        const statusMatch =
          includeRejected || q.status !== QUESTION_STATUS.REJECTED;
        return langMatch && statusMatch;
      });

      if (limit && limit > 0) {
        questionsToExport = questionsToExport.slice(0, limit);
      }

      if (questionsToExport.length === 0) {
        showMessage("No questions to export with selected options.", 3000);
        return;
      }

      if (format === "sheets") {
        if (!config.sheetUrl) {
          showMessage(
            "Please enter a Google Apps Script URL in settings.",
            5000
          );
          return;
        }
        setIsProcessing(true);
        setStatus("Sending data to Google Sheets...");
        try {
          await saveQuestionsToSheets(config.sheetUrl, questionsToExport);
          showMessage(`Export launched! Check new tab for status.`, 5000);
        } catch (e) {
          logger.error(e);
          showMessage(`Error: ${e.message}`, 5000);
        } finally {
          setIsProcessing(false);
        }
        return;
      }

      if (segmentFiles && format === "csv") {
        const groupedData = questionsToExport.reduce((acc, q) => {
          const typeAbbrev = q.type === "True/False" ? "T/F" : "MC";
          const key = `${q.language || "English"}_${q.discipline}_${
            q.difficulty
          }_${typeAbbrev}`;
          if (!acc[key]) acc[key] = [];
          acc[key].push(q);
          return acc;
        }, {});

        let filesGenerated = 0;
        const datePart = formatDate(new Date()).replace(/-/g, "");

        Object.keys(groupedData).forEach((groupKey) => {
          const groupQuestions = groupedData[groupKey];
          const csvContent = getCSVContent(
            groupQuestions,
            config.creatorName,
            config.reviewerName
          );
          const fileNameParts = groupKey
            .replace(/ & /g, "_")
            .replace(/ /g, "_");
          const filename = `${fileNameParts}_${datePart}.csv`;
          downloadFile(csvContent, filename);
          filesGenerated++;
        });
        showMessage(`Exported ${filesGenerated} segmented files.`, 4000);
        return;
      }

      if (format === "csv") {
        const csvContent = getCSVContent(
          questionsToExport,
          config.creatorName,
          config.reviewerName
        );
        downloadFile(csvContent, `bulk_export_${Date.now()}.csv`, "text/csv");
      } else if (format === "json") {
        downloadFile(
          JSON.stringify(questionsToExport, null, 2),
          `bulk_export_${Date.now()}.json`,
          "application/json"
        );
      } else if (format === "markdown") {
        const md = questionsToExport
          .map((q) => {
            return `## ${q.question}\n\n**Difficulty:** ${
              q.difficulty
            } | **Type:** ${q.type} | **Language:** ${
              q.language
            }\n\n**Options:**\n- A: ${q.options?.A}\n- B: ${q.options?.B}\n${
              q.options?.C ? `- C: ${q.options.C}\n` : ""
            }${q.options?.D ? `- D: ${q.options.D}\n` : ""}\n**Correct:** ${
              q.correct
            }\n\n---\n`;
          })
          .join("\n");
        downloadFile(md, `bulk_export_${Date.now()}.md`, "text/markdown");
      }

      showMessage(
        `Exported ${
          questionsToExport.length
        } questions as ${format.toUpperCase()}.`,
        4000
      );
    },
    [
      uniqueFilteredQuestions,
      allQuestionsMap,
      showMessage,
      config.sheetUrl,
      setIsProcessing,
      setStatus,
      config.creatorName,
      config.reviewerName,
    ]
  );

  return {
    handleExportByGroup,
    handleExportCurrentTarget,
    handleExportToSheets,
    handleLoadFromSheets,
    handleLoadFromFirestore,
    handleBulkExport,
  };
};

import { useState, useRef } from "react";
import { processUploadedFile } from "../utils/fileProcessor";
import { generateContentSecure as generateContent } from "../services/geminiSecure";
import {
  processMultipleFiles,
  analyzeOptimization,
} from "../utils/contextOptimizer";
import { logger } from "../utils/logger";

export const useFileHandler = (
  config,
  setConfig,
  addQuestionsToState,
  showMessage,
  setStatus,
  isApiReady,
  effectiveApiKey
) => {
  const [files, setFiles] = useState([]);
  const fileInputRef = useRef(null);
  const [isDetecting, setIsDetecting] = useState(false);

  const removeFile = (index) => {
    setFiles((prev) => prev.filter((_, i) => i !== index));
  };

  const getFileContext = () => {
    if (files.length === 0) return "";

    // Use context optimizer for smart file processing
    const optimizedContext = processMultipleFiles(
      files.map((f) => ({ name: f.name, content: f.content })),
      config.discipline
    );

    // Log optimization results
    const originalContext = files
      .map((f) => `## ${f.name}\n${f.content}`)
      .join("\n\n");
    const analysis = analyzeOptimization(originalContext, optimizedContext);

    if (analysis.reduction.percentage > 0) {
      // Optimization info available
    }

    return "\n\n### ATTACHED LOCAL SOURCE FILES:\n" + optimizedContext;
  };

  const handleFileChange = async (e, showHistory) => {
    const newFiles = Array.from(e.target.files);
    if (newFiles.length === 0) return;

    let importedCount = 0;
    let referenceCount = 0;
    let totalAccepted = 0;
    let totalRejected = 0;
    const errors = [];

    for (const file of newFiles) {
      const result = await processUploadedFile(file, config.creatorName);

      if (result.error) {
        errors.push(`${file.name}: ${result.error}`);
        continue;
      }

      if (result.type === "questions") {
        addQuestionsToState(result.data, showHistory);
        importedCount += result.data.length;

        const rejected = result.data.filter(
          (q) => q.status === "rejected"
        ).length;
        totalRejected += rejected;
        totalAccepted += result.data.length - rejected;
      } else if (result.type === "reference") {
        setFiles((prev) => [...prev, result.data]);
        referenceCount++;
      }
    }

    if (importedCount > 0) {
      if (totalRejected > 0) {
        showMessage(
          `Import Audit: ${totalAccepted} Success, ${totalRejected} Errors flagged for review.`,
          6000
        );
      } else {
        showMessage(`Successfully imported ${importedCount} questions.`, 4000);
      }
    }

    if (referenceCount > 0)
      showMessage(`Added ${referenceCount} reference files.`, 3000);
    if (errors.length > 0) {
      logger.error("File processing errors:", errors);
      showMessage(`Some files failed: ${errors.slice(0, 2).join(", ")}`, 6000);
    }

    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleDetectTopics = async () => {
    if (files.length === 0) return;
    if (!isApiReady) {
      showMessage(
        "API key is required for detection. Please enter it in the settings panel.",
        5000
      );
      return;
    }

    setIsDetecting(true);
    setStatus("Scanning...");
    const prompt = `Analyze content. Identify 3 prominent technical disciplines. Return ONLY comma-separated list. ${getFileContext()}`;
    try {
      const detected = await generateContent(
        effectiveApiKey,
        "Technical Analyst",
        prompt,
        setStatus
      );
      setConfig((prev) => ({
        ...prev,
        discipline: detected.split(",")[0].trim(),
      }));
      setStatus("Detected");
      setTimeout(() => setStatus(""), 2000);
    } catch {
      setStatus("Failed");
    } finally {
      setIsDetecting(false);
    }
  };

  return {
    files,
    setFiles,
    fileInputRef,
    isDetecting,
    handleFileChange,
    removeFile,
    getFileContext,
    handleDetectTopics,
  };
};

/**
 * useFiltering Hook
 *
 * Manages all filtering and search state for the question list, including:
 * - Search term
 * - Filter mode (pending/accepted/rejected/all)
 * - Show history toggle
 * - Filter by creator
 * - Filter by tags
 * - Sort order
 * - Current review index
 * - Computed filtered question lists
 * - LocalStorage persistence
 */
import { useState, useEffect, useMemo, useRef } from "react";
import {
  createFilteredQuestions,
  createUniqueFilteredQuestions,
} from "../utils/questionFilters";
import { STORAGE_KEYS } from "../utils/constants";
import { logger } from "../utils/logger";

/**
 * Custom hook for managing question filtering state and logic.
 *
 * @param {Object} params - Hook parameters
 * @param {Array} params.questions - Current session questions
 * @param {Array} params.historicalQuestions - Historical questions from cloud
 * @param {Object} params.config - App configuration (creatorName, discipline, difficulty, language)
 * @param {string} params.appMode - Current app mode ('create', 'review', 'database', etc.)
 * @returns {Object} Filtering state and handlers
 */
export function useFiltering({
  questions,
  historicalQuestions,
  config,
  appMode,
  allQuestionsMap,
}) {
  // ========================================================================
  // STATE - Filter & Search
  // ========================================================================
  const [searchTerm, setSearchTerm] = useState(
    () => localStorage.getItem(STORAGE_KEYS.PREF_SEARCH) || ""
  );
  const [filterMode, setFilterMode] = useState(
    () => localStorage.getItem(STORAGE_KEYS.PREF_FILTER) || "pending"
  );
  const [showHistory, setShowHistory] = useState(
    () => localStorage.getItem(STORAGE_KEYS.PREF_HISTORY) === "true"
  );
  const [filterByCreator, setFilterByCreator] = useState(false);
  const [filterTags, setFilterTags] = useState([]);
  const [filterScoreTier, setFilterScoreTier] = useState(""); // '', 'exceptional', 'very-good', 'good', 'adequate', 'needs-work'

  // PERSISTED NAVIGATION: Survive page refreshes
  const [currentReviewIndex, setCurrentReviewIndex] = useState(() => {
    if (appMode !== "review") return 0;
    const saved = localStorage.getItem(STORAGE_KEYS.PREF_REVIEW_INDEX);
    return saved ? parseInt(saved, 10) : 0;
  });

  const [sortBy, setSortBy] = useState("default");

  // Track the uniqueId of the current question for better cross-refresh restoration
  const [lastUniqueId, setLastUniqueId] = useState(
    () => localStorage.getItem(STORAGE_KEYS.PREF_LAST_ID) || null
  );

  // Reset review index when entering Review mode FROM another mode (not refresh)
  const lastModeRef = useRef(appMode);

  // Persistence for review index
  useEffect(() => {
    if (appMode === "review") {
      localStorage.setItem(STORAGE_KEYS.PREF_REVIEW_INDEX, currentReviewIndex);
    }
  }, [currentReviewIndex, appMode]);

  // ========================================================================
  // EFFECTS - Persistence
  // ========================================================================

  // Persist filter preferences to localStorage
  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.PREF_SEARCH, searchTerm);
    localStorage.setItem(STORAGE_KEYS.PREF_FILTER, filterMode);
    localStorage.setItem(STORAGE_KEYS.PREF_HISTORY, showHistory);
  }, [searchTerm, filterMode, showHistory]);

  // NOTE: Position is preserved when switching filters - no reset needed
  // The existing restoration logic handles keeping the user on the same question

  // DISABLED: Old reset logic that was causing questions to jump
  // We now handle this more intelligently below
  /*
  // Reset review index when filters change
  // NOTE: discipline, difficulty, and language are intentionally excluded
  // Changing these filters should maintain the current question position when possible
  useEffect(() => {
    logger.log(
      "≡ƒöä [useFiltering] Resetting review index to 0. Triggered by:",
      {
        appMode,
        filterMode,
        searchTerm,
      }
    );
    setCurrentReviewIndex(0);
  }, [
    appMode,
    // config.discipline, // REMOVED: Don't reset index when discipline changes
    // config.difficulty, // REMOVED: Don't reset index when difficulty changes
    // config.language,   // REMOVED: Don't reset index when language changes
    filterMode,
    searchTerm,
  ]);
  */

  // ========================================================================
  // COMPUTED VALUES - Filtered Questions
  // ========================================================================

  // PERFORMANCE: Destructure config to avoid unnecessary recalculations
  // when config object reference changes but values don't
  const { creatorName, discipline, difficulty, type, language } = config;

  // STABILITY: Track previous contextFilteredQuestions to avoid unnecessary re-renders
  const prevContextFilteredRef = useRef([]);

  // 1. First, get questions that match all filters EXCEPT status (for counts)
  const contextFilteredQuestions = useMemo(() => {
    const newResult = createFilteredQuestions(
      questions,
      historicalQuestions,
      showHistory || appMode === "review" || appMode === "create", // Show history in Create & Review modes
      "all", // Ignore status for this intermediate list
      filterByCreator,
      searchTerm,
      creatorName,
      discipline,
      appMode === "review" ? null : difficulty, // Review mode: ignore difficulty filter
      appMode === "review" ? null : type, // Review mode: ignore type filter
      language,
      filterTags,
      filterScoreTier
    );

    // STABILITY: Only return new array if the question IDs or important content changed
    // This prevents infinite recalculation loops while still detecting real changes
    const newIds = newResult.map((q) => q.id || q.uniqueId).join(",");
    const prevIds = prevContextFilteredRef.current
      .map((q) => q.id || q.uniqueId)
      .join(",");

    // Also check if critique scores, status, OR verification/rewrites changed
    const generateHash = (list) =>
      list
        .map((q) => {
          // STABILITY: Include as many relevant fields as possible to detect changes
          // Use q.id or q.uniqueId for stable identification
          const id = q.id || q.uniqueId;
          const score = q.critiqueScore ?? "none";
          const improved = q.improvedScore ?? "none";
          const rewriteScore = q.suggestedRewrite?.critiqueScore ?? "none";
          const status = q.status || "pending";
          const verified = q.humanVerified ? "yes" : "no";
          const rewrite = q.suggestedRewrite ? "yes" : "no";
          const lang = q.language || "English";
          const lastModified = q.lastModified || q.updatedAt || "0";

          return `${id}:${score}:${status}:${verified}:${rewrite}:${rewriteScore}:${improved}:${lang}:${lastModified}`;
        })
        .join("|");

    const newHash = generateHash(newResult);
    const prevHash = generateHash(prevContextFilteredRef.current);

    if (
      newIds === prevIds &&
      newHash === prevHash &&
      prevContextFilteredRef.current.length > 0
    ) {
      // STABILITY: When caching, check if any accepted questions need to be filtered
      // This prevents index jumps when status changes during heartbeat cycles
      if (newResult.length === prevContextFilteredRef.current.length) {
        return prevContextFilteredRef.current;
      }
    }

    // NOTE: We no longer pre-filter accepted questions in review mode.
    // The filter buttons (Pending/Accepted/Rejected/All) handle status filtering.
    // This allows the "Accepted" filter to work correctly and show accurate counts.

    prevContextFilteredRef.current = newResult;
    return newResult;
  }, [
    questions,
    historicalQuestions,
    showHistory,
    appMode,
    filterByCreator,
    searchTerm,
    creatorName,
    discipline,
    difficulty,
    type,
    language,
    filterTags,
    filterScoreTier,
  ]);

  // 2. Calculate counts based on UNIQUE questions per status
  // This ensures pill counts match what the user actually sees in the list
  const contextCounts = useMemo(() => {
    // Helper to get unique count for a specific status filter
    const getUniqueCountForStatus = (statusFilter) => {
      let filtered;
      if (statusFilter === "all") {
        filtered = contextFilteredQuestions;
      } else if (statusFilter === "pending") {
        filtered = contextFilteredQuestions.filter(
          (q) => !q.status || q.status === "pending"
        );
      } else if (statusFilter === "other") {
        filtered = contextFilteredQuestions.filter(
          (q) =>
            q.status &&
            q.status !== "pending" &&
            q.status !== "accepted" &&
            q.status !== "rejected"
        );
      } else {
        filtered = contextFilteredQuestions.filter(
          (q) => q.status === statusFilter
        );
      }
      // Apply same uniqueness logic as uniqueFilteredQuestions
      return createUniqueFilteredQuestions(filtered, language, allQuestionsMap)
        .length;
    };

    const pending = getUniqueCountForStatus("pending");
    const accepted = getUniqueCountForStatus("accepted");
    const rejected = getUniqueCountForStatus("rejected");
    const other = getUniqueCountForStatus("other");
    const all = getUniqueCountForStatus("all");

    // DIAGNOSTIC LOGGING: Identify mysterious statuses
    if (other > 0) {
      const otherStatuses = contextFilteredQuestions
        .filter(
          (q) =>
            q.status &&
            q.status !== "pending" &&
            q.status !== "accepted" &&
            q.status !== "rejected"
        )
        .reduce((acc, q) => {
          acc[q.status] = (acc[q.status] || 0) + 1;
          return acc;
        }, {});
      logger.warn(
        "ΓÜá∩╕Å [Count Discrepancy] Found non-standard statuses:",
        otherStatuses
      );
    }

    return { pending, accepted, rejected, other, all };
  }, [contextFilteredQuestions, language, allQuestionsMap]);

  // 3. Now apply the status filter for the actual view
  const filteredQuestions = useMemo(() => {
    if (filterMode === "all") return contextFilteredQuestions;
    return contextFilteredQuestions.filter((q) => {
      if (filterMode === "pending") return !q.status || q.status === "pending";
      if (filterMode === "other") {
        // "other" is a computed category - questions with non-standard statuses
        return (
          q.status &&
          q.status !== "pending" &&
          q.status !== "accepted" &&
          q.status !== "rejected"
        );
      }
      return q.status === filterMode;
    });
  }, [contextFilteredQuestions, filterMode]);

  // 4. Get unique questions for the current language, sorted consistently
  const uniqueFilteredQuestions = useMemo(() => {
    // A. Group and Select Variants
    const result = createUniqueFilteredQuestions(
      filteredQuestions,
      language,
      allQuestionsMap
    );

    // C. Apply Stable Sort (Canonical Date = Earliest creation time of any variant in the group)
    // This ensures that translating a question (creating a newer variant)
    // does not cause the question card to jump to the top of the list.
    const getCanonicalDate = (q) => {
      if (!allQuestionsMap || !allQuestionsMap.has(q.uniqueId)) {
        // Fallback if map missing - use a static anchor (0) for stability
        const dateStr = q.created || q.dateAdded;
        return dateStr ? new Date(dateStr).getTime() : 0;
      }
      const variants = allQuestionsMap.get(q.uniqueId);
      // Find the earliest date among all variants to anchor the group's position
      // Use epoch 0 as absolute fallback for stability during hydration
      return Math.min(
        ...variants.map((v) => {
          const dateStr = v.created || v.dateAdded;
          return dateStr ? new Date(dateStr).getTime() : 0;
        })
      );
    };

    // Pre-calculate dates to avoid finding variants during sort
    const dateMap = new Map();
    result.forEach((q) => dateMap.set(q.uniqueId, getCanonicalDate(q)));

    // Sort: Newest Original First (Standard Blog/Feed sort)
    // Add uniqueId as tiebreaker for fully stable sort
    return result.sort((a, b) => {
      const dateA = dateMap.get(a.uniqueId);
      const dateB = dateMap.get(b.uniqueId);

      // Primary sort: canonical date (newest first)
      if (dateB !== dateA) {
        return dateB - dateA;
      }

      // Tiebreaker: uniqueId (alphabetical) for stability
      return (a.uniqueId || "").localeCompare(b.uniqueId || "");
    });
  }, [filteredQuestions, language, allQuestionsMap]);
  // STABILITY: allQuestionsMap IS included now, but we've stabilized the date fallback.

  // STABILITY: Preserve current question position when the question list updates
  // This handles AI critiques, language switches, and remote syncs
  const lastKnownUniqueIdRef = useRef(null);
  const lastKnownIndexRef = useRef(currentReviewIndex);
  const lastKnownListRef = useRef(uniqueFilteredQuestions);

  useEffect(() => {
    const indexChanged = currentReviewIndex !== lastKnownIndexRef.current;

    if (uniqueFilteredQuestions.length === 0) {
      lastKnownUniqueIdRef.current = null;
      lastKnownIndexRef.current = currentReviewIndex;
      lastKnownListRef.current = uniqueFilteredQuestions;
      return;
    }

    // A. Detect the current question's uniqueId
    const currentQ = uniqueFilteredQuestions[currentReviewIndex];
    const currentUniqueId = currentQ?.uniqueId;

    // B. If the user intentionally navigated, update our tracking and STOP
    if (indexChanged) {
      lastKnownUniqueIdRef.current = currentUniqueId;
      lastKnownIndexRef.current = currentReviewIndex;
      lastKnownListRef.current = uniqueFilteredQuestions;

      if (currentUniqueId) {
        localStorage.setItem(STORAGE_KEYS.PREF_LAST_ID, currentUniqueId);
        setLastUniqueId(currentUniqueId);
      }
      return;
    }

    // DISABLED: This was causing position jumps when switching filters
    // The "same question" may be at a different index in a different filter's list
    // if (
    //   listRefChanged &&
    //   lastKnownUniqueIdRef.current &&
    //   lastKnownUniqueIdRef.current !== currentUniqueId
    // ) {
    //   const preservedIndex = uniqueFilteredQuestions.findIndex(
    //     (q) => q.uniqueId === lastKnownUniqueIdRef.current
    //   );
    //
    //   if (preservedIndex !== -1 && preservedIndex !== currentReviewIndex) {
    //     setCurrentReviewIndex(preservedIndex);
    //     lastKnownIndexRef.current = preservedIndex;
    //     lastKnownListRef.current = uniqueFilteredQuestions;
    //     return;
    //   }
    // }

    // D. Update tracking for next run
    if (currentUniqueId) {
      lastKnownUniqueIdRef.current = currentUniqueId;
      localStorage.setItem(STORAGE_KEYS.PREF_LAST_ID, currentUniqueId);
      setLastUniqueId(currentUniqueId);
    }
    lastKnownIndexRef.current = currentReviewIndex;
    lastKnownListRef.current = uniqueFilteredQuestions;
  }, [uniqueFilteredQuestions, currentReviewIndex, setCurrentReviewIndex]);

  // ========================================================================
  // NAVIGATION RESTORATION & RESET
  // ========================================================================

  const hasRestoredRef = useRef(false);

  // 1. Reset review index when entering Review mode FROM another mode (not refresh)
  useEffect(() => {
    // skip reset if we are currently restoring from refresh
    if (hasRestoredRef.current) {
      if (
        appMode === "review" &&
        lastModeRef.current !== "review" &&
        lastModeRef.current !== "database"
      ) {
        logger.log(
          "≡ƒöä [useFiltering] Resetting review index: Entered Review mode"
        );
        setCurrentReviewIndex(0);
      }
    }
    lastModeRef.current = appMode;
  }, [appMode]);

  // 2. Reset review index when discipline changes (in review mode)
  useEffect(() => {
    // Only reset if we've already finished the initial restoration
    if (hasRestoredRef.current && appMode === "review") {
      logger.log(
        "≡ƒöä [useFiltering] Resetting review index: Discipline changed"
      );
      setCurrentReviewIndex(0);
    }
  }, [discipline, appMode]);

  // 3. Handle restoration on mount or mode change
  // TRIGGER: Now runs AFTER potential resets in the same render cycle
   
  useEffect(() => {
    if (
      appMode === "review" &&
      !hasRestoredRef.current &&
      uniqueFilteredQuestions.length > 0
    ) {
      // Small delay to ensure all questions from initial fetch are processed
      const savedId = localStorage.getItem(STORAGE_KEYS.PREF_LAST_ID);
      const savedIndex = parseInt(
        localStorage.getItem(STORAGE_KEYS.PREF_REVIEW_INDEX) || "0",
        10
      );

      logger.log("≡ƒÄ» [Restoration] Attempting restoration...", {
        savedId,
        savedIndex,
        listSize: uniqueFilteredQuestions.length,
      });

      if (savedId) {
        const idx = uniqueFilteredQuestions.findIndex(
          (q) => q.uniqueId === savedId
        );
        if (idx !== -1) {
          logger.log(
            `≡ƒÄ» [Restoration] Found saved question ${savedId} at index ${idx}`
          );
          setCurrentReviewIndex(idx);
          hasRestoredRef.current = true;
          return;
        }
      }

      if (savedIndex > 0 && savedIndex < uniqueFilteredQuestions.length) {
        logger.log(
          `≡ƒÄ» [Restoration] Falling back to saved index ${savedIndex}`
        );
        setCurrentReviewIndex(savedIndex);
      }
      hasRestoredRef.current = true;
    }
  }, [appMode, uniqueFilteredQuestions.length]);

  // ========================================================================
  // RETURN
  // ========================================================================
  return {
    // State
    searchTerm,
    setSearchTerm,
    filterMode,
    setFilterMode,
    showHistory,
    setShowHistory,
    filterByCreator,
    setFilterByCreator,
    filterTags,
    setFilterTags,
    currentReviewIndex,
    setCurrentReviewIndex,
    sortBy,
    setSortBy,
    filterScoreTier,
    setFilterScoreTier,
    lastUniqueId,
    setLastUniqueId,

    // Computed values
    contextFilteredQuestions,
    contextCounts,
    filteredQuestions,
    uniqueFilteredQuestions,
  };
}

import { useEffect, useRef } from "react";
import { logger } from "../utils/logger";

/**
 * Hook to handle one-time database migrations.
 * Encapsulates logic for fixing legacy data issues on app load.
 *
 * @param {Object} params
 * @param {Object} params.user - Current authenticated user
 * @param {boolean} params.authLoading - Authentication loading state
 * @param {boolean} params.isAdmin - Whether the user is an admin
 * @param {Function} params.showMessage - Toast notification handler
 * @param {Function} params.handleLoadFromFirestore - Function to reload data after migration
 * @param {Function} params.setConfig - Config setter for language migration
 */
export function useMigrations({
  user,
  authLoading,
  isAdmin,
  showMessage,
  handleLoadFromFirestore,
  setConfig,
}) {
  // ========================================================================
  // MIGRATION 0: Language Reset (runs for all users, once)
  // ========================================================================
  useEffect(() => {
    const migrationKey = "language_reset_v1";
    const hasReset = localStorage.getItem(migrationKey);

    if (!hasReset && setConfig) {
      logger.log("≡ƒöä Running language reset migration...");
      setConfig((prev) => ({ ...prev, language: "English" }));
      localStorage.setItem(migrationKey, "true");
      logger.log("Γ£à Language reset to English");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Migration 1: Fix auto-accepted questions (missing reviewCompletedAt)
  const hasAutoAcceptMigratedRef = useRef(false);

  useEffect(() => {
    const runAutoAcceptMigration = async () => {
      const migrationKey = "ue5_migration_auto_accept_fix";
      if (localStorage.getItem(migrationKey) === "completed") return;

      if (
        user &&
        !authLoading &&
        isAdmin &&
        !hasAutoAcceptMigratedRef.current
      ) {
        hasAutoAcceptMigratedRef.current = true;
        try {
          logger.log(
            "≡ƒöä Running migration: fixing auto-accepted questions..."
          );

          // Dynamic imports to avoid bundling firebase if not needed
          const { db } = await import("../services/firebase");
          const { collection, getDocs, doc, updateDoc } = await import(
            "firebase/firestore"
          );

          const questionsRef = collection(db, "questions");
          const snapshot = await getDocs(questionsRef);

          let fixedCount = 0;
          const batch = [];

          snapshot.forEach((docSnap) => {
            const question = docSnap.data();
            if (question.status === "accepted" && !question.reviewCompletedAt) {
