  }, [user, authLoading, isAdmin, showMessage, handleLoadFromFirestore]);
}

import { useMemo } from "react";
import { logger } from "../utils/logger";

/**
 * Hook to calculate the total number of pending questions for the Review badge.
 * This count increases when questions are kicked back to review.
 *
 * @param {Map} allQuestionsMap - Map of all questions grouped by uniqueId
 * @returns {number} Total count of pending questions
 */
export function usePendingCount(allQuestionsMap) {
  const totalPendingQuestions = useMemo(() => {
    let pending = 0;
    allQuestionsMap.forEach((variants) => {
      // Use the English version or first variant to determine status
      const canonical =
        variants.find((v) => (v.language || "English") === "English") ||
        variants[0];
      if (canonical && (!canonical.status || canonical.status === "pending")) {
        pending++;
      }
    });
    return pending;
  }, [allQuestionsMap]);

  return totalPendingQuestions;
}

import { useState, useCallback, useRef } from 'react';

/**
 * Hook for tracking multi-stage progress with time estimation
 * @param {Array} stages - Array of stage objects with { name, weight }
 */
export const useProgressTracker = (stages) => {
    const [progress, setProgress] = useState({
        currentStage: 0,
        percentage: 0,
        stageName: stages[0]?.name || 'Processing',
        estimatedTimeLeft: null,
        message: ''
    });

    const startTime = useRef(null);
    const stageStartTime = useRef(null);

    const startTracking = useCallback(() => {
        startTime.current = Date.now();
        stageStartTime.current = Date.now();
        setProgress({
            currentStage: 1,
            percentage: 0,
            stageName: stages[0]?.name || 'Processing',
            estimatedTimeLeft: null,
            message: ''
        });
    }, [stages]);

    const updateProgress = useCallback((stageIndex, stageProgress, message = '') => {
        if (stageIndex >= stages.length) return;

        // Calculate overall percentage
        const completedWeight = stages.slice(0, stageIndex).reduce((sum, s) => sum + s.weight, 0);
        const currentStageWeight = stages[stageIndex].weight * Math.min(1, Math.max(0, stageProgress));
        const totalPercentage = Math.round((completedWeight + currentStageWeight) * 100);

        // Estimate time remaining
        let estimatedTimeLeft = null;
        if (startTime.current && totalPercentage > 5) {
            const elapsed = (Date.now() - startTime.current) / 1000;
            const estimatedTotal = (elapsed / totalPercentage) * 100;
            estimatedTimeLeft = Math.round(estimatedTotal - elapsed);
        }

        setProgress({
            currentStage: stageIndex + 1,
            totalStages: stages.length,
            percentage: totalPercentage,
            stageName: stages[stageIndex].name,
            estimatedTimeLeft,
            message
        });
    }, [stages]);

    const completeStage = useCallback((stageIndex) => {
        if (stageIndex + 1 < stages.length) {
            stageStartTime.current = Date.now();
            updateProgress(stageIndex + 1, 0);
        } else {
            // All stages complete
            setProgress({
                currentStage: stages.length,
                totalStages: stages.length,
                percentage: 100,
                stageName: 'Complete',
                estimatedTimeLeft: 0,
                message: 'All stages completed!'
            });
        }
    }, [stages, updateProgress]);

    const reset = useCallback(() => {
        startTime.current = null;
        stageStartTime.current = null;
        setProgress({
            currentStage: 0,
            percentage: 0,
            stageName: stages[0]?.name || 'Processing',
            estimatedTimeLeft: null,
            message: ''
        });
    }, [stages]);

    return {
        progress,
        startTracking,
        updateProgress,
        completeStage,
        reset
    };
};

export default useProgressTracker;

import { useEffect, useState, useCallback, useRef } from "react";
import {
  subscribeToAllQuestions,
  getQueuedQuestionIds,
} from "../services/firebase";
import { logger } from "../utils/logger";

/**
 * Custom hook for real-time Firestore synchronization.
 * Replaces cache-based approach with live listeners.
 *
 * MULTI-USER SUPPORT:
 * - When User A accepts a question, User B sees it disappear instantly
 * - When User A is reviewing question #5, User B can review #6 simultaneously
 * - Prevents duplicate work and ensures data consistency
 *
 * @param {boolean} enabled - Whether to enable real-time sync
 * @returns {Object} { questions, isLoading, error, refresh, syncStatus }
 */
export const useRealtimeQuestions = (enabled = true) => {
  const [questions, setQuestions] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const [syncStatus, setSyncStatus] = useState("disconnected"); // disconnected | connecting | synced

  // Track previous question count for change detection
  const prevCountRef = useRef(0);

  // Manual refresh function (forces re-subscription)
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const refresh = useCallback(() => {
    setRefreshTrigger((prev) => prev + 1);
  }, []);

  useEffect(() => {
    if (!enabled) {
      setIsLoading(false);
      setSyncStatus("disconnected");
      return;
    }

    logger.log("≡ƒöä Setting up real-time question sync...");
    setIsLoading(true);
    setError(null);
    setSyncStatus("connecting");

    // Subscribe to real-time updates
    const unsubscribe = subscribeToAllQuestions(
      (updatedQuestions) => {
        const prevCount = prevCountRef.current;
        const newCount = updatedQuestions.length;

        // Detect changes from other users
        if (prevCount > 0 && newCount !== prevCount) {
          const diff = newCount - prevCount;
          if (diff > 0) {
            logger.log(`≡ƒôÑ ${diff} new question(s) added by another user`);
          } else {
            logger.log(
              `≡ƒôñ ${Math.abs(
                diff
              )} question(s) removed/accepted by another user`
            );
          }
        }

        // FIX: Prevent real-time updates from overwriting queued (pending sync) items
        // This prevents the race condition where server's old "pending" status
        // overwrites local "accepted" status before the queue syncs
        const queuedIds = getQueuedQuestionIds();
        if (queuedIds.size > 0) {
          logger.log(
            `≡ƒ¢í∩╕Å Protecting ${queuedIds.size} queued items from server overwrite`
          );
        }

        // Merge: use server data for non-queued items, keep local state for queued items
        setQuestions((prevQuestions) => {
          // Build lookup map for previous questions
          const prevMap = new Map();
          for (const q of prevQuestions) {
            prevMap.set(q.uniqueId, q);
          }
          // Merge with queue protection
          const merged = [];
          for (const serverQ of updatedQuestions) {
            if (queuedIds.has(serverQ.uniqueId)) {
              // Keep local version (with user's pending changes) for queued items
              merged.push(prevMap.get(serverQ.uniqueId) || serverQ);
            } else {
              merged.push(serverQ);
            }
          }
          return merged;
        });

        prevCountRef.current = newCount;
        setIsLoading(false);
        setError(null);
        setSyncStatus("synced");
      },
      5000 // Max 5000 questions
    );

    // Cleanup on unmount or when refreshTrigger changes
    return () => {
      logger.log("≡ƒ¢æ Cleaning up real-time listener");
      setSyncStatus("disconnected");
      unsubscribe();
    };
  }, [enabled, refreshTrigger]);

  return {
    questions,
    isLoading,
    error,
    refresh,
    syncStatus, // "disconnected" | "connecting" | "synced"
  };
};

import { useCallback } from "react";
import {
  QUALITY_PASS_THRESHOLD,
  TOAST_DURATION,
  TARGET_PER_CATEGORY,
} from "../utils/constants";

/**
 * Hook for managing review mode bulk actions.
 * Handles clearing pending, bulk accepting, and bulk critiquing.
 *
 * @param {Object} params - Hook parameters
 * @param {Array} params.uniqueFilteredQuestions - Filtered questions list
 * @param {Function} params.setQuestions - Setter for questions state
 * @param {Function} params.handleUpdateStatus - Function to update question status
 * @param {Function} params.handleCritique - Function to critique a question
 * @param {Function} params.showMessage - Function to display toast messages
 * @returns {Object} Review action handlers
 */
export const useReviewActions = ({
  uniqueFilteredQuestions,
  allQuestions, // Added: Full dataset for global operations
  handleUpdateStatus,
  handleCritique,
  showMessage,
  bulkDeleteQuestions, // Added: New semantic action
}) => {
  /**
   * Clear all pending questions after confirmation.
   */
  const handleClearPending = useCallback(() => {
    if (
      window.confirm(
        "Are you sure you want to delete ALL pending questions? This cannot be undone."
      )
    ) {
      if (bulkDeleteQuestions) {
        // Collect all pending IDs from the full dataset
        const pendingIds = allQuestions
          .filter((q) => q.status !== "accepted" && q.status !== "rejected")
          .map((q) => q.id);

        bulkDeleteQuestions(pendingIds);
      }
      showMessage("All pending questions cleared.", 3000);
    }
  }, [bulkDeleteQuestions, allQuestions, showMessage]);

  /**
   * Bulk accept all questions with critique score >= threshold that are human verified.
   */
  const handleBulkAcceptHighScores = useCallback(() => {
    const highScoreQuestions = uniqueFilteredQuestions.filter(
      (q) =>
        q.critiqueScore >= QUALITY_PASS_THRESHOLD &&
        q.status !== "accepted" &&
        q.humanVerified
    );

    if (highScoreQuestions.length === 0) {
      showMessage(
        `No verified questions with score ΓëÑ ${QUALITY_PASS_THRESHOLD} to accept.`,
        TOAST_DURATION.MEDIUM
      );
      return;
    }

    highScoreQuestions.forEach((q) => handleUpdateStatus(q.id, "accepted"));
    showMessage(
      `Γ£ô Accepted ${highScoreQuestions.length} high-scoring questions!`,
      4000
    );
  }, [uniqueFilteredQuestions, handleUpdateStatus, showMessage]);

  /**
   * Bulk critique all questions without critique scores.
   * Processes sequentially to avoid rate limits.
   */
  const handleBulkCritiqueAll = useCallback(async () => {
    const uncritiquedQuestions = uniqueFilteredQuestions.filter(
      (q) => q.critiqueScore === undefined || q.critiqueScore === null
    );

    if (uncritiquedQuestions.length === 0) {
      showMessage("All questions already have critique scores.", 3000);
      return;
    }

    showMessage(
      `Running critique on ${uncritiquedQuestions.length} questions...`,
      3000
    );

    // Process sequentially to avoid rate limits
    for (const q of uncritiquedQuestions) {
      await handleCritique(q);
    }

    showMessage(
      `Γ£ô Critique complete for ${uncritiquedQuestions.length} questions!`,
      4000
    );
  }, [uniqueFilteredQuestions, handleCritique, showMessage]);

  /**
   * Trim excess pending questions to ensure equal distribution across categories.
   * Finds the category with the LEAST questions and trims all others to match.
   */
  const handleTrimExcess = useCallback(
    async (discipline) => {
      // 1. Group questions by category key (e.g., "Beginner MC")
      const groups = {};
      const pendingToDelete = [];

      // Initialize groups using ALL questions (not just filtered/visible ones)
      const sourceQuestions =
        allQuestions && allQuestions.length > 0
          ? allQuestions
          : uniqueFilteredQuestions;

      sourceQuestions.forEach((q) => {
        if (q.discipline !== discipline) return;

        const typeAbbrev = q.type === "True/False" ? "T/F" : "MC";
        const key = `${q.difficulty} ${typeAbbrev}`;

        if (!groups[key]) {
          groups[key] = {
            accepted: [],
            pending: [],
            rejected: [],
            total: 0,
          };
        }

        if (q.status === "accepted") groups[key].accepted.push(q);
        else if (q.status === "rejected") groups[key].rejected.push(q);
        else groups[key].pending.push(q);

        // Only count Accepted + Pending for the target (Rejected don't count towards "quota")
        if (q.status !== "rejected") {
          groups[key].total++;
        }
      });

      // 2. Use the standard target (40) instead of finding the minimum
      const target = TARGET_PER_CATEGORY;

      // 3. Determine which pending questions to delete
      let deleteCount = 0;
      Object.entries(groups).forEach(([_key, group]) => {
        const currentValid = group.accepted.length + group.pending.length;

        if (currentValid > target) {
          const surplus = currentValid - target;
          // We can only delete Pending questions. We cannot delete Accepted ones to reach target.
          const deletableCount = Math.min(surplus, group.pending.length);

          if (deletableCount > 0) {
            // Remove newest pending questions first
            const toRemove = group.pending.slice(0, deletableCount);
            toRemove.forEach((q) => pendingToDelete.push(q));
            deleteCount += toRemove.length;
          }
        }
      });

      if (deleteCount === 0) {
        showMessage(
          `Balanced! All sections already have ${target} (or fewer) questions.`,
          3000
        );
        return;
      }

      if (
        window.confirm(
          `Trimming to Common Count: ${target}\n\n` +
            `Found ${deleteCount} excess pending questions in ${discipline} that exceed the lowest section count (${target}).\n\n` +
            `Proceed to delete them?`
        )
      ) {
        // Get IDs of questions to delete
        const idsToDelete = Array.from(
          new Set(pendingToDelete.map((q) => q.id))
        );

        // Use new bulk action if available
        if (bulkDeleteQuestions) {
          bulkDeleteQuestions(idsToDelete);
        }

        showMessage(
          `Γ£à Trimmed ${pendingToDelete.length} questions successfully!`,
          TOAST_DURATION.LONG
        );
      }
    },
    [uniqueFilteredQuestions, allQuestions, showMessage, bulkDeleteQuestions]
  );

  return {
    handleClearPending,
    handleBulkAcceptHighScores,
    handleBulkCritiqueAll,
    handleTrimExcess,
  };
};

/**
 * useToast Hook - Enhanced Version
 *
 * Features:
 * - Smart message replacement (similar messages update instead of stack)
 * - Priority levels (high=sticky, medium=normal, low=replaceable)
 * - Progress toast support
 * - Deduplication
 *
 * NOTE: Regex patterns here are used for toast message matching.
 * Input is application-controlled, not user-provided - no DoS risk.
 */
/* eslint-disable sonarjs/slow-regex */
import { useState, useCallback, useRef } from "react";

// Patterns for messages that should replace (not stack)
const REPLACEABLE_PATTERNS = [
  /Score:\s*\d+\/100/i, // Score updates
  /Critiquing\s+\d+/i, // Critique progress
  /Translating.*\d+/i, // Translation progress
  /Generated\s+\d+/i, // Generation counts
  /Processing\s+\d+/i, // Processing progress
  /Loading/i, // Loading states
  /Saving/i, // Saving states
  /\d+\s*of\s*\d+/i, // X of Y progress
  /\(\d+\/\d+\)/, // (X/Y) progress
];

// Priority durations
const PRIORITY_CONFIG = {
  high: { duration: 0, sticky: true }, // Stays until manually dismissed
  medium: { duration: 6000, sticky: false }, // 6 seconds
  low: { duration: 3000, sticky: false }, // 3 seconds
  progress: { duration: 0, sticky: true }, // Progress toasts persist
};

/**
 * Check if a message matches any replaceable pattern
 */
const getMessagePattern = (message) => {
  for (const pattern of REPLACEABLE_PATTERNS) {
    if (pattern.test(message)) {
      return pattern;
    }
  }
  return null;
};

/**
 * Custom hook for managing toast notifications.
 *
 * @returns {Object} Toast state and handlers
 */
export function useToast() {
  const [toasts, setToasts] = useState([]);
  const toastIdCounter = useRef(0);

  /**
   * Add or update a toast notification.
   * Smart replacement: If message matches a pattern, update existing toast.
   *
   * @param {string} message - Toast message
   * @param {Object} options - Toast options
   * @param {string} options.type - Toast type ('info', 'success', 'error', 'warning', 'progress')
   * @param {string} options.priority - Priority level ('high', 'medium', 'low')
   * @param {number} options.duration - Custom duration in ms (overrides priority default)
   * @param {number} options.progress - Progress value 0-100 (for progress type)
   * @param {string} options.id - Custom ID for updating specific toasts
   */
  const addToast = useCallback((message, options = {}) => {
    const {
      type = "info",
      priority = "medium",
      duration,
      progress,
      id: customId,
    } = options;

    const config = PRIORITY_CONFIG[priority] || PRIORITY_CONFIG.medium;
    const finalDuration = duration ?? config.duration;
    const pattern = getMessagePattern(message);

    setToasts((prev) => {
      // Check for exact duplicate
      if (prev.some((t) => t.message === message)) {
        return prev;
      }

      // Smart replacement: Find existing toast with matching pattern
      if (pattern || customId) {
        const existingIndex = prev.findIndex(
          (t) =>
            (customId && t.id === customId) ||
            (pattern && pattern.test(t.message))
        );

        if (existingIndex !== -1) {
          // Update existing toast instead of adding new one
          const updated = [...prev];
          updated[existingIndex] = {
            ...updated[existingIndex],
            message,
            type,
            progress,
            duration: finalDuration,
            updatedAt: Date.now(),
          };
          return updated;
        }
      }

      // Create new toast
      const id = customId || `toast-${++toastIdCounter.current}`;
      const newToast = {
        id,
        message,
        type,
        priority,
        duration: finalDuration,
        sticky: config.sticky,
        progress,
        createdAt: Date.now(),
      };

      // Add new toast, keeping max 3 (but never remove high priority)
      const newToasts = [...prev, newToast];

      // If over limit, remove oldest low-priority toast
      if (newToasts.length > 3) {
        const lowPriorityIndex = newToasts.findIndex(
          (t) => t.priority === "low" && !t.sticky
        );
        if (lowPriorityIndex !== -1) {
          newToasts.splice(lowPriorityIndex, 1);
        } else {
          // If no low priority, remove oldest non-sticky
          const removableIndex = newToasts.findIndex((t) => !t.sticky);
          if (removableIndex !== -1) {
            newToasts.splice(removableIndex, 1);
          }
        }
      }

      return newToasts;
    });
  }, []);

  /**
   * Remove a toast by ID.
   */
  const removeToast = useCallback((id) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  /**
   * Update a progress toast
   */
  const updateProgress = useCallback((id, progress, message) => {
    setToasts((prev) =>
      prev.map((t) =>
        t.id === id
          ? {
              ...t,
              progress,
              message: message || t.message,
              updatedAt: Date.now(),
            }
          : t
      )
    );
  }, []);

  /**
   * Complete and auto-dismiss a progress toast
   */
  const completeProgress = useCallback((id, message, duration = 2000) => {
    setToasts((prev) =>
      prev.map((t) =>
        t.id === id
          ? {
              ...t,
              progress: 100,
              message: message || t.message,
              sticky: false,
              duration,
              type: "success",
            }
          : t
      )
    );
  }, []);

  /**
   * Legacy showMessage for backward compatibility
   * @param {string} msg - Message to display
   * @param {string|number} typeOrDuration - Toast type OR duration (backward compat)
   * @param {number} duration - Duration in ms
   */
  const showMessage = useCallback(
    (msg, typeOrDuration = "info", duration) => {
      // Backward compatibility: if second arg is number, treat as duration
      const isNumberArg = typeof typeOrDuration === "number";
      let finalDuration = isNumberArg ? typeOrDuration : duration;
      let type = isNumberArg ? "info" : typeOrDuration;
      let priority = "medium";

      // Auto-detect type/priority based on message content (overrides defaults)
      if (
        msg.includes("Error") ||
        msg.includes("Failed") ||
        msg.includes("Γ¥î") ||
        msg.includes("Γ¢ö")
      ) {
        priority = "high";
        type = "error";
      } else if (msg.includes("ΓÜá∩╕Å") || msg.includes("Warning")) {
        type = "warning";
      } else if (
        msg.includes("Γ£ô") ||
        msg.includes("Γ£à") ||
        msg.includes("Success") ||
        msg.includes("complete")
      ) {
        type = "success";
      } else if (
        msg.includes("...") ||
        msg.includes("Loading") ||
        msg.includes("Saving")
      ) {
        priority = "low";
      }

      addToast(msg, { type, priority, duration: finalDuration });
    },
    [addToast]
  );

  return {
    toasts,
    addToast,
    removeToast,
    updateProgress,
    completeProgress,
    showMessage,
  };
}

