import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import {
  convertQuestionToScormFormat,
  validateQuestionsForExport,
  generateScormPackageFiles,
} from "../scormExporter";

describe("SCORM Exporter Service", () => {
  // --- Test Data ---
  const validQuestion = {
    guid: "q1",
    questionText: "What is Nanite?",
    type: "Multiple Choice",
    difficulty: "Beginner",
    choices: ["Geometry System", "Lighting System", "Sound System"],
    correctAnswer: "Geometry System",
  };

  const invalidQuestion = {
    guid: "q2",
    questionText: "", // Missing text
    type: "Multiple Choice",
    choices: ["A"], // Too few choices
    correctAnswer: "B", // Not in choices
  };

  // --- convertQuestionToScormFormat ---
  describe("convertQuestionToScormFormat", () => {
    it("should transform Firestore question to SCORM format", () => {
      const result = convertQuestionToScormFormat(validQuestion);

      expect(result.id).toBe("q1");
      expect(result.text).toBe("What is Nanite?");
      expect(result.choices).toHaveLength(3);
      expect(result.choices[0]).toEqual({
        text: "Geometry System",
        correct: true,
      });
      expect(result.choices[1]).toEqual({
        text: "Lighting System",
        correct: false,
      });
    });

    it("should handle T/F questions", () => {
      const tfQuestion = {
        questionText: "UE5 is free?",
        type: "True/False",
        choices: ["True", "False"],
        correctAnswer: "True",
      };
      const result = convertQuestionToScormFormat(tfQuestion);
      expect(result.choices).toHaveLength(2);
      expect(result.choices.find((c) => c.text === "True").correct).toBe(true);
    });
  });

  // --- validateQuestionsForExport ---
  describe("validateQuestionsForExport", () => {
    it("should pass valid questions", () => {
      const result = validateQuestionsForExport([validQuestion]);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    it("should detect invalid questions", () => {
      const result = validateQuestionsForExport([invalidQuestion]);
      expect(result.valid).toBe(false);
      const errorText = result.errors.join(" ");
      expect(errorText).toContain("Missing question text");
      expect(errorText).toContain("at least 2 choices");
      expect(errorText).toContain("Correct answer not found");
    });

    it("should warn on low question count", () => {
      const result = validateQuestionsForExport([validQuestion]); // Only 1
      expect(result.valid).toBe(true); // Still valid
      expect(result.warnings).toHaveLength(1);
    });
  });

  // --- generateScormPackageFiles ---
  describe("generateScormPackageFiles", () => {
    // Mock global fetch
    const fetchMock = vi.fn();

    beforeEach(() => {
      global.fetch = fetchMock;
      // Setup default mock response
      fetchMock.mockResolvedValue({
        text: () => Promise.resolve("TEMPLATE_CONTENT"),
      });
    });

    afterEach(() => {
      vi.restoreAllMocks();
    });

    it("should fetch all template files and generate questions.js", async () => {
      const config = {
        title: "Test Quiz",
        passingScore: 70,
        timeLimit: 15,
      };

      const files = await generateScormPackageFiles([validQuestion], config);

      // Verify fetch calls
      expect(fetchMock).toHaveBeenCalledTimes(5);
      expect(fetchMock).toHaveBeenCalledWith(
        expect.stringContaining("imsmanifest.xml")
      );

      // Verify output files
      expect(files["imsmanifest.xml"]).toBe("TEMPLATE_CONTENT"); // In real run it replaces strings, but mock returns simpler
      expect(files["questions.js"]).toContain('title: "Test Quiz"');
      expect(files["questions.js"]).toContain("passingScore: 70");
      expect(files["questions.js"]).toContain("timeLimit: 900"); // 15 * 60
      expect(files["questions.js"]).toContain('"text": "What is Nanite?"');
    });

    it("should replace template variables in manifest", async () => {
      // Mock manifest content specifically
      fetchMock.mockImplementation((url) => {
        if (url.includes("imsmanifest.xml")) {
          return Promise.resolve({
            text: () =>
              Promise.resolve(
                "<title>UE5 Scenario Tracker</title><id>com.example.ue5scenario.scorm12</id>"
              ),
          });
        }
        return Promise.resolve({ text: () => Promise.resolve("") });
      });

      const files = await generateScormPackageFiles([validQuestion], {
        title: "New Title",
      });

      expect(files["imsmanifest.xml"]).toContain("<title>New Title</title>");
      expect(files["imsmanifest.xml"]).toContain("com.ue5questiongen");
    });
  });
});

/**
 * Cloud Functions Service
 * Secure wrapper for calling Firebase Cloud Functions
 * This replaces direct Gemini API calls to keep the API key server-side
 */

import { getFunctions, httpsCallable } from "firebase/functions";
import { app, auth } from "./firebase";
import { logger } from "../utils/logger";

// Initialize Cloud Functions
const functions = getFunctions(app, "us-central1");

/**
 * Calls the generateQuestions Cloud Function
 * @param {string} systemPrompt - System instruction for the AI
 * @param {string} userPrompt - User's question/request
 * @param {function} setStatus - Optional status callback
 * @param {number} temperature - Temperature for generation (default 0.2)
 * @param {string} model - Model name (default 'gemini-2.0-flash')
 * @returns {Promise<string>} Generated text response
 */
export const generateContentViaCloudFunction = async (
  systemPrompt,
  userPrompt,
  setStatus = () => {},
  temperature = 0.2,
  model = "gemini-2.0-flash-exp"
) => {
  try {
    setStatus("Calling secure Cloud Function...");

    const generateQuestions = httpsCallable(functions, "generateQuestions");

    const result = await generateQuestions({
      systemPrompt,
      userPrompt,
      temperature,
      model,
    });

    if (!result.data.success) {
      throw new Error(result.data.error || "Cloud Function failed");
    }

    setStatus("Response received!");

    // Store grounding sources globally (for backward compatibility)
    if (
      result.data.groundingSources &&
      result.data.groundingSources.length > 0
    ) {
      logger.log("≡ƒôÜ Grounding sources found:", result.data.groundingSources);
      window.__lastGroundingSources = result.data.groundingSources;
    }

    return result.data.textResponse;
  } catch (error) {
    logger.error("Cloud Function error:", error);
    setStatus(`Error: ${error.message}`);
    throw error;
  }
};

/**
 * Calls the generateCritique Cloud Function
 * @param {object} question - Question object { question, options, correct, modeLabel }
 * @returns {Promise<{score: number, text: string, rewrite: object, changes: string}>}
 */
export const generateCritiqueViaCloudFunction = async (
  question,
  model = "gemini-1.5-flash"
) => {
  try {
    const generateCritique = httpsCallable(functions, "generateCritique");

    const result = await generateCritique({
      question: question.question,
      options: question.options,
      correct: question.correct,
      type: question.type || "Multiple Choice", // Preserve question type
      modeLabel: question.modeLabel,
      model: model,
    });

    if (!result.data.success) {
      throw new Error(result.data.error || "Critique failed");
    }

    logger.log(
      "[CloudFunction DEBUG] Raw result.data:",
      JSON.stringify(result.data).substring(0, 200)
    );
    logger.log("[CloudFunction DEBUG] Extracted score:", result.data.score);
    logger.log(
      "[CloudFunction DEBUG] Extracted improvedScore:",
      result.data.improvedScore
    );

    return {
      score: result.data.score,
      improvedScore: result.data.improvedScore || null,
      text: result.data.text,
      rewrite: result.data.rewrite,
      changes: result.data.changes,
    };
  } catch (error) {
    logger.error("Critique Cloud Function error:", error);
    throw error;
  }
};

/**
 * Helper to check if user is authenticated (required for Cloud Functions)
 * @returns {boolean}
 */
export const isUserAuthenticated = () => {
  return !!auth.currentUser;
};

/**
 * Calls the migrateTranslations Cloud Function
 * Links existing translated questions with their English originals via uniqueId
 * SUPER ADMIN ONLY
 * @returns {Promise<{success: boolean, stats: object}>}
 */
export const migrateTranslationsViaCloudFunction = async () => {
  try {
    const migrateTranslations = httpsCallable(functions, "migrateTranslations");

    const result = await migrateTranslations();

    if (!result.data.success) {
      throw new Error(result.data.error || "Migration failed");
    }

    return {
      success: true,
      stats: result.data.stats,
    };
  } catch (error) {
    logger.error("Migration Cloud Function error:", error);
    throw error;
  }
};

/**
 * Calls the sendReviewerInvites Cloud Function
 * Sends personalized invite emails to reviewers via SendGrid
 * ADMIN ONLY
 * @param {Array} invites - Array of invite objects { email, inviteUrl, code, note }
 * @returns {Promise<{success: boolean, sent: string[], failed: object[], total: number}>}
 */
export const sendReviewerInvitesViaEmail = async (invites) => {
  try {
    const sendReviewerInvites = httpsCallable(functions, "sendReviewerInvites");

    const result = await sendReviewerInvites({ invites });

    if (!result.data.success) {
      throw new Error(result.data.error || "Email send failed");
    }

    return {
      success: true,
      sent: result.data.sent,
      failed: result.data.failed,
      total: result.data.total,
    };
  } catch (error) {
    logger.error("SendReviewerInvites Cloud Function error:", error);
    throw error;
  }
};

