import JSZip from "jszip";
import { logger } from "../utils/logger";
import { SCORM_DEFAULTS } from "../utils/constants";

/**
 * SCORM 1.2 Exporter Service
 * Converts Firestore questions to SCORM packages
 */

/**
 * Convert a Firestore question to SCORM quiz format
 * @param {Object} question - Firestore question object
 * @returns {Object} SCORM-formatted question
 */
export function convertQuestionToScormFormat(question) {
  const { questionText, type, choices, correctAnswer, guid, difficulty } =
    question;

  // For Multiple Choice: choices is array of strings, correctAnswer is the correct string
  // For True/False: choices is ["True", "False"], correctAnswer is "True" or "False"

  const scormChoices = choices.map((choiceText) => ({
    text: choiceText,
    correct: choiceText === correctAnswer,
  }));

  return {
    // eslint-disable-next-line sonarjs/pseudo-random
    id: guid || `q-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
    text: questionText,
    type: type,
    difficulty: difficulty || "Medium",
    choices: scormChoices,
  };
}

/**
 * Generate SCORM package configuration
 * @param {Array} questions - Array of Firestore questions
 * @param {Object} config - Package configuration
 * @returns {Object} Package files ready for zipping
 */
export async function generateScormPackageFiles(questions, config = {}) {
  const {
    title = "UE5 Knowledge Assessment",
    description = "Test your Unreal Engine 5 knowledge",
    passingScore = SCORM_DEFAULTS.PASSING_SCORE,
    timeLimit = SCORM_DEFAULTS.TIME_LIMIT_MINUTES, // minutes
  } = config;

  // Convert questions to SCORM format
  const scormQuestions = questions.map(convertQuestionToScormFormat);

  // Load template files from public directory
  const templatePath = "/scorm-template/";

  // Fetch template files
  const [scormJs, indexHtml, styleCSS, gameJs, manifest] = await Promise.all([
    fetch(`${templatePath}scorm.js`).then((r) => r.text()),
    fetch(`${templatePath}index.html`).then((r) => r.text()),
    fetch(`${templatePath}style.css`).then((r) => r.text()),
    fetch(`${templatePath}game.js`).then((r) => r.text()),
    fetch(`${templatePath}imsmanifest.xml`).then((r) => r.text()),
  ]);

  // Replace template variables in manifest
  const processedManifest = manifest
    .replace(/UE5 Scenario Tracker/g, title)
    .replace(
      /com\.example\.ue5scenario\.scorm12/g,
      `com.ue5questiongen.${Date.now()}`
    );

  // Replace template variables in index.html
  const processedIndexHtml = indexHtml.replace(/UE5 Scenario Tracker/g, title);

  // Create questions.js file with our questions
  const questionsJs = `// Generated questions for SCORM package
// Generated: ${new Date().toISOString()}

window.QUIZ_CONFIG = {
  title: "${title}",
  description: "${description}",
  passingScore: ${passingScore},
  timeLimit: ${timeLimit * 60}, // Convert minutes to seconds
  totalQuestions: ${scormQuestions.length}
};

window.QUESTIONS = ${JSON.stringify(scormQuestions, null, 2)};
`;

  return {
    "scorm.js": scormJs,
    "index.html": processedIndexHtml,
    "style.css": styleCSS,
    "game.js": gameJs,
    "questions.js": questionsJs,
    "imsmanifest.xml": processedManifest,
  };
}

/**
 * Generate and download SCORM package as .zip file
 * @param {Array} questions - Array of Firestore questions
 * @param {Object} config - Package configuration
 */
export async function exportToScorm(questions, config = {}) {
  if (!questions || questions.length === 0) {
    throw new Error("No questions provided for SCORM export");
  }

  try {
    // Generate package files
    const files = await generateScormPackageFiles(questions, config);

    // Create ZIP file
    const zip = new JSZip();

    // Add all files to ZIP
    Object.entries(files).forEach(([filename, content]) => {
      zip.file(filename, content);
    });

    // Generate ZIP blob
    const blob = await zip.generateAsync({ type: "blob" });

    // Create download link
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;

    // Generate filename with timestamp
    const timestamp = new Date().toISOString().split("T")[0];
    const sanitizedTitle = (config.title || "UE5_Quiz")
      .replace(/[^a-z0-9]/gi, "_")
      .toLowerCase();
    link.download = `${sanitizedTitle}_${timestamp}_scorm12.zip`;

    // Trigger download
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    // Clean up
    URL.revokeObjectURL(url);

    return {
      success: true,
      filename: link.download,
      questionCount: questions.length,
    };
  } catch (error) {
    logger.error("SCORM export failed:", error);
    throw new Error(`Failed to generate SCORM package: ${error.message}`);
  }
}

/**
 * Validate questions before export
 * @param {Array} questions - Questions to validate
 * @returns {Object} Validation result
 */
export function validateQuestionsForExport(questions) {
  const errors = [];
  const warnings = [];

  if (!questions || questions.length === 0) {
    errors.push("No questions selected for export");
    return { valid: false, errors, warnings };
  }

  if (questions.length < 5) {
    warnings.push(
      "Less than 5 questions selected. Consider adding more for a comprehensive assessment."
    );
  }

  if (questions.length > 100) {
    warnings.push(
      "More than 100 questions selected. Large packages may take longer to load in the LMS."
    );
  }

  questions.forEach((q, index) => {
    if (!q.questionText || q.questionText.trim() === "") {
      errors.push(`Question ${index + 1}: Missing question text`);
    }

    if (!q.choices || q.choices.length < 2) {
      errors.push(`Question ${index + 1}: Must have at least 2 choices`);
    }

    if (!q.correctAnswer) {
      errors.push(`Question ${index + 1}: Missing correct answer`);
    }

    if (q.choices && !q.choices.includes(q.correctAnswer)) {
      errors.push(`Question ${index + 1}: Correct answer not found in choices`);
    }
  });

  return {
    valid: errors.length === 0,
    errors,
    warnings,
    questionCount: questions.length,
  };
}

/**
 * Training Data Service
 *
 * Manages collection of AI training data (correction pairs):
 * - Saves original vs. corrected question pairs
 * - Exports data in JSONL format for Vertex AI fine-tuning
 */

import {
  collection,
  addDoc,
  getDocs,
  query,
  orderBy,
  limit,
  Timestamp,
} from "firebase/firestore";
import { getDb, auth } from "./firebase";
import { logger } from "../utils/logger";

/**
 * Save a training pair (original vs. corrected question)
 * @param {Object} original - Original question before correction
 * @param {Object} corrected - Corrected/improved question
 * @param {string} correctionType - Type of correction (e.g., "question_text", "options", "answer")
 * @returns {Promise<{success: boolean, docId?: string, error?: string}>}
 */
export const saveTrainingPair = async (
  original,
  corrected,
  correctionType = "general"
) => {
  try {
    if (!auth.currentUser) {
      return { success: false, error: "Not authenticated" };
    }

    const trainingData = {
      // Original question data
      original: {
        question: original.question,
        options: original.options,
        correct: original.correct,
        discipline: original.discipline,
        difficulty: original.difficulty,
        type: original.type,
      },
      // Corrected question data
      corrected: {
        question: corrected.question,
        options: corrected.options,
        correct: corrected.correct,
        discipline: corrected.discipline,
        difficulty: corrected.difficulty,
        type: corrected.type,
      },
      // Metadata
      correctionType,
      originalQuestionId: original.uniqueId,
      correctedBy: auth.currentUser.uid,
      correctedByEmail: auth.currentUser.email,
      correctedAt: Timestamp.now(),
    };

    const docRef = await addDoc(
      collection(getDb(), "training_data"),
      trainingData
    );

    logger.log(`Γ£à Training pair saved: ${docRef.id}`);
    return { success: true, docId: docRef.id };
  } catch (error) {
    logger.error("Failed to save training pair:", error);
    return { success: false, error: error.message };
  }
};

/**
 * Export training data in JSONL format for Vertex AI fine-tuning
 * Format: {"input": "original question prompt", "output": "corrected question"}
 * @param {number} maxRecords - Maximum number of records to export
 * @returns {Promise<{success: boolean, data?: string, count?: number, error?: string}>}
 */
export const exportTrainingData = async (maxRecords = 1000) => {
  try {
    if (!auth.currentUser) {
      return { success: false, error: "Not authenticated" };
    }

    const trainingQuery = query(
      collection(getDb(), "training_data"),
      orderBy("correctedAt", "desc"),
      limit(maxRecords)
    );

    const snapshot = await getDocs(trainingQuery);
    const records = [];

    snapshot.forEach((doc) => {
      const data = doc.data();

      // Format for Vertex AI fine-tuning
      const record = {
        input: formatQuestionPrompt(data.original),
        output: formatQuestionOutput(data.corrected),
        metadata: {
          id: doc.id,
          correctionType: data.correctionType,
          discipline: data.original.discipline,
        },
      };

      records.push(record);
    });

    // Convert to JSONL format (one JSON object per line)
    const jsonl = records.map((r) => JSON.stringify(r)).join("\n");

    return { success: true, data: jsonl, count: records.length };
  } catch (error) {
    logger.error("Failed to export training data:", error);
    return { success: false, error: error.message };
  }
};

/**
 * Format original question as a prompt for fine-tuning input
 */
const formatQuestionPrompt = (q) => {
  return `Generate a ${q.difficulty || "Medium"} difficulty ${
    q.type || "Multiple Choice"
  } question about ${q.discipline || "UE5"}.

Original:
Question: ${q.question}
A: ${q.options?.A || ""}
B: ${q.options?.B || ""}
C: ${q.options?.C || ""}
D: ${q.options?.D || ""}
Correct: ${q.correct}

Please improve this question.`;
};

/**
 * Format corrected question as expected output for fine-tuning
 */
const formatQuestionOutput = (q) => {
  return `Question: ${q.question}
A: ${q.options?.A || ""}
B: ${q.options?.B || ""}
C: ${q.options?.C || ""}
D: ${q.options?.D || ""}
Correct: ${q.correct}`;
};

/**
 * Download training data as JSONL file
 */
export const downloadTrainingDataAsFile = async () => {
  const result = await exportTrainingData();

  if (!result.success) {
    throw new Error(result.error);
  }

  const blob = new Blob([result.data], { type: "application/jsonl" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `ue5-training-data-${
    new Date().toISOString().split("T")[0]
  }.jsonl`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);

  return { success: true, count: result.count };
};

