describe("createUniqueFilteredQuestions", () => {
  const variants = [
    { uniqueId: "1", language: "English", question: "Hello" },
    { uniqueId: "1", language: "Spanish", question: "Hola" },
    { uniqueId: "2", language: "French", question: "Bonjour" },
    { uniqueId: "3", language: "English", question: "Good day" },
  ];

  it("returns one question per uniqueId with matching language", () => {
    // uniqueId '2' (French only) is excluded when viewing English
    // because it has no English variant - this is intentional language leakage prevention
    const result = createUniqueFilteredQuestions(variants, "English");
    expect(result).toHaveLength(2); // uniqueId '1' and '3' only
    const ids = result.map((q) => q.uniqueId);
    expect(ids).toContain("1");
    expect(ids).toContain("3");
    expect(ids).not.toContain("2"); // French-only question excluded
  });

  it("prefers selected language", () => {
    const result = createUniqueFilteredQuestions(variants, "Spanish");
    const q1 = result.find((q) => q.uniqueId === "1");
    expect(q1.language).toBe("Spanish");
  });

  it("falls back to English if selected language missing", () => {
    const result = createUniqueFilteredQuestions(variants, "German");
    const q1 = result.find((q) => q.uniqueId === "1");
    expect(q1.language).toBe("English");
  });

  it("excludes questions without English or preferred language", () => {
    // This is intentional behavior to prevent language leakage
    // (e.g., Chinese questions appearing in English queue)
    const result = createUniqueFilteredQuestions(variants, "German");
    const q2 = result.find((q) => q.uniqueId === "2");
    expect(q2).toBeUndefined(); // French-only question is excluded
  });
});

/**
 * Tests for quizUtils.js - Quiz GUID and randomization utilities
