export const getTokenUsage = () => {
  const data = getAnalytics();
  const inputTokens = data.generations.reduce(
    (sum, g) => sum + (g.tokensUsed?.input || 0),
    0
  );
  const outputTokens = data.generations.reduce(
    (sum, g) => sum + (g.tokensUsed?.output || 0),
    0
  );

  return {
    inputTokens,
    outputTokens,
    totalCost: data.summary.estimatedCost,
  };
};

/**
 * Logs a critique action (apply or reject)
 * @param {Object} actionData - Action data
 * @param {string} actionData.questionId - Question ID
 * @param {string} actionData.action - 'applied' | 'rejected'
 * @param {number} actionData.critiqueScore - Original critique score
 * @param {string} actionData.discipline - Question discipline
 */
export const logCritiqueAction = (actionData) => {
  const data = getAnalytics();

  const action = {
    id: crypto.randomUUID(),
    timestamp: new Date().toISOString(),
    questionId: actionData.questionId,
    action: actionData.action, // 'applied' or 'rejected'
    critiqueScore: actionData.critiqueScore,
    discipline: actionData.discipline || "Unknown",
  };

  if (!data.critiqueActions) {
    data.critiqueActions = [];
  }

  data.critiqueActions.push(action);

  // Update critique acceptance rate
  const totalActions = data.critiqueActions.length;
  const appliedActions = data.critiqueActions.filter(
    (a) => a.action === "applied"
  ).length;
  data.summary.critiqueAcceptanceRate =
    totalActions > 0 ? Math.round((appliedActions / totalActions) * 100) : 0;

  saveAnalytics(data);
};

/**
 * Answer Validator - Validates that the correct answer matches the source excerpt
 * Checks if key terms from the correct answer appear in the SourceExcerpt
 *
 * NOTE: Regex patterns are for text normalization and HTML tag removal.
 * Input is question/answer text from app database - controlled, no DoS risk.
 */
/* eslint-disable sonarjs/slow-regex */

/**
 * Extract key terms from text (removes common words)
 * @param {string} text - Text to extract terms from
 * @returns {string[]} Array of key terms
 */
function extractKeyTerms(text) {
  if (!text) return [];

  // Common words to ignore
  const stopWords = new Set([
    "a",
    "an",
    "the",
    "is",
    "are",
    "was",
    "were",
    "be",
    "been",
    "being",
    "have",
    "has",
    "had",
    "do",
    "does",
    "did",
    "will",
    "would",
    "could",
    "should",
    "may",
    "might",
    "must",
    "shall",
    "can",
    "need",
    "dare",
    "to",
    "of",
    "in",
    "for",
    "on",
    "with",
    "at",
    "by",
    "from",
    "as",
    "into",
    "through",
    "during",
    "before",
    "after",
    "above",
    "below",
    "between",
    "under",
    "again",
    "further",
    "then",
    "once",
    "here",
    "there",
    "when",
    "where",
    "why",
    "how",
    "all",
    "each",
    "few",
    "more",
    "most",
    "other",
    "some",
    "such",
    "no",
    "not",
    "only",
    "own",
    "same",
    "so",
    "than",
    "too",
    "very",
    "just",
    "and",
    "but",
    "or",
    "because",
    "until",
    "while",
    "although",
    "this",
    "that",
    "these",
    "those",
    "used",
    "use",
    "using",
    "uses",
    "which",
    "what",
    "it",
    "its",
  ]);

  // Extract words, normalize, filter
  const words = text
    .toLowerCase()
    .replace(/<[^>]+>/g, "") // Remove HTML tags
    .replace(/[^a-z0-9\s]/g, " ") // Remove special chars
    .split(/\s+/)
    .filter((word) => word.length > 2 && !stopWords.has(word));

  return [...new Set(words)]; // Remove duplicates
}

/**
 * Validates that the correct answer matches the source excerpt
 * @param {Object} question - Question object
 * @returns {{ isValid: boolean, confidence: number, warning: string | null, details: Object }}
 */
export function validateAnswer(question) {
  // Get the correct answer based on CorrectLetter
  const correctLetter = question.CorrectLetter || question.correctLetter;
  const sourceExcerpt = question.SourceExcerpt || question.sourceExcerpt;

  if (!correctLetter || !sourceExcerpt) {
    return {
      isValid: false,
      confidence: 0,
      warning: "Missing CorrectLetter or SourceExcerpt",
      details: {
        correctLetter: correctLetter || null,
        hasExcerpt: !!sourceExcerpt,
      },
    };
  }

  // Get the correct answer text
  const letterToOption = {
    A: question.OptionA || question.optionA,
    B: question.OptionB || question.optionB,
    C: question.OptionC || question.optionC,
    D: question.OptionD || question.optionD,
  };

  const correctAnswer = letterToOption[correctLetter.toUpperCase()];

  if (!correctAnswer) {
    return {
      isValid: false,
      confidence: 0,
      warning: `No option found for letter ${correctLetter}`,
      details: { correctLetter, options: letterToOption },
    };
  }

  // Extract key terms from both
  const answerTerms = extractKeyTerms(correctAnswer);
  const excerptText = sourceExcerpt.toLowerCase();

  // Count how many answer terms appear in excerpt
  let matchedTerms = 0;
  const matchedKeyTerms = [];

  for (const term of answerTerms) {
    if (excerptText.includes(term)) {
      matchedTerms++;
      matchedKeyTerms.push(term);
    }
  }

  // Calculate confidence
  const matchRatio =
    answerTerms.length > 0 ? matchedTerms / answerTerms.length : 0;
  const confidence = Math.round(matchRatio * 100);

  // Determine validity
  let isValid = confidence >= 50;
  let warning = null;

  if (confidence < 30) {
    warning = `Answer "${correctAnswer}" not found in source excerpt`;
    isValid = false;
  } else if (confidence < 50) {
    warning = `Low confidence: only ${matchedTerms}/${answerTerms.length} key terms matched`;
  } else if (confidence < 70) {
    warning = `Moderate confidence: verify answer matches source`;
  }

  return {
    isValid,
    confidence,
    warning,
    details: {
      correctAnswer,
      correctLetter,
      answerTerms,
      matchedTerms: matchedKeyTerms,
      totalTerms: answerTerms.length,
    },
  };
}

/**
 * Batch validate answers
 * @param {Array} questions - Array of question objects
 * @returns {Array} Questions with answerValidation field added
 */
export function validateAnswersBatch(questions) {
  return questions.map((q) => ({
    ...q,
    answerValidation: validateAnswer(q),
  }));
}

export default validateAnswer;

/**
 * Bulk Delete "deleted" Questions from Firestore
 *
 * This script permanently removes all questions with status: "deleted"
 * Run this in the browser console (F12) when signed in as admin
 */

import { getDb } from "./src/services/firebase.js";
import {
  collection,
  query,
  where,
  getDocs,
  deleteDoc,
} from "firebase/firestore";
import { logger } from "./logger";

export async function bulkDeleteSoftDeleted(discipline = null, dryRun = true) {
  logger.log("≡ƒùæ∩╕Å Bulk Delete Script Starting...");
  logger.log(`Mode: ${dryRun ? "DRY RUN" : "LIVE DELETE"}`);

  try {
    // Query for all "deleted" questions
    const questionsRef = collection(getDb(), "questions");
    let q = query(questionsRef, where("status", "==", "deleted"));

    // Optionally filter by discipline
    if (discipline) {
      q = query(
        questionsRef,
        where("status", "==", "deleted"),
        where("discipline", "==", discipline)
      );
      logger.log(`≡ƒôì Filtering by discipline: ${discipline}`);
    }

    const snapshot = await getDocs(q);
    logger.log(`≡ƒôè Found ${snapshot.size} questions with status "deleted"`);

    if (snapshot.size === 0) {
      logger.log("Γ£à No deleted questions found. Database is clean!");
      return { success: true, deleted: 0 };
    }

    // Show preview
    logger.log("\n≡ƒôï Preview of questions to delete:");
    snapshot.docs.slice(0, 10).forEach((doc) => {
      const q = doc.data();
      logger.log(
        `- ${doc.id} | ${q.discipline} | ${q.question?.substring(0, 60)}...`
      );
    });

    if (snapshot.size > 10) {
      logger.log(`... and ${snapshot.size - 10} more`);
    }

    if (dryRun) {
      logger.log("\nΓÜá∩╕Å DRY RUN MODE - No questions were deleted");
      logger.log("To actually delete, run: bulkDeleteSoftDeleted(null, false)");
      return { success: true, deleted: 0, dryRun: true };
    }

    // Confirm before deletion
    logger.log("\nΓÜá∩╕Å LIVE DELETE MODE - About to permanently delete questions");
    logger.log("Deleting in 3 seconds... Press Ctrl+C to cancel");
    await new Promise((resolve) => setTimeout(resolve, 3000));

    // Delete all
    const deletePromises = snapshot.docs.map((doc) => deleteDoc(doc.ref));
    await Promise.all(deletePromises);

    logger.log(
      `Γ£à Successfully deleted ${snapshot.size} questions from Firestore`
    );
    logger.log("≡ƒÆí Refresh the page to see the updated counts");

    return {
      success: true,
      deleted: snapshot.size,
      discipline: discipline,
    };
  } catch (error) {
    logger.error("Γ¥î Bulk delete failed:", error);
    return {
      success: false,
      error: error.message,
    };
  }
}

// Auto-export for console use
if (typeof window !== "undefined") {
  window.bulkDeleteSoftDeleted = bulkDeleteSoftDeleted;
  logger.log("Γ£à Loaded: window.bulkDeleteSoftDeleted(discipline, dryRun)");
  logger.log('Example: bulkDeleteSoftDeleted("VFX", true) // Dry run for VFX');
  logger.log(
    "Example: bulkDeleteSoftDeleted(null, false) // Delete ALL deleted questions"
  );
}

