export const migrateAutoAcceptedQuestions = async () => {
  try {
    if (!auth.currentUser) {
      logger.error("Γ¥î Must be signed in to run migration");
      return { success: false, error: "Not authenticated" };
    }

    logger.log("≡ƒöä Starting migration: Fixing auto-accepted questions...");

    // Get all questions
