  // Generate ~10 questions per discipline
  const disciplines = [
    "Worldbuilding",
    "Game Dev",
    "Look Dev",
    "Tech Art",
    "VFX",
    "Animation",
    "Programming",
  ];

  disciplines.forEach((d) => {
