    }
  }

  // 2. Parse as Markdown Table
  const lines = cleanText.split("\n");
  const dataLines = lines.filter((line) => {
    const trimmed = line.trim();
    if (!trimmed) return false;
    const pipeCount = (trimmed.match(/\|/g) || []).length;
    const isSeparator =
