      trimmed.match(/\|\s*:?\s*-{2,}\s*:?\s*\|/);
    const isHeader = /\|\s*ID\s*\|/i.test(trimmed);
    return pipeCount >= 4 && !isHeader && !isSeparator;
  });

  dataLines.forEach((line, index) => {
    const normalizedLine = line.replace(/∩╜£/g, "|");
    const cols = normalizedLine.split("|").map((c) => c.trim());

    if (cols[0] === "") cols.shift();
    if (cols[cols.length - 1] === "") cols.pop();

    const discipline = cols[1];
    const typeRaw = cols[2];
    const difficulty = cols[3];
    const question = cols[4];
    const optA = cols[6];
    const optB = cols[7];
    const optC = cols[8];
    const optD = cols[9];
    const correctLetter = cols[10];
    const sourceUrl = cols[11];
    const sourceExcerpt = cols[12];
    const tagsRaw = cols[13];
    let qualityScore = null;
    if (cols[14]) {
      const match = cols[14].match(/\d+/);
      if (match) qualityScore = parseInt(match[0]);
    }

    if (!question || !correctLetter || question.includes("---")) return;

    let tags = [];
    if (tagsRaw && tagsRaw !== "-" && tagsRaw !== "") {
      tags = tagsRaw
        .split(",")
        .map((t) => t.trim().replace(/^#/, ""))
        .filter((t) => t);
    }

    const type =
      typeRaw && typeRaw.toLowerCase().includes("true")
        ? "True/False"
        : "Multiple Choice";

    let options = {};
    if (type === "True/False") {
      options = { A: "TRUE", B: "FALSE" };
    } else {
      options = { A: optA || "", B: optB || "", C: optC || "", D: optD || "" };
      const isMalformed = Object.values(options).some(
        (opt) => opt && opt.trim().length === 1 && /^[A-D]$/i.test(opt.trim())
      );
      if (isMalformed) return;
    }

    parsed.push({
      id: Date.now() + index + Math.random(),
      uniqueId: crypto.randomUUID(),
      discipline: discipline || "General",
      type: type || "Multiple Choice",
      difficulty: difficulty || "Easy",
      question: question || "",
      options,
      correct: correctLetter || "",
      sourceUrl: sourceUrl && !sourceUrl.includes(" ") ? sourceUrl : "",
      sourceExcerpt: sourceExcerpt || "",
      tags: tags,
      qualityScore: qualityScore,
      status: "pending",
      critique: null,
      critiqueScore: null,
    });
  });

  const deduplicated = removeDuplicateQuestions(parsed);
  return deduplicated.map((q) => normalizeQuestion(q));
};

/**
 * Intelligently converts a Multiple Choice question to True/False format.
 * Creates a statement from the question + correct answer, randomly makes it TRUE or FALSE.
 * @param {Object} mcQuestion - The Multiple Choice question to convert.
 * @param {string} difficulty - The difficulty level to apply.
 * @returns {Object} The converted True/False question.
 */
export const convertMCtoTF = (mcQuestion, difficulty) => {
  const correctAnswerText = mcQuestion.options[mcQuestion.correct];
  const wrongAnswers = Object.entries(mcQuestion.options)
    .filter(([key, val]) => key !== mcQuestion.correct && val && val.trim())
    .map(([, val]) => val);

  // Check if the original question is already effectively True/False
  const lowerCorrect = correctAnswerText
    .trim()
    .toLowerCase()
    .replace(/[.,!]$/, "");
  const isBooleanAnswer = ["true", "false", "yes", "no"].includes(lowerCorrect);

  let newStatement = mcQuestion.question.trim().replace(/\?$/, "");
  let makeItTrue = true; // Default

  if (isBooleanAnswer) {
    // PRESERVE MODE: If original answer is True/False, we keep the statement as is.
    // We cannot easily flip the truthiness of a statement without complex NLP (e.g. adding "not").
    // So we force the new question to match the original truthiness.

    // If original correct was "TRUE" or "YES" -> New Correct is A (TRUE)
    makeItTrue = ["true", "yes"].includes(lowerCorrect);

    // Statement is just the original question text (which is likely a statement)
    // newStatement remains the same
  } else {
    // STANDARD MODE: Randomly decide if this will be a TRUE or FALSE question (50/50)
    makeItTrue = Math.random() > 0.5;
    const targetAnswer = makeItTrue
      ? correctAnswerText
      : wrongAnswers[Math.floor(Math.random() * wrongAnswers.length)] ||
        "incorrect";

    // 1. Handle "Can you..." -> "You can [stem] [answer]"
    if (/^Can you/i.test(newStatement)) {
      const stem = newStatement.replace(/^Can you\s+/i, "");
      newStatement = `You can ${stem} ${targetAnswer}`;
    }
    // 2. Handle "Is..." -> "[Subject] is [Answer]"
    else if (/^Is\s+/i.test(newStatement)) {
      const stem = newStatement.replace(/^Is\s+/i, "");
      newStatement = `${stem} is ${targetAnswer}`;
    }
    // 3. Handle "What/Which..." -> "[Stem] is [Answer]"
    else {
      // Check for WH- words
      const isWhQuestion = /^(What|Which|How|Where|When|Why)\s+/i.test(
        newStatement
      );

      if (isWhQuestion) {
        const stem = newStatement
          .replace(
            /^(What|Which|How|Where|When|Why)\s+(is|are|does|do|can|should|would)\s+/i,
            ""
          )
          .trim();
        newStatement = `${stem} is ${targetAnswer}`;
      } else {
        // Fallback for other structures: append answer
        newStatement = `${newStatement} is ${targetAnswer}`;
      }
    }
  }

  // Cleanup: Remove double spaces, capitalize, add period
  newStatement = newStatement.replace(/\s+/g, " ").trim();
  newStatement = newStatement.charAt(0).toUpperCase() + newStatement.slice(1);
  if (!newStatement.endsWith(".")) newStatement += ".";

  return {
    ...mcQuestion,
    type: "True/False",
    difficulty: difficulty,
    question: newStatement,
    options: { A: "TRUE", B: "FALSE", C: "", D: "" },
    correct: makeItTrue ? "A" : "B",
    originalMC: mcQuestion.question, // Keep original for reference
  };
};

// ============================================================================
// QUESTION FILTERING UTILITIES
// ============================================================================

/**
 * Primary filter: Filters questions by status, creator, search term, discipline, difficulty, type, and language
 * @param {Array} questions - Current session questions
 * @param {Array} historicalQuestions - Historical questions from previous sessions
 * @param {boolean} showHistory - Whether to show all questions or just current session
 * @param {string} filterMode - Filter by status: 'pending', 'accepted', 'rejected', or 'all'
 * @param {boolean} filterByCreator - Whether to filter by reviewer name (shows questions reviewed by current user)
 * @param {string} searchTerm - Text search term
 * @param {string} creatorName - Current user's creator name
 * @param {string} discipline - Selected discipline (e.g., 'Technical Art')
 * @param {string} difficulty - Selected difficulty setting (e.g., 'Easy', 'Medium', 'Hard')
 * @param {string} language - Selected language (e.g., 'English', 'Chinese (Simplified)')
 * @returns {Array} Filtered questions
 */
const normalizeDiff = (d) => {
  if (!d) return "";
  const lower = d.toString().trim().toLowerCase();

  // Map all variants to canonical lowercase values (case-insensitive)
  if (lower === "easy" || lower === "beginner") return "easy";
  if (lower === "medium" || lower === "intermediate") return "medium";
  if (lower === "hard" || lower === "expert") return "hard";

  return lower; // Return lowercase version for consistent comparison
};

const normalizeType = (t) => {
  if (!t) return "";
  const lower = t.toLowerCase();
  if (lower === "t/f" || lower === "true/false") return "True/False";
  if (lower === "mc" || lower === "multiple choice") return "Multiple Choice";
  return t; // Fallback
};

export const createFilteredQuestions = (
  questions,
  historicalQuestions,
  showHistory,
  filterMode,
  filterByCreator,
  searchTerm,
  creatorName,
  discipline,
  difficulty,
  type,
  language,
  selectedTags = []
) => {
  // Determine source: either current session or all history
  const sourceQuestions = showHistory
    ? [...questions, ...historicalQuestions]
    : questions;

  return sourceQuestions.filter((q) => {
    // 1. Status Filter
    // CRITICAL FIX: Handle 'all' mode explicitly
    if (filterMode !== "all") {
      if (filterMode === "pending") {
        // Pending: show questions with no status or explicit "pending" status
        if (q.status && q.status !== "pending") return false;
      } else if (filterMode === "accepted") {
        if (q.status !== "accepted") return false;
      } else if (filterMode === "rejected") {
        if (q.status !== "rejected") return false;
      } else if (filterMode === "other") {
        // Other: any status that isn't empty, pending, accepted, or rejected
        if (
          !q.status ||
          q.status === "pending" ||
          q.status === "accepted" ||
          q.status === "rejected"
        )
          return false;
      }
    }

    // 2. Reviewer Filter (filter by who reviewed the question)
    if (filterByCreator && q.reviewerName !== creatorName) return false;

    // 3. Discipline Filter
    if (discipline && q.discipline !== discipline) return false;

    // 4. Tags Filter
    if (selectedTags && selectedTags.length > 0) {
      if (!q.tags || q.tags.length === 0) return false;
      // OR Logic: must have at least one of the selected tags
      if (!selectedTags.some((tag) => q.tags.includes(tag))) return false;
    }

    // 5. Difficulty & Type Filter
    if (difficulty) {
      // Check Difficulty (both normalized to lowercase for comparison)
      if (normalizeDiff(q.difficulty) !== normalizeDiff(difficulty))
        return false;

      // Check Type (only if specified)
      if (type && normalizeType(q.type) !== normalizeType(type)) return false;
    }

    // 6. Search Term Filter
    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      const searchFields = [
        q.uniqueId,
        q.question,
        q.discipline,
        q.difficulty,
        // Search within options
        ...(q.options ? Object.values(q.options) : []),
      ];

      // Check if any field contains the term
      const matches = searchFields.some(
        (field) => field && field.toString().toLowerCase().includes(term)
      );

      if (!matches) return false;
    }

    return true;
  });
};

/**
 * Secondary filter: Groups questions by uniqueId and selects one variant per group
 * Prioritizes the selected language, then English, then any available variant
 * @param {Array} filteredQuestions - Already filtered questions from createFilteredQuestions
 * @param {string} language - Preferred language to display
 * @returns {Array} Unique questions (one per uniqueId) in preferred language
 */
export const createUniqueFilteredQuestions = (
  filteredQuestions,
  language = "English",
  allQuestionsMap = null
) => {
  // FIX: Collect all unique IDs first, sort them, then process in stable order
  // This prevents dependency on the iteration order of filteredQuestions
  const uniqueIds = new Set();
  filteredQuestions.forEach((q) => uniqueIds.add(q.uniqueId));

  const sortedUniqueIds = Array.from(uniqueIds).sort();
  const uniqueQuestions = [];

  sortedUniqueIds.forEach((id) => {
    // FIX: Always get variants from the filtered list first to respect discipline filter
    // This prevents questions from other disciplines appearing when "All Disciplines" is selected
    let variants = filteredQuestions.filter((fq) => fq.uniqueId === id);

    // If allQuestionsMap exists and we found variants in filtered list,
    // we can use the map to find additional language variants of the SAME question
    // but ONLY if they would have passed the same filters (same discipline)
    if (allQuestionsMap && allQuestionsMap.has(id) && variants.length > 0) {
      // Use the first variant to check discipline
      const referenceDiscipline = variants[0].discipline;

      // Get all variants from map and filter to match the reference discipline
      const mapVariants = allQuestionsMap.get(id);
      variants = mapVariants.filter(
        (v) => v.discipline === referenceDiscipline
      );
    }

    let selected = null;

    // 1. Try to find exact language match
    selected = variants.find((v) => (v.language || "English") === language);

    // 2. Fall back to English
    if (!selected) {
      selected = variants.find((v) => (v.language || "English") === "English");
    }

    // 4. Last resort fallback removed to prevent language leakage (e.g. Chinese questions appearing in English queue)
    // If no variant exists for the preferred language or English, this question group is hidden from the current view.
    // ADDED: Text-based sanity check for English fallbacks
    if (!selected) {
      const isEnglishView = language === "English";
      selected = variants.find((v) => {
        const itemLang = v.language || "English";
        if (itemLang !== "English") return false;

        // If specifically viewing English, check for Chinese characters in text
        // (This catches Chinese questions that are incorrectly tagged as English)
        if (isEnglishView) {
          const text = v.question || v.text || "";
          if (/[\u4e00-\u9fa5]/.test(text)) return false;
        }
        return true;
      });
    }

    if (selected) {
      uniqueQuestions.push(selected);
    }
  });

  return uniqueQuestions;
};

import { validateURL } from "./urlValidator";
import { validateAnswer } from "./answerValidator";

/**
 * Unified Question Validator
 * Checks for:
 * 1. Critical failures (Auto-reject):
 *    - Missing source URL
 *    - Invalid URL pattern
 *    - Missing source excerpt
 *    - Excerpt too short (< 20 chars)
 *
 * 2. Warnings (Flag for review):
 *    - Answer doesn't match source excerpt (low confidence)
 *    - URL missing "-in-unreal-engine" suffix (medium confidence)
 *
 * @param {Object} question - The question object to validate
 * @returns {{
 *   isValid: boolean,
 *   isCriticalFailure: boolean,
 *   confidence: number,
 *   warnings: string[],
 *   details: Object
 * }}
 */
export function validateQuestion(question) {
  const warnings = [];
  let isCriticalFailure = false;
  let overallConfidence = 100;

  const urlResult = validateURL(question.SourceURL || question.sourceUrl);
  if (!urlResult.isValid) {
    isCriticalFailure = true;
    warnings.push(`Critical: ${urlResult.warning}`);
  } else if (urlResult.warning) {
    warnings.push(urlResult.warning);
    overallConfidence = Math.min(overallConfidence, urlResult.confidence);
  }

  // 2. Validate Source Excerpt (Critical)
  const excerpt = question.SourceExcerpt || question.sourceExcerpt;
  if (!excerpt || typeof excerpt !== "string") {
    isCriticalFailure = true;
    warnings.push("Critical: Missing source excerpt");
  } else if (excerpt.length < 20) {
    isCriticalFailure = true;
    warnings.push(`Critical: Source excerpt too short ("${excerpt}")`);
  } else if (/^\d+$/.test(excerpt.trim())) {
    // Catch cases where excerpt is just a number (like "100")
    isCriticalFailure = true;
    warnings.push(`Critical: Invalid source excerpt ("${excerpt}")`);
  }

  // 3. Validate Answer Match (Warning)
  // Only run if we have a valid excerpt
  let answerResult = { confidence: 100, warning: null };
  if (!isCriticalFailure) {
    answerResult = validateAnswer(question);
    // Add warning if validation fails or has warnings (both need the same handling)
    if (!answerResult.isValid || answerResult.warning) {
      warnings.push(answerResult.warning);
      overallConfidence = Math.min(overallConfidence, answerResult.confidence);
    }
  }

  return {
    isValid: !isCriticalFailure,
    isCriticalFailure,
    confidence: overallConfidence,
    warnings,
    details: {
      url: urlResult,
      answer: answerResult,
    },
  };
}

/**
 * Batch validate questions
 * @param {Array} questions
 * @returns {Array} Questions with validation metadata attached
 */
export function validateQuestionsBatch(questions) {
  return questions.map((q) => {
    const validation = validateQuestion(q);
    return {
      ...q,
      _validation: validation,
    };
  });
}

import { logger } from "../utils/logger";
/**
 * Utility functions for quiz GUID generation and seeded randomization
 */

/**
 * Generate a UUID v4 GUID
 * NOTE: Using Math.random for GUID generation is acceptable here.
 * This is for generating unique identifiers, not for security purposes.
 * @returns {string} GUID in format: xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx
 */
export function generateGUID() {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function (c) {
    // eslint-disable-next-line sonarjs/pseudo-random
    const r = (Math.random() * 16) | 0;
    const v = c === "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

/**
 * Simple hash function to convert string to number
 * @param {string} str - String to hash
 * @returns {number} Hash value
 */
function hashString(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash = hash & hash; // Convert to 32bit integer
  }
  return Math.abs(hash);
}

/**
 * Create a seeded random number generator
 * Uses a simple Linear Congruential Generator (LCG)
 * @param {string} seed - String seed (e.g., GUID)
 * @returns {Function} Random function that returns 0-1
 */
export function createSeededRandom(seed) {
  let state = hashString(seed);

  return function () {
    // LCG using GCC's constants
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

/**
 * Shuffle an array using a seeded random function
 * Fisher-Yates shuffle with custom RNG
 * @param {Array} array - Array to shuffle
 * @param {Function} randomFn - Seeded random function
 * @returns {Array} Shuffled copy of array
 */
export function seededShuffle(array, randomFn) {
  const copy = [...array];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(randomFn() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

/**
 * Report quiz results to SCORM LMS
 * @param {Object} results - Quiz results
 * @param {string} quizGuid - Quiz instance GUID
 * @param {number} timeSpent - Time spent in seconds
 */
export function reportToSCORM(results, quizGuid, timeSpent) {
  if (typeof window.SCORM12 === "undefined" || !window.SCORM12.isConnected()) {
    logger.log("SCORM not available - results not sent to LMS");
    logger.log("Quiz GUID:", quizGuid);
    logger.log("Results:", results);
    return;
  }

  try {
    // Send score
    window.SCORM12.setScoreRaw(results.percentage, 0, 100);

    // Send pass/fail status
    window.SCORM12.setStatus(results.passed ? "passed" : "failed");

    // Send session time
    window.SCORM12.setSessionTimeSeconds(timeSpent);

    // Send quiz GUID as suspend data for debugging
    // SCORM 1.2 allows up to 4096 characters in suspend_data
    const suspendData = JSON.stringify({
      quizGuid,
      completedAt: new Date().toISOString(),
      score: results.percentage,
      correct: results.correct,
      total: results.total,
    });

    window.SCORM12.setValue("cmi.suspend_data", suspendData);

    // Commit all changes
    window.SCORM12.commit();

    logger.log("Quiz results sent to SCORM LMS");
    logger.log("Quiz GUID:", quizGuid);
  } catch (error) {
    logger.error("Failed to report to SCORM:", error);
  }
}

/**
 * Quota Enforcement Utilities
 * Prevents generation when category/discipline quotas are met
 */

import { TARGET_PER_CATEGORY, TARGET_TOTAL, CATEGORY_KEYS } from "./constants";

/**
 * Calculates current question counts by category
 * @param {Array} questions - All questions
 * @returns {Object} Category counts
 */
export const getCategoryCounts = (questions) => {
  const counts = {};

  CATEGORY_KEYS.forEach((cat) => {
    counts[cat] = questions.filter(
      (q) => q.difficulty === cat && q.status !== "rejected"
    ).length;
  });

  return counts;
};

/**
 * Calculates counts by discipline and difficulty
 * @param {Array} questions - All questions
 * @returns {Object} Nested counts { discipline: { difficulty: count } }
 */
export const getDisciplineCounts = (questions) => {
  const counts = {};

  questions.forEach((q) => {
    if (q.status === "rejected") return;

    const discipline = q.discipline || "Unknown";
    const difficulty = q.difficulty || "Unknown";

    if (!counts[discipline]) counts[discipline] = {};
    if (!counts[discipline][difficulty]) counts[discipline][difficulty] = 0;

    counts[discipline][difficulty]++;
  });

  return counts;
};

/**
 * Checks if a category has reached its quota
 * @param {string} category - Category key (e.g., "Easy MC")
 * @param {Array} questions - All questions
 * @returns {boolean} True if quota met or exceeded
 */
export const isCategoryFull = (category, questions) => {
  const count = questions.filter(
    (q) => q.difficulty === category && q.status !== "rejected"
  ).length;

  return count >= TARGET_PER_CATEGORY;
};

/**
 * Checks if specific discipline+difficulty combo is full
 * @param {string} discipline - Discipline (e.g., "Blueprints")
 * @param {string} difficulty - Difficulty (e.g., "Easy MC")
 * @param {Array} questions - All questions
 * @returns {boolean} True if quota met
 */
export const isDisciplineFull = (discipline, difficulty, questions) => {
  const count = questions.filter(
    (q) =>
      q.discipline === discipline &&
      q.difficulty === difficulty &&
      q.status !== "rejected"
  ).length;

  return count >= TARGET_PER_CATEGORY;
};

/**
 * Checks if total question count has been reached
 * @param {Array} questions - All questions
 * @returns {boolean} True if total quota met
 */
export const isTotalQuotaMet = (questions) => {
  const count = questions.filter((q) => q.status !== "rejected").length;
  return count >= TARGET_TOTAL;
};

/**
 * Gets remaining quota for a specific category
 * @param {string} category - Category key
 * @param {Array} questions - All questions
 * @returns {number} Remaining questions allowed (0 if full)
 */
export const getRemainingQuota = (category, questions) => {
  const current = questions.filter(
    (q) => q.difficulty === category && q.status !== "rejected"
  ).length;

  return Math.max(0, TARGET_PER_CATEGORY - current);
};

/**
 * Gets quota status for all categories
 * @param {Array} questions - All questions
 * @returns {Object} { category: { current, target, remaining, isFull } }
 */
export const getQuotaStatus = (questions) => {
  const status = {};

  CATEGORY_KEYS.forEach((cat) => {
    const current = questions.filter(
      (q) => q.difficulty === cat && q.status !== "rejected"
    ).length;

    status[cat] = {
      current,
      target: TARGET_PER_CATEGORY,
      remaining: Math.max(0, TARGET_PER_CATEGORY - current),
      isFull: current >= TARGET_PER_CATEGORY,
      percentage: Math.round((current / TARGET_PER_CATEGORY) * 100),
    };
  });

  // Add total
  const totalCurrent = questions.filter((q) => q.status !== "rejected").length;
  status.TOTAL = {
    current: totalCurrent,
    target: TARGET_TOTAL,
    remaining: Math.max(0, TARGET_TOTAL - totalCurrent),
    isFull: totalCurrent >= TARGET_TOTAL,
    percentage: Math.round((totalCurrent / TARGET_TOTAL) * 100),
  };

  return status;
};

/**
 * Validates if generation should be allowed
 * @param {string} discipline - Selected discipline
 * @param {string} difficulty - Selected difficulty
 * @param {number} batchSize - Number of questions to generate
 * @param {Array} questions - All existing questions
 * @param {string} type - Selected type (MC or T/F)
 * @returns {Object} { allowed: boolean, reason: string, maxAllowed: number, forceType: string }
 */
export const validateGeneration = (
  discipline,
  difficulty,
  batchSize,
  questions,
  type = "Multiple Choice"
) => {
  // Helper to normalize difficulty from "Easy MC" -> "Easy"
  const normalizeDiff = (d) => {
    if (!d) return d;
    const base = d.split(" ")[0];
    // Map config values to base difficulty
    if (base === "Beginner") return "Easy";
    if (base === "Intermediate") return "Medium";
    if (base === "Expert") return "Hard";
    return base;
  };

  const targetDiff = normalizeDiff(difficulty);

  // Check total quota - WARN only, don't block
  // Individual category quotas (below) control actual blocking
  // This prevents blocking generation for unfilled categories when others are full
  // Note: we call isTotalQuotaMet but don't block on it - individual category limits control blocking
  isTotalQuotaMet(questions);

  // Filter questions for this discipline and base difficulty
  const relevantQuestions = questions.filter((q) => {
    if (q.status === "rejected") return false;
    if (q.discipline !== discipline) return false;
    const qDiff = normalizeDiff(q.difficulty);
    return qDiff === targetDiff;
  });

  // Count MC and T/F separately
  const mcCount = relevantQuestions.filter(
    (q) => q.type === "Multiple Choice" || q.type === "MC"
  ).length;

  const tfCount = relevantQuestions.filter(
    (q) => q.type === "True/False" || q.type === "T/F"
  ).length;

  const MC_QUOTA = TARGET_PER_CATEGORY;
  const TF_QUOTA = TARGET_PER_CATEGORY;

  // Check if both MC and T/F are full for this difficulty
  if (mcCount >= MC_QUOTA && tfCount >= TF_QUOTA) {
    return {
      allowed: false,
      reason: `Both MC (${mcCount}/${MC_QUOTA}) and T/F (${tfCount}/${TF_QUOTA}) are full for ${difficulty}. Select a different difficulty.`,
      maxAllowed: 0,
    };
  }

  // For specific type selection
  if (type === "Multiple Choice" || type === "MC") {
    if (mcCount >= MC_QUOTA) {
      return {
        allowed: false,
        reason: `MC quota full for ${difficulty} (${mcCount}/${MC_QUOTA}). Switch to T/F.`,
        maxAllowed: 0,
        forceType: "True/False",
      };
    }
    return {
      allowed: true,
      reason: "Generation allowed",
      maxAllowed: Math.min(batchSize, MC_QUOTA - mcCount),
    };
  }

  if (type === "True/False" || type === "T/F") {
    if (tfCount >= TF_QUOTA) {
      return {
        allowed: false,
        reason: `T/F quota full for ${difficulty} (${tfCount}/${TF_QUOTA}). Switch to MC.`,
        maxAllowed: 0,
        forceType: "Multiple Choice",
      };
    }
    return {
      allowed: true,
      reason: "Generation allowed",
      maxAllowed: Math.min(batchSize, TF_QUOTA - tfCount),
    };
  }

  // Default: allow generation
  const totalRemaining = MC_QUOTA - mcCount + (TF_QUOTA - tfCount);
  return {
    allowed: true,
    reason: "Generation allowed",
    maxAllowed: Math.min(batchSize, totalRemaining),
  };
};

/**
 * Rate Limit State Manager
 * Exposes rate limit state for UI consumption with reactive updates.
 */

// Internal state
const rateLimitState = {
  isLimited: false,
  retryAfter: 0,
  listeners: new Set(),
};

/**
 * Gets the current rate limit status.
 * @returns {{ isLimited: boolean, retryAfter: number, remainingSeconds: number }}
 */
export const getRateLimitStatus = () => {
  const now = Date.now();
  const remainingMs = Math.max(0, rateLimitState.retryAfter - now);
  return {
    isLimited: rateLimitState.isLimited && remainingMs > 0,
    retryAfter: rateLimitState.retryAfter,
    remainingSeconds: Math.ceil(remainingMs / 1000),
  };
};

/**
 * Sets the rate limit state (called by gemini.js fetchWithRetry).
 * @param {boolean} isLimited
 * @param {number} retryAfter - Timestamp when limit expires
 */
export const setRateLimitState = (isLimited, retryAfter) => {
  rateLimitState.isLimited = isLimited;
  rateLimitState.retryAfter = retryAfter;
  notifyListeners();
};

/**
 * Clears rate limit state after successful request.
 */
export const clearRateLimitState = () => {
  rateLimitState.isLimited = false;
  rateLimitState.retryAfter = 0;
  notifyListeners();
};

/**
 * Subscribe to rate limit state changes.
 * @param {Function} callback - Called when state changes
 * @returns {Function} Unsubscribe function
 */
export const subscribeToRateLimitState = (callback) => {
  rateLimitState.listeners.add(callback);
  return () => rateLimitState.listeners.delete(callback);
};

/** Notify all listeners of state change */
const notifyListeners = () => {
  rateLimitState.listeners.forEach((cb) => cb(getRateLimitStatus()));
};

/**
 * reviewerAnalytics.js - Reviewer Activity Analytics
 *
 * Provides functions to aggregate and analyze reviewer performance metrics
 * from Firestore question data.
 */

import { collection, query, where, getDocs, orderBy } from "firebase/firestore";
import { getDb } from "../services/firebase";
import { logger } from "../utils/logger";

/**
 * Fetches all questions that have been reviewed (have reviewCompletedAt timestamp)
 * @returns {Promise<Array>} Array of reviewed question objects
 */
export const fetchReviewedQuestions = async () => {
  try {
    const auditRef = collection(getDb(), "audit_logs");

    // Query for questions that have been completed (accepted or rejected)
    const q = query(
      auditRef,
      where("reviewCompletedAt", "!=", null),
      orderBy("reviewCompletedAt", "desc")
    );

    const querySnapshot = await getDocs(q);
    const questions = [];

    querySnapshot.forEach((doc) => {
      questions.push({
        id: doc.id,
        ...doc.data(),
      });
    });

    return questions;
  } catch (error) {
    logger.error("Error fetching reviewed questions:", error);
    throw error;
  }
};

/**
 * Aggregates reviewer activity metrics from question data
 * @param {Array} questions - Array of question objects
 * @returns {Array} Array of reviewer stats objects
 */
export const aggregateReviewerStats = (questions) => {
  const reviewerMap = new Map();

  questions.forEach((q) => {
    // Use reviewerName or acceptedBy as the reviewer identifier
    const reviewerName = q.reviewerName || q.acceptedBy || "Unknown";

    if (!reviewerMap.has(reviewerName)) {
      reviewerMap.set(reviewerName, {
        name: reviewerName,
        totalQuestionsReviewed: 0,
        totalReviewTimeSeconds: 0,
        reviewDurations: [], // Track individual durations for avg calculation
        acceptedCount: 0,
        rejectedCount: 0,
        firstReviewDate: null,
        lastReviewDate: null,
      });
    }

    const stats = reviewerMap.get(reviewerName);

    // Increment question count
    stats.totalQuestionsReviewed += 1;

    // Track acceptance/rejection
    if (q.status === "accepted") {
      stats.acceptedCount += 1;
    } else if (q.status === "rejected") {
      stats.rejectedCount += 1;
    }

    // Add review duration if available
    if (q.reviewDuration && q.reviewDuration > 0) {
      stats.totalReviewTimeSeconds += q.reviewDuration;
      stats.reviewDurations.push(q.reviewDuration);
    }

    // Track date range
    const reviewDate = q.reviewCompletedAt || q.acceptedAt;
    if (reviewDate) {
      const date = new Date(reviewDate);
      if (!stats.firstReviewDate || date < stats.firstReviewDate) {
        stats.firstReviewDate = date;
      }
      if (!stats.lastReviewDate || date > stats.lastReviewDate) {
        stats.lastReviewDate = date;
      }
    }
  });

  // Convert Map to array and calculate averages
  const reviewerStats = Array.from(reviewerMap.values()).map((stats) => ({
    ...stats,
    averageReviewTimeSeconds:
      stats.reviewDurations.length > 0
        ? Math.round(
            stats.reviewDurations.reduce((sum, d) => sum + d, 0) /
              stats.reviewDurations.length
          )
        : 0,
    // Calculate review velocity (questions per day)
    reviewVelocity:
      stats.firstReviewDate && stats.lastReviewDate
        ? calculateVelocity(
            stats.totalQuestionsReviewed,
            stats.firstReviewDate,
            stats.lastReviewDate
          )
        : 0,
  }));

  // Sort by total questions reviewed (descending)
  return reviewerStats.sort(
    (a, b) => b.totalQuestionsReviewed - a.totalQuestionsReviewed
  );
};

/**
 * Calculate review velocity (questions per day)
 * @param {number} totalQuestions - Total questions reviewed
 * @param {Date} startDate - First review date
 * @param {Date} endDate - Last review date
 * @returns {number} Questions per day
 */
const calculateVelocity = (totalQuestions, startDate, endDate) => {
  const daysDiff = Math.max(
    1,
    Math.ceil((endDate - startDate) / (1000 * 60 * 60 * 24))
  );
  return (totalQuestions / daysDiff).toFixed(2);
};

/**
 * Format duration in seconds to human-readable string
 * @param {number} seconds - Duration in seconds
 * @returns {string} Formatted duration (e.g., "2m 30s", "1h 15m")
 */
export const formatDuration = (seconds) => {
  if (!seconds || seconds < 0) return "--";

  if (seconds < 60) {
    return `${seconds}s`;
  } else if (seconds < 3600) {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return secs > 0 ? `${mins}m ${secs}s` : `${mins}m`;
  } else {
    const hours = Math.floor(seconds / 3600);
    const mins = Math.floor((seconds % 3600) / 60);
    return mins > 0 ? `${hours}h ${mins}m` : `${hours}h`;
  }
};

/**
 * Format date to readable string
 * @param {Date|string} dateVal - Date value
 * @returns {string} Formatted date
 */
export const formatDate = (dateVal) => {
  if (!dateVal) return "N/A";
  try {
    const date = dateVal instanceof Date ? dateVal : new Date(dateVal);
    return isNaN(date.getTime()) ? "Invalid Date" : date.toLocaleDateString();
  } catch (e) {
    logger.error("Date formatting error:", e);
    return "Invalid Date";
  }
};

/**
 * Main function to fetch and aggregate reviewer analytics
 * @returns {Promise<Object>} Analytics data with reviewer stats and metadata
 */
export const getReviewerAnalytics = async () => {
  try {
    const reviewedQuestions = await fetchReviewedQuestions();
    const reviewerStats = aggregateReviewerStats(reviewedQuestions);

    return {
      reviewerStats,
      metadata: {
        totalQuestionsReviewed: reviewedQuestions.length,
        totalReviewers: reviewerStats.length,
        lastUpdated: new Date().toISOString(),
      },
    };
  } catch (error) {
    logger.error("Error getting reviewer analytics:", error);
    throw error;
  }
};

import { logger } from "../utils/logger";
/**
 * Security utility functions for file uploads and data processing.
 *
 * NOTE: Regex patterns are for validating uploaded CSV files.
 * Input is file content - controlled environment, no DoS risk.
 */
/* eslint-disable sonarjs/slow-regex */
// Maximum file size in bytes (5MB)
const MAX_FILE_SIZE = 5 * 1024 * 1024;

// Allowed MIME types for CSV
const ALLOWED_MIME_TYPES = [
  "text/csv",
  "application/csv",
  "application/vnd.ms-excel",
  "text/plain", // Fallback for some systems
];

/**
 * Validates a file before processing.
 * Checks for size, extension, and MIME type.
 * @param {File} file - The file object to validate.
 * @returns {Object} - { isValid: boolean, error: string | null }
 */
export const validateFile = (file) => {
  // 1. Check File Size
  if (file.size > MAX_FILE_SIZE) {
    return {
      isValid: false,
      error: `File "${file.name}" exceeds the 5MB size limit.`,
    };
  }

  // 2. Check Extension
  const fileName = file.name.toLowerCase();
  if (!fileName.endsWith(".csv")) {
    return { isValid: false, error: `File "${file.name}" is not a .csv file.` };
  }

  // 3. Check MIME Type (Advisory only, as browsers can be spoofed or inconsistent)
  // We rely more on content parsing, but this is a good first gate.
  if (!ALLOWED_MIME_TYPES.includes(file.type) && file.type !== "") {
    // Note: file.type can be empty string on Windows sometimes
    logger.warn(`Warning: Unusual MIME type for CSV: ${file.type}`);
  }

  return { isValid: true, error: null };
};

/**
 * Sanitizes a string to prevent CSV Injection (Formula Injection).
 * Removes leading characters that could trigger formula execution in Excel/Sheets.
 * @param {string} text - The text to sanitize.
 * @returns {string} - The sanitized text.
 */
export const sanitizeCSVField = (text) => {
  if (!text) return "";
  const str = String(text);
  // If the field starts with =, +, -, or @, prepend a single quote to force it as text
  if (/^[=+\-@]/.test(str)) {
    return "'" + str;
  }
  return str;
};

/**
 * Validates the content of a CSV file.
 * Checks for empty content, malformed lines, and potential malicious patterns.
 * @param {string} content - The raw CSV content string.
 * @returns {Object} - { isValid: boolean, error: string | null, sanitizedContent: string }
 */
export const validateCSVContent = (content) => {
  if (!content || content.trim().length === 0) {
    return { isValid: false, error: "File is empty." };
  }

  const lines = content.split(/\r\n|\n|\r/);
  if (lines.length < 2) {
    // Expect at least header + 1 row
    return {
      isValid: false,
      error: "CSV file must contain a header and at least one data row.",
    };
  }

  // Basic Header Validation (Optional: Check for required columns)
  const header = lines[0].toLowerCase();
  if (!header.includes("question") && !header.includes("id")) {
    return {
      isValid: false,
      error: "Invalid CSV format: Missing 'Question' or 'ID' columns.",
    };
  }

  // Scan for obvious malicious patterns (very basic heuristic)
  // Note: True virus scanning requires a backend.
  // We can check for excessive length or binary characters which might indicate a non-text file.
  const nullByteIndex = content.indexOf("\0");
  if (nullByteIndex !== -1) {
    return {
      isValid: false,
      error:
        "File contains binary data (null bytes). It may not be a valid text/CSV file.",
    };
  }

  return { isValid: true, error: null };
};

/**
 * String utilities for text processing, markdown rendering, and CSV parsing.
 *
 * NOTE: Regex patterns here are for text/markdown processing.
 * Input is application-controlled (internal question text), not user-provided - no DoS risk.
 */
/* eslint-disable sonarjs/slow-regex */
import DOMPurify from "dompurify";

export const chunkArray = (array, size) => {
  const result = [];
  for (let i = 0; i < array.length; i += size) {
    result.push(array.slice(i, i + size));
  }
  return result;
};

/**
 * Calculate text similarity using Levenshtein distance (0-1 score)
 * @param {string} str1 - First string to compare
 * @param {string} str2 - Second string to compare
 * @returns {number} Similarity score between 0 (different) and 1 (identical)
 */
export const textSimilarity = (str1, str2) => {
  if (!str1 || !str2) return 0;

  // Normalize: lowercase, remove extra whitespace, remove HTML tags
  const normalize = (s) =>
    s
      .toLowerCase()
      .replace(/<[^>]*>/g, "")
      .replace(/\s+/g, " ")
      .trim();
  const a = normalize(str1);
  const b = normalize(str2);

  if (a === b) return 1;
  if (a.length === 0 || b.length === 0) return 0;

  // For very long strings, use a simpler word-based comparison for performance
  if (a.length > 500 || b.length > 500) {
    const wordsA = new Set(a.split(" "));
    const wordsB = new Set(b.split(" "));
    const intersection = [...wordsA].filter((w) => wordsB.has(w)).length;
    const union = new Set([...wordsA, ...wordsB]).size;
    return union > 0 ? intersection / union : 0;
  }

  // Levenshtein distance calculation
  const matrix = Array(b.length + 1)
    .fill(null)
    .map(() => Array(a.length + 1).fill(null));

  for (let i = 0; i <= a.length; i++) matrix[0][i] = i;
  for (let j = 0; j <= b.length; j++) matrix[j][0] = j;

  for (let j = 1; j <= b.length; j++) {
    for (let i = 1; i <= a.length; i++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      matrix[j][i] = Math.min(
        matrix[j][i - 1] + 1, // deletion
        matrix[j - 1][i] + 1, // insertion
        matrix[j - 1][i - 1] + cost // substitution
      );
    }
  }

  const maxLen = Math.max(a.length, b.length);
  return 1 - matrix[b.length][a.length] / maxLen;
};

/**
 * Compute word-level diff between two strings for inline highlighting
 * Uses Longest Common Subsequence (LCS) algorithm for accurate diff
 * @param {string} oldText - Original text
 * @param {string} newText - New/modified text
 * @returns {Array<{type: 'unchanged'|'removed'|'added', text: string}>} Array of diff segments
 */
export const computeWordDiff = (oldText, newText) => {
  if (!oldText && !newText) return [];
  if (!oldText) return [{ type: "added", text: newText }];
  if (!newText) return [{ type: "removed", text: oldText }];
  if (oldText === newText) return [{ type: "unchanged", text: oldText }];

  // Tokenize into words (preserving punctuation attached to words)
  const tokenize = (text) => text.split(/(\s+)/).filter((t) => t.length > 0);

  const oldTokens = tokenize(oldText);
  const newTokens = tokenize(newText);

  // Build LCS table
  const m = oldTokens.length;
  const n = newTokens.length;
  const dp = Array(m + 1)
    .fill(null)
    .map(() => Array(n + 1).fill(0));

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (oldTokens[i - 1] === newTokens[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }

  // Backtrack to find the diff
  let i = m,
    j = n;

  const tempDiff = [];
  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && oldTokens[i - 1] === newTokens[j - 1]) {
      tempDiff.unshift({ type: "unchanged", text: oldTokens[i - 1] });
      i--;
      j--;
    } else if (j > 0 && (i === 0 || dp[i][j - 1] >= dp[i - 1][j])) {
      tempDiff.unshift({ type: "added", text: newTokens[j - 1] });
      j--;
    } else {
      tempDiff.unshift({ type: "removed", text: oldTokens[i - 1] });
      i--;
    }
  }

  // Merge consecutive segments of the same type for cleaner output
  const merged = [];
  for (const segment of tempDiff) {
    if (merged.length > 0 && merged[merged.length - 1].type === segment.type) {
      merged[merged.length - 1].text += segment.text;
    } else {
      merged.push({ ...segment });
    }
  }

  return merged;
};

export const renderMarkdown = (t) => {
  if (!t) return "";

  // Step 1: Convert markdown-style formatting to HTML
  const html = String(t)
    // Headers
    .replace(
      /^### (.*$)/gim,
      '<h3 class="text-orange-400 font-bold text-xs mt-3 mb-1 uppercase tracking-wide">$1</h3>'
    )
    .replace(
      /^#### (.*$)/gim,
      '<h4 class="text-slate-200 font-bold text-[10px] mt-2 mb-1 uppercase">$1</h4>'
    )
    // Bold (**text**)
    .replace(
      /\*\*(.*?)\*\*/g,
      '<strong class="text-orange-300 font-bold">$1</strong>'
    )
    // Inline code (`code`)
    .replace(
      /`([^`]+)`/g,
      '<code class="px-1.5 py-0.5 rounded bg-blue-950/50 text-blue-300 font-mono text-[0.9em] border border-blue-900/50">$1</code>'
    )
    // Lists
    .replace(
      /^\s*\* (.*$)/gim,
      '<div class="ml-3 flex items-start gap-2"><span class="text-orange-500 mt-1 text-[10px] flex-shrink-0">ΓÇó</span><span>$1</span></div>'
    )
    // Italics (*text*)
    .replace(/\*([^\n*]+)\*/g, '<em class="text-slate-300 italic">$1</em>')
    // Double newlines
    .replace(/\n\s*\n/g, '<div class="h-2"></div>')
    // Single newlines
    .replace(/\n/g, "<br />");

  // Step 2: Sanitize with DOMPurify to prevent XSS
  const sanitized = DOMPurify.sanitize(html, {
    ALLOWED_TAGS: [
      "b",
      "i",
      "em",
      "strong",
      "code",
      "br",
      "div",
      "span",
      "h3",
      "h4",
      "h5",
      "h6",
      "ul",
      "ol",
      "li",
      "p",
    ],
    ALLOWED_ATTR: ["class"],
    ALLOW_DATA_ATTR: false,
  });

  return sanitized;
};

export const sanitizeText = (text) => renderMarkdown(text);

export const stripHtmlTags = (text) => {
  if (typeof text !== "string") return text;
  // Use DOMParser for safer HTML parsing (avoids XSS via innerHTML)
  const parser = new DOMParser();
  const doc = parser.parseFromString(text, "text/html");
  return doc.body.textContent || "";
};

export const safe = (t) => {
  if (t === null || t === undefined) return '""';
  const str = String(t);
  let content = stripHtmlTags(str);
  content = (content || "").trim();
  content = content
    .replace(/[\u200B\uFEFF\u00A0]/g, " ")
    .replace(/\s\s+/g, " ")
    .trim();
  content = content.replace(/(\r\n|\n|\r|\t)/gm, " ");
  content = content.replace(/['"]/g, "");
  const escaped = content.replace(/"/g, '""');
  return `"${escaped}"`;
};

export const parseCSVLine = (text) => {
  const result = [];
  let cell = "";
  let insideQuote = false;
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (char === '"') {
      if (insideQuote && text[i + 1] === '"') {
        cell += '"';
        // eslint-disable-next-line sonarjs/updated-loop-counter -- Intentional: skip escaped quote
        i++;
      } else {
        insideQuote = !insideQuote;
      }
    } else if (char === "," && !insideQuote) {
      result.push(cell);
      cell = "";
    } else {
      cell += char;
    }
  }
  result.push(cell);
  return result;
};

